int main() {
	i64 n, k; scanf("%lld%lld", &n, &k);

	auto getSegment = [&](i64 x) {
		if(x == 0) return n + 1;
		i64 ok = 0, ng = n;
		while(ng - ok > 1) {
			i64 mid = (ok + ng) >> 1;

			if(n / mid > x) ok = mid;
			else ng = mid;
		}
		return ok + 1;
	};

	std::vector<int> latte;
	for(i64 i = 1; i * i <= n; i++) {
		latte.push_back(i);
		latte.push_back(n / i);
	}
	sort(begin(latte), end(latte)); latte.erase(unique(begin(latte), end(latte)), end(latte));
	reverse(begin(latte), end(latte));

	std::vector<std::pair<i64, i64>> vec;
	for(auto x: latte) {
		i64 L = getSegment(x), R = std::min(n + 1, getSegment(x - 1));
		if(L < R) vec.push_back({L, R});
	}

	const int MOD = 1e9 + 7;
	auto dp = make_v<i64>(k + 1, (int)vec.size()); dp[0][0] = 1;
	for(int i = 0; i < k; i++) {
		i64 cur = 0, tmp = 0;
		for(int j = (int)vec.size() - 1; j >= 0; j--) {
			i64 Y = vec[j].second - 1;
			while(cur < vec.size() and (vec[cur].second - 1) * Y <= n) {
				(tmp += dp[i][cur++]) %= MOD;
			}

			i64 width = vec[j].second - vec[j].first;
			(dp[i + 1][j] += tmp * width % MOD) %= MOD;
		}
	}

	i64 ans = 0;
	for(auto v: dp[k]) (ans += v) %= MOD;
	printf("%lld\n", ans);
	return 0;
}

