const int N = 1e2 + 10, M = 32e3 + 10, mod = 1e9 + 7;
int n, k, ans, dp[3][M], total, psum[M];

int32_t main() {
	ios::sync_with_stdio(0);
	cin.tie(0);

	cin >> n >> k;

	int sq = 1;
	while (sq * sq <= n)
		sq++;

	dp[0][0] = 1;
	for (int i = 0; i < sq; i++)
		psum[i] = 1;
	for (int i = 1; i < sq; i++)
		dp[1][i] = 1;
	total = sq - 1;

	for (int i = 2; i <= k; i++) {
		int now = (i % 3), prv = (now + 2) % 3, ppr = (now + 1) % 3;

		int tmp = 0;
		for (int z = 2; z < sq; z++)
			tmp = (tmp + dp[ppr][z] * (n / z - sq + 1) % mod) % mod;

		for (int j = 1; j < sq; j++) {
			int add = (n / j - sq + 1) * psum[j] % mod;
			dp[now][j] = (total + tmp + add) % mod;

//			cout << i << ' ' << j << " : " << dp[now][j] << ' ' << tmp << ' ' << add << endl;
			tmp = (tmp - dp[ppr][j + 1] * (n / (j + 1) - sq + 1) % mod) % mod;
		}

		psum[0] = total = 0;
		for (int j = 1; j < sq; j++)
			total = (total + dp[now][j]) % mod;
		for (int j = 1; j < sq; j++)
			psum[j] = (psum[j - 1] + dp[prv][j]) % mod;
	}

	for (int i = 1; i < sq; i++) {
		ans = (ans + dp[k % 3][i]) % mod;
		ans = (ans + dp[(k + 2) % 3][i] * (n / i - sq + 1) % mod) % mod;
	}
	cout << (ans + mod) % mod << endl;
