    vector<unsigned long long> count0(sqrtN, 1);
    for (int i = sqrtN; i >= 1; i--)
    {
        double start = double(n) / (i + 1);
        double end = double(n) / i;
        if (start < sqrtN)
            continue;
        // (start, end]
        count0.push_back(int(end) - int(start));
    }
    int m = count0.size();
    vector<unsigned long long> count(count0.begin(), count0.end());
    for (int iter = 2; iter <= k; iter++)
    {
        vector<unsigned long long> nextCount(m);
        unsigned long long sum = 0;
        for (int i = m - 1; i >= 0; i--)
        {
            sum = (sum + count[m - 1 - i]) % BASE;
            nextCount[i] = sum * count0[i] % BASE;
        }
        count = nextCount;
    }
    unsigned long long result = 0;
    for (int i = 0; i < m; i++)
    {
        result = (result + count[i]) % BASE;
    }
    cout << result << endl;

    return 0;
}

