	SegmentTree(const size_t n, const F f, const Monoid E) : f(f), E(E) {
		sz = 1;
		while(sz < n) sz <<= 1;
		data.assign(sz << 1, E);
	}
	void set(int k, const Monoid x) {
		data[k + sz] = x;
	}
	void build() {
		for(int k = sz - 1; k > 0; k--) data[k] = f(data[2 * k + 0], data[2 * k + 1]);
	}
	void update(int k, const Monoid x) {
		k += sz;
		data[k] = x;

		while(k >>= 1) data[k] = f(data[k << 1 ^ 0], data[k << 1 ^ 1]);
	}
	Monoid query(int a, int b) {
		Monoid L = E, R = E;
		for(a += sz, b += sz; a < b; a >>= 1, b >>= 1) {
			if(a & 1) L = f(L, data[a++]);
			if(b & 1) R = f(data[--b], R);
		}
		return f(L, R);
	}
	const Monoid operator[](const int k) const {
		return data[k + sz];
	}
};

int main() {
	i64 n, k; scanf("%lld%lld", &n, &k);

	const int MOD = 1e9 + 7;
	auto f = [](i64 a, i64 b) { return (a + b) % MOD; };
	std::vector<SegmentTree<i64>> dp(k + 1, SegmentTree<i64>(1e5 + 10, f, 0)); dp[0].update(1, 1);
	std::vector<SegmentTree<i64>> to(k + 1, SegmentTree<i64>(1e5 + 10, f, 0));
	for(int i = 0; i < k; i++) {
		for(i64 j = 1; j <= std::min((i64)1e5, n); j++) {
			i64 tmp = dp[i].query(0, std::min((i64)1e5, n) / j + 1);
			dp[i + 1].update(j, tmp);
			dp[i + 1].update(j, to[i].query(0, j + 1));
		}
		for(i64 j = 1; j <= std::min((i64)1e5, n); j++) {
			i64 L = (n - 1) / j, R = n / j;
			i64 tmp = dp[i].query(0, j + 1) * (R - L) % MOD;

			to[i + 1].update(j, tmp);
		}
	}

	printf("%lld\n", (dp[k].query(0, 1e5 + 1) + to[k].query(0, 1e5 + 1) % MOD));
	return 0;
}

