    for (int cs = 1; cs <= T; cs++) {
        int n, k;
        cin >> n >> k;

        ll root = sqrt(n) + 1;
        ll dpS[root][k];
        ll dpL[root][k];

        for (int i = 0; i < root; i++) {
            for (int j = 0; j < k; j++) {
                dpS[i][j] = 0;
                dpL[i][j] = 0;
            }
        }

        ll countLarge[root];
        for (int i = 0; i < root; i++)
        {
            countLarge[i] = max(n / (i + 1), (int) root) - max(n / (i + 2), (int)root);
        }

        ll sufS[root], preL[root];

        for (int i = 0; i < root; i++) {
            sufS[i] = 0;
            preL[i] = 0;
        }

        sufS[root - 1] = 1;
        preL[0] = 1;

        for (int i = 0; i < k; i++) {
            ll curSum = 0;
            for (int j = root - 1; j >= 0; j--) {
                curSum += sufS[j];
                sufS[j] = 0;
                curSum = curSum % Mod;
                dpS[j][i] = curSum;
            }
            curSum = 0;
            for (int j = 0; j < root; j++) {
                curSum += preL[j];
                curSum = curSum % Mod;
                preL[j] = 0;
                dpL[j][i] = (curSum * countLarge[j]) % Mod;
            }

            for (int j = 0; j < root; j++) {
                ll maxVal = n / (j + 1);
                if (maxVal > root) maxVal = root;
                sufS[maxVal - 1] += dpS[j][i];
                sufS[maxVal - 1] = sufS[maxVal - 1] % Mod;
                preL[j] += dpS[j][i];
                preL[j] = preL[j] % Mod;
            }

            for (int j = 0; j < root; j++) {
                sufS[j] +=  dpL[j][i];
                sufS[j] %= Mod;
            }
        }

        ll ans = 0;
        for (int i = 0; i < root; i++) {
            ans += dpL[i][k - 1] + dpS[i][k - 1];
            ans = ans % Mod;
        }
        cout << ans << endl;
    }

    //double end_time = clock();
    //printf( "Time = %lf ms\n", ( (end_time - start_time) / CLOCKS_PER_SEC)*1000);
    return 0;
}

