const int MOD = 1e9+7;
inline int add(int a, int b){ return (a+b)%MOD; }
inline int sub(int a, int b){ return ((a-b)%MOD + MOD)%MOD; }
inline int mul(int a, int b){ return ((ll)a*b)%MOD; }

void solve(){
    int n, k;
    cin >> n >> k;
    vector<pair<int, int>> range;
    for(int i = 1; i*i <= n; ++i){
        range.push_back({n/i, 1});
    }
    int last = range.back().F;
    for(int i = last-1; i > 0; --i){
        range.push_back({i, n/i-n/(i+1)});
    }

    int l = range.size();

    v2<int> dp = fill(k, l, 0);
    v2<int> pref = fill(k, l, 0);
    for(int j = 0; j < l; ++j){
        dp[0][j] = range[j].S;
    }
    pref[0][0] = dp[0][0];
    for(int j = 1; j < l; ++j){
        pref[0][j] = add(pref[0][j-1], dp[0][j]);
    }

    for(int i = 1; i < k; ++i){
        for(int j = 0; j < l; ++j){
            dp[i][j] = mul(range[j].S, pref[i-1][l-1-j]);
        }

        pref[i][0] = dp[i][0];
        for(int j = 1; j < l; ++j){
            pref[i][j] = add(pref[i][j-1], dp[i][j]);
        }
    }

    cout << pref[k-1][l-1] << "\n";
}

