// まずはdp[N][K]というので考えてみる
// 例えばA=dp[3][50], B=dp[2][50]を比べると、(残り50個、今の制約が3と2)
// A = dp[1][49] + dp[2][49] + .. dp[N/3][49]
// B = dp[1][49] + dp[2][49] + .. dp[N/3][49] + dp[N/3+1][49] + .. + dp[N/2][49]
// よって
// B = A + dp[N/3+1][49] + .. dp[N/2][49]
// ところで、 dp[N/3+1][49] = dp[N/2][49]である
// なぜなら隣りにおけるのは2までなので
// よって
// B = A + (N/2 - N/3) * dp[N/2][49]である

// また、上のように大きいnが参照できない場合
// dp[N][K] = dp[1][K-1]である

// 実際にdp[N]は状態数が多すぎるので、
// x^2 > Nならばdp[x] = dp[1][N/x]というふうに割り当てる(x^2<=Nならばdp[0][x])
// 以下略

ll N;
ll n;
#define ROOT 35000
ll dp[2][ROOT][101];
void setv(int i, int j, int k, ll v, char mark=' ') {
    dp[i][j][k] = v;
}
ll solve(ll K) {
    memset(dp, 0, sizeof(dp));
    for (int i = 0; i < 2; i++) 
        for (int j = 0; j < ROOT; j++)
            dp[i][j][0] = 1;
    for (int k = 1; k <= K; k++) {
        // 大きい数から
        // i = 1
        // -- j == N (1,1)
        setv(1, 1, k, dp[0][1][k-1]);
        // -- j = N-1 .. N/n
        for (ll j = 2; j <= n; j++) {
            ll a = N/(j-1);
            ll b = N/j;
            setv(1, j, k, (dp[1][j-1][k] + ((N/b - N/a) * dp[0][j][k-1]) % MOD) % MOD, '-');
        }
        // i = 0
        for (ll j = n; j >= 1; j--) {
            if ((j + 1) * (j + 1) > N) {
                setv(0, j, k, (dp[1][N/(j+1)][k] + ((N/j - N/(j+1)) * dp[1][j][k-1]) % MOD) % MOD, '*');
            }
            else {
                setv(0, j, k, (dp[0][j+1][k] + ((N/j - N/(j+1)) * dp[1][j][k-1]) % MOD) % MOD, 'x');
            }
        }
    }
    return dp[0][1][K];
}

int main(){
    scanf("%lld",&N);
    n = (ll)sqrt(N);
    long long K;
    scanf("%lld",&K);
    ll res = solve(K);
    cout << res << endl;
    return 0;
}

