    set<long long> s;
    for(int i = 1; i * i <= N; i++){
        s.insert(i);
        s.insert(N / i);
    }

    int S = s.size();

    vector<int> v;
    vector<pair<long long, long long>> interval;
    interval.reserve(S);
    for(int i : s) interval.push_back(make_pair(0LL, i));
    interval[0].first = 0;
    for(int i = 1; i < S; i++) interval[i].first = interval[i - 1].second;

    // for(int i = 0; i < S; i++) cout << interval[i].first << " " << interval[i].second << endl;

    vector<long long> dp(s.size());

    for(int i = 0; i < S; i++) dp[i] = interval[i].second - interval[i].first;

    for(int k = 2; k <= K; k++){
        vector<long long> ndp(s.size(), 0LL);
        for(int i = 0; i < S; i++){
            for(int j = 0; j < S && interval[i].second * interval[j].second <= N; j++){
                ndp[j] += dp[i];
                ndp[j] %= MOD;
            }
        }
        dp = ndp;
    }

    long long ans = 0;
    for(int i = 0; i < S; i++){
        ans += dp[i] * (interval[i].second - interval[i].first);
        ans %= MOD;
    }
    cout << ans << endl;

    return 0;
}

