	for (int i = 1; i <= n; i++) {
		ll sm = 0, cur = 0, curs = 0;
		for (int j = 1; j <= sq; j++) {
			cur += pref[i][j];
			cur = (cur + MOD) % MOD;
			dp[i][j] += cur;
			dp[i][j] %= MOD;

			curs += slf[i][j];
			ll dl = (k / j);
			curs = (curs + MOD) % MOD;
			dp[i][j] += (dl - sq) * curs;
			dp[i][j] %= MOD;

			sm += dp[i - 1][j];
			sm %= MOD;
		}
		for (int j = 1; j <= sq; j++) {
			dp[i][j] += sm;
			dp[i][j] %= MOD;
		}

		for (int j = 1; j <= sq; j++) {
			ll dl = (k / j);
			dl -= sq;
			pref[i + 1][1] += dp[i - 1][j] * dl;
			pref[i + 1][j + 1] -= dp[i - 1][j] * dl;

