			slf[i + 1][sq + 1] -= dp[i - 1][j];
		}

		if (i == n) {
			for (int j = 1; j <= sq; j++) {
				ll dl = (k / j);
				dl -= sq;
				ans += dp[i][j] + (dp[i - 1][j] * dl);
