void func(long long N, long long K){

    vector<lli> v;
    vector<mint> dp;

    for(lli i=1;i*i<=N;i++){
        v.push_back(N/i);
    }
    lli now = v[v.size()-1];
    for(lli i=now-1;i>0;i--){
        v.push_back(i);
    }

    reverse(v.begin(),v.end());

    lli size = v.size();
    dp.resize(size);
    dp[0]=1;
    REP(i,1,size){
        dp[i] = v[i]-v[i-1];
    }

    REP(i,1,K){
        vector<mint> sum(size+1);
        sum[0]=0;
        REP(i,0,size)sum[i+1] = sum[i]+dp[i];

        REP(i,0,size){
