            else eleNum = v[i]-v[i-1];
            lli index = (lli)(lower_bound(v.begin(),v.end(),N/v[i])-v.begin());

            dp[i] = sum[index+1]*eleNum;
        }
    }

    mint sum = 0;
    REP(i,0,size)sum+=dp[i];
    cout<<sum<<endl;

}

