using namespace std;

int main() {

	SINT64 N;	cin >> N;
	SINT64 M;	cin >> M;

	vector<SINT64> data;

	rep(i,2,N+1) {
		if ((N/i) >= i) {
			data.emplace_back((N/(i-1))-(N/i));
		} else {
			break;
		}
	}

	SINT64 buf = 0;
	rep(i,0,data.size()) {
		buf += data[i];
	}
	buf = N-buf;

	while(1) {
		if (buf == 0) break;
		buf--;
		data.emplace_back(1);
	}
	reverse(data.begin(),data.end());

	vector<vector<SINT64>> DP(data.size());

	rep(i,0,data.size()) {
		DP[i].emplace_back(data[i]);
	}
	rep(i,1,M) {
		SINT64 sum = 0;
		rep(j,0,data.size()) {
			sum += DP[j][i-1];
			sum %= MOD;
			DP[data.size()-1-j].emplace_back((sum*data[data.size()-1-j])%MOD);
		}
	}
