template<typename D = long long, int useAssert = 1>
class BIT{
public:
  int n;
  vector<D> bit;
  BIT():n(-1){};
  BIT(int n_){
    n=1;
    while(n < n_+2) n *= 2;
    bit.resize(n+1, 0);
  }

  //[0, i]までの総和を得る
  D sum(int i){
    if(useAssert) assert( i >= 0 && i <= n );
    i++;
    D s=0;
    while(i>0){
      s = (s + bit[i]);
      i -= i & -i;
    }
    return s;
  }

  //i番目の要素にx加算(0 オリジン)
  void add(int i, D x){
    if(useAssert) assert( i >= 0 && i <= n );
    i+=2;

    while(i <= n){
      bit[i] = (bit[i] + x);
      i += i & -i;
    }
  }

  D sum(int l, int r){ //[l, r) 0オリジン
    if(useAssert){
      assert(l <= r);
      assert( 0 <= l && l <= n);
      assert( 0 <= r && r <= n);
    }
    return sum(r) - sum(l);
  }
};


