    while(L + 1 < R){
      int M = (L + R) / 2;
      N / (x + M) == N / x? (L = M):(R = M);
    }
    return x + L;
  };

  vector<P> LR;
  {
    int l = 1;
    while(l <= N){
      int r = getR(l);
      LR.emplace_back(l, r);
      l = r + 1;
    }
  }

  auto getT=[&](int t){
    int L = 0, R = (int)LR.size();
    while(L + 1 < R){
      int M = (L + R) / 2;
      int l, r; tie(l, r) = LR[M];
      t >= l? (L = M): (R = M);
    }
    return L;
  };


  BIT<mint, 1> dp(LR.size() + 10);
  for(int i=0;i<(int)LR.size();i++){
    int l, r; tie(l, r) = LR[i];
    dp.add(i, r - l + 1);
  }


