// 累積和
template <class T>
struct RuisekiwaT : vector<T>
{
	using vector<T>::at;
	RuisekiwaT(const vector<T>& A) : vector<T>(A.size() + 1)
	{
		REP(i, A.size()) { at(i + 1) = at(i) + A[i]; }
	}

	// [l..r) の累積和
	T Range(int l, int r) { return at(r) - at(l); }
}; template <class T> RuisekiwaT<T> Ruisekiwa(const vector<T>& A) { return RuisekiwaT<T>(A); }


void solve()
{
	READ(llong, N, K);

	if (N==1)
	{
		WRITE(1);
		return;
	}

	vector<llong> t;
	{
		vector<llong> tbl;

		llong i = 1;
		while (i <= N)
		{
			tbl.push_back(i - 1);
			i = (N / (N / i) + 1);
		}
		tbl.push_back(N);

		REP(i, tbl.size() - 1)
		{
			t.push_back(tbl[i + 1] - tbl[i]);
		}
	}
	int M = t.size();

	auto ans = t;
	REP(i, K)
	{
		vector<llong> next(ans.size());
		auto ru = Ruisekiwa(ans);

		REP(j, M)
		{
			next[j] = t[j] * ru[M - j] % 1000000007;
		}
		swap(ans, next);
	}

	WRITE(ans[0]);
}

