    for(int j = sz-1;j >= 0;--j){
      acc += calc[sz-1-j];
      next[j] = acc * (elem[j+1] - elem[j]);
      next[j] %= mod;
    }
    calc = next;
  }
  ll res = 0LL;
  for(int i = 0;i < sz;++i){
    res += calc[i];
    res %= mod;
  }
  cout << res << endl;
  return 0;
}

