ll dp1[40100][110], dp2[40100][110], dp3[40100][110];

ll f(int n, int k);
ll g(int n, int k);
ll h(int n, int k);

ll g(int n, int k){
    if(n == 0){
        return 0;
    }

    if(dp2[n][k] != -1){
        return dp2[n][k];
    }

    dp2[n][k] = (f(n, k) + g(n - 1, k)) % MOD;
    return dp2[n][k];
}

ll h(int n, int k){
    if(n == 0){
        return 0;
    }

    if(dp3[n][k] != -1){
        return dp3[n][k];
    }

    dp3[n][k] = (f(n, k) * (N / n - sq) % MOD + h(n - 1, k)) % MOD;
    return dp3[n][k];
}

ll f(int n, int k){
    if(k == 0){
        return 1;
    }else if(k == 1){
        return N / n;
    }

    if(dp1[n][k] != -1){
        return dp1[n][k];
    }

    ll res = g(sq, k - 1);

    res = res + g(n, k - 2) * (N / n - sq) % MOD + (h(sq, k - 2) + MOD - h(n, k - 2));

    // for(int i=1;i<=sq;++i){
    //     int l = std::min(N / i, N / n) - sq;

    //     res = res + f(i, k - 2) * l % MOD;
    // }

    res %= MOD;

    return dp1[n][k] = res;
}


int main(){
    std::cin.tie(nullptr);
    std::ios::sync_with_stdio(false);

    std::cin >> N >> K;

    memset(dp1, -1, sizeof(dp1));
    memset(dp2, -1, sizeof(dp2));
    memset(dp3, -1, sizeof(dp3));

    sq = (int)std::sqrt(N);

    ll res = f(1, K);
    std::cout << res << std::endl;
}

