		dp[1][i] = 1;

	repi(i, 1, k)
	{
		rep(j, n2)
		{
			rep(j2, n2 - j)
			{
				dp[i + 1][j2] += dp[i][j] * range[j];
			}
		}
	}

	mint ans = 0;
	rep(i, n2)
		ans += dp[k][i] * range[i];

	cout << ans.n << endl;

	return 0;
}

