void bfs() {
	int cnt = 1, times = 0;
	queue< int > Q;
	Q.push(S);
	vis[S] = 1;	

	while(!Q.empty()) {
		int tmp = Q.front(); Q.pop();
		--cnt;

		foreach(i, v[tmp]) {
			if(vis[*i][0]) break;
			vis[*i][0] = 1;
			foreach(j, v[*i]) {
				if(vis[*j][1]) break;
				vis[*j][1] = 1;
				foreach(k, v[*j]) {
					if(!vis[*k][2]) {
						vis[*k][2] = 1;
						if(*k == T) {
							ans = times + 1;
							return;
						}
						Q.push(*k);
					}
				}
			}
		}

		if(cnt == 0) {
			cnt = Q.size();
			++times;
		}
	}
} 

