int base[2][N], len[N];

void add(int &x, int y) {
  x += y;
  if(x >= MOD) x -= MOD;
}

void upd(int id, int at, int x) {
  for(int i = at; i < int(v.size()); i += i & (-i)) {
    add(base[id][i], x);
  }
}

int sum(int id, int at) {
  int ans = 0;
  for(int i = at; i > 0; i -= i & (-i)) {
    add(ans, base[id][i]);
  }
  return ans;
}

