  }
  for(int i = 0; i + 1 < int(v.size()); i++) {
    len[i] = v[i + 1] - v[i];
  }
  upd(0, 1, 1);
  for(int q = 1; q <= k; q++) {
    for(int i = 1; i < int(v.size()); i++) {
      base[q & 1][i] = 0;
    }
    int cur = 1, whe = int(v.size()) - 1;
    for(int i = 1, j; i <= n; i = j + 1, cur++, whe--) {
      j = n / (n / i);
