struct mint
{
	lint n;
	mint()
	{
		n = 0;
	}
	mint(lint a)
	{
		if (a < 0)
			n = 0 - abs(a);
		else
			n = a % mod;
	}
	mint& operator+=(mint a)
	{
		n += a.n;
		n %= mod;
		return *this;
	}
	mint& operator-=(mint a)
	{
		n += mod;
		n -= a.n;
		n %= mod;
		return *this;
	}
	mint& operator*=(mint a)
	{
		n *= a.n;
		n %= mod;
		return *this;
	}
	mint& operator%=(mint a)
	{
		n %= a.n;
		return *this;
	}
	mint& operator++()
	{
		n++;
		n %= mod;
		return *this;
	}
	mint& operator--()
	{
		n += mod;
		n--;
		n %= mod;
		return *this;
	}
};

mint operator+(mint a, mint b)
{
	a += b;
	return a;
}
mint operator-(mint a, mint b)
{
	a -= b;
	return a;
}
mint operator*(mint a, mint b)
{
	a *= b;
	return a;
}

mint dp[100000] = {};

lint range[100000] = {};

mint s[100000];

int main()
{
	lint n, k;
	cin >> n >> k;

	lint n2 = 0;
	for (lint i = 1; i * i <= n; i++)
	{
		range[n2] = n / i - n / (i + 1);
		n2++;
	}
	if (n2 * (n2 + 1) <= n)
	{
		rep(i, n2)
		{
			range[n2 + i] = range[n2 - 1 - i];
			range[n2 - 1 - i] = 1;
		}
		n2 = n2 * 2;
	}
	else
	{
		rep(i, n2 - 1)
		{
			range[n2 + i] = range[n2 - 2 - i];
			range[n2 - 2 - i] = 1;
		}
		n2 = n2 * 2 - 1;
	}

	rep(i, n2)
		dp[i] = 1;

	repi(i, 1, k)
	{
		rep(j, n2 + 1)
			s[j] = 0;

		rep(j, n2)
		{
			s[j + 1] = s[j] + dp[j] * range[j];
		}
		rep(j, n2)
			dp[j] = s[n2 - j] - s[0];
	}

	mint ans = 0;
	rep(i, n2)
		ans += dp[i] * range[i];

	cout << ans.n << endl;

	return 0;
}

