int main(){
  ll n = in();
  ll k = in();
  ll sqrtn = sqrt(n) + 10;
  function<mint(ll,ll)> func =
    [&](ll place,ll height){
      if(place==k)return mint(1);
      if(height*height<=n){
        static vvector<mint> dp(k,vector<mint>(sqrtn));
        static vvector<bool> used(k,vector<bool>(sqrtn));
        if(used[place][height])return dp[place][height];
        mint &it = dp[place][height];
        it = mint(0);
        if(height>1){
          it += func(place,height-1);
        }
        it += func(place+1,n/height);
        used[place][height] = true;
        return it;
      }else{
        static vvector<mint> dp(k,vector<mint>(sqrtn));
        static vvector<bool> used(k,vector<bool>(sqrtn));
        ll inv = n / height;
        if(used[place][inv])return dp[place][inv];
        mint &it = dp[place][inv];
        it = mint(0);

        it += func(place,n/(inv+1));
        it += func(place+1,inv) * (height-n/(inv+1));

        used[place][inv] = true;
        return it;
      }
    };

  per(i,k){
    func(i,n);
  }

  cout << func(0,n) << endl;
  return 0;
}

