using namespace std;
using ll = long long;
const ll mof = 1e9+7;
int solve(int n,int k)
{
    vector<int> facts;
    int sqrtn = static_cast<int>(sqrt(n));
    for(int i=1;i<=sqrtn;++i)
    {
        facts.push_back(i);
        if(n/i != i)
            facts.push_back(n/i);
    }
    facts.push_back(0);
    sort(facts.begin(),facts.end());
    vector<ll> dp0,dp1;
    dp1.resize(facts.size());
    for(int i=1;i<facts.size();++i)
        dp1[i] = (dp1[i-1] + facts[i] - facts[i-1]) % mof;
    for(int i=2;i<=k;++i)
    {
        dp0 = dp1;
        dp1.resize(dp0.size(),0);
        for(int j=1;j<dp0.size();++j)
        {
            dp1[j] = dp0[facts.size() - j] * (facts[j] - facts[j-1]) % mof;
            dp1[j] += dp1[j-1];
            dp1[j] %= mof;
        }
    }
    return dp1.back();
}
int main()
{
    int n,k;
    cin>>n>>k;
    cout<<solve(n,k)<<endl;
}

