struct mint {
	int64_t value;
	mint():value(0){}
	mint(int64_t value_) : value(value_%MOD) {}
	inline mint& operator += (const mint& rhs) {
		value += rhs.value;
		if (value >= MOD) { value -= MOD; }
		return *this;
	}
	inline mint& operator -= (const mint& rhs) {
		value -= rhs.value;
		if (value < 0) {
			value += MOD;
		}
		return *this;
	}
	inline mint& operator *= (const mint& rhs) {
		value *= rhs.value;
		value %= MOD;
		return *this;
	}
	inline mint& operator %= (const mint& rhs) {
		return *this;
	}
};

inline mint operator + (const mint& lhs, const mint& rhs) { mint res = lhs; res += rhs; return res; }
inline mint operator - (const mint& lhs, const mint& rhs) { mint res = lhs;	res -= rhs;	return res; }
inline mint operator * (const mint& lhs, const mint& rhs) { mint res = lhs;	res *= rhs;	return res; }
inline mint operator % (const mint& lhs, const uint64_t& rhs) { return lhs; }

ostream & operator << (ostream & out, mint n) { return out << n.value; }

// x^n % mod
// O(log n)
mint mod_pow(mint x, uint64_t n) {
	mint res = 1;
	while (n > 0) {
		if (n & 1) res = res * x;
		x = x*x;
		n >>= 1;
	}
	return res;
}


void solve() {
	int N, K; cin >> N >> K;
	int window = sqrt(N);
	vector<int> nums;
	map<int, int> enc;

	RFOR(i, 1, window + 1) {
		int tar = N / i;
		nums.push_back(i);
		if (i != tar) {
			nums.push_back(tar);
		}
	}
	sort(ALL(nums));

	REP(i,nums.size()){
		enc[nums[i]] = i;
	}

	vector<vector<mint> > dp(K, vector<mint>(nums.size()));
	REP(i, dp[0].size()) {
		dp[0][i] = nums[i];
	}

	FOR(i, 1, dp.size()) {
		REP(j, dp[i].size()) {
			int cnt = (j >= 1 ? nums[j] - nums[j - 1] : 1);
			dp[i][j] = dp[i - 1][dp[i].size()-j-1] * cnt;
		}
		FOR(j, 1, dp[i].size()) {
			dp[i][j] += dp[i][j - 1];
		}
	}

	cout << dp.back().back() << endl;
}

