int main() {
    ll n,k;
    cin >> n >> k;
    ll MOD = 1000000007;

    ll sum[150000] = {};
    int count = 0;
    ll dp[150000][k];
    rep(i,150000){
        dp[0][i] = 0;
        dp[1][i] = 0;
    }

    if(n==1){
        cout << '1' << endl;
        return 0;
    }

    // 数数え
    srep(i,1,n){
        if(n/i<i)break;
        sum[count] = i;
        count++;
    }

    drep(i,count){
        if(n/sum[i] == sum[i])continue;
        sum[count] = n/sum[i];
        count++;
    }

    rep(i,count){
        if(i==0){
            dp[i][0] = sum[i];
        }else{
            dp[i][0] = sum[i] - sum[i-1];
        }
    }

    srep(j,1,k){
        ll tmp = 0;
        drep(i,count){
            if(i==count-1){
                tmp += dp[count-1-i][j-1];
                dp[i][j] = dp[i][0]*tmp % MOD;
            }else{
                tmp += dp[count-1-i][j-1];
                tmp %= MOD;
                dp[i][j] = dp[i][0]*tmp % MOD;
            }
        }
    }

    ll ans = 0;
    rep(i,count){
        ans += dp[i][k-1];
        ans %= MOD;
    }
    cout << ans << endl;
    return 0;
}

