class Solver2 {
 public:
  LL n, k;
  Solver2(LL n, LL k) : n(n), k(k){};

  void solve() {
    vector<LL> x;
    for (int i = 0; i * i <= n; ++i) {
      x.push_back(i);
    }
    for (int i = x.size() - 1; x[i] > 0; --i) {
      LL tmp = n / x[i];
      if (tmp > x.back()) x.push_back(tmp);
    }
    int l = x.size();
    vector<Modint<>> dp(l, Modint<>(1));
    for (int i = 0; i < k; ++i) {
      vector<Modint<>> dp2(l);
      for (int j = 1; j < l; ++j) {
        int p = distance(x.begin(), lower_bound(x.begin(), x.end(), n / x[j]));
        dp2[j] = dp[p] * (x[j] - x[j - 1]);
      }
      for (int j = 1; j < l; ++j) {
        dp2[j] += dp2[j - 1];
      }
      swap(dp, dp2);
    }
    cout << dp[l - 1] << endl;
  }
};
