const int N = 2e5+5 ,M = 1e2+5 ,mod = 1e9+7 ;

int n ,k ,to[N] ;
vector<pair<int,int>> val_cnt ;
void init(){
    int i = 1 ;
    while(i<=n){
        int st = i ,en = n ;
        while(st<en){
            int mid = (st+en+1)/2 ;
            if(n/mid == n/i) st = mid ;
            else en = mid-1 ;
        }
        val_cnt.push_back({st,st-i+1});
        i = st+1 ;
    }
    sort(val_cnt.begin(),val_cnt.end());
    for(i=0;i<val_cnt.size();++i){
        int st = 0 ,en = val_cnt.size()-1 ;
        while(st<en){
            int mid = (st+en+1)/2 ;
            if(1ll * val_cnt[i].first * val_cnt[mid].first <= n) st = mid ;
            else en = mid-1 ;
        }
        to[i] = st ;
    }
}
int mem[M][N] ;
int solve(int i,int cur){
    if(cur<0) return 0;
    int&ret = mem[i][cur] ;
    if(~ret) return ret ;
    ret = solve(i,cur-1) ;
    if(i+1==k) return ret = (ret + val_cnt[cur].second)%mod ;
    return ret = (ret + 1ll * val_cnt[cur].second * solve(i+1,to[cur])%mod)%mod ;
}
