        layer.emplace_back(i, 0);
        layer.emplace_back(N / i, 0);
    }
    sort(layer.begin(), layer.end());
    layer.erase(unique(layer.begin(), layer.end()), layer.end());
    rep(i, layer.size() - 1) {
        int l = N / layer[i + 1].first;
        int r = N / layer[i].first;
        layer[i].second = r - l;
    }
    layer.back().second = 1;
    int M = layer.size();
    map<int, int> ma;
    rep(i, M) ma[layer[i].first] = i;
    vector<vector<int64>> dp(K + 1, vector<int64>(M));
