        }
        rep(j, M) {
            int nj = ma[N / layer[j].first];
            dp[i + 1][j] = dp[i][nj] * layer[j].second;
        }
    }
    int ans = 0;
    rep(j, M) add(ans, dp[K][j]);
    cout << ans << '\n';
}

