using namespace std;
typedef unsigned long long ll;
const int maxn = 40005;
const int mod = 1000000007;

int n,m,sqrtn;

ll f1[maxn],f2[maxn];

void upd(ll&ret,ll val){
  ret+=val;
  if(ret>=mod)ret-=mod;
}

struct P{
  int l,r;
  ll sum, per, add;
};
struct T{
  P st[maxn * 4];
  void down(int id){
    upd(st[id<<1].sum, st[id<<1].per*st[id].add%mod);
    upd(st[id<<1|1].sum, st[id<<1|1].per*st[id].add%mod);
    st[id<<1].add+=st[id].add;
    st[id<<1|1].add+=st[id].add;
    st[id].add=0;
  }
  void up(int id){
    st[id].sum = st[id<<1].sum;
    upd(st[id].sum, st[id<<1|1].sum);
    st[id].per = st[id<<1].per;
    upd(st[id].per, st[id<<1|1].per);
  }
  void build(int id, int l,int r, int flag){
    st[id].l = l,st[id].r = r;
    st[id].sum = st[id].add = 0;
    if(l==r){
      if(!flag){
        if(l<=sqrtn)
        st[id].per=1;
        else st[id].per=0;
      }
      else{
        int tt = n/l;
        if(tt>sqrtn){
          st[id].per=tt-max(n/(l+1), sqrtn);
        } else st[id].per=0;
      }
      return;
    }
    int m=(l+r)>>1;
    build(id<<1,l,m,flag);
    build(id<<1|1,m+1,r,flag);
    up(id);
  }
  void add(int id, int l,int r, ll val){
    if(l==st[id].l&&r==st[id].r){
      upd(st[id].add, val);
      upd(st[id].sum, st[id].per*val%mod);
      return;
    }
    down(id);
    int m = (st[id].l+st[id].r)>>1;
    if(r<=m)add(id<<1,l,r,val);
    else if(l>m)add(id<<1|1,l,r,val);
    else {
      add(id<<1,l,m,val);
      add(id<<1|1,m+1,r,val);
    }
    up(id);
  }
  ll query(int id, int pos){
    if(st[id].l==st[id].r){
      return st[id].sum;
    }
    down(id);
    int m = (st[id].l+st[id].r)>>1;
    if(pos<=m)return query(id<<1,pos);
    else return query(id<<1|1,pos);
  }
}t[2];

void solve() {
  t[0].build(1, 1, sqrtn, 0);
  t[1].build(1, 1, sqrtn, 1);
  for(int i=1;i<=sqrtn;i++){
    t[0].add(1, 1,sqrtn,f1[i]);
    t[1].add(1, i,sqrtn, f1[i]);
  }
  for(int i=1;i<=sqrtn;i++){
    t[0].add(1,1,i,f2[i]);
  }
  for(int i=1;i<=sqrtn;i++)f1[i]=t[0].query(1, i);
  for(int i=1;i<=sqrtn;i++)f2[i]=t[1].query(1, i);
}

