    for (int i = 1; i <= b; ++i)
        sum[0][i][0] = 1;
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= b; ++j) {
            dp[i][j][0] = sum[i - 1][b][0] + sum[i - 1][b][1] - sum[i - 1][j - 1][1];
            if (dp[i][j][0] < 0)
                dp[i][j][0] += MOD;
            if (dp[i][j][0] >= MOD)
                dp[i][j][0] -= MOD;
            dp[i][j][1] = 1LL * x[j] * sum[i - 1][j][0] % MOD;
        }
        for (int j = 1; j <= b; ++j) {
            for (int t = 0; t < 2; ++t) {
                sum[i][j][t] = sum[i][j - 1][t] + dp[i][j][t];
                if (sum[i][j][t] >= MOD)
                    sum[i][j][t] -= MOD;
            }
        }
    }
    cout << (sum[n][b][0] + sum[n][b][1]) % MOD;
    return 0;
}

