int main() {
    int_m::m = MOD;
    i64 N, K;
    cin >> N >> K;
    i64 M = floor(sqrt(N));
    l[0] = l[1] = Sl = vector<int_m>(M + 1, 0);
    h[0] = h[1] = Sh = vector<int_m>(M + 1, 0);
    l[0][1] = 1;
    for(int k = 0; k < K; k++) {
        for(int i = 1; i <= M; i++) {
            Sl[i] = l[0][i] + (i ? Sl[i - 1] : 0);
        }
        for (int i = M; i > 0; i--) {
            Sh[i] = h[0][i] + (i < M ? Sh[i + 1] : 0);
        }
        for(int i = 1; i <= M; i++) {
            l[1][i] = Sl[M] + Sh[i];
        }
        for(int i = 1; i <= M; i++) {
            if(N / i <= M) continue;
            h[1][i] = Sl[i] * int_m((N / i) - max((N / (i + 1)) + 1, M) + 1);
        }
        swap(l[0], l[1]);
        swap(h[0], h[1]);
    }
    int_m ans = 0;
    for(int i = 0; i <= M; i++) ans += l[0][i];
    for(int i = 0; i <= M; i++) ans += h[0][i];
