		int L = N / S[i + 1].first;
		int R = N / S[i].first;
		S[i].second = R - L;
	}
	S.back().second = 1;
	int M = S.size();
	map<int, int>mp;
	REP(i, M)mp[S[i].first] = i;
	vector<VI> dp(K + 1, VI(M));
	dp[0][mp[N]] = 1;
	REP(i, K) {
		for (int j = M - 2; j >= 0; j--) {
			dp[i][j] += dp[i][j + 1];
			dp[i][j] %= mod;
		}
		REP(j, M) {
			int nj = mp[N / S[j].first];
			dp[i + 1][j] += dp[i][nj]*S[j].second;
			dp[i + 1][j] %= mod;
		}
	}



	int ans = 0;
	REP(i, M) {
		ans += dp[K][i];
		ans %= mod;
	}

	cout << ans << endl;


	return 0;
}

