    cin>>N>>K;
    unordered_map<int,int> mp;
    int l=1,r=2,count=0;
    mp[0]=1;
    while(r<=N){
        count++;
        l=r;
        r=N/(N/l)+1;
        mp[count]=r-l;
    }
    long long dp[120][1000000];
    for(int i=0;i<K;i++){
        long long sum=0;
        for(int j=count;j>=0;j--){
            if(i==0){
                dp[0][j]=mp[j];
                continue;
            }
            long long a=mp[j];
            sum+=dp[i-1][count-j];
            sum%=MOD;
            dp[i][j]=sum*a;
            dp[i][j]%=MOD;
        }
    }
    long long answer=0;
    for(int i=0;i<=count;i++){
        answer+=dp[K-1][i];
        answer%=MOD;
    }
    cout<<answer<<endl;
}

