    if(i*(i+1)<=n)a.push_back((n/i)-(n/(i+1)));
  }

  std::sort(all(a));

  ll size=a.size();

  std::vector<ll> dp(size,0);
  std::vector<ll> sum(size,0);

  rep(i,0,size)dp[i]=a[i];
  sum[0]=dp[0];
  rep(i,1,size)sum[i]=(sum[i-1]+dp[i])%MOD;

  rep(i,1,k){
    rep(j,0,size){
      dp[j]=(a[j]*sum[size-1-j])%MOD;
    }

    sum[0]=dp[0];
    rep(j,1,size)sum[j]=(sum[j-1]+dp[j])%MOD;
  }

  std::cout<<sum[size-1];

  return 0;
}

