        int n = max_n;
        vector<ll> fact(n + 1);
        fact[0] = 1;
        for (int i = 1; i <= n; i++) {
            fact[i] = (fact[i - 1] * i) % MOD;
        }
        this->fact = fact;
    }

    template<typename T>
    //templateをつかってみｔか
    ll pow(T x, int y) {
        if (y == 0) return 1;
        if (y == 1) return x;
        if (y == 2) return (x * x) % MOD;
//        if (y % 2 == 1) return pow(x, y / 2) * pow(x, y / 2) % MOD;
        if (y % 2 == 1) return pow(pow(x, y / 2), 2) * x % MOD;
//        return pow(x, y / 2) * pow(x, y / 2) % MOD;
        return pow(pow(x, y / 2), 2) % MOD;
    }

    ll nCk(int n, int k) {
//        return (fact[n] * pow(fact[n-k],MOD-2) * pow(fact[k],MOD-2)) % MOD;
        return (((fact[n] * pow(fact[n - k], MOD - 2)) % MOD) * pow(fact[k], MOD - 2)) % MOD;
    }

    /**
     * x ^ -1を求める
     */
    template<typename T>
    ll inv(T x) {
        return pow(x, MOD - 2);
    }
};

class Solve {
public:
    void input() {

    }

    void solve() {
        input();
        ll N, K;
        cin >> N >> K;
        ll mid = (ll) round(sqrt(1.0 * N)) - 1;
        ll dim = N / mid;
        Combination cmb(3);

        vector<ll> vals;
        for (int i = 1; i <= mid; ++i) {
            vals.push_back(N / i);
        }
        vector<ll> vols;
        vector<ll> nums;
        for (int i = 1; i <= dim; ++i) {
            vols.push_back(N / i);
            nums.push_back(i);
        }
        for (int i = 0; i + 1 < vols.size(); ++i) {
            vols[i] -= vols[i + 1];
        }

        for (int i = 0; i < vals.size(); ++i) {
            vals[i] = cmb.pow(vals[i], K - 1);
        }
        for (int i = 0; i < vols.size(); ++i) {
            nums[i] = cmb.pow(nums[i], K - 1);
        }
        ll ans = 0;
        for (int i = 0; i < vals.size(); ++i) {
            ans += vals[i];
            ans %= MOD;
        }
        for (int i = 0; i + 1 < vols.size(); ++i) {
            ans += (vols[i] * nums[i]) % MOD;
            ans %= MOD;
        }
        cout << ans << endl;

    }
};


