    lint i = 1;
    while (i <= N / i)
    {
        vp.emplace_back(i, N / i);
        i++;
    }
    int n = vp.size();
    REP(i, n)
    {
        if (vp[i].first == vp[i].second) continue;
        vp.emplace_back(vp[i].second, vp[i].first);
    }
