using namespace std;

class Solution {
public:
    int solve(int n, int K) {
        const long long MOD = 1000000007;

        int m = 0;
        while (m * 1LL * m <= n) {
            ++m;
        }
        --m;

        vector<int> P;
        for (int i = 1; i <= m; ++i) {
            P.push_back(i);
            P.push_back(n / i);
        }
        P.push_back(0);
        sort(P.begin(), P.end());
        P.resize(unique(P.begin(), P.end()) - P.begin());

        // for (auto x : P) {
        //     cout << x << " ";
        // }
        // cout << endl;
        // cout << "m " << m << endl;

        int N = P.size();

        vector<long long> dp(N, 0);
        dp[1] = 1;
        vector<long long> ndp(dp);

        for (int _ = 0; _ < K; ++_) {
            fill(ndp.begin(), ndp.end(), 0);

            long long sum = 0;
            for (int i = 0; i <= m; ++i) {
                (sum += dp[i]) %= MOD;
            }

            for (int i = m, j = m + 1; i > 0; --i) {
                if (j < N && P[i] * 1LL * P[j] <= n) {
                    (sum += dp[j]) %= MOD;
                    ++j;
                }
                ndp[i] = sum;
            }

            sum = 0;
            for (int i = 0; i <= m; ++i) {
                (sum += dp[i]) %= MOD;
            }

            for (int i = m + 1, j = m; i < N; ++i) {
                long long cnt = P[i] - P[i - 1];
                if (j >= 0 && P[j] * 1LL * P[i] > n) {
                    (sum += MOD - dp[j]) %= MOD;
                    --j;
                }
                // cout << P[i] << " " << cnt << " " << sum << endl;
                (ndp[i] = sum * cnt % MOD) %= MOD;
            }

            swap(dp, ndp);

            // for (int j = 0; j < N; ++j) {
            //     cout << j << ":" << dp[j] << endl;
            // }
        }

        long long res = 0;
        for (int i = 0; i < N; ++i) {
            (res += dp[i]) %= MOD;
        }

        return res;
    }

private:


};

