        y = n/(n/x);
        l[++cnt] = x;
        r[cnt] = y;
    }
    for (int i = 1; i <= cnt; ++i) dp[1][i] = (dp[1][i-1] + r[i]-l[i]+1)%MOD;
    for (int i = 2; i <= k; ++i) {
        for (int j = 1; j <= cnt; ++j) {
            dp[i][j] = (dp[i][j-1] + (dp[i-1][cnt-j+1])*1LL*(r[j]-l[j]+1)%MOD)%MOD;
        }
    }
    printf("%d\n", dp[k][cnt]);
    return 0;
}

