template <int mod>
struct ModInt {
  int x;
  ModInt(): x(0) {}
  ModInt(i64 a) { x = a % mod; if (x < 0) x += mod; }
  ModInt &operator+=(ModInt that) { x = (x + that.x) % mod; return *this; }
  ModInt &operator-=(ModInt that) { x = (x + mod - that.x) % mod; return *this; }
  ModInt &operator*=(ModInt that) { x = (i64) x * that.x % mod; return *this; }
  ModInt &operator/=(ModInt that) { return *this *= that.inverse(); }
  ModInt operator-() { return ModInt(-this->x); }
  friend ostream& operator<<(ostream &os, ModInt m) { return os << m.x; }
  ModInt inverse() {
    int a = x, b = mod, u = 1, v = 0;
    while (b) { int t = a / b; a -= t * b; u -= t * v; swap(a, b); swap(u, v); }
    return ModInt(u);
  }
  #define op(o, p) ModInt operator o(ModInt that) { return ModInt(*this) p that; }
    op(+, +=) op(-, -=) op(*, *=) op(/, /=)
  #undef op
  #define op(o) bool operator o(ModInt that) const { return x o that.x; }
    op(==) op(!=) op(<) op(<=) op(>) op(>=)
  #undef op
};

using mint = ModInt<1000000007>;

void solve() {
  int N, K; cin >> N >> K;

  vi32 t; {
    set<int> se = { 0 };
    for (int i = 1; i * i <= N; i++) {
      se.insert(i), se.insert(N / i);
    }
    each(s, se) t.push_back(s);
  }
  int M = t.size() - 1;

  vector<vector<mint>> dp(2, vector<mint>(M + 1));
  vector<vector<mint>> ac(2, vector<mint>(M + 1));
  reps(j, M) ac[0][j] = 1;

  rep(i, K) {
    int p = (i + 0) % 2;
    int n = (i + 1) % 2;
    reps(j, M) {
      int o = lower_bound(all(t), N / t[j]) - t.begin();
      /*
       * 今回選ぶ整数は、区間 (t[j - 1], t[j]] にある整数.
       * 区間の大きさ R = t[j] - t[j - 1]
       * 区間内の整数を x_1, x_2, ..., x_R とおく.
       * すると N / x_1 = N / x_2 = ... = N / x_R が成り立つ.
       * したがって、Σ_{j=1}^{N/x_R} dp[p][j] 通りの選び方がある.
       */
      dp[n][j] += ac[p][o] * (t[j] - t[j - 1]);

      // dpの累積和を更新する
      ac[n][j] += ac[n][j - 1] + dp[n][j];
    }
    rep(j, M + 1) dp[p][j] = 0;
    rep(j, M + 1) ac[p][j] = 0;
  }
  cout << ac[K & 1][M] << '\n';
}

