        dp0[0][i] = dp1[0][i] = 1;
    }

    for (int i = 1; i <= k; i++) {
        for (int j = 1; j <= sqn; j++) {
            dp0[i][j] = (dp0[i][j-1] + dp1[i-1][j]) % Z;
        }

        int s = dp0[i][sqn], lj = sqn;
        for (int j = sqn; j >= 1; j--) {
            s = (s + 1ll * (n / j - lj) * dp0[i-1][j]) % Z;
            dp1[i][j] = s;
            lj = n / j;
        }
    }

    cout << dp1[k][1] << endl;

    return 0;
}

