int main(void){
    long long n, k; cin >> n >> k;
    vector<long long> v;
    for(long long i = 1; i * i <= n; i++){
        if(i * i == n){
            v.push_back(i);
            break;
        }
       v.push_back(i);
       v.push_back(n / i);
    }
    sort(v.begin(),v.end());

    long long N = v.size();
    long long vv[N];
    long long L = 0;
    for(int i = 0; i < N; i++){
        vv[i] = v[i] - L;
        L = v[i];
    }

    long long dp[k + 1][N];
    long long a[N + 1];
    for (int i = 0; i < k + 1; i++) for (int j = 0; j < N; j++) dp[i][j] = 0;
    for (int i = 1; i <= k; i++) {
        if (i == 1) a[0] = 1;
        else a[0] = 0;
        for (int j = 0; j < N; j++) {
            a[j + 1] = a[j] + dp[i-1][j];
            a[j + 1] %= MOD;
        }
        for(int j = 0; j < N; j++){
            dp[i][j] = a[N - j] * vv[j];
            dp[i][j] %= MOD;
        }
    }
    long long ans = 0;
    for (int i = 0; i < N; i++) {
        ans += dp[k][i];
        ans %= MOD;
    }
    cout << ans << endl;

    return 0;
}

