int main(int argc, char *argv[]) {
  // read inputs
  long N, K;
  scanf("%ld %ld", &N, &K);

  // divide region
  const long num1 = sqrt(N) - 1, num0 = N / (num1 + 1);

  // solve dp
  vector<long> acc0s(num0 + 1, 0), acc1s(num1 + 1, 0);
  vector<vector<long>> dp0ss(K + 1, vector<long>(num0 + 1, 0)),
      dp1ss(K + 1, vector<long>(num1 + 1, 0));
  // initialize (k = 1)
  for (long i = 1; i <= num0; i++) {
    dp0ss[1][i] = 1;
  }
  acc0s[0] = 0;
  for (long i = 1; i <= num0; i++) {
    acc0s[i] = mod(acc0s[i - 1] + dp0ss[1][i], NUM_MOD);
  }
  for (long i = 1; i <= num1; i++) {
    dp1ss[1][i] = mod(N / i - N / (i + 1), NUM_MOD);
  }
  for (long i = 1; i <= num1; i++) {
    acc1s[i] = mod(acc1s[i - 1] + dp1ss[1][i], NUM_MOD);
  }
  // update
  for (long k = 2; k <= K; k++) {
    // update dp0ss
    for (long i = 1; i <= num0; i++) {
      if (i <= num1) {
        dp0ss[k][i] = mod(acc0s[num0] - acc0s[0] + acc1s[num1] - acc1s[i - 1], NUM_MOD);
      } else {
        dp0ss[k][i] = mod(acc0s[N / i] - acc0s[0], NUM_MOD);
      }
    }
    // update dp1ss
    for (long i = 1; i <= num1; i++) {
      dp1ss[k][i] = mod((N / i - N / (i + 1)) * (acc0s[i] - acc0s[0]), NUM_MOD);
    }
    // update acc0s
    acc0s[0] = 0;
    for (long i = 1; i <= num0; i++) {
      acc0s[i] = mod(acc0s[i - 1] + dp0ss[k][i], NUM_MOD);
    }
    // update acc1s
    for (long i = 1; i <= num1; i++) {
      acc1s[i] = mod(acc1s[i - 1] + dp1ss[k][i], NUM_MOD);
    }
  }

