template <typename T>
set<T> factors(T a) {
    set<T> facs;
    for (T i = 1; i * i <= a; ++i) {
        facs.insert(i);
        facs.insert(a / i);
    }
    return facs;
}

int main() {
    ll n, k;
    cin >> n >> k;
    if (n == 1) {
        cout << 1 << "\n";
        return 0;
    }
    auto facs = factors(n);
    int m     = facs.size();
    vi vfac;
    for (auto &f : facs)
        vfac.push_back(f);

    vvl dp(k, vl(m, 0));
    for (int i = 0; i < m; ++i)
        dp[0][i] = vfac[i];

    for (int j = 1; j < k; ++j) {
        for (int i = 0; i < m; ++i) {
            ll num = vfac[i];
            if (i)
                num -= vfac[i - 1];
            int idx  = lower_bound(vfac.begin(), vfac.end(), n / vfac[i]) - vfac.begin();
            dp[j][i] = (dp[j - 1][idx] * num) % MOD;
        }
        for (int i = 1; i < m; ++i) {
            dp[j][i] = (dp[j][i] + dp[j][i - 1]) % MOD;
        }
    }
    cout << dp[k - 1][m - 1] << "\n";
    return 0;
}

