typedef long long ll;

struct mint{
    static const long long MOD = 1000000007;

    long long v;

    mint() : v(0) {}
    mint(long long x){
        x = x % MOD;
        if(x < 0){ x += MOD; }
        v = x;
    }
    mint& operator+=(mint a){
        v += a.v;
        if(v >= MOD){ v -= MOD; }
        return *this;
    }
    mint& operator*=(mint a){
        v *= a.v;
        v %= MOD;
        return *this;
    }
    mint& operator-=(mint a){
        v -= a.v;
        if(v < 0){ v += MOD; }
        return *this;
    }
    mint& operator/=(mint a){
        return (*this) *= a.inv();
    }

    mint operator*(mint a) const{
        return mint(v) *= a;
    }

    mint operator+(mint a) const {
        return mint(v) += a;
    }

    mint operator-(mint a) const {
        return mint(v) -= a;
    }

    mint pow(long long k) const {
        mint res(1),tmp(v);
        while(k){
            if(k&1) res *= tmp;
            tmp *= tmp;
            k >>= 1;
        }
        return res;
    }
    mint inv(){return pow(MOD - 2); }

    static mint comb(long long n, int k){
        mint res(1);
        for(int i = 0; i < k; ++i){
            res *= mint(n - i);
            res /= mint(i + 1);
        }
        return res;
    }

    static mint factorial(long long n){
        mint res(1);
        for(int i = n; i > 1; --i){
            res *= mint(i);
        }
        return res;
    }

    bool operator<(const mint &a) const {
        return v < a.v;
    };
};

int main(){
    ll n, k;
    cin >> n >> k;

    vector<ll> ds;
    for(ll i = 1; i * i <= n; ++i){
        ds.push_back(i);
        ds.push_back(n / i);
    }
    sort(ds.begin(), ds.end());
    ds.erase(unique(ds.begin(), ds.end()), ds.end());
    vector<mint> num;
    for(ll i = 0; i < ds.size() - 1; ++i){
        num.push_back(
            n / ds.at(i) - n / ds.at(i + 1)
        );
    }
    num.push_back(1);
    reverse(num.begin(), num.end());

    vector<vector<mint>> dp(k, vector<mint>(num.size()));
    for(ll i = 0; i < num.size(); ++i){
        dp.at(0).at(i) = num.at(i);
    }
    for(ll i = 1; i < k; ++i){
        vector<mint> cs(num.size(), 0);
        cs.at(0) = dp.at(i - 1).at(0);
        for(ll j = 1; j < num.size(); ++j){
            cs.at(j) = cs.at(j - 1) + dp.at(i - 1).at(j);
        }

        for(ll j = 0; j < num.size(); ++j){
            dp.at(i).at(j) = cs.at(cs.size() - j - 1) * num.at(j);
        }
    }

    mint ans = accumulate(dp.back().begin(), dp.back().end(), mint(0));
    cout << ans.v << endl;
    return 0;
}

