//ここから編集する
class Solve {
public:
    Int N, K;
    vector<vector<Int>> dpf;
    vector<vector<Int>> dpg;

    Int modadd(Int a, Int b) {
        return (a + b) % MOD;
    }

    Int f(Int k, Int x) {
        if (x * x > N) {
            return g(k, N / x);
        }
        if (k == 1) return 1;

        if (dpf[k][x] != -1) return dpf[k][x];

        Int ret = 0;
        Int Lk = N / ((Int) ceil(sqrt(N)) + 1);

//        if ((x + 1) * (x + 1) <= N) {
        if (x != Lk) {
            ret = f(k, x + 1);
            Int add = (N / x - N / (x + 1)) * g(k - 1, x) % MOD;
            ret = modadd(ret, add);
        } else {
            // xがLkのとき
            for (Int i = 1; i * i <= N; ++i) {
                ret = modadd(ret, f(k - 1, i));
            }
            Int add = (N / x - N / (x + 1)) * g(k - 1, x) % MOD;
            ret = modadd(ret, add);
        }
//        for (Int i = 1; i * i <= N; ++i) {
//            ret = modadd(ret, f(k - 1, i));
//        }
//
//        for (Int i = x; i * i < N; ++i) {
//            if ((N / i) * (N / i) <= N) continue;
//            Int kei = (N / i - N / (i + 1));
//            Int tmp = kei * g(k - 1, i) % MOD;
//            ret = modadd(ret, tmp);
//        }

        return dpf[k][x] = ret;
    }

    Int g(Int k, Int x) {
        if (k == 1) return 1;
        if (dpg[k][x] != -1) return dpg[k][x];

        Int ret = 0;
//        Int ret = f(k, N / x);
        if (x == 1) ret = f(k - 1, 1);
        else {
            ret = g(k, x - 1);
            ret = modadd(ret, f(k - 1, x));
        }
//        for (Int i = 1; i <= x; ++i) {
//            ret = modadd(ret, f(k - 1, i));
//        }


        return dpg[k][x] = ret;

    }

    void solve() {
        cin >> N >> K;
        dpf.resize(K + 1, vector<Int>(round(sqrt(N)) + 1, -1));
        dpg.resize(K + 1, vector<Int>(round(sqrt(N)) + 1, -1));

        Int ans = 0;
        for (Int i = 1; i * i <= N; ++i) {
            ans = modadd(ans, f(K, i));
        }
//        for (Int i = 1; (i + 1) * (i + 1) <= N; ++i) {
        for (Int i = 1; i * i < N; ++i) {
            if ((N / i) * (N / i) <= N) continue;
            Int kei = (N / i - N / (i + 1));
            Int tmp = kei * g(K, i) % MOD;
            ans = modadd(ans, tmp);
        }

        cout << ans << endl;

    }
};


int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    cout << fixed << setprecision(10);

    Solve().solve();


    return 0;
}

