int main()
{
    cin.tie(0);
    ios::sync_with_stdio(false);
    ll n, K;
    cin >> n >> K;
    ll B = floor(sqrt(n));
    dp[0][1][0] = 1;
    // dp[i][j][0]: 次 n / j 以下はセーフ (前 B 以下)
    // dp[i][j][1]: 次 j 以下はセーフ (前 B + 1 以上)
    rep(i,K){
        mod sm = 0;
        srep(j,1,B+1){
            dp[i+1][1][0] += dp[i][j][0];
            dp[i+1][B+1][0] -= dp[i][j][0];
            dp[i+1][1][0] += dp[i][j][1];
            dp[i+1][j+1][0] -= dp[i][j][1];
            sm += dp[i][j][0];
        }
        dp[i+1][B][1] += max(n / B - B, 0LL) * sm;
        for(int j = B - 1; j >= 1; --j){
            sm -= dp[i][j + 1][0];
            dp[i+1][j][1] += sm * max((n / j - n / (j + 1)), 0LL);
        }
        srep(j,1,B+2){
            dp[i+1][j+1][0] += dp[i+1][j][0];
        }
    }
    mod ans = 0;
    rep(i,B+1){
        ans += dp[K][i][0];
    }
    rep(i,B+1){
        ans += dp[K][i][1];
    }
    cout << ans << "\n";
    return 0;
}

