    vp rho(int v) {        assert(v);        if (v == 1)return vp();        vi ret;        if (!sz(primes)) setprime();        int lim = 300;                      /*64bit*/        if (v < 4294967296)lim = 80;      /*32bit*/        else if (v < 281474976710656LL)lim = 120; /*48bit*/        for (int i = 0; i < lim; i += 5) {            /*v<=1の判定回数を減らせる分高速化できる事を期待している*/            while (v % primes[i] == 0) ret.push_back(primes[i]), v /= primes[i];            while (v % primes[i + 1] == 0) ret.push_back(primes[i + 1]), v /= primes[i + 1];            while (v % primes[i + 2] == 0) ret.push_back(primes[i + 2]), v /= primes[i + 2];            while (v % primes[i + 3] == 0) ret.push_back(primes[i + 3]), v /= primes[i + 3];            while (v % primes[i + 4] == 0) ret.push_back(primes[i + 4]), v /= primes[i + 4];            if (v <= 1) {                sort(ret);/*試し割りだけで終わった時*/                return run_length(ret);            }        }        int lower_prime_bound = primes[lim - 1] * primes[lim - 1];        /*試し割りするか*/        mt19937 mr;        mr.seed(clock());        int c;        auto fac = [&](int v, const int loop = 10) {/*        if (v == 4)return 2ll; //試し割りで消えた*/            c = mr() % v;            int x = mr() % v;            int y = x;            int d = 1;            int lim = sqrt(v) + 2;            /*brentによる改良 差分を一操作で求められる*/            for (int i = 1, mul = 1, next_2pow = 2; d == 1 && i <= lim; i++) {                if (i == next_2pow) {                    y = x;                    next_2pow <<= 1;                }                x = ((u128) x * x + c) % v;                mul = ((u128) mul * abs(x - y)) % v;/*ユークリッドの互除法と同じ原理で因数は保たれる*/                if (i % loop == 0) {/*10とかなんとか iによっては死ぬ*/                    d = gcd(mul, v);                    mul = 1;                }            }            if (d == v) return -1ll;            return d;        };        queue<int> q;        q.push(v);        while (!q.empty()) {            int v = q.front();            q.pop();            if (prime(v)) {                ret.push_back(v);                continue;            }            int d = -1;            /*基本loop回数10でやり、駄目なら1で*/            for (int i = 0; d == -1 && i < 5; i++)d = fac(v, 10);            if (d == -1)while (d == -1)d = fac(v, 1);            int d2 = v / d;            rep(_, 2) {                if (d <= lower_prime_bound)ret.push_back(d);                else q.push(d);                d = d2;            }        }        sort(ret);        return run_length(ret);    }
    //商がqになるような[l, r)を持つ
    struct dra { ll q, l, r,len; dra(ll q_,ll l_,ll r_):q(q_),l(l_),r(r_),len(r_-l_){}};
    vector<dra> drange(ll n, ll l = 1, ll r = -1) {        if (r == -1)r = n+1;        vector<dra> res;        for (ll x = l; x < r;) {            ll divisor = n / x;            ll e;            if (divisor == 0) { e = r; } else { e = min(r, n / divisor + 1); }            res.emplace_back(divisor, x, e);            x = e;        }        return res;    }/*@formatter:on*/;
}
