int main() {
	int n, m; cin >> n >> m;
	int sqrtn = floorsqrt(n);
	vvmodll a(m + 1, vmodll(sqrtn));
	a[0][0] = 1;
	Loop(j, sqrtn) {
		a[1][j] = 1;
	}
	for (int i = 2; i <= m; ++i) {
		vmodll lsum(sqrtn);
		Loop(j, sqrtn) {
			if (j > 0) lsum[j] += lsum[j - 1];
			lsum[j] += a[i - 2][j];
		}
		vmodll rsum(sqrtn);
		Loopr(j, sqrtn) {
			if (j < sqrtn - 1) rsum[j] += rsum[j + 1];
			rsum[j] += a[i - 2][j] * (n / (j + 1) - sqrtn);
		}
		vmodll sum(sqrtn);
		Loop(j, sqrtn) {
			if (j > 0) sum[j] += sum[j - 1];
			sum[j] += a[i - 1][j];
		}
		Loop(j, sqrtn) {
			a[i][j] += sum[sqrtn - 1];
			if (j == 0) {
				a[i][j] += rsum[j];
			}
			else {
				a[i][j] += lsum[j - 1] * (n / (j + 1) - sqrtn);
				a[i][j] += rsum[j];
			}
		}
	}
	modll ans = 0;
	Loop(j, sqrtn) {
		ans += a[m][j];
		ans += a[m - 1][j] * (n / (j + 1) - sqrtn);
	}
	cout << ans << endl;
}

