long long dp[100000][110];
int main() {

    int n, k;
    scanf("%d %d", &n, &k);

    int last = n;
    int tmp = 0, ss = 0;
    for(int i = 1 ; i*i <= n ; i++) {
        dp[i][0] = last - n/(i+1), last = n/(i+1);
        tmp=i;
        ss += dp[i][0];
    }
    while(n - ss > 0) {
        dp[++tmp][0] = 1;
        ss++;
    }

    // for(int i = 1 ; i <= tmp ; i++) {
    //     printf("%d\n", dp[i][0]);
    // }

    for(int j = 1 ; j < k ; j++) {
        long long sum = 0;
        for(int i = 1 ; i <= tmp ; i++) {
            sum += dp[tmp-i+1][j-1];
            sum %= MOD;
            dp[i][j] = sum * dp[i][0] % MOD;
        }
    }
    long long ans = 0;
    for(int i = 1 ; i <= tmp ; i++){
        ans += dp[i][k-1] % MOD;
    }
    printf("%lld\n", ans % MOD);

    return 0;
}

