const int mod = 1e9 + 7;
inline int add(const int &x, const int &y) {
	return (x + y >= mod) ? (x +  y - mod) : (x + y);
}
inline void Add(int &x, const int &y) {
	x += y; (x >= mod) ? (x -= mod) : 0;
}
inline int sub(const int &x, const int &y) {
	return (x < y) ? (x - y + mod) : (x - y);
}
inline void Sub(int &x, const int &y) {
	x -= y; (x < 0) ? (x += mod) : 0;
}
inline int qpow(int a, int b) {
	if (!a) return 0;
	int res = 1;
	for (; b; b >>= 1, a = 1ll * a * a % mod) if (b & 1) res = 1ll * res * a % mod;
	return res;
}

int n, K;
int f[2][50000][2], suf[2][50000];
int main() {
	n = read(); K = read();
	if (n <= 50000) {
		f[0][1][0] = 1;
		rep(i, 1, K) {
			int now = i & 1, pre = now ^ 1;
			rep(j, 1, n) Add(f[pre][j][0], f[pre][j - 1][0]);
			rep(j, 1, n) {
				f[now][j][0] = f[pre][n / j][0];
			}
		}
		int ans = 0;
		rep(i, 1, n) Add(ans, f[K & 1][i][0]);
		printf("%d\n", ans);
		return 0;
	}
	int sqr = (int) sqrt(n);
	f[0][1][0] = 1;
	rep(ii, 1, K) {
		int now = ii & 1, pre = now ^ 1;
		per(j, sqr, 1) suf[pre][j] = (suf[pre][j + 1] + f[pre][j][1]) % mod;
		rep(j, 1, sqr) (f[pre][j][0] += f[pre][j - 1][0]) %= mod;
		rep(j, 1, sqr) {
			f[now][j][0] = f[pre][min(n / j, sqr)][0];
			if (n / j > sqr) {
				f[now][j][0] = add(f[now][j][0], suf[pre][j]);
			}
		}
		for (int i = sqr + 1, j; i <= n; i = j + 1) {
			j = n / (n / i); int len = j - i + 1;
			f[now][n / i][1] = 1ll * len * f[pre][n / i][0] % mod;
		}
	}
	int ans = 0;
	rep(i, 1, sqr + 2) Add(ans, f[K & 1][i][0]), Add(ans, f[K & 1][i][1]);
	printf("%d\n", ans);
	return 0;
}

