vector<ll> get(ll n){
  vector<ll> res;
  ll now=n;
  ll i=2;
  for(;(i-1)*(i-1)<=n;i++){
    ll lb=0,rb=n+1;
    while(rb-lb>1){
      ll mid=(lb+rb)/2;
      if(mid<=n/i) lb=mid;
      else rb=mid;
    }
    res.push_back(now-lb);
    now=lb;
  }
  for(int j=now;j>=1;j--) res.push_back(1);

  vector<ll> r2;
  r2.push_back(0);
  for(int i=res.size()-1;i>=0;i--) r2.push_back(res[i]);
  return r2;
}
