constexpr lint MOD = 1000000007;

int main()
{
    lint N;
    cin >> N;
    lint K;
    cin >> K;

    vector<pint> vp;
    lint i = 1;
    while (i <= N / i)
    {
        vp.emplace_back(i, N / i);
        i++;
    }
    int n = vp.size();
    REP(i, n)
    {
        if (vp[i].first == vp[i].second) continue;
        vp.emplace_back(vp[i].second, vp[i].first);
    }
    sort(ALL(vp));

    vector<lint> dp(vp.size());
    dp[0] = 1;
    // dbg(vp);
    REP(_, K)
    {
        vector<lint> dp_new(vp.size());
        REP(i, vp.size())
        {
            (dp_new[vp.size() - 1 - i] += dp[i]) %= MOD;
        }
        IREP(i, dp_new.size() - 1) (dp_new[i] += dp_new[i + 1]) %= MOD;
        REP(i, dp_new.size())
        {
            dp_new[i] = dp_new[i] * (i == 0 ? 1 : vp[i].first - vp[i - 1].first) % MOD;
        }
        swap(dp, dp_new);
    }
    lint ret = accumulate(ALL(dp), 0LL);
    cout << ret % MOD << endl;
    return 0;
}

