int F() {
	register int x = 0, ch = getchar(), f = 0;
	while(!isdigit(ch)) f |= (ch == '-'), ch = getchar();
	while(isdigit(ch)) x = (x << 1) + (x << 3) + (ch ^ 48), ch = getchar();
	return f ? -x : x;
}
int main() {
	n = F(); m = F(); int len = sqrt(m) + 1; s[0][1] = 1;
	for(register int i = 0; i < n; ++i) {
		for(register int j = 1; j < len; ++j) s[i][j] = (s[i][j] + s[i][j - 1]) % mod;
		for(register int j = len - 2; j > 0; j--) block[i][j] = (block[i][j] + block[i][j + 1]) % mod;
		for(register int j = 1; j < len; ++j) {
			block[i + 1][j] = s[i][j] * (m / j - m / (j + 1));
			if(m / j == j) block[i + 1][j] = 0;
			block[i + 1][j] %= mod;
		}
		for(register int j = 1; j < len; ++j) s[i + 1][j] = block[i][j] + s[i][len - 1], s[i + 1][j] % mod;
	}
	ans = 0;
	for(register int i = 1; i <= len; ++i) ans = (ans + block[n][i] + s[n][i]) % mod;
