// dp[k][i] := 長さkの列で、積がN以下で、末尾がiの数列の数
long long dp[102][100000];
long long N, K;
long long mod = 1e9 + 7;

int main(){
    cin >> N >> K;
    for(int i = 1; i * i <= N; i++){
        dp[1][i] = 1;
        dp[2][i] = N / i;
    }

    for(int k = 3; k <= K + 1; k++){
        long long dp_base = 0;
        for(int i = 1; i * i <= N; i++){
            dp_base += dp[k - 1][i];
        }

        long long dp_prev_sum[100000] = {};
        for(int i = 1; i * i <= N; i++){
            dp_prev_sum[i] = dp_prev_sum[i - 1] + dp[k - 2][i];
            dp_prev_sum[i] %= mod;
        }

        long long ura_dp[100000] = {};
        long long ura_dp_sum = 0;
        int i = 1;
        for(; (i + 1) * (i + 1) <= N; i++){
            ura_dp[i] = (N / i - N / (i + 1)) * dp_prev_sum[i] % mod;
            ura_dp_sum += ura_dp[i];
            ura_dp_sum %= mod;
        }
        ura_dp[i] = (N / i - i) * dp_prev_sum[i] % mod;
        ura_dp_sum += ura_dp[i];
        ura_dp_sum %= mod;

        dp[k][1] = dp_base + ura_dp_sum;
        dp[k][1] %= mod;

        for(int i = 2; i * i <= N; i++){
            dp[k][i] = dp[k][i - 1] + (mod - ura_dp[i - 1]);
            dp[k][i] %= mod;
        }

    }

    cout << dp[K+1][1] << endl;

}

