template<class T> struct strling{
    V<V<T>> S;
    constexpr strling(int MAX) noexcept : S(MAX,V<T>(MAX,0)){
        S[0][0]=1;
        for(int n=1;n<MAX;n++){
            for(int k=1;k<=n;k++){
                S[n][k]=S[n-1][k-1]+S[n-1][k]*k;
            }
        }
    }
    constexpr T get(int n,int k){
        if(n<0||k<0||n<k)return mint(0);
        else return S[n][k];
    }
