const int mod = 1000000007;
struct mint {
	ll x;
	mint(ll x = 0) :x(x%mod) {}
	mint& operator+=(const mint a) {
		if ((x += a.x) >= mod) x -= mod;
		return *this;
	}
	mint& operator-=(const mint a) {
		if ((x += mod - a.x) >= mod) x -= mod;
		return *this;
	}
	mint& operator*=(const mint a) {
		(x *= a.x) %= mod;
		return *this;
	}
	mint operator+(const mint a) const {
		mint res(*this);
		return res += a;
	}
	mint operator-(const mint a) const {
		mint res(*this);
		return res -= a;
	}
	mint operator*(const mint a) const {
		mint res(*this);
		return res *= a;
	}
};

long long N, K;

mint dp[110][111000];
mint sdp[111000];
long long num[111000];

mint solve() {
	int iter = 0;
	for (int i = 1; i <= N;) {
		int j = N / i;
		if (i <= j) num[iter++] = 1, ++i;
		else num[iter++] = N / j - i + 1, i = N / j + 1; 
	}

	memset(dp, 0, sizeof(dp));
	dp[0][0] = 1;
	for (int k = 0; k < K; ++k) {
		memset(sdp, 0, sizeof(sdp));
		for (int j = 0; j <= iter; ++j) sdp[j + 1] = sdp[j] + dp[k][j];
		for (int j = 0; j < iter; ++j) dp[k + 1][j] = sdp[iter - j] * mint(num[j]);
	}

	mint res = 0;
	for (int j = 0; j <= iter; ++j) res += dp[K][j];
	return res;
}


int main() {
	cin >> N >> K;
	puts(solve().x);

	return 0;
}

