main() {
    int64_t n, k;
    cin >> n >> k;

    constexpr auto M = 1000000007;

    int64_t s = sqrt(n);
    if ((s + 1) * (s + 1) <= n) {
        ++s;
    }

    vector<vector<int64_t>> counts(k + 1, vector<int64_t>(s + 1, 0));
    vector<vector<int64_t>> counts2(k + 1, vector<int64_t>(s + 1, 0));
    std::fill(counts[0].begin(), counts[0].end(), 1);
    std::iota(counts[1].begin(), counts[1].end(), 0);
    for (auto i : irange(0L, 2L)) {
        for (int64_t l = 1; l <= s; ++l) {
            counts2[i][l] = counts2[i][l - 1] +
                            (counts[i][l] * (n / l - n / (l + 1))) % M;
            counts2[i][l] %= M;
        }
    }

    for (auto i : irange(2L, k + 1)) {
        for (auto j : irange(1L, s + 1)) {
            int64_t num = counts[i - 1][s];

            num += (counts2[i - 2][n / (s + 1)] - counts2[i - 2][j - 1] + M) %
                   M;
            num %= M;

            counts[i][j] = (counts[i][j - 1] + num) % M;
        }

        for (int64_t l = 1; l <= s; ++l) {
            counts2[i][l] = counts2[i][l - 1] +
                            (counts[i][l] * (n / l - n / (l + 1))) % M;
            counts2[i][l] %= M;
        }
    }

    int64_t ans = (counts[k][s] + counts2[k - 1][n / (s + 1)]) % M;

    cout << ans << endl;
}

