using ll = long long int;
using P = std::pair<int, ll>;

constexpr ll mod = 1e9 + 7;

std::vector<P> vec;
std::unordered_map<int, int> ind;

ll dp[100][70000];

int main()
{

    int n, k;
    std::cin >> n >> k;

    for (int i = 1; i * i <= n; ++i)
    {
        vec.emplace_back(i, 0);
        vec.emplace_back(n / i, 0);
    }

    std::sort(std::begin(vec), std::end(vec));

    vec.erase(std::unique(std::begin(vec), std::end(vec)), std::end(vec));

    for (int i = 0; i < vec.size() - 1; ++i)
        vec[i].second = n / vec[i].first - n / vec[i + 1].first;

    vec.rbegin()->second = 1;

    /*std::cerr << "DEBUG" << std::endl;
    for (auto p : vec)
        std::cerr << p.first << ' ' << p.second << std::endl;
    */

    for (int i = 0; i < vec.size(); ++i)
        ind[vec[i].first] = i;

    dp[0][vec.size() - 1] = vec.rbegin()->second;
    for (int i = vec.size() - 2; i >= 0; --i)
        dp[0][i] = vec[i].second + dp[0][i + 1];

    for (int i = 1; i < k; ++i)
    {
        for (int j = vec.size() - 1; j >= 0; --j)
        {
            dp[i][j] = dp[i - 1][ind[n / vec[j].first]];
            if (j != vec.size() - 1)
                dp[i][j] = (dp[i][j + 1] + dp[i][j] * vec[j].second) % mod;
        }
    }

    /*std::cerr << "DEBUG" << std::endl;

    for (int i = 0; i < k; ++i)
