int main() {
    int N, K; cin >> N >> K;
    dp[0][1] = mint(1);

    int sq = 1; while(sq * sq < N) sq++;
    if(sq * sq > N) sq--;

    for(int i=1; i<=sq; i++) {
        int v = N / i;
        coeff[i] = mint(max(0, v - sq));
    }
    for(int i=1; i<=sq; i++) {
        coeff[i] -= coeff[i+1];
    }

    for(int i=0; i<K; i++) {
        for(int x=1; x<=sq; x++) {
            // 1 から sq まで全部一様に足す (いもす的に)
            dp[i+1][1   ] += dp[i][x];
            dp[i+1][sq+1] -= dp[i][x];

            // dp[i][sq+x] にある値を然るべきところに配る
            dp[i+1][1   ] += dp[i][sq+x] * coeff[x];
            dp[i+1][x+1 ] -= dp[i][sq+x] * coeff[x];

            // dp[i+1][sq+x] に値を配る
            dp[i+1][sq+x   ] += dp[i][x];
            dp[i+1][sq+sq+1] -= dp[i][x];
        }
        for(int x=1; x<=2*sq; x++) {
            dp[i+1][x] += dp[i+1][x-1];
        }
    }

    mint ans(0);
    for(int i=1; i<=sq; i++) {
        mint v = dp[K][i];
        ans += v;
    }

    for(int i=sq; i>=1; i--) {
        coeff[i] += coeff[i+1];
    }

    mint sub(0);
    for(int i=sq+1; i<=2*sq; i++) {
        mint v = dp[K][i] - sub;
        sub += v;
        ans += v * coeff[i - sq];
    }
    cout << ans << endl;
    return 0;
}

