ll dat[101][1 << K];
ll laz1[101][1 << K];
ll laz2[101][1 << K];
ll mod = 1e9 + 7;

void eval(int A, int l, int r, int I) {
	if (A * 2 < 1 << K) {
		laz1[I][A * 2] = laz1[I][A * 2] * laz1[I][A] % mod;
		laz1[I][A * 2 + 1] = laz1[I][A * 2 + 1] * laz1[I][A] % mod;
		laz2[I][A * 2] = (laz2[I][A * 2] * laz1[I][A] + laz2[I][A]) % mod;
		laz2[I][A * 2 + 1] = (laz2[I][A * 2 + 1] * laz1[I][A] + laz2[I][A]) % mod;
	}
	dat[I][A] = (dat[I][A] * laz1[I][A] + laz2[I][A] * (r - l)) % mod;
	laz1[I][A] = 1;
	laz2[I][A] = 0;
}

ll update(int L, int R, ll X, ll Y, int A, int l, int r, int I) {
	eval(A, l, r, I);
	if (r <= L || R <= l) return dat[I][A];
	if (L <= l && r <= R) {
		laz1[I][A] = X;
		laz2[I][A] = Y;
		return (dat[I][A] * laz1[I][A] + laz2[I][A] * (r - l)) % mod;
	}

	return dat[I][A] = (update(L, R, X, Y, A * 2, l, (l + r) / 2, I) + update(L, R, X, Y, A * 2 + 1, (l + r) / 2, r, I)) % mod;
}

void add(int L, int R, ll X, ll Y, int I) {
	update(L, R, X, Y, 1, 0, KM, I);
}

ll check(int L, int R, int A, int l, int r, int I) {
	eval(A, l, r, I);
	if (r <= L || R <= l) return 0;
	if (L <= l && r <= R) return dat[I][A];

	return (check(L, R, A * 2, l, (l + r) / 2, I) + check(L, R, A * 2 + 1, (l + r) / 2, r, I)) % mod;
}

ll query(int L, int R, int I) {
	return check(L, R, 1, 0, KM, I);
}

