int n, k;
ll dp[105][100005];
void solve() {
    cin >> n >> k;

    vector<pair<int, int>> s;
    for (int i = 1; i * i <= n; ++i) {
        s.emplace_back(i, 0);
        s.emplace_back(n / i, 0);
    }

    all(sort, s);
    s.erase(all(unique, s), s.end());

    auto m = sz(s);
    rep(i, m - 1) {
        auto l = n / s[i + 1].first;
        auto r = n / s[i].first;
        s[i].second = r - l;
    }
    s.back().second = 1;

    map<int, int> mp;
    rep(i, m)
        mp[s[i].first] = i;

    dp[0][mp[n]] = 1;
    rep(i, k) {
        repd(j, m - 1)
            plusMod(dp[i][j], dp[i][j + 1]);
        rep(j, m) {
            auto nj = mp[n / s[j].first];
            plusMod(dp[i + 1][j], dp[i][nj] * s[j].second);
        }
    }

    ll ans = 0;
    rep(j, m)
        plusMod(ans, dp[k][j]);

    cout << ans << endn;

}


int main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    cout << fixed << setprecision(15);

    solve();

    cout << flush;

    return 0;
}

