        for (li i = nn; i < 2 * nn; i++) {
            li next = n / opp;
            nums[i] = next - cur + 1;
            cur = next + 1;
            opp--;
        }
        dp[0][0] = nums[0];
        repp(i, 1, nn * 2) {
            dp[0][i] = nums[i] + dp[0][i - 1];
        }
        repp(i, 1, k) {
            dp[i][0] = dp[i - 1][nn * 2 - 1] * nums[0] % MOD;
            repp(j, 1, nn * 2) {
                dp[i][j] = (dp[i - 1][nn * 2 - 1 - j] * nums[j] % MOD + dp[i][j - 1]) % MOD;
            }
        }
        //dump(nums, nn * 2);
        //rep(i, k) {
        //    rep(j, nn * 2)cout << dp[i][j] << " "; cout << endl;
        //}
        cout << dp[k - 1][nn * 2 - 1] << endl;
    } else {
        rep(i, nn) {
            nums[i] = 1;
        }
        li cur = nn + 1;
        li opp = nn - 1;
        for (li i = nn; i < 2 * nn - 1; i++) {
            li next = n / opp;
            nums[i] = next - cur + 1;
            cur = next + 1;
            opp--;
        }
        dp[0][0] = nums[0];
        repp(i, 1, nn * 2 - 1) {
            dp[0][i] = nums[i] + dp[0][i - 1];
        }
        repp(i, 1, k) {
            dp[i][0] = dp[i - 1][nn * 2 - 2] * nums[0] % MOD;
            repp(j, 1, nn * 2 - 1) {
                dp[i][j] = (dp[i - 1][nn * 2 - 2 - j] * nums[j] % MOD + dp[i][j - 1]) % MOD;
            }
        }
        //dump2d(dp, nn * 2 - 1, k);
        cout << dp[k - 1][nn * 2 - 2] << endl;
    }

    return 0;
}

