            dp[i+1][j]+=dp[i][nj]%M*ML[j]%M;
            dp[i+1][j]%=M;
        }
    }
    ll ans = 0;
    for(int i = 0; i < msize; i++){
        ans+=dp[k][i]%M;
    }
    cout<<ans%M;
}

