	for (int i = 0; i < K; i++) {
		for (int j = m - 2; j >= 0; j--) {
			dp[i][j] += dp[i][j + 1] % mod;
			dp[i][j] %= mod;
		}
		for (int j = 0; j < m; j++) {
			int nj = mp[N / s[j].first];
			dp[i + 1][j] += dp[i][nj] * s[j].second % mod;
			dp[i + 1][j] %= mod;
		}
	}
	ll ans = 0;
	for (int j = 0; j < m; j++) {
		ans += dp[K][j] % mod;
		ans %= mod;
	}
