ll binary(ll n , ll v){
    ll left = 1 , right = n , ans = n+1;
    while(left <= right){
        ll mid = (left+right)/2;
        if(n/mid < v){
            ans = min(ans , mid);
            right = mid-1;
        }
        else
            left = mid+1;
    }
    return ans;
}

