		int j=N/i;
		if(i<=j){
			num[iter]=1;
			i++;
		}
		else{
			num[iter]=N/j-i+1;
			i=N/j+1;
		}
		iter++;
	}
	dp[0][0]=1;
	rep(k,K){
		fill(sdp,sdp+iter,0);
		rep(j,iter){
			sdp[j+1]=(sdp[j]+dp[k][j])%MOD;
		}
		rep(j,iter){
			dp[k+1][j]=sdp[iter-j]*num[j]%MOD;
		}
	}
	rep(i,iter+1){
		ans+=dp[K][i];
		ans%=MOD;
	}
	prin(ans);
	return 0;
}

