    vector<ll> z(h);
    for (ll i = 0; i < h; i++) {
        z[i] = n / (i + 1) - n / (i + 2);
        if (i==h-1)z[i] = n / (i + 1) -h;
    }
    vector<vector<ll>> dp(k+3,vector<ll>(h));
    dp[1][0] = 1;
    for (int i = 2; i < k+3; i++) {
        vector<ll> rui(h);
        for (int j = 0; j < h; j++) {
            rui[j] = dp[i - 2][j];
        }
        for (int j = 1; j < h; j++) {
            rui[j] += rui[j - 1];
            rui[j] %= 1000000007;
        }
        vector<ll> zdp(h);
        for (int j = 0; j < h; j++) {
            zdp[j] = rui[j]* z[j];
            zdp[j] %= 1000000007;
        }
        for (int j = h-2; j > -1; j--) {
            zdp[j] += zdp[j+1];
            zdp[j] %= 1000000007;
        }
        ll q = 0;
        for (int j = 0; j < h; j++) {
            q += dp[i - 1][j];
            q %= 1000000007;
        }
        for (int j = 0; j < h; j++) {
            dp[i][j] = zdp[j] + q;
            dp[i][j] %= 1000000007;
        }
    }
    cout << dp[k + 2][0] << endl;
}

