        int now = n / i;
        int tmp = n / now;
        now = n / tmp;
        bounds.push_back(now);
        i = tmp;
    }
    bounds.push_back(0);
    // trace(bounds);
    reverse(bounds.begin(), bounds.end());
    int sz = (int)bounds.size() - 1;
    vector<LL> init(sz + 1, 0);
    // init
    for (int i = sz; i >= 1; i--) {
        init[i] = bounds[i] - bounds[i - 1];
    }
    // trace(init);
    vector<LL> dp(init.begin(), init.end());
    for (int kk = 2; kk <= k; kk++) {
        vector<LL> nxt(sz + 1, 0);
        for (int i = 1; i <= sz; i++) {
            nxt[sz - i + 1] = dp[i];
        }
        dp[sz] = (nxt[sz]) % MOD;
        for (int i = sz - 1; i >= 1; i--) {
            dp[i] = (dp[i + 1] + nxt[i]) % MOD;
        }
        for (int i = 1; i <= sz; i++) {
            dp[i] = (dp[i] * init[i]) % MOD;
        }
        // trace(dp);
    }
    LL res = 0;
    for (auto& v: dp) {
        res += v;
        if (res >= MOD) res -= MOD;
    }
    cout << res << '\n';

    return 0;
}

