#define MOD 1000000007

class Mod
{
public:
    long long value;
    long long mod;
    Mod(const long long x, const long long m = 1000000007)
    {
        set_mod(m);
        set_value(x);
    }

    void set_mod(const long long m)
    {
        this->mod = m;
    }

    void set_value(const long long x)
    {
        this->value = x % this->mod;
    }

    Mod &operator=(const long long x)
    {
        this->value = x;
        return *this;
    }

    Mod &operator+=(const long long x)
    {
        this->value = (this->value + x) % this->mod;
        return *this;
    }

    Mod &operator+=(const Mod x)
    {
        *this += x.value;
        return *this;
    }

    Mod &operator-=(const long long x)
    {
        this->value = (this->value - x) % this->mod;
        return *this;
    }

    Mod &operator-=(const Mod x)
    {
        *this -= x.value;
        return *this;
    }

    Mod &operator*=(const long long x)
    {
        this->value = (this->value * x) % this->mod;
        return *this;
    }

    Mod &operator*=(const Mod x)
    {
        *this *= x.value;
        return *this;
    }

    Mod &operator/=(const long long x)
    {
        long long a = x;
        long long b = this->mod;
        long long u = 1;
        long long v = 0;
        while (b)
        {
            long long t = a / b;
            a -= t * b;
            swap(a, b);
            u -= t * v;
            swap(u, v);
        }
        u %= this->mod;
        if (u < 0)
            u += this->mod;
        *this *= Mod(u, this->mod);
        return *this;
    }

    Mod &operator/=(const Mod x)
    {
        *this /= x.value;
        return *this;
    }

    Mod operator+(const long long x) const
    {
        return Mod(*this) += x;
    }

    Mod operator+(const Mod x) const
    {
        return Mod(*this) += x;
    }

    Mod operator-(const long long x) const
    {
        return Mod(*this) -= x;
    }

    Mod operator-(const Mod x) const
    {
        return Mod(*this) -= x;
    }

    Mod operator*(const long long x) const
    {
        return Mod(*this) *= x;
    }

    Mod operator*(const Mod x) const
    {
        return Mod(*this) *= x;
    }

    Mod operator/(const long long x) const
    {
        return Mod(*this) /= x;
    }

    Mod operator/(const Mod x) const
    {
        return Mod(*this) /= x;
    }
};

