ll dp[2][101][150000];
ll sigma[2][101][150000];

ll tagget_for_0 = 0;
ll tagget_for_1 = 0;

ll Compute[150000];
ll LL[150000];
ll RR[150000];

ll compute(ll x)
{
    if (Compute[x] != -1)
        return Compute[x];
    long long L = 0, R = 0;
    ll l = 0, r = 1e9;
    while (l + 1 < r)
    {
        ll mid = (l + r) / 2;
        if (n / mid > x)
            l = mid;
        else
            r = mid;
    }
    L = r;

    l = 0, r = 1e9;
    while (l + 1 < r)
    {
        ll mid = (l + r) / 2;
        if (n / mid >= x)
            l = mid;
        else
            r = mid;
    }

    R = l;
    //cout << x << " : " << L << " " << R << endl;
    LL[x] = L;
    RR[x] = R;
    return Compute[x] = R - L + 1;
}

ll oks(int vetka, int x)
{
    if (vetka == 0)
    {
        return x <= tagget_for_0;
    }
    else
    {
        return x <= tagget_for_1;
    }
    return 0;
}

void calc(int t, int len, int x)
{
    if (t == 0)
    {
        dp[t][len][x] = (sigma[0][len - 1][ROOT] + sigma[1][len - 1][x]) % MOD;
    }
    else
    {
        dp[t][len][x] = compute(x) * sigma[0][len - 1][x] % MOD;
    }
}

signed main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);
    cin >> n >> k;
    while (ROOT * ROOT <= n)
        ROOT++;
    for (int i = 1; i <= 49999; i++)
        Compute[i] = -1;
    for (int i = 1; i <= 49999; i++)
    {
        compute(i);
    }
    for (int i = 1; i <= 49999; i++)
    {
        if (LL[i] * LL[i] > n)
        {
            tagget_for_0 = RR[i + 1];
            tagget_for_1 = i;
        }
    }
    if (n == 2)
    {
        tagget_for_0 = 1;
        tagget_for_1 = 1;
    }
    if (n == 3)
    {
        tagget_for_0 = 1;
        tagget_for_1 = 1;
    }

    //cout << tagget_for_0 << " " << tagget_for_1 << endl;

    for (int i = 1; i <= 49999; i++)
    {
        if (oks(0, i)) dp[0][1][i] = 1;
        if (oks(1, i)) dp[1][1][i] = compute(i);
        sigma[0][1][i] = (sigma[0][1][i - 1] + dp[0][1][i]) % MOD;
        //sigma[1][1][i] = (sigma[1][1][i - 1] + dp[1][1][i]) % MOD;
    }
    for (int x = 49999; x >= 0; x--)
    {
        sigma[1][1][x] = (sigma[1][1][x + 1] + dp[1][1][x]) % MOD;
    }
    for (int i = 2; i <= k; i++)
    {
        for (int x = 1; x <= 49999; x++)
        {
            if (oks(0, x)) calc(0, i, x);
            if (oks(1, x)) calc(1, i, x);
            sigma[0][i][x] = (sigma[0][i][x - 1] + dp[0][i][x]) % MOD;
            //sigma[1][i][x] = (sigma[1][i][x - 1] + dp[1][i][x]) % MOD;
        }
        for (int x = 49999; x >= 0; x--)
        {
            sigma[1][i][x] = (sigma[1][i][x + 1] + dp[1][i][x]) % MOD;
        }
    }

    ll ans = 0;
    for (int i = 1; i <= 49999; i++)
    {
        ans += oks(0, i) * dp[0][k][i] + oks(1, i) * dp[1][k][i];
        ans %= MOD;
    }
    cout << ans % MOD;
}

