template< typename T >
vector<pair<pair<T, T>, T>> quotient_range(T N) {
    T M;
    vector<pair<pair<T, T>, T>> ret;
    for (M = 1; M * M <= N; M++) ret.emplace_back(make_pair(M, M), N / M);
    for (T i = M; i >= 1; i--) {
        T L = N / (i + 1) + 1;
        T R = N / i;
        if (L <= R and ret.back().first.second < L) ret.emplace_back(make_pair(L, R), N / L);
    }
    return ret;
}

