#define fastIO ios::sync_with_stdio(false);cin.tie(0);cout.tie(0);

const ll LOG = 31;
const ll MOD = (ll)1e9 + 7;
struct RNG{
  ll lef;
  ll rig;
  ll vv;
  ll ans;
};

int main(){
  fastIO;
  ll n, k;
  cin >> n >> k;
  vector<RNG> cur;
  ll p = 1;
  ll ni;
  while(p<n){
    ni = p;
    for(ll j = LOG - 1; j >= 0 ; j -- ){
      if((ni + (1 << j)) > n) continue;
      if((n/p) == n/(ni + (1 << j))){
        ni += (1 << j);
      }
    }
    cur.push_back({p, ni, n/p, 1});
    p = ni + 1;
  }
  ll m = cur.size();
  vector<RNG> nx;
  ll q;
  ll pref;
  for(ll i = 2 ; i <= k ; i ++ ){
    nx = cur;
    for(auto &p : nx) p.ans = 0;
    q = 0;
    pref = 0;
    for(ll p = nx.size() - 1; p >= 0 ; p -- ){
      while(cur[q].rig < nx[p].vv){
        pref += ((cur[q].rig - cur[q].lef + 1) * 1ll * cur[q].ans) % MOD;
        q ++ ;
      }
      nx[p].ans = pref;
      nx[p].ans += ((nx[p].vv - cur[q].lef + 1) * 1ll * cur[q].ans) % MOD;
      if(nx[p].ans >= MOD) nx[p].ans -= MOD;
    }
    cur = nx;
  }
  ll res = 0;
  for(auto pq : nx){
    res += ((pq.rig - pq.lef + 1) * 1ll * pq.ans) % MOD;
    if(res >= MOD) res -= MOD;
  }
  cout << res << "\n";
  return 0;
}

