template<typename T>
void unique_sort(std::vector<T>& vec) {
    std::sort(vec.begin(), vec.end());
    vec.erase(std::unique(vec.begin(), vec.end()), vec.end());
}

// n*n <= xを満たす最大のnを返す。
// sqrt(x)をintでキャストした時に、まるめ誤差によって小さくなることが
int64_t sqrt_int(int64_t x) {
    assert(0 <= x);
    if (x <= 1) { return x; }
    int128_t ret = std::sqrt(x);
    assert(ret * ret <= x);
    assert(x < (ret + 2) * (ret + 2));
    return ((ret + 1) * (ret + 1) <= x) ? ret + 1 : ret;
}

