    G[u].emplace_back(1, N+v);
    G[N+u].emplace_back(0, N+N+v);
    G[N+N+u].emplace_back(0, v);
  }
  dijkstra<edge> dij(G, N+1);
  int S, T; std::cin >> S >> T; --S; --T;
  dij.search(S);
  int ans = dij.d[T];
  if(ans > N) ans = -1;
  fin(ans);
  return 0;
}

