	if (sqrtN * (sqrtN + 1) > N)
	{
		intervalCount = sqrtN * 2 - 1;
		intervalLength.resize(intervalCount);
		for (ll i = 0; i < sqrtN; ++i)
		{
			intervalLength[i] = 1;
		}
		for (ll i = 1; i <= sqrtN - 2; ++i)
		{
			intervalLength[intervalCount - i] = N / i - N / (i + 1);
		}
		if (sqrtN != 1)
		{
			intervalLength[sqrtN] = N / (sqrtN - 1) - sqrtN;
		}
	}
	else
	{
		intervalCount = sqrtN * 2;
		intervalLength.resize(intervalCount);
		for (ll i = 0; i < sqrtN; ++i)
		{
			intervalLength[i] = 1;
		}
		for (ll i = 1; i <= sqrtN - 1; ++i)
		{
			intervalLength[intervalCount - i] = N / i - N / (i + 1);
		}
		intervalLength[sqrtN] = N / sqrtN - sqrtN;
	}

	vector<rll> prevTable;
	vector<rll> currTable(intervalCount, 1);

	for (ll i = 0; i < K; ++i)
	{
