ll mod_pow(ll x, ll n, ll mod = MOD) {
	if (n == 0) return 1;
	ll res = mod_pow(x * x % mod, n / 2, mod);
	if (n & 1) res = res * x % mod;

	return res;
}

ll div2 = mod_pow(2, MOD - 2, MOD);

struct LazySegTree {
	vector<ll> node, lazy;
	int n;

	LazySegTree() {}
	LazySegTree(int _n) {
		n = 1;
		while (n < _n) n *= 2;

		node.resize(2 * n - 1, 0);
		lazy.resize(2 * n - 1, 0);
	}

	void eval(int k, int l, int r) {
		if (lazy[k] == 0) return;
		(node[k] += lazy[k]) %= MOD;

		if (r - l > 1) {
			(lazy[k * 2 + 1] += lazy[k] * div2 % MOD) %= MOD;
			(lazy[k * 2 + 2] += lazy[k] * div2 % MOD) %= MOD;
		}

		lazy[k] = 0;
	}

	void add(int a, int b, ll x, int k = 0, int l = 0, int r = -1) {
		if (r < 0) r = n;
		eval(k, l, r);

		if (b <= l || r <= a) return;
		if (a <= l && r <= b) {
			(lazy[k] += (r - l) * x % MOD) %= MOD;
			eval(k, l, r);
		}
		else {
			add(a, b, x, k * 2 + 1, l, (l + r) / 2);
			add(a, b, x, k * 2 + 2, (l + r) / 2, r);
			node[k] = (node[k * 2 + 1] + node[k * 2 + 2]) % MOD;
		}
	}

	ll query(int a, int b, int k = 0, int l = 0, int r = -1) {
		if (r < 0) r = n;
		eval(k, l, r);

		if (b <= l || r <= a) return 0;
		if (a <= l && r <= b) return node[k];
		ll vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
		ll vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
		return (vl + vr) % MOD;
	}
};


LazySegTree dp[102];

