	ll X = 1;
	while (X * X <= N) X++;
	X--;

	REP(i, K + 2) dp[i] = LazySegTree(X + 1);

	dp[0].add(1, 2, 1);
	REP(i, K + 1) {
		ll cc = dp[i].query(1, X + 1);
		FOR(j, 1, X + 1) {
			// k ? jでj>kのとき
			ll cnt = N / j - X;
			if (i > 0) dp[i + 1].add(j, j + 1, dp[i - 1].query(1, j) * cnt % MOD);
			// j ? kでj>=kのとき
			if (i + 2 <= K + 1) dp[i + 2].add(1, j + 1, dp[i].query(j, j + 1) * cnt % MOD);
			dp[i + 1].add(j, j + 1, cc);
		}
	}

	cout << dp[K + 1].query(1, 2) << endl;

	return 0;
}

