        fac[0]=1,ifac[0]=1;
        for(int i=1;i<10101011;i++)fac[i]=fac[i-1]*i;
        ifac[10101010]=fac[10101010].inv();
        for(int i=10101009;i>=0;i--)ifac[i]=ifac[i+1]*(i+1);
    }
    mint comb(lint b){
        if(init)build();
        if(a==0&&b==0)return 1;
        if((lint)a<b||a<0)return 0;
        return fac[a]*ifac[a-b]*ifac[b];
    }
    mint fact(){
