    while(pos <= n) {
        int x = n / pos, y = n / x;
        range.push_back({pos, y});
        len.push_back(x);
        val.push_back(1);
        pos = y + 1;
    }
    //for(int i = 0; i < range.size(); i++)
    //    cout << "(" << range[i].first << ", " << range[i].second << ") " << len[i] << '\n';
    for(int i = 0; i < k - 1; i++) {
