            psum[j] = (psum[j]*(range[j].second - range[j].first + 1) + psum[j - 1]) % MOD;
        for(int j = 0; j < val.size(); j++) {
            //cout << len[j] << " " << bnd(cv, psum, len[j]) << endl;
            val[j] = bnd(cv, psum, len[j]);
        }
    }
