//!  8888ba.88ba           oo           !//
//!  88  '8b  '8b                       !//
//!  88   88   88 .d8888b. dP 88d888b.  !//
//!  88   88   88 88'  '88 88 88'  '88  !//
//!  88   88   88 88.  .88 88 88    88  !//
//!  dP   dP   dP '88888P8 dP dP    dP  !//
//!=====================================!//
int main()
{
    using mint = ModInt<MOD>;
    const ll N = read<ll>();
    const int K = read<int>();
    const ll M = (ll)std::sqrt(N);
    const ll RM = (N / M == M ? M - 1 : M);
    std::vector<ll> min, max;
    for (ll i = 1; i <= M; i++) { min.push_back(i), max.push_back(i); }
    for (ll i = RM; i >= 1; i--) { min.push_back((N + i + 1) / (i + 1)), max.push_back(N / i); }
    std::vector<mint> dp(M + RM, 0);
    dp[0] = 1;
    for (int i = 0; i < K; i++) {
        std::vector<mint> imos(M + RM, 0);
        for (ll j = 0; j < M + RM; j++) { imos[M + RM - j - 1] += dp[j]; }
        for (ll j = M + RM - 2; j >= 0; j--) { imos[j] += imos[j + 1]; }
        for (ll j = 0; j < M + RM; j++) { dp[j] = imos[j] * (max[j] - min[j] + 1); }
    }
    std::cout << std::accumulate(dp.begin(), dp.end(), mint(0)) << std::endl;
    return 0;
}

