const long long MOD = 1000000007;

int dp1[110][31700], dp2[110][31700];

void solve(long long N, long long K){
    int M;
    for(M = 1; M * M <= N; ++M) ;
    for(int i = 1; i * i <= N; ++i) {
        dp1[0][i] = 1;
        if (N / i > i) {
            dp2[0][i] = N / i - N / (i + 1);
        }
    }

    for(int i = 1; i < K; ++i) {
        int a = 0;
        for(int j = 1; j * j <= N; ++j) {
            a = (a + dp1[i-1][j]) % MOD;
            if (N / j > j) {
                dp2[i][j] = a * (N / j - N / (j + 1)) % MOD;
            }
        }
        for(int j = 1; j * j <= N; ++j) {
            dp1[i][j] = a;
        }
        int c = 0;
        for(int j = M - 1; j >= 1; --j) {
            c = (c + dp2[i - 1][j]) % MOD;
            dp1[i][j] = (dp1[i][j] + c) % MOD;
        }
    }
    int res = 0;
    for(auto a: dp1[K - 1]) {
        res = (res + a) % MOD;
    }
    for(auto a: dp2[K - 1]) {
        res = (res + a) % MOD;
    }
    cout << res << endl;

