const int MOD = 1000000007;

struct mint { int n; mint(int n_ = 0) : n(n_) {} };
mint operator-(mint a) { return -a.n + MOD * (a.n != 0); }
mint operator+(mint a, mint b) { int x = a.n + b.n; return x - (x >= MOD) * MOD; }
mint operator-(mint a, mint b) { int x = a.n - b.n; return x + (x < 0) * MOD; }
mint operator*(mint a, mint b) { return (long long)a.n * b.n % MOD; }
mint &operator+=(mint &a, mint b) { return a = a + b; }
mint &operator-=(mint &a, mint b) { return a = a - b; }
mint &operator*=(mint &a, mint b) { return a = a * b; }
istream &operator>>(istream &i, mint &a) { return i >> a.n; }
ostream &operator<<(ostream &o, mint a) { return o << a.n; }

int main() {
  cin.tie(nullptr);
  ios::sync_with_stdio(false);
  ll N, K;
  cin >> N >> K;
  // i=N/prev -> 1..i
  vector<int> from;
  vector<int> cnt;
  from.push_back(1);
  ll k = 1;
  while (k <= N) {
    ll l = k;
    ll r = N+1;
    while (r - l > 1) {
      ll m = (l + r) / 2;
      if (N / l == N / m) {
        l = m;
      } else {
        r = m;
      }
    }
    from.push_back(r);
    cnt.push_back(r - k);
    k = r;
  }
  const int m = cnt.size();
  vector<mint> dp0(m+1);
  dp0[0] = 1;
  rep(i, K) {
    vector<mint> dp1(m+1);
    rep(j, m) {
      // from[j] * k <= N
      // k <= floor(N/from[j])
      int k = upper_bound(from.begin(), from.end(), N/from[j]) - from.begin();
      dp1[0] += dp0[j];
      dp1[k] -= dp0[j];
    }
    rep(j, m) {
      dp1[j+1] += dp1[j];
      dp1[j] *= cnt[j];
    }
    dp0 = dp1;
  }
  mint ans = 0;
  rep(j, m) {
    ans += dp0[j];
  }
  cout << ans << endl;
