{
	ll N, K; cin >> N >> K;

	if (N == 1)
	{
		cout << 1;
		return 0;
	}

	vt<TableOfEqualDivResult> layer;
	TableOfEqualDiv(N, layer);
	layer.insert(layer.begin(), TableOfEqualDivResult());

	vvt<mll> dp = VVT<mll>(K + 1, Size(layer));
	rep(j, 1, Size(layer)) dp[1][j] = dp[1][j - 1] + layer[j].c;
	rep(i, 2, K + 1) rep(j, 1, Size(layer))
		dp[i][j] = dp[i - 1][Size(layer) - j] * layer[j].c + dp[i][j - 1];

	cout << dp[K][Size(layer) - 1];
	return 0;
}

