        prv2[i] = 1;
    } 
    int temp = sqrt(k);
    if(temp * temp == k)temp--;
    FOR(i, n){
        int num = 1;
        for(; num <= temp; num++){
            dp[num] = prv2[num]; 
            int fac = ((k/num) - max(k/(num + 1), (long long)sqrt(k)));
            dp2[num] = prv[num]*fac;
            //cout << dp[num] << "  " << dp2[num] << endl;
        } 
        if(num * num == k){
            dp[num] = prv[num];
            num--;
        }
        int pr = 0;
        for(int j = 1; j <= sqrt(k); j++){
            prv[j] = dp[j] + prv[j-1];
            prv[j] %= mod;
            //debug(prv[j]);
        }
        pr = prv[sqrt(k)];
        for(int j = 1; j <= temp; j++){
            prv2[j] = pr + dp2[temp - j + 1];
            prv2[j] %= mod;
            pr = prv2[j];
        //    cout << pr << " "; 
        }
        int x = 1, y = temp;
        while(x <  y){
            swap(prv2[x], prv2[y]); 
            x++; y--;
        }
    }
    cout << prv2[1];

}

