int main() {
  std::ios::sync_with_stdio(false), std::cin.tie(0);
  int n, k;
  cin >> n >> k;
  int m = 0;
  for(; m * m < n; m++);

  // dump(m);
  for(int i = 1; i <= m; i++) {
    // i 以下の数ととなりになれるやつの数
    int now = max(n / i, m);
    int next = max(n / (i + 1), m);
    num[i] = max(now - next, 0);
    // dump(i, num[i]);
  }
  for(int i = 1; i <= m; i++) dp[0][i][0] = 1;
  for(int i = 1; i <= m; i++) dp[0][i][1] = num[i];

  for(int i = 0; i < k - 1; i++) {
    for(int j = 1; j <= m; j++) {
      auto d = dp[i][j][0];
      dp[i+1][1][0] += d;
      dp[i+1][min(n/j, m) + 1][0] += -d;

      dp[i+1][j][1] += d;
    }
    for(int j = 1; j <= m; j++) {
      auto d = dp[i][j][1];
      dp[i + 1][1][0] += d;
      dp[i + 1][j + 1][0] += -d;
    }
    for(int j = 2; j <= m; j++) dp[i + 1][j][0] += dp[i + 1][j-1][0];
    for(int j = 2; j <= m; j++) dp[i + 1][j][1] += dp[i + 1][j-1][1];
    for(int j = 1; j <= m; j++) dp[i + 1][j][1] *= num[j];
  }

  modint ans = 0;
  for(int i = 1; i <= m; i++) ans += dp[k-1][i][0];
  for(int i = 1; i <= m; i++) ans += dp[k-1][i][1];
  cout << ans << endl;
  return 0;
}

