const long long MOD = 1000000007;

void solve(long long N, long long K){
  set<ll> p;
  for(long long i = 1; i*i <= N; i++){
    p.insert(i);
    p.insert(N/i);
  }
  vector<ll> pp(p.begin(),p.end());
  vector<vector<ll>> dp(K,vector<ll>(p.size()));
  ll S=p.size();
  for (int i=0; i<(long long)pp.size();i++)
  {
    dp[0][i]=pp[i];
  }
  REP(K-1){
    for (int j=0;j< (long long)pp.size();j++)
    {
      if(j==0){
        dp[i+1][j]=dp[i][S-1]%MOD;
      }else{
        dp[i+1][j]=dp[i][S-1-j]*(pp[j]-pp[j-1])%MOD;
        dp[i+1][j]+=dp[i+1][j-1];
        dp[i+1][j]%=MOD;
      }
    }
  }
  cout<<dp[K-1][S-1]<<endl;
}

