  }
  sort(div.begin(), div.end());
  vector<LL> initial;
  int prev = 0;
  for (auto v : div) {
    initial.push_back(v-prev);
    prev = v;
  }
  vector<LL> curr = initial;
  vector<LL> next(curr.size(), 0);
  for (int k=0; k<K-1; k++) {
    LL t = 0;
    for (int i=0; i<(int)curr.size(); i++) {
      int j = (int)(curr.size()-i-1);
      t += curr[i] ;
      t %= MOD;
      next[j] = (initial[j] * t) % MOD;
    }
    swap(curr, next);
  }
  int res = 0;
  for (auto v : curr) {
    res = (res + v) % MOD;
  }
  cout << res << endl;
  return 0;
}

