ll bs(ll x, ll y){
	ll l = 0, r = MOD, mid, ans = 0;
	while(l<=r){
		mid=l+r>>1;
		if(mid*x<=y){
			l = mid + 1;
			ans = max(ans,mid);
		}
		else r = mid - 1;
	}
	return ans;
}

