using namespace std;

const int P = 1000000007;
const int maxN = 64000;

vector < int > bounds, ways;
int d[2][maxN], add[maxN];

int buildBounds(int p) {
  for (int i = 1; i * i <= p; ++i) {
    ways.push_back(i);
    bounds.push_back(p / i);
  }

  int m = bounds.size();
  for (int i = 0; i < m; ++i) {
    ways.push_back(bounds[m - 1 - i]);
    bounds.push_back(ways[m - 1 - i]);
  }

  return m + m;
}

int main() {
  int n, p;
  cin >> n >> p;
  assert(1 <= n && n <= 1e3);
  assert(1 <= p && p <= 1e9);
  int m = buildBounds(p);

  int u = 0, v = 1;
  memset(d[u], 0, sizeof(d[u]));
  d[u][m - 1] = 1;
  for (int i = 0; i < n; ++i, swap(u, v)) {
    int covered = m - 1;
    memset(add, 0, sizeof(add));
    memset(d[v], 0, sizeof(d[v]));
    for (int j = 0; j < m; ++j) {
      if (d[u][j] == 0) {
        continue;
      }
      while (covered >= 0 && bounds[covered] <= ways[j]) {
        --covered;
      }

      add[covered + 1] += d[u][j];
      if (add[covered + 1] >= P) {
        add[covered + 1] -= P;
      }

      for (int k = covered; k >= 0; --k) {
        int right = min(bounds[k], ways[j]);
        int left = k == m - 1 ? 1 : bounds[k + 1] + 1;

        if (left <= right) {
          d[v][k] += (long long)(d[u][j]) * (long long)(right - left + 1) % (long long)(P);
          if (d[v][k] >= P) {
            d[v][k] -= P;
          }
        } else {
          break;
        }
      }
    }

    for (int j = 1; j < m; ++j) {
      add[j] += add[j - 1];
      if (add[j] >= P) {
        add[j] -= P;
      }
    }

    for (int j = 0; j < m; ++j) {
      int right = bounds[j];
      int left = j == m - 1 ? 1 : bounds[j + 1] + 1;
      d[v][j] += (long long)(add[j]) * (long long)(right - left + 1) % (long long)(P);
      if (d[v][j] >= P) {
        d[v][j] -= P;
      }
    }
  }

  long long res = 0;
  for (int i = 0; i < m; ++i) {
    res += d[u][i];
  }

  cout << res % P << endl;

  return 0;
}

