// ABC 132解説.
// https://img.atcoder.jp/abc132/editorial.pdf
#include <bits/stdc++.h>
using namespace std;
using LL = long long;
const LL MOD = 1e9 + 7;
const LL MAX_K = 101;
const LL MAX_N = 1e5;
LL dp[MAX_K][MAX_N];

int main() {

    // 1. 入力情報取得.
    LL N, K;
    scanf("%lld %lld", &N, &K);

    // 2. 解説通り.
    // dp[i][x]: 最後の整数が, x であるような i個 の 整数を並べて条件を満たせる場合の数.
    // ex.
    // [入力例]
    // 10 3
    // ※下記, dp[3][XX] については, 計算方法を ()内 に, 記載した.
    // dp[1][1]  = 1, dp[2][1]  = 10, dp[3][1]  = 27 (= dp[2][1] + ... + dp[2][10])
    // dp[1][2]  = 1, dp[2][2]  = 5,  dp[3][2]  = 22 (= dp[2][1] + dp[2][2] + dp[2][3] + dp[2][4] + dp[2][5])
    // dp[1][3]  = 1, dp[2][3]  = 3,  dp[3][3]  = 18 (= dp[2][1] + dp[2][2] + dp[2][3])
    // dp[1][4]  = 1, dp[2][4]  = 2,  dp[3][4]  = 15 (= dp[2][1] + dp[2][2])
    // dp[1][5]  = 1, dp[2][5]  = 2,  dp[3][5]  = 15 (= dp[2][1] + dp[2][2])
    // dp[1][6]  = 1, dp[2][6]  = 1,  dp[3][6]  = 10 (= dp[2][1])
    // dp[1][7]  = 1, dp[2][7]  = 1,  dp[3][7]  = 10 (= dp[2][1])
    // dp[1][8]  = 1, dp[2][8]  = 1,  dp[3][8]  = 10 (= dp[2][1])
    // dp[1][9]  = 1, dp[2][9]  = 1,  dp[3][9]  = 10 (= dp[2][1])
    // dp[1][10] = 1, dp[2][10] = 1,  dp[3][10] = 10 (= dp[2][1])
    // -> dp[3][1] + dp[3][2] + ... + dp[3][9] + dp[3][10] = 147通り と 計算するようである.

    LL nr = sqrt(N + 0.0);
    LL ir = N / nr;
    for(LL x = 1; x < nr + ir; x++) dp[1][x] = 1;

    for(LL k = 2; k <= K; k++){

         // 2-1. N ～ r まで集計.
         // ex.
         // x = 5 に 6 ～ 10, x = 4 に 4 ～ 5, x = 3 に 3 を 集約.
         for(LL x = nr + ir - 1; x >= nr; x--){
             dp[k][x] = dp[k - 1][nr + ir - x] + dp[k][x + 1];
             dp[k][x] %= MOD;
         }

         // 2-2. r - 1～ 1 まで集計.
         // ex.
         // x = 2 ～ 1 までを集計.
         for(LL x = nr - 1; x > 0; x--){
             dp[k][x] = dp[k][x + 1] + dp[k - 1][nr + ir - x] * (N / x - N / (x + 1));
             dp[k][x] %= MOD;
         }
    }
    // for(LL x = 1; x < nr + ir; x++) cout << dp[K][x] << " ";
    // cout << endl;

    // 3. 後処理.
    LL ans = 0;
    for(LL x = 1; x < nr; x++)       ans += dp[K][x], ans %= MOD;
    for(LL x = nr; x < nr + ir; x++) ans += dp[K][x] * (N / (nr + ir - x) - N / (nr + ir - x + 1)), ans %= MOD;
    printf("%lld\n", ans);
    return 0;

}

