int64_t const MOD = 1e9+7;

template<int64_t Prime>
struct mod_int {
  int64_t v_;
  mod_int(int64_t x=0) : v_(x) { normalize(); }
  void normalize() { ((v_ %= Prime) += Prime) %= Prime; }
  mod_int operator+=(mod_int const& r){ (v_ += r.v_) %= Prime; return *this; }
  mod_int operator-=(mod_int const& r){ (v_ += Prime - r.v_) %= Prime; return *this; }
  mod_int operator*=(mod_int const& r){ (v_ *= r.v_) %= Prime; return *this; }
  mod_int operator+(mod_int const& r) { mod_int res(*this); return res += r; }
  mod_int operator-(mod_int const& r) { mod_int res(*this); return res -= r; }
  mod_int operator*(mod_int const& r) { mod_int res(*this); return res *= r; }
  mod_int pow(int x) const {
    int64_t res = 1, v = v_;
    while(x > 0) {
      if(x&1) (res *= v) %= Prime;
      x/=2; (v *= v) %= Prime;
    }
    return mod_int(res);
  }
  mod_int inv() const { return pow(Prime-2); }
};
typedef mod_int<MOD> mint;

int main() {
  int N, K; std::cin >> N >> K;
  int L = std::min(N/100, 31630);
  while(L*L <= N) ++L;
  std::vector<mint> dp1(L+1), dp2(L+1);
  std::fill_n(dp1.begin()+1, std::min(L, N), mint(1));
  std::fill_n(dp2.begin()+1, L, mint(1));

  mint sum; 
  while(K--) {
    std::swap(dp1, dp2);
    // sum up previous dp1[] to current dp2[]
    for(int i = 1; i <= L; ++i) dp2[i] += dp2[i-1];
    //
    sum = dp2[N/(L+1)];
    // sum up previous dp2[] to current dp1[]
    for(int i = L; i > 0; --i) {
      sum += dp1[i]*mint(N/i - N/(i+1));
      dp1[i] = sum;
    }
  }
  fin(sum.v_);
  return 0;
}

