int main() {
    ll N, K;
    cin >> N >> K;

    constexpr ll MOD = 1e9 + 7;

    //i = 1, 2, ..., NをN / iで分類
    //各要素の意味「first = N / iとなるiがsecond個ある」
    vector<pair<ll, ll>> elements;
    for (ll i = N; i > 0; ) {
        ll div = N / i;

        ll next = min(N / (div + 1), i - 1);
        ll num = i - next;
        elements.emplace_back(div, num);
        i = next;
    }

    //dp[i][j] := i個を設置して最後がj番目の割った数になる場合の数
    vector<vector<ll>> dp(K + 1, vector<ll>(elements.size(), 0));

    //1個設置する方法は1通り
    for (ll j = 0; j < elements.size(); j++) {
        dp[1][j] = 1;
    }

    for (ll i = 1; i < K; i++) {
        ll sum = 0, num = 0, index = elements.size() - 1;
        for (ll j = 0; j < elements.size(); j++) {
            while (num < elements[j].first) {
                (sum += dp[i][index] * elements[index].second) %= MOD;
                num += elements[index].second;
                index--;
            }
            dp[i + 1][j] = sum;
        }
    }

    ll ans = 0;
    for (ll j = 0; j < elements.size(); j++) {
        (ans += dp[K][j] * elements[j].second) %= MOD;
    }
