int64_t root(int64_t n){
    int64_t ret = pow((long double)n, 0.5L);
    while(ret*ret > n) ret--;
    while((ret+1)*(ret+1) <= n) ret++;
    return ret;
}

int main(){
    int N, K;
    cin >> N >> K;
    int Q = root(N);
    int num[32000];
    num[1] = 1;
    for(int i=1; i<Q; i++){
        num[i] = N/i - N/(i+1);
    }
    num[Q] = N/Q - Q;

    static int64_t dp1[101][32000], dp2[101][32000];
    dp1[0][1] = 1;
    for(int i=0; i<K; i++){
        int64_t sum1 = 0;
        for(int j=1; j<=Q; j++) add(sum1, dp1[i][j]);
        for(int j=1; j<=Q; j++) add(dp1[i+1][j], sum1);

        int64_t sum2 = 0;
        for(int j=Q; j>=1; j--){
            add(sum2, dp2[i][j]);
            add(dp1[i+1][j], sum2);
        }

        int64_t sum3 = 0;
        for(int j=1; j<=Q; j++){
            add(sum3, dp1[i][j]);
            add(dp2[i+1][j], sum3 * num[j]);
        }
    }

    int64_t ans = 0;
    for(int j=1; j<=Q; j++) add(ans, dp1[K][j] + dp2[K][j]);
    cout << ans << endl;
    return 0;
}

