        cs.push_back(MP(N/i));
    }
    cs.push_back(MP(0));
    std::sort(ALL(cs), [](MP& x, MP& y) {
        return x < y;
    });

    dp[0][0] = MP(1);
    for(int x = 0; x < K; x++) {
        for(int i = 0; i < cs.size(); i++) {
            dp[x][i+1] += dp[x][i];
        }
        for(int i = 0; i < cs.size()-1; i++) {
            dp[x+1][i] = dp[x][cs.size()-1-i-1] * (cs[i+1] - cs[i]);
        }
    }

    MP ans(0);
    for(int x = 0; x <= cs.size(); x++) {
        ans += dp[K][x];
    }

    cout << ans.x ;
}

