void solv()	 {
	cin >> n >> k;
	vector<ll> v;
	v.push_back(0);
	for (ll i = 1; i * i <= n; i++)
	{
		v.push_back(i);
		v.push_back(n / i);
	}

	vsort(v);
	dup(v);
	ll dp[110][100010];
	all0(dp);
	rep(i, v.size() - 1) {
		dp[0][i] = v[i + 1] - v[i];
	}

	rep2(i, 1, k) {
		vl r;
		rep(j, v.size() - 1) {
			r.push_back(dp[i - 1][j]);
			if (j > 0)inf(r[j] += r[j - 1]);
		}

		rep(j, v.size() - 1) {
			dp[i][j] = inff(r[r.size() - 1 - j] * (v[j + 1] - v[j]));
		}
	}
	ll res = 0;
	rep(i,v.size() -1){
		inf(res += dp[k - 1][i]);
	}
	cout << res << endl;
}


