//N/? > N/xとなる最大の?
ll bins(ll N, ll x) {
	ll l = 0;
	ll r = 1e10;
	while (l + 1 < r) {
		ll mid = l + (r - l) / 2;
		if (N / x < N / mid)l = mid;
		else r = mid;
	}
	return l;
}

int main() {
	ll N, K;
