		PRI(1);
		return 0;
	}
	vector<ll> v,c;
	v.push_back(N);
	while (v.back() > 1) v.push_back(bins(N, v.back()));
	v.push_back(0);
	//N/v[*]=N/?=aである?の個数
	for (int i = 0; i < v.size() - 1; ++i) c.push_back(v[i] - v[i + 1]);
	v.pop_back();
	reverse(v.begin(), v.end());
	reverse(c.begin(), c.end());
	vector<vector<ll>> tbl(K + 1);
