            psum+=dp[i][0][j];
            psum%=p;
            dp[i+1][1][j]=psum*dp[1][1][j]%p;
            //printf("%lld ",dp[i+1][1][j]);
        }
        //printf(": ");
        for(int j=sqrtn;j>=1;j--){
            psum+=dp[i][1][j];
            psum%=p;
            dp[i+1][0][j]=psum;
            //printf("%lld ",dp[i+1][0][j]);
        }
        //printf("\n");
    }
    ll ans=0;
    for(int j=1;j<=sqrtn;j++){
        ans+=dp[k][0][j]+dp[k][1][j];
        ans%=p;
    }
    printf("%lld\n",ans);
    return 0;
}

