#define MOD 1000000007

int main() {
	set_mod(MOD);
	int N, K;
	cin >> N >> K;

	vector<int> nums;
	for (int n = 1; n * n <= N; n++)
		nums.push_back(n);
	for (int n = nums[nums.size() - 1]; n >= 1; n--)
		nums.push_back(N / n);
	if (nums[nums.size() / 2 - 1] == nums[nums.size() / 2])
		nums.erase(nums.begin() + nums.size() / 2);

	const int nsize = (int)nums.size();
	vector<int> subs(nsize);
	subs[0] = 1;
	for (int i = 1; i < nsize; i++)
		subs[i] = nums[i] - nums[i - 1];

	vector<vector<Modint>> dp(K + 1, vector<Modint>(nsize, 0));
	dp[0][0] = 1;
	for (int k = 1; k <= K; k++)
	{
		vector<Modint> dpksum(nsize);
		dpksum[0] = dp[k - 1][0];
		for (int i = 1; i < nsize; i++)
			dpksum[i] = dpksum[i - 1] + dp[k - 1][i];

		for (int i = 0; i < nsize; i++)
			dp[k][i] = dpksum[nsize - 1 - i] * subs[i];
	}

	Modint ans = 0;
	for (int i = 0; i < nsize; i++)
		ans += dp[K][i];
	cout << ans << endl;
	return 0;
}

