  cout << fixed << setprecision(15);

  int n, k;
  cin >> n >> k;
  int rootn = sqrt(n);
  using mint = ModInt<MOD>;
  vector<int> num(rootn + 1);
  int pre = rootn;
  rrep1 (i, rootn) {
    num[rootn - i + 1] = n / i - pre;
    pre = n / i;
  }
  vector<vector<mint>> dp(k + 1, vector<mint>(2 * rootn + 1)), dpcsum(k + 1, vector<mint>(2 * rootn + 1));
  fill(all(dp[1]), 1);
  irep (i, 2, k + 1) {
    rep1 (j, rootn) {
      dpcsum[i - 1][j] = dpcsum[i - 1][j - 1] + dp[i - 1][j];
    }
    rep1 (j, rootn) {
      dpcsum[i - 1][rootn + j] = dpcsum[i - 1][rootn + j - 1] + dp[i - 1][rootn + j] * num[j];
    }
    rep1 (j, rootn) {
      dp[i][j] = dpcsum[i - 1][2 * rootn - j + 1];
      dp[i][2 * rootn - j + 1] = dpcsum[i - 1][j];
    }
  }
  mint ans = 0;
  rep1 (x, rootn) {
    ans += dp[k][x];
  }
  rep1 (x, rootn) {
    ans += dp[k][x + rootn] * num[x];
  }
  cout << ans << endl;
  return 0;
}

