const int mod = 1000000007;

struct mint {
    ll x; // typedef long long ll;
    mint(ll x = 0) : x((x % mod + mod) % mod) {}

    mint &operator+=(const mint a) {
        if ((x += a.x) >= mod) x -= mod;
        return *this;
    }

    mint &operator-=(const mint a) {
        if ((x += mod - a.x) >= mod) x -= mod;
        return *this;
    }

    mint &operator*=(const mint a) {
        (x *= a.x) %= mod;
        return *this;
    }

    mint operator+(const mint a) const {
        mint res(*this);
        return res += a;
    }

    mint operator-(const mint a) const {
        mint res(*this);
        return res -= a;
    }

    mint operator*(const mint a) const {
        mint res(*this);
        return res *= a;
    }

    mint pow(ll t) const {
        if (!t) return 1;
        mint a = pow(t >> 1);
        a *= a;
        if (t & 1) a *= *this;
        return a;
    }

    // for prime mod
    mint inv() const {
        return pow(mod - 2);
    }

    mint &operator/=(const mint a) {
        return (*this) *= a.inv();
    }

    mint operator/(const mint a) const {
        mint res(*this);
        return res /= a;
    }

    friend std::istream &operator>>(std::istream &in, mint &o) {
        ll a;
        in >> a;
        o = a;
        return in;
    }

    friend std::ostream &operator<<(std::ostream &out, const mint &o) {
        out << o.x;
        return out;
    }

};

map<ll, mint> map_csum(map<ll, mint> m) {
    vector<ll> keys;
    for (auto e : m)keys.push_back(e.first);
    for (int i = 1; i < keys.size(); i++) {
        m[keys[i]] += m[keys[i - 1]];
    }
    return m;
}

int main() {

    ll n;
    int k;
    cin >> n >> k;

    set<ll> candidate;
    for (ll i = 1; i * i <= n; i++) {
        candidate.insert(i);
        candidate.insert(n / i);
    }

    vector<ll> candidate_vec;
    for (ll l : candidate) candidate_vec.push_back(l);
    reverse(candidate_vec.begin(), candidate_vec.end());

    map<ll, int> layer;

    layer[1] = 1;
    for (int i = 1; i < candidate_vec.size(); i++) {
        ll a = n / (candidate_vec[i - 1]);
        ll b = n / candidate_vec[i];

        ll cou = b - a;

        layer[b] = cou;
    }


    vector<map<ll, mint>> dp(k);
    for (auto e : layer) dp[0][e.first] = e.second;
    for (int i = 1; i < k; i++) {

        map<ll,mint> prev = map_csum(dp[i-1]);

        for (auto ej : layer) {
            dp[i][ej.first] += prev[n / ej.first] * ej.second;

        }

    }


    mint ans = 0;
    for (auto e : layer) ans += dp[k - 1][e.first];
    cout << ans << endl;

}

