mint solve() {
    memset(dp, 0, sizeof(dp));

    //COUT(N);

    memset(num, 0, sizeof(num));
    int iter = 0;
    for (long long i = 1; i <= N; ++iter) {
        long long j = N / i;
        if (i <= j) num[iter] = 1, ++i;
        else {
            long long lim = N / j;
            num[iter] = lim - i + 1;
            i = lim + 1;
        }
        //cout << iter << ": " << num[iter] << endl;
