            sdp[j+1] = sdp[j] + dp[k][j];
        }

        for (long long j = 0; j < iter; ++j) {
            dp[k+1][j] = sdp[iter - j] * mint(num[j]);

            //cout << k+1 << ", " << j << ": " << dp[k+1][j] << endl;
        }
    }

    mint res = 0;
    for (long long j = 0; j <= iter; ++j) {
        res += dp[K][j];
    }
    return res;
}

