  while (p * p <= n) {
    a[i] = p;
    b[i] = n / p;
    ++p;
    ++i;
  }
  --p;
  if (p * p == n) --i;
  while (p > 0) {
    a[i] = n / p;
    b[i] = p;
    --p;
    ++i;
  }
  len = i;
}

