  DQ[0][0] = DP[0][0];
  for (int i = 1; i < len; ++i) {
    DP[0][i] = c[i];
    DQ[0][i] = DQ[0][i - 1] + DP[0][i];
  }

  for (int j = 1; j < k; ++j) {
    for (int i = 0; i < len; ++i) {
      int v = len - i - 1;
