        m[i] = v[i] - v[i - 1], f[0][i] = m[i];
    for(int i = 1; i < k; ++i) {
        nx = (i & 1);
        long long sum = 0;
        memset(f[nx], 0, sizeof(f[nx]));
        for(int j = 0; j < sz; ++j) {
            sum += f[nx ^ 1][j];
            sum %= mo;
            f[nx][siz - j - 1] += sum * m[sz - j - 1] % mod;
            f[nx][siz - j - 1] %= mo;
        }
    }
    long long ans = 0;
    for(int i = 0; i < siz; ++i)
        ans += f[nx][i];
    cout << ans % mo << endl;
    return 0;
}

