#define MOD (1000000007LL)

void _main();
int main()
{
    cout << setprecision(12);
    _main();
    return 0;
}

void _main()
{
    ll mul; llin(mul);
    ll len; llin(len);

    S set<ll> rangeset;
    srep (i, 1LL, mul+100LL) {
        ll j = mul / i;
        if (i > j) break;
        rangeset.insert(i);
        rangeset.insert(j);
    }
    S V<ll> ranges;
    for (auto r : rangeset) ranges.pb(r);

    ll rangesize = ranges.size();
    ll bufsize = sizeof(ll) * rangesize;

    S ll dp[100005];
    S ll dp_prev[100005];
    memset(dp, 0, bufsize);
    dp[0] = 1LL;

    rep (c, len) {
        memcpy(dp_prev, dp, bufsize);
        memset(dp, 0, bufsize);

        ll prevcnt = 0LL;
        ll previdx = 0LL;
        ll nextidx = rangesize - 1LL;

        rep (d, rangesize) {
            ll nextleft = ((nextidx < 1) ? 0LL : ranges[nextidx-1]);
            ll nextright = ranges[nextidx];
            prevcnt += dp_prev[previdx];
            prevcnt %= MOD;
            dp[nextidx] = (prevcnt * (nextright - nextleft)) % MOD;
            previdx++;
            nextidx--;
        }
    }

    ll ans = 0LL;
    rep (i, rangesize) {
        ans += dp[i];
        ans %= MOD;
    }

    debug_printf("---- ans\n");
    cout << ans << endl;
}

