int main(void)
{
	ll N, K; cin >> N >> K;

	if (N == 1)
	{
		cout << 1;
		return 0;
	}

	vt<ll> layer;
	if (floor(sqrt(N)) == sqrt(N))
		layer.resize((sqrt(N) - 1) * 2 + 1);
	else
		layer.resize(sqrt(N) * 2);
	layer.resize(Size(layer) + 1);

	// 前半レイヤー構築
	ll j = 1;
	ll r = (sqrt(N) < 2) ? 2 : sqrt(N);
	rep(i, 1, r)
	{
		if (i == 1) { layer[j]++; continue; }
		if (N / (i - 1) == N / i) layer[j]++;
		else layer[++j]++;
	}
	// 中間レイヤー構築
	if (ceil(sqrt(N)) == floor(sqrt(N))) layer[++j]++;
	// 後半レイヤー構築	
	j = Size(layer);
	rep(i, 1, r)
		layer[--j] = abs(N / i - (N / (i + 1) + 1)) + 1;

	vvt<mll> dp = VVT<mll>(K + 1, Size(layer));
	rep(j, 1, Size(layer)) dp[1][j] = dp[1][j - 1] + layer[j];
	rep(i, 2, K + 1) rep(j, 1, Size(layer))
		dp[i][j] = dp[i - 1][Size(layer) - j] * layer[j] + dp[i][j - 1];

	cout << dp[K][Size(layer) - 1];
	return 0;
}

