int main()
{
	ll N, K;
	cin >> N >> K;

	ll len = sqrt(N);
	ll rlen = (len*len == N ? len - 1 : len);
	vector<ll> normal(len + 1, 1);
	normal[0] = 0;
	vector<ll> dup(rlen + 1, 0);
	FOR(i, 1, rlen) dup[i] = N / i - N / (i + 1);
	dup[rlen] = N / rlen - len;
	vector<ll> inv = dup;

	vector<ll> nbit(len + 1), rbit(rlen + 1);
	REP(i, K - 1) {
		fill(nbit.begin(), nbit.end(), 0);
		fill(rbit.begin(), rbit.end(), 0);

		FOR(i, 1, len + 1) {
			(nbit[len] += normal[i]) %= MOD;
			(rbit[i] += normal[i]) %= MOD;
		}
		FOR(i, 1, rlen + 1) {
			(nbit[i] += inv[i]) %= MOD;
		}
		REP(i, rlen)(rbit[i+1] += rbit[i]) %= MOD;
		for (int i = len; i > 1; i--)(nbit[i - 1] += nbit[i]) %= MOD;

		FOR(i, 1, len + 1)normal[i] = nbit[i];
		FOR(i, 1, rlen + 1)inv[i] = rbit[i] * dup[i];
	}

	ll res = accumulate(normal.begin(), normal.end(), 0ll) + accumulate(inv.begin(), inv.end(), 0ll);
	res %= MOD;
	cout << res << endl;
	return 0;
}

