// MOD = 1000000007;
vi quotient_counts(int n) {
  vi ret;
  for (int i = 1; i <= n; i++) {
    int j = n / i;
    if (i <= j) ret.push_back(1);
    else {
      ret.push_back(n / j - i + 1);
      i = n / j;
    }
  }
  return ret;
}

void solve(int n, int k) {
  vi q_cnt = quotient_counts(n);
  int qn = sz(q_cnt);
  vector dp(k + 1, vector<mint>(qn));
  dp[0][0] = 1;
  rep(i, k) {
    vector<mint> cum(qn + 1);
    rep(j, qn) cum[j + 1] = cum[j] + dp[i][j];
    rep(j, qn) dp[i + 1][j] = cum[qn - j] * mint(q_cnt[j]);
  }
  mint ans = 0;
  each(x, dp[k]) ans += x;
  COUT(ans);
}


