    ios::sync_with_stdio(false);

    ll n,k;
    cin >> n >> k;

    set<ll> st;
    for(ll i = 1; i*i <= n; i++){
        st.insert(i);
        st.insert(n/i);
    }

    map<ll,ll> mp;

    ll ok = n+1;
    ll ng = 0;
    for(auto itr = st.begin(); itr != st.end(); itr++){
        ll t = *itr;
        ll tok = ok;
        ll tng = ng;
        while(abs(tok - tng) > 1){
            ll middle = (tok + tng)/2;
            if(n/middle > t){
                tng = middle;
            }else{
                tok = middle;
            }
        }
        mp.insert({t,ok - tok});
        ok = tok;
    }

    map<ll,ll> dp1,dp2;
    for(auto itr = dp1.begin(); itr != dp1.end(); itr++){
        dp2.insert({(*itr).first,0});
    }

    dp2[n] = 1;

    for(int i = 0; i < k; i++){
        ll sum = 0;
        if(i%2 == 0){
            for(auto itr = mp.begin(); itr != mp.end(); itr++){
                auto x = *itr;
                auto y = dp2[n/x.first];
                sum += y;
                sum %= MOD;
                dp2.erase(n/x.first);
                dp1.insert({x.first,sum*x.second});
            }
        }else{
            for(auto itr = mp.begin(); itr != mp.end(); itr++){
                auto x = *itr;
                auto y = dp1[n/x.first];
                sum += y;
                sum %= MOD;
                dp1.erase(n/x.first);
                dp2.insert({x.first,sum*x.second});
            }
        }
    }

    ll ans = 0;

    if(k%2 == 0){
        for(auto itr = dp2.begin(); itr != dp2.end(); itr++){
            ans += (*itr).second;
            ans %= MOD;
        }
    }else{
        for(auto itr = dp1.begin(); itr != dp1.end(); itr++){
            ans += (*itr).second;
            ans %= MOD;
        }
    }

    cout << ans << endl;

    return 0;
}

