	while (1) {
		if (i > N)
			break;
		int j = N / i;
		if (i <= j) {
			num.push_back(1);
			i++;
		} else {
			num.push_back(N / j - i + 1);
			i = N / j + 1;
		}
	}
	M = num.size();
	vector< vector< int > > dp(K + 1, vector< int >(M + 1, 1));
	vector< vector< int > > S(K + 1, vector< int >(M + 1, 0));
	rep(j, M) S[0][j + 1] = 1;
	rep(i, K) rep(j, M) {
		(dp[i + 1][j + 1] = S[i][M - j] * num[j]) %= MOD;
		(S[i + 1][j + 1] = S[i + 1][j] + dp[i + 1][j + 1]) %= MOD;
	}
	int ans = S[K][M];
	cout << ans << endl;
	//cout << num;
	//cout << dp;
	return 0;
}

