LL solve(LL K, LL N) {

	auto f = [](LL n) {
		// make a group
		vector<mint>ret;
		for (LL i = 1; i <= n;) {
			LL j = n / i;
			if (i <= j) {
				ret.push_back(1);
				i++;
			}
			else {
				ret.push_back(n / j - i + 1);
				DD(de(i, n / j + 1,j));
				i = n / j + 1;
			}
		}
		//for (auto it : ret) {
		//	cout << it.get() << ", ";
		//}cout << endl;
		return ret;
	};
	vector<mint> x = f(N);
	int sz = (int)x.size();
	vector<mint>dp(sz + 1, 0);
	dp[0] = 1;
	FOR(k, 0, K) {
		vector<mint>csum(sz + 1, 0);
		FOR(i, 0, sz) {
			csum[i + 1] += csum[i] + dp[i];
		}
		auto dpquery = [&](int L, int R) {
			return csum[R] - csum[L];
		};
		vector<mint>nx(sz + 1, 0);
		FOR(i, 0, sz) {
			nx[i] += x[i] * dpquery(0, sz - i);
		}
		nx.swap(dp);
	}

	mint res = 0;
	for (auto it : dp)res += it;

	return res.get();
}

LL x(LL a, LL N, LL K, LL cnt) {
	if (cnt == K) {
		return 1;
	}
	else {
		LL ret = 0;
		FOR(i, 1, N + 1) {
			if (a*i <= N) {
				ret += x(i, N, K, cnt + 1);
			}
			else break;
		}
		return ret;
	}
}


int main() {
	cin.tie(0);
	ios_base::sync_with_stdio(false);

	LL N, K; cin >> N >> K;
	cout << solve(K, N) << endl;
	//DD(de(x(1, N, K, 0)));
	return 0;
	auto f = [](LL K, LL n) {
		LL ret = x(1, n, K, 0);
		return ret;
	};

	FOR(K, 1, 5) {
		FOR(n, 1, 50) {
			LL ans = f(K, n);
			DD(de(K, n, ans, solve(K, n)));
		}

	}

	return 0;
}

