mint dp[110][111000];
mint sdp[111000];
long long num[111000];

mint solve() {
  //各レイヤーの個数
  int iter = 0;
  for(int i = 1; i <= N; ) {
    int j = N / i;
    if(j >= i) {
      // sqrt(N)以下
      num[iter++] = 1;
      ++i;
    } else {
      // sqrt(N)以上
      num[iter++] = N/j - i + 1;
      i = N/j + 1;
    }
  }

  memset(dp, 0, sizeof(dp));
  dp[0][0] = 1; //長さ0の場合は1で初期化する(*numされる対象となる)
  for(int k=0; k<K; ++k) {
    //現在のkの累積和を計算
    memset(sdp, 0, sizeof(sdp));
    for(int j=0; j<iter; ++j) sdp[j+1] = sdp[j] + dp[k][j];
    for(int j=0; j<iter; ++j) dp[k+1][j] = sdp[iter - j] * mint(num[j]);
  }

  mint res = 0;
  for(int j=0; j<iter; ++j) res += dp[K][j];
  return res;
}

int main() {
  cin >> N >> K;
  cout << solve() << endl;
}

