int main() {
	cin >> N >> K;
	for (int i = 1; i*i <= N; i++) SQRT = i;

	for (int i = 1; i <= SQRT; i++) { dp[1][i] = 1; }
	for (int i = 2; i <= K; i++) {
		long long sum = 0;
		for (int j = 1; j <= SQRT; j++) sum += dp[i - 1][j];
		sum %= mod;
		for (int j = 1; j <= SQRT; j++) dp[i][j] = sum;

		if (i == 2) {
			for (int j = 1; j <= SQRT; j++) {
				dp[i][j] += ((N / j) - SQRT);
				dp[i][j] %= mod;
			}
		}
		if (i >= 3) {
			long long rem = 0;
			for (int j = 0; j <= SQRT; j++) r[j] = 0;
			for (int j = 1; j <= SQRT; j++) {
				rem += dp[i - 2][j]; rem %= mod;
				r[j] += rem * ((N / j) - max(SQRT, N / (j + 1)));
				r[j] %= mod;
			}
			long long ret = 0;
			for (int j = SQRT; j >= 1; j--) {
				ret += r[j]; ret %= mod;
				dp[i][j] += ret;
				dp[i][j] %= mod;
			}
		}
	}

	long long ans = 0;
	for (int i = 1; i <= SQRT; i++) { ans += dp[K][i]; ans %= mod; }
