struct point {
    int x, y;

    void read() {
        scan(x, y);
    }

    ll cross(const point &b) const {
        return 1LL * x * b.y - 1LL * y * b.x;
    }

    point operator-(const point &b) const {
        return {x - b.x, y - b.y};
    }

    bool para(const point &b) const { // parallel
        return 1LL * x * b.y == 1LL * y * b.x;
    }

    bool operator<(const point &b) const {
        return cross(b) < 0;
    }
};

struct segment {
    point p, dir;

    bool on_same_line(const segment &other) const {
        return dir.para(other.dir) && (p - other.p).para(dir);
    }

    bool para(const segment &b) const {
        return dir.para(b.dir);
    }

    bool operator==(const segment &b) const {
        return this->on_same_line(b);
    }
};
struct fraction {
    int n, d;
    bool operator<(const fraction& that) const {
        return 1LL * n * that.d < 1LL * that.n * d;
    }
    bool operator==(const fraction& that) const {
        return n == that.n && d == that.d;
    }
    bool operator>=(const fraction& that) const {
        return !(*this < that);
    }
    bool operator>(const fraction& that) const {
        return 1LL * n * that.d > 1LL * that.n * d;
    }
    fraction inverse() const {
        return n < 0 ? fraction{-d, -n} : fraction{d, n};
    }
    fraction(int n, int d) {
        if (d < 0) n = -n, d = -d;
        int g = __gcd(abs(n), d);
        n /= g, d /= g;
        this->n = n, this->d = d;
    }
    explicit fraction(int x): n(x), d(1) {}
    fraction operator+(const fraction& that) const {
        return fraction{n * that.d + that.n * d, d * that.d};
    }
    fraction operator-(const fraction& that) const {
        return fraction{n * that.d - that.n * d, d * that.d};
    }
    fraction floor() const {
        if (d == 0) return *this;
        return fraction((n < 0 ? n - (d - 1) : n) / d);
    }
    friend ostream& operator<<(ostream& out, const fraction& f) {
        return out << "(" << f.n <<',' << f.d << ')';
    }
    pii to_pair() const {
        return {n, d};
    }
};
using Num = modnum<mod>;
struct Binom {
    vector<Num> f;
    explicit Binom(int n){
        f.resize(n + 1);
        f[0] = 1;
        up (i, 1, n) f[i] = f[i - 1] * i;
    }
    Num get_binom(int x, int y) const {
        assert(x <= SZ(f) - 1);
        assert(x >= 0 && y >= 0);
        if (x < y) return 0;
        return f[x] / (f[y] * f[x - y]);
    }
    Num get_fact(int n) const {
        assert(n < SZ(f));
        return f[n];
    }
};

//https://codeforces.com/blog/entry/22072
struct HLD {
    HLD(int n, int* heavy_son, int* fa, int* depth) : top(n + 1), pos(n + 1), depth(depth), fa(fa) {
        int index = 0;
        // 节点编号从1开始
        for (int i = 1; i <= n; i++) {
            if (i != heavy_son[fa[i]]) {
                for (int j = i; j != 0; j = heavy_son[j]) {
                    top[j] = i;
                    pos[j] = ++index; // pos从1开始
                }
            }
        }
    }
    template <typename BinOpr>
    //返回值是 LCA(u,v)
    int process_path(int u, int v, BinOpr op, bool value_on_edge = false) const {
        while (top[u] != top[v]) {
            if (depth[top[u]] < depth[top[v]]) swap(u, v);
            op(pos[top[u]], pos[u]);
            u = fa[top[u]];
        }
        if (depth[u] > depth[v]) swap(u, v);
        op(pos[u] + value_on_edge, pos[v]);
        return u;
    }
    vector<int> top, pos; // pos从0开始
    const int *depth, *fa;
};

