        else r=mid;
    }
    return l;
}

bool square(long long val) {
    long long x=sqrt(val);
    return (x*x==val);
}

void hen() {
    flag=square(n);
    sqr=sqrt(n);
    rep(i, 1, sqr) v.push_back(n/i);

    Unique();
    rep(i, 1, sqr) {
        f[1][i]=1;
        sum[1][i]=i;
        sumlen[1][i]=sumlen[1][i-1];
        add(sumlen[1][i], number(n/i));
    }
    rep(i, 0, (long long)v.size()-1) g[1][i]=v[i];

    rep(i, 2, k) {
        rep(j, 1, sqr) {
            add(f[i][j], g[i-1][Find(n/j)]);

            sum[i][j]=sum[i][j-1];
            add(sum[i][j], f[i][j]);
            sumlen[i][j]=sumlen[i][j-1];
            add(sumlen[i][j], (1ll*f[i][j]*number(n/j))%mod);
        }

        if(i<k) {
            rep(j, 0, (long long)v.size()-1) {
                long long val=v[j];
                add(g[i][j], sum[i][sqr]);
                long long id=Search(val);
                add(g[i][j], (1ll*sum[i-1][id]*number(val))%mod);
                add(g[i][j], (0ll+sumlen[i-1][sqr]-sumlen[i-1][id]+mod)%mod);
            }
        } else {
            long long ans=0;
            add(ans, sum[k][sqr]);
            add(ans, sumlen[k-1][sqr]);
            if(flag) ans-=f[k][sqr];
            cout << ans;
        }
    }
}


