const int MAX=32000;
const ll MOD=1e9+7;

ll adm(ll a, ll b){
	if(a+b<MOD)return a+b;
	else return a+b-MOD;
}

ll tim(ll a, ll b){
	return (a*b)%MOD;
}

int N,K;
void input(){
	cin>>N>>K;
}

int s,t;
ll dp1[105][MAX];
ll dp2[105][MAX];
ll tmp[105];

void solve(){
	s=sqrt(N);
	if(N<s*(s+1))t=s-1;
  	else t=s;
	ll mul[MAX];
	rep1(i,s)mul[i]=(ll)N/i-N/(i+1);

  	if(t==s-1){
		rep1(i,s)dp1[1][i]=1;
		rep1(i,s)dp2[1][i]=1;

		rep1(k,K-1){
			rep1(i,s)dp2[k+1][i]=adm(dp2[k+1][i-1], dp1[k][i]);
			dp1[k+1][s]=dp2[k+1][s];
			for(int i=s-1; i>=1; i--){
				dp1[k+1][i]=adm(dp1[k+1][i+1], tim(dp2[k][i],mul[i]));
   	    	 }
		}
		ll ans=0;
		rep1(i,t)ans=adm(ans, dp1[K][i]);
		rep1(i,s)ans=adm(ans, tim(dp2[K][i], mul[i]));
		cout<<ans<<endl;
	}

	else{
		rep1(i,s)dp1[1][i]=1;
		rep1(i,s)dp2[1][i]=1;

		rep1(k,K-1){
			rep1(i,s)dp2[k+1][i]=adm(dp2[k+1][i-1], dp1[k][i]);
			dp1[k+1][s]=adm(dp2[k+1][s], tim(mul[s],dp2[k][s]));
			for(int i=s-1; i>=1; i--){
				dp1[k+1][i]=adm(dp1[k+1][i+1], tim(dp2[k][i],mul[i]));
   	    	 }
		}
		ll ans=0;
		rep1(i,s)ans=adm(ans, dp1[K][i]);
		rep1(i,s)ans=adm(ans, tim(dp2[K][i], mul[i]));
		cout<<ans<<endl;
	}
}


