const int MOD = 1e9 + 7;

int main() {
    int n, k; cin >> n >> k;
    vector<int> bnd{};
    int boundary = 1;
    int div = n;
    while(boundary <= n){
        bnd.push_back(boundary);
        if(n / boundary != n / (boundary+1)){
            boundary++;
            div = n / boundary;
        } 
        else{
            if(div <= 0){ break;}
            boundary = n / div + 1; 
            div--;
        }
    }
    bnd.push_back(n+1);
    int length = (int)bnd.size() - 1;
    vector<vector<ll>> dp(k, vector<ll>(length, 0));
    for(int i=0; i<length; i++){
        dp[0][i] = bnd[i+1] - bnd[i];
    }
    for(int i=0; i<k-1; i++){
        vector<ll> cumsum(length+1, 0);
        for(int j=0; j<length; j++){
            cumsum[j+1] = cumsum[j] + dp[i][j];
            cumsum[j+1] %= MOD;
        }
        for(int j=0; j<length; j++){
            dp[i+1][j] += dp[0][j] * cumsum[length - j]; 
            dp[i+1][j] %= MOD;
        }
    }

    // Debug
    // for(auto& line:dp){
    //     for(auto& v:line){
    //         cout << v << " ";
    //     }
    //     cout << endl;
    // }
    ll ans = 0;
    for(auto& v:dp[k-1]){
        ans += v;
        ans %= MOD;
    }
    cout << ans << endl;
    return 0;
}

