constexpr int MOD = 1000000007;

int main()
{
    int N, K;
    cin >> N >> K;
    vector<int> vp;
    for (int i = 1; i * i <= N; i++)
    {
        vp.emplace_back(i);
        if (i != N / i) vp.emplace_back(N / i);
    }
    sort(vp.begin(), vp.end());
    REP(i, vp.size() - 1) vp[i] = vp[i + 1] - vp[i];
    vector<int> dp(vp.size());
    dp[0] = 1;
    REP(_, K)
    {
        reverse(dp.begin(), dp.end());
        IREP(i, dp.size() - 1)
        {
            (dp[i] += dp[i + 1]) %= MOD;
            dp[i + 1] = dp[i + 1] * (lint)vp[i] % MOD;
        }
    }
    cout << accumulate(dp.begin(), dp.end(), 0LL) % MOD << endl;
}

