const int M = 1e9 + 7;

int32_t main() {

  ios::sync_with_stdio(false);
  cout.tie(nullptr);
  cin.tie(nullptr);

  int n, k;
  cin >> n >> k;

  int last = 0;
  vector<int> val, num;
  vector<vector<long long>> dp;
  for (int i = 1; i * i <= n; ++i) {
    int l = n / (i + 1) + 1, r = n / i;
    val.push_back(r);
    num.push_back(r - l + 1);
    last = l;
  }
  for (int i = last - 1; i > 0; --i) val.push_back(i), num.push_back(1);
  reverse(val.begin(), val.end());
  reverse(num.begin(), num.end());
  dp.resize(k + 1, vector<int> (num.size(), 0));
  dp[0][0] = 1;

  int m = num.size(); 
  for (int i = 1; i <= k; ++i) {
    long long sum = 0, j = m - 1;
    for (int i2 = 0; i2 < m; ++i2) sum = (sum + dp[i - 1][i2]) % M; 
    for (int i2 = 0; i2 < m; ++i2) {
      while (1ll * val[j] * val[i2] > n) {
        sum -= dp[i - 1][j--];
        if (sum < 0) sum += M;
      }
      dp[i][i2] = sum * num[i2] % M;
    }
  }

  long long ans = 0;
  for (int i = 0; i < m; ++i) ans = (ans + dp[k][i]) % M;
  cout << ans << '\n';
}

