bool pair_comp(pair<ll,ll> a, pair<ll,ll> b) {
  if(a.first == b.first) return a.second > b.second;
  else return a.first > b.first;
}

int main(int argc, char *argv[]) {
  int n,k;
  cin >> n >> k;

  vector<pair<ll,ll> > g;
  pair<ll,ll> p;
  int i0 = floor( (1+sqrt(4*n+1))/2 );
  p.first = n/i0; p.second = n/(n/i0) - n/(n/i0+1);
  g.push_back(p);
  for(int i = 1; i < i0; i++) {
    p.first = n/i; p.second = 1;
    g.push_back(p);
    if(i<n/i0) {
      p.first = i; p.second = n/i - n/(i+1);
      g.push_back(p);
    }
  }
  sort(g.begin(),g.end(),pair_comp);
  //rep(i,0,g.size()) cout << g[i].first << " " << g[i].second << endl;



  ll **a = new ll*[g.size()];
  ll *ruiseki = new ll[g.size()];
  rep(i,0,g.size()) {a[i] = new ll[k];}
  rep(i,0,g.size()) {a[i][0] = 1;}
  rep(l,1,k) {
    ruiseki[0] = a[0][l-1];
    rep(i,1,g.size()) {
      ruiseki[i] = ruiseki[i-1] + a[i][l-1]*g[i].second;
      ruiseki[i] %= MOD;
    }
    rep(i,0,g.size()) {
      a[i][l] = ruiseki[g.size()-i-1];
    }
  }



  ll answer = 0;
  rep(i,0,g.size()) {
    answer = (answer + a[i][k-1]*g[i].second)%MOD;
  }
  cout << answer << endl;



  return 0;
}

