ll dp[102][112345];
ll dp1[102][112345], dp2[102][112345]; // dp1:下から累積和 i以下, dp2: 上から*cnt累積和 i以上

ll solve(int N, int K) {
	ll X = 1;
	while (X * X <= N) X++;
	X--;

	dp[0][1] = 1;

	REP(i, K + 1) {
		FOR(j, 1, X + 1) dp1[i][j] = (dp1[i][j - 1] + dp[i][j]) % MOD;
		for (int j = X; j > 0; j--) dp2[i][j] = (dp2[i][j + 1] + dp[i][j] * (N / j - X) % MOD) % MOD;

		FOR(j, 1, X + 1) {
			if (i > 0) {
				(dp[i + 1][j] += dp1[i - 1][j - 1] * (N / j - X) % MOD) %= MOD; // k overX j (k < j)
				(dp[i + 1][j] += dp2[i - 1][j]) %= MOD; // k overX j (k >= j)
			}
			(dp[i + 1][j] += dp1[i][X]) %= MOD; // X以下, j
		}

	}

	return dp[K + 1][1];
}

int main() {
	int N, K;
	cin >> N >> K;

	cout << solve(N, K) << endl;
	return 0;
}

