            dpS[j][i] = curSum;
        }
        curSum = 0;
        F0R(j, root) {
            curSum += preL[j];
            curSum = curSum % MOD;
            preL[j] = 0;

            dpL[j][i] = (curSum*countLarge[j]) % MOD;
        }

        F0R(j, root) {
            ll maxVal = N / (j+1);
            if (maxVal > root) maxVal = root;
            sufS[maxVal-1] += dpS[j][i];
            sufS[maxVal-1] = sufS[maxVal-1] % MOD;
            preL[j] += dpS[j][i];
            preL[j] = preL[j] % MOD;
        }

        F0R(j, root) {
            sufS[j] += dpL[j][i];
            sufS[j] = sufS[j] % MOD;
        }
    }

    ll ans = 0;
    F0R(i, root) {
        ans += dpL[i][K-1] + dpS[i][K-1];
        ans %= MOD;
    }

    cout << ans << endl;


    return 0;
}

