    vector<ll> cnt(2 * sq + 1, 1);
    cnt[0] = 0;
    for (int i = 1; i <= sq; i++)
    {
        cnt[2 * sq - i + 1] = n / i % MOD;
        if (i != 1)
            cnt[2 * sq - i + 2] = (cnt[2 * sq - i + 2] + MOD - n / i) % MOD;
    }
    cnt[sq + 1] = (cnt[sq + 1] + MOD - sq) % MOD;
    SegmentTree<RangeSumQuery> st(2 * sq + 1);
    vector<SegmentTree<RangeSumQuery>> dp(k, st);
    dp[0] = SegmentTree<RangeSumQuery>(cnt);
    for (int i = 1; i < k; i++)
    {
        for (int j = 1; j <= 2 * sq; j++)
        {
            dp[i].update(j, cnt[j] * dp[i - 1].query(1, 2 * sq + 2 - j) % MOD);
        }
    }
    cout << dp[k - 1].query(1, 2 * sq + 1) << endl;
