int main() {
  ll N,K;
  cin>>N>>K;
  map<ll,ll> m;
  ll t = 1LL;
  while(t*(t+1LL)<N){
    m[N/t]=1LL;
    m[t]=(N/t-N/(t+1));
    t++;
  }
  if(t*(t+1LL)==N){
    m[t]=1LL;
    m[t+1LL]=1LL;
  }
  else {
    if(m[N/t]==0) m[N/t]=1LL;
  }
  ll l = m.size();
  vector<ll> v(l);
  ll i = 0LL;
  for(auto x:m){
    v[i]=(x.second)%mod;
    i++;
  }
  reverse(v.begin(),v.end());
  vector<ll> dp(l,0LL);
  dp[0]=1LL;
  for(ll j = 0LL; j < K; j++){
    vector<ll> S(l);
    for(ll k = 0LL; k < l; k++){
      if(k==0LL) S[k]=dp[k]%mod;
      else S[k]=(dp[k]+S[k-1])%mod;
    }
    for(ll k = 0LL; k < l;k++){
      dp[k]=((S[l-k-1LL]%mod)*(v[k]%mod))%mod;
    }
  }
  ll ans = 0LL;
  for(auto x:dp) ans=(ans+x)%mod;
  cout<<ans<<endl;
}

