int MOD_N = (10 * 10 * 10) * (10 * 10 * 10) * (10 * 10 * 10) + 7;

int main() {
    int N, K;
    cin >> N; cin >> K;
    int **counts = new int*[K-1];
    for (int k = 0; k < K - 1; ++k) {
        counts[k] = new int[N];
    }
    for (int n = 1; n <= N; ++n) {
        int q = N / n;
        counts[0][n - 1] = q;
    }
    for (int k = 3; k <= K; ++k) {
        for (int n = 1; n <= N; ++n) {
            int q = N / n;
            int c;
            if (n > 2 && q == (N / (n - 1))) {
                c = counts[k - 2][n - 2];
            } else {
                c = 0;
                for (int m = 1; m <= q; ++m) {
                    c += counts[k - 3][m - 1];
                    if (c > MOD_N) {
                        c -= MOD_N;
                    }
                }
            }
            counts[k - 2][n - 1] = c;
        }
    }
    int count = 0;
    for (int n = 1; n <= N; ++n) {
        count += counts[K-2][n-1];
        if (count > MOD_N) {
            count -= MOD_N;
        }
    }
    cout << count << "\n";
    return 0;
}

