vector<long long> get_array(int n) {
  int root_n = (int)sqrt(n);
  vector<long long> array(root_n, 1);
  for (int i = n / root_n - 1; i >= 1; i--) {
    int add = n / i - n / (i + 1);
    if (add != 0) {
      array.push_back((long long)add);
    }
  }
  return array;
}
const long long MOD = 1000000007;

int main() {
  int max, length;
  cin >> max >> length;

  vector<long long> array = get_array(max);
  int size = array.size();

  int dp[length][size] = {};
  for (int i = 0; i < size; i++) {
    dp[0][i] = array[i];
  }

  for (int current = 1; current < length; current++) {
    int pre = current - 1;
    long long sum_pre = 0;
    for (int i = 0; i < size; i++) {
      sum_pre += dp[pre][i];
    }
    for (int i = 0; i < size; i++) {
      dp[current][i] = (int)(((sum_pre % MOD) * array[i]) % MOD);
      sum_pre -= dp[current - 1][size - 1 - i];
    }
  }
  long long ans = 0;
  for (int i = 0; i < size; i++) {
    ans = (ans + dp[length - 1][i]) % MOD;
  }
  cout << ans % MOD << endl;

  return 0;
}

#include <iostream>
#include <map>
#include <vector>
using namespace std;
using large = long long;
constexpr int mod = 1'000'000'007;

struct X {
    int first;
    int last;
    int mem_cnt;
};

static int solve(const int n, const int k) {
    auto ranges = vector<X>();
    for (int div = 1; div <= n;) {
        auto x = X();
        x.first = div;
        x.last = n / (n / div);
        x.mem_cnt = x.last - x.first + 1;
        ranges.push_back(x);
        div = x.last + 1;
    }

    auto dp = vector<vector<int>>(k + 1, vector<int>(ranges.size()));
    dp[0] = vector<int>(ranges.size(), 1);

    for (int i = 0; i < k; ++i) {
        int acc = 0;
        for (int ri = 0; ri < ranges.size(); ++ri) {
            int cnt = (large(dp[i][ranges.size() - 1 - ri]) * ranges[ri].mem_cnt) % mod;
            dp[i + 1][ri] = ((acc += cnt) %= mod);
        }
    }

    return dp[k][ranges.size() - 1];
}

int main() {
    int n, k;
    cin >> n >> k;
    cout << solve(n, k);
    return 0;
}

