const int M = (int) 1e9 + 7;

int add(int a, int b) {
        a += b;
        if (a >= M)
                a -= M;
        if (a < 0)
                a += M;
        return a;
}

int mul(int a, int b) {
        return a * (ll) b % M;
}

int n, k;
int func(int i) {
        return n / (n / i);
}

const int N = (int) 1e5 + 7;
int dp[2][N];
int sum[N];

int get_sum(int l, int r) {
        if (l == 0)
                return sum[r];
        return sum[r] - sum[l - 1];
}

int main() {
        ios_base::sync_with_stdio(false);
        cin.tie(0), cout.tie(0);

        cin >> n >> k;
        vector <int> a;
        vector <int> b;
        int i = 1;
        while (i <= n) {
                int j = func(i);
                a.push_back(i);
                b.push_back(j);
                i = j + 1;
        }

        int sz = (int) a.size();
        for (int i = 0; i < sz; i++) {
                int l = a[i], r = b[i];
                dp[1][i] = (r - l + 1);
        }

        for (int ln = 2; ln <= k; ln++) {
                int now = ln % 2, last = 1 - now;
                int cur = 0;
                for (int i = 0; i < sz; i++) {
                        cur = add(cur, dp[last][i]);
                        sum[i] = cur;
                }
                for (int i = 0; i < sz; i++) {
                        int l = a[i], r = b[i];
                        dp[now][i] = mul(r - l + 1, sum[sz - i - 1]);
                }
        }

        int res = 0, cur = k % 2;
        for (int i = 0; i < sz; i++)
                res = add(res, dp[cur][i]);
        cout << res << "\n";

