        b = r;
    }
    FOR(i, 1, b) s.insert(i);
    vec v;
    for(int i: s) v.pb(i);
    //vdebug(v);
    int n = SZ(v);
    vec num(n);
    REP(i, n){
        if(i == 0) num[i] = 1;
        else num[i] = v[i] - v[i - 1];
    }
    vec dual(n);
    REP(i, n){
        int x = N / v[i];
        dual[i] = Lower_bound(v, x);
    }
    //vdebug(dual);
    //vdebug(num);

    mmat dp(K + 1, mvec(n + 1, 0));
    dp[0][0] = 1;
    REP(i, K){
        mint S = 0;
        REP(j, n){
            S += dp[i][j] * num[j];
            dp[i][j] = S;
        }
        REP(j, n){
            dp[i + 1][j] = dp[i][dual[j]];
        }
    }
    //mdebug(dp);
    mint ans = 0;
    REP(j, n) ans += dp[K][j] * num[j];
    Out(ans);

    return 0;
}

#include <iostream>
