int MOD_N = (10 * 10 * 10) * (10 * 10 * 10) * (10 * 10 * 10) + 7;
long MOD_100N = 100 * MOD_N;

int main() {
    int N, K;
    cin >> N; cin >> K;
    vector<int> nums;
    nums.push_back(1);
    for (int n = 2; n < N; ++n) {
        if ((N/(n-1)) != N/n) {
            nums.push_back(n);
        }
    }
    int nums_n = nums.size();
    long **counts = new long*[K-1];
    for (int k = 0; k < K - 1; ++k) {
        counts[k] = new long[nums_n];
    }
    for (int i = 0; i < nums_n; ++i) {
        int n = nums[i];
        counts[0][i] = N / n;
    }
    long sums[nums_n];
    for (int k = 3; k <= K; ++k) {
        sums[0] = counts[k - 3][0];
        for (int i = 1; i < nums_n; ++i) {
            int m = nums[i - 1];
            int n = nums[i];
            long c = sums[i - 1] + counts[k - 3][i - 1] * (n - m - 1) + counts[k - 3][i];
            if (c > MOD_100N) {
                c %= MOD_N;
            }
            sums[i] = c;
        }
        for (int i = 0, j = nums_n - 1; i < nums_n; ++i) {
            int n = nums[i];
            int q = counts[0][i]; // N / n;
            while (nums[j] > q) { j--; }
            long c = sums[j];
            c += counts[k - 3][j] * (q - nums[j]);
            if (c > MOD_100N) {
                c %= MOD_N;
            }
            counts[k - 2][i] = c;
        }
    }
    long count = counts[K - 2][0];
    for (int i = 1; i < nums_n; ++i) {
        int m = nums[i - 1];
        int n = nums[i];
        count += counts[K - 2][i - 1] * (n - m - 1) + counts[K - 2][i];
        if (count > MOD_100N) {
            count %= MOD_N;
        }
    }
    count += counts[K - 2][nums_n - 1] * (N - nums[nums_n - 1]);
    if (count > MOD_N) {
        count %= MOD_N;
    }
    cout << count << "\n";
    return 0;
}

