using namespace std;

const int mod = 1e9 + 7;

const int N = 105;
const int M = 4e4 + 5;

int dp[N][2][M];

int add(int x, int y) {
	int ret = (x + y);
	if (ret < 0) {
		ret += mod;
	}
	if (ret >= mod) {
		ret -= mod;
	}
	return ret;
}
int mul(int x, int y) {
	return (long long)x*y%mod;
}

int cc[M];

void solve() {
	int n, k;
	scanf("%d %d", &n, &k);
	int SQ = sqrt(n);
	while ((SQ + 1)*(SQ + 1) <= n) ++SQ;
	for (int i = 1; i <= SQ; ++i) {
		++dp[1][0][i];
	}
	for (int st = SQ + 1; st <= n;) {
		int l = st, r = n, mid;
		int v = n / st;
		while (l < r) {
			mid = (l + r + 1) / 2;
			if (n / mid != v) {
				r = mid - 1;
			}
			else {
				l = mid;
			}
		}
		dp[1][1][v] = l - st + 1;
		cc[v] = l - st + 1;
		st = l + 1;
	}
	int tmp1[M], tmp2[M];
	int maxi = n / (SQ + 1);
	for (int ind = 2; ind <= k; ++ind) {
		//만약 bit == 0 이라면 우선적으로 1부터 SQ까지 모든 값이 똑같이 더해지게 된다. 
		//bit==0 이라면 bit==1 에 대해서는 상태 dp[ind][1][x]에 dp[ind-1][0][x]의 값이 더해지게 된다.
		//만약 bit==1 이라면 사실 dp[ind][0][y] (1<=y<=x)까지 모두 dp[ind-1][1][x]의 값이 더해지게 된다.
		int sum = 0;
		memset(tmp1, 0, sizeof(tmp1));
		memset(tmp2, 0, sizeof(tmp2));

		for (int x = 1; x <= SQ; ++x) {
			sum = add(sum, dp[ind - 1][0][x]);
			tmp2[maxi] = add(tmp2[maxi], dp[ind - 1][0][x]);
			tmp2[x -1] = add(tmp2[x-1], -dp[ind - 1][0][x]);
		}
		tmp1[0] = sum;
		for (int x = 1; x <= SQ; ++x) {
			tmp1[0] = add(tmp1[0], dp[ind - 1][1][x]);
			tmp1[x + 1] = add(tmp1[x + 1], -dp[ind - 1][1][x]);
		}
		for (int x = 1; x <= SQ; ++x) {
			tmp1[x] = add(tmp1[x], tmp1[x - 1]);
			dp[ind][0][x] = tmp1[x];
		}

		for (int x = maxi; x >= 1; --x) {
			tmp2[x] = add(tmp2[x], tmp2[x + 1]);
			dp[ind][1][x] = mul(tmp2[x], cc[x]);
		}
	}
	int ret = 0;
	for (int x = 1; x <= SQ; ++x) {
		ret = add(ret, dp[k][1][x]);
		ret = add(ret, dp[k][0][x]);
	}
	printf("%d\n", ret);
}
int main() {
	//freopen("input.txt", "r", stdin);
	solve();
}

