int main(void){
	int n, k;
	cin >> n >> k;

	vector<int> ary;
	for(int i = 1; i * i <= n; ++i) {
		const int j = n / i;
		ary.push_back(i);
		ary.push_back(j);
	}

	sort(begin(ary), end(ary));
	const int m = unique(begin(ary), end(ary)) - begin(ary);
	vector<mint> coef(m, 0);


	rep(j, m) {
		const int prv = (j - 1 >= 0) ? ary[j - 1] : 0;
		const int cur = ary[j];
		coef[j] = mint(cur - prv);
		dp[1][j] = coef[j];
	}

	rep(i, 1, k) {
		int pos = m - 1;

		rep(j, m) {
			while(pos >= 0 and 1LL * ary[j] * ary[pos] > n) pos--;
			dp[i + 1][pos] += dp[i][j];
		}

		rrep(j, m) {
			if(j + 1 < m) {
				dp[i + 1][j] += dp[i + 1][j + 1];
			}
		}

		rep(j, m) dp[i + 1][j] *= coef[j];
	}

	mint ans = ZERO;
	rep(j, m) ans += dp[k][j];
	cout << ans << endl;

	return 0;
}

