	for (ll i = 1; i * i <= N; i++)
		layer.push_back(1);
	// 後半レイヤー構築	
	ll r = (sqrt(N) < 2) ? 2 : sqrt(N);
	for (ll i = r - 1; 0 < i; i--)
		layer.push_back(abs(N / i - (N / (i + 1) + 1)) + 1);
