    int64_t sqn;
    for(sqn=1;sqn*sqn<=n;++sqn);
    --sqn;

    vector<int64_t> rg(2*sqn);
    for(int i=1;i<=sqn;++i){
        rg[i-1] = i;
        rg[2*sqn-i] = n/i;
    }

    static int64_t dp[100000][100];    
    dp[0][0] = 1;
    for(int i=1;i<2*sqn;++i){
        dp[i][0] = (rg[i]-rg[i-1]) % mod;
        dp[i][0] = (dp[i][0] + dp[i-1][0]) % mod;
    }
    for(int kk=1;kk<k;++kk){
        dp[0][kk] = dp[2*sqn-1][kk-1] % mod;
        for(int i=1;i<2*sqn;++i){
