            while(ng-ok>1){
                int64_t mid = (ok+ng)/2;
                if(rg[i]*rg[mid] <= n) ok = mid;
                else ng = mid;
            }
            dp[i][kk] = dp[ok][kk-1] * (rg[i]-rg[i-1]) % mod;
            dp[i][kk] = (dp[i][kk] + dp[i-1][kk]) % mod;
        }
