    vector<int> A, C;
    {
        int t = 1;
        while (t < N) {
            A.push_back(N / t);
            C.push_back(N / (N / t));
            t = N / (N / t) + 1;
        }
    }
    int M = A.size();
    vector<Int> dp(M, 1), dp2(M), sum(M);
    for (int i = 1; i < K; i++) {
        sum[0] = C[0] * dp[0] % MOD;
        for (int j = 1; j < M; j++) {
            sum[j] = (sum[j-1] + (C[j] - C[j-1]) * dp[j]) % MOD;
        }
        for (int j = 0; j < M; j++) {
            int t = upper_bound(begin(C), end(C), A[j]) - begin(C) - 1;
            dp2[j] = (sum[t] + (A[j] == C[t] ? 0 : (A[j] - C[t]) * dp[t+1])) % MOD;
        }
        swap(dp2, dp);
    }
    Int ans = C[0] * dp[0];
    for (int i = 1; i < M; i++) {
        ans = (ans + (C[i] - C[i-1]) * dp[i]) % MOD;
    }
