    }
    vector<vector<modll>> dpover(K + 2, vector<modll>(v.size())), dpunder(K + 2, vector<modll>(sqn + 1, 0));
    for (int i = 0; i < v.size(); i++) {
        dpover[1][i] = v[i];
    }
    for (int i = 1; i <= sqn; i++)
        dpunder[1][i] = 1;

    for (int k = 1; k < K; k++) {
        modll tmp = 0;
        for (int i = v.size() - 1; i >= 0; i--) {
            tmp += dpover[k][i];
            dpunder[k + 1][i + 1] += tmp;
        }
        vector<modll> csum(sqn + 1);
        csum[1] = dpunder[k][1];
        for (int i = 2; i <= sqn; i++) {
            csum[i] = csum[i - 1] + dpunder[k][i];
        }
        for (int i = 0; i < v.size(); i++) {
            dpover[k + 1][i] = v[i] * csum[i + 1];
        }
        for (int i = 1; i <= sqn; i++) {
