template<typename T>
struct SegTree {
	T init_val;
	int n;
	vector<T> all, part;

	SegTree() {}
	SegTree(int _n, T init_val) : init_val(init_val) {
		n = 1;
		while (n < _n) n *= 2;
		all.resize(n * 2 - 1, init_val);
		part.resize(n * 2 - 1, init_val);
	}

	// [a,b)の要素にxを加算
	void add(int a, int b, T x, int k = 0, int l = 0, int r = -1) {
		if (r < 0) r = n;

		if (r <= a || b <= l) return;

		if (a <= l && r <= b) {
			(all[k] += x) %= MOD;
		}
		else {
			(part[k] += (min(b, r) - max(a, l)) * x % MOD) %= MOD;
			add(a, b, x, k * 2 + 1, l, (l + r) / 2);
			add(a, b, x, k * 2 + 2, (l + r) / 2, r);
		}
	}

	// [a,b)の合計を求める
	T query(int a, int b, int k = 0, int l = 0, int r = -1) {
		if (r < 0) r = n;

		if (r <= a || b <= l) return init_val;
		if (a <= l && r <= b) return ((r - l) * all[k] % MOD + part[k]) % MOD;

		T res = (min(b, r) - max(a, l)) * all[k] % MOD;
		res += query(a, b, k * 2 + 1, l, (l + r) / 2);
		res += query(a, b, k * 2 + 2, (l + r) / 2, r);
		res %= MOD;
		return res;
	}
};


SegTree<ll> dp[102];

