            e[i][j] += ds[i - 1][j];
            e[i][j] *= b[j];
            d[i][j] %= M;
            e[i][j] %= M;
        }
        for(ll j = x; j >= 1; j--)
        {
            es[i][j] = es[i][j + 1] + e[i][j];
            es[i][j] %= M;
        }
        for(ll j = 1; j <= x; j++)
        {
            ds[i][j] = ds[i][j - 1] + d[i][j];
            ds[i][j] %= M;
        }
    }
    printf("%lld\n", (ds[k - 1][x] + es[k - 1][1]) % M);
    return 0;
}

