		vec tmp(B.size(), 0);
		for (ll j = 0; j < tmp.size(); ++j)
		{
			tmp[0] = (tmp[0] + B[j]) % MOD;
			tmp[tmp.size() - j - 1] = (tmp[tmp.size() - j - 1] - B[j] + MOD) % MOD;
		}

		for (ll j = 1; j < tmp.size(); ++j)
		{
			tmp[j] += tmp[j - 1];
