using namespace std;

int MOD_N = (10 * 10 * 10) * (10 * 10 * 10) * (10 * 10 * 10) + 7;

int main() {
    int N, K;
    cin >> N; cin >> K;
    vector<int> nums;
    nums.push_back(1);
    for (int n = 2; n < N; ++n) {
        if ((N/(n-1)) != N/n) {
            nums.push_back(n);
        }
    }
    long **counts = new long*[K-1];
    for (int k = 0; k < K - 1; ++k) {
        counts[k] = new long[nums.size()];
    }
    for (int i = 0; i < nums.size(); ++i) {
        int n = nums[i];
        counts[0][i] = N / n;
    }
    for (int k = 3; k <= K; ++k) {
        for (int i = 0; i < nums.size(); ++i) {
            int n = nums[i];
            int q = N / n;
            long c = counts[k - 3][0];
            for (int j = 1; j < nums.size(); ++j) {
                int l = nums[j - 1];
                int m = nums[j];
                if (m > q) {
                    c += counts[k - 3][j - 1] * (q - l);
                } else {
                    c += counts[k - 3][j - 1] * (m - l - 1) + counts[k - 3][j];
                }
                if (c > MOD_N) {
                    c %= MOD_N;
                }
                if (m >= q) {
                    break;
                }
            }
            if (q > nums[nums.size() - 1]) {
                c += counts[k - 3][nums.size() - 1] * (q - nums[nums.size() - 1]);
                if (c > MOD_N) {
                    c %= MOD_N;
                }
            }
            counts[k - 2][i] = c;
        }
    }
    long count = counts[K - 2][0];
    for (int i = 1; i < nums.size(); ++i) {
        int m = nums[i - 1];
        int n = nums[i];
        count += counts[K - 2][i - 1] * (n - m - 1) + counts[K - 2][i];
        if (count > MOD_N) {
            count %= MOD_N;
        }
    }
    count += counts[K - 2][nums.size() - 1] * (N - nums[nums.size() - 1]);
    if (count > MOD_N) {
        count %= MOD_N;
    }
    cout << count << "\n";
    return 0;
}

