  while(L*L <= N) ++L;
  std::vector<mint> dp1(L+1), dp2(L+1);
  std::fill_n(dp1.begin()+1, std::min(L, N), mint(1));
  std::fill_n(dp2.begin()+1, L, mint(1));

  mint sum; 
  while(K--) {
    std::swap(dp1, dp2);
    // sum up previous dp1[] to current dp2[]
    for(int i = 1; i <= L; ++i) dp2[i] += dp2[i-1];
    //
    sum = dp2[N/(L+1)];
    // sum up previous dp2[] to current dp1[]
    for(int i = L; i > 0; --i) {
      sum += dp1[i]*mint(N/i - N/(i+1));
      dp1[i] = sum;
    }
  }
  fin(sum.v_);
  return 0;
}

