    ll* st = new ll[sq + 1];
    for (int i = 1;i <= sq;++i)
        st[i] = n / (i + 1) + 1;
    ll* ct = new ll[sq + 1];
    ct[1] = n - st[1] + 1;
    for (int i = 2;i <= sq;++i)
        ct[i] = st[i - 1] - st[i];

