    for (int i = 1;i <= sq;++i)
        cout << ct[i] << " ";
    cout << endl;
#endif

    ll** dp1 = new ll*[k + 1];
    ll** dp2 = new ll*[k + 1];
    for (int i = 0;i <= k;++i){
        dp1[i] = new ll[st[sq]];
        dp2[i] = new ll[sq + 1];
    } 
    // 初期化
    for (int i = 1;i < st[sq];++i)
        dp1[1][i] = 1;
    for (int i = 1;i <= sq;++i)
        dp2[1][i] = ct[i];
    // 遷移
    for (int i = 2;i <= k;++i){
        /* dp1の直前の累積和を求める */
        vector<ll> sum1{0};
        for (int j = 1;j < st[sq];++j){
            auto iter = sum1.end() - 1;
            sum1.push_back((*iter + dp1[i - 1][j]) % mod);
        }
        /* dp2の直前の累積和を求める */
        vector<ll> sum2{0};
        for (int j = 1;j <= sq;++j){
            auto iter = sum2.end() - 1;
            sum2.push_back((*iter + dp2[i - 1][j]) % mod);
        }
        /* dp1を更新する */
        for (int j = 1;j < st[sq];++j)
            dp1[i][j] = (sum1[st[sq] - 1] + (sum2[sq] - sum2[(int)min((ll)j - 1,sq)] + mod) % mod) % mod;
        /* dp2を更新する */
        for (int j = 1;j <= sq;++j)
            dp2[i][j] = sum1[(int)min((ll)j,st[sq] - 1)] * ct[j] % mod;
    }

#ifdef TEST
