            cout << dp2[i][j] << " ";
        cout << endl;
    }
#endif

    ll ans = 0;
    for (int j = 1;j < st[sq];++j){
        ans += dp1[k][j];
        ans %= mod;
    }
    for (int j = 1;j <= sq;++j){
