ll dp[110][100005];
ll sdp[100005];
ll sum[100005];


int main() {

	ll n, k;
	cin >> n >> k;

	int layer = 0;//最大値がi/jになるグループにまとめる（高々2√N）

	for (int i = 1; i <= n;)
	{
		int j = n / i;

		if (i <= j) {
			//前半
			sum[layer] = 1;
			i++;
			layer++;
		}
		else
		{
			//後半
			sum[layer] = n / j - i + 1;
			i = n / j + 1;
			layer++;
		}
	}


	dp[0][0] = 1;


	for (int i = 0; i < k; i++)
	{

		//累積和
		memset(sdp, 0, sizeof(sdp));

		for (int j = 0; j < layer; j++)
		{
			sdp[j + 1] = sdp[j] + dp[i][j];
			sdp[j + 1] %= MOD;
		}

		for (int j = 0; j < layer; j++)
		{
			dp[i + 1][j] = sdp[layer - j] * sum[j];
			dp[i + 1][j] %= MOD;
		}

	}


	ll ans = 0;
	for (int i = 0; i <= layer; i++)
	{
		ans += dp[k][i];
		ans %= MOD;
	}

	cout << ans << endl;


	return 0;
}

