using namespace std ;

const long long mod = 1e9 + 7ll ;
const int MAXK = 105 ;
const int MAXN = 1e9 + 10 ;
const int SQRTMAXN = sqrt(MAXN)+1 ;

long long n , k ;
long long dp[MAXK][SQRTMAXN] ;
long long dpsum1[MAXK][SQRTMAXN] ;
long long dpsum2[MAXK][SQRTMAXN] ;

int main()
{
	ios_base::sync_with_stdio(0) ;
	cin.tie(0) ;
	cin>>n>>k ;
	int sqrtn = 0 ;
	for(long long i = 1ll ; i * i <= n ; ++i)
		sqrtn++ ;
	long long choices = 0 ;
	for(int j = 1 ; j <= sqrtn ; ++j)
	{
		choices = max(0ll , n / j - sqrtn) ;
		dp[1][j] = 1ll ;
		dp[2][j] = n / j ;
		dpsum1[1][j] = (dpsum1[1][j-1] + dp[1][j]) % mod ;
		dpsum2[1][j] = (dpsum2[1][j-1] + ((dp[1][j] * choices) % mod)) % mod ;
		dpsum1[2][j] = (dpsum1[2][j-1] + dp[2][j]) % mod ;
		dpsum2[2][j] = (dpsum2[2][j-1] + ((dp[2][j] * choices) % mod)) % mod ;
	}
	for(int i = 3 ; i <= k ; ++i)
	{
		for(int j = 1 ; j <= sqrtn ; ++j)
		{
			choices = max(0ll , n / j - sqrtn) ;
			dp[i][j] = (dpsum1[i-2][j-1] * choices) % mod ;
			long long x = (dpsum2[i-2][sqrtn] - dpsum2[i-2][j-1] + mod) % mod ;
			dp[i][j] = (dp[i][j] + x) % mod ;
			dp[i][j] = (dp[i][j] + dpsum1[i-1][min(n/j , sqrtn*1ll)]) % mod ;
		}
		for(int j = 1 ; j <= sqrtn ; ++j)
		{
			choices = n / j ;
			choices = max(0ll , choices - sqrtn) ;
			dpsum1[i][j] = (dpsum1[i][j-1] + dp[i][j]) % mod ;
			dpsum2[i][j] = (dpsum2[i][j-1] + ((dp[i][j] * choices) % mod)) % mod ;
		}
	}
	long long ans = 0ll ;
	for(int j = 1 ; j <= sqrtn ; ++j)
	{
		choices = n / j ;
		long long x = (dp[k-1][j] * max(0ll , choices - sqrtn)) % mod ;
 		ans = (ans + dp[k][j]) % mod ;
 		ans = (ans + x) % mod ;
	}
	return cout<<ans<<"\n" , 0 ;
}

