using namespace std;


typedef pair<ll,ll> P;

ll N,K;
ll dp[105][40000];
vector<P> V;
map<ll,ll> MAP;


int main(){

	scanf("%lld %lld",&N,&K);

	for(ll i = 1; i*i <= N; i++){

		V.push_back(P(i,0));
		V.push_back(P(N/i,0));
	}
	sort(V.begin(),V.end());
	V.erase(unique(V.begin(),V.end()),V.end());

	for(ll i = 0; i < V.size()-1; i++){

		ll left = N/V[i+1].first+1;
		ll right = N/V[i].first;

		V[i].second = right-left+1;	//区間長
	}
	V.back().second = 1; //1

	for(ll i = 0; i < V.size(); i++){

		MAP[V[i].first] = i;
	}

	for(ll i = 0; i <= K; i++){
		for(ll a = 0; a < V.size(); a++){

			dp[i][a] = 0;
		}
	}

	dp[0][MAP[N]] = 1; //dp[数列の長さ][N/xの値] = 場合の数

	for(ll i = 0; i < K; i++){
		//累積和
		for(ll p = V.size()-2; p >= 0; p--){

			dp[i][p] += dp[i][p+1];
			dp[i][p] %= MOD;
		}
		for(ll p = 0; p < V.size(); p++){ //p:遷移先

			ll loc = MAP[N/V[p].first]; //loc:遷移元

			dp[i+1][p] += (dp[i][loc]*V[p].second)%MOD;
			dp[i+1][p] %= MOD;
		}
	}

	ll ans = 0;
	for(ll i = 0; i < V.size(); i++){

		ans += dp[K][i];
		ans %= MOD;
	}

	printf("%lld\n",ans);

	return 0;
}

