using namespace std;

class Solution {
public:
    int solve(int n, int K) {
        const long long MOD = 1000000007;

        vector<int> X;
        for (int i = 1; i * i <= n; ++i) {
            X.push_back(i);
            if (i * i < n) {
                X.push_back(n / i);
            }
        }
        X.push_back(0);
        sort(X.begin(), X.end());
        // X.erase(unique(X.begin(), X.end()), X.end());

        int N = X.size();
        vector<long long> dp(N, 1);
        dp[0] = 0;
        vector<long long> ndp(dp);

        for (int _ = 0; _ < K; ++_) {
            fill(ndp.begin(), ndp.end(), 0);

            for (int i = 1, j = N - 1; i < N; ++i) {
                while (j >= 1 && X[i] * 1LL * X[j] > n) {
                    --j;
                }
                long long cnt = X[i] - X[i - 1];
                ndp[i] = dp[j] * cnt % MOD;
                (ndp[i] += ndp[i - 1]) %= MOD;
            }
            swap(ndp, dp);
        }

        return dp[N - 1];
    }
};

int main(int argc, char** argv) {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int n, k;
    cin >> n >> k;

    Solution sol;
    cout << sol.solve(n, k) << "\n";

    return 0;
}

