void solve(){
    ll n,k;
    cin >> n >> k;
    ll lim=sqrt(n);
    rp(i,lim+1) dp[0][i]=1;
    repi(i,1,lim+1) sumdp[0][i]=sumdp[0][i-1]+dp[0][i];
    repi(i,1,lim+1) dp[1][i]=n/i;
    repi(i,1,lim+1) sumdp[1][i]=sumdp[1][i-1]+dp[1][i];
    repi(i,2,k){
        mint sum=sumdp[i-1][lim];
        repi(j,1,lim+1){
            sum+=(mint)(max(lim,n/j)-lim)*dp[i-2][j];
        }
        repi(j,1,lim+1){
            dp[i][j]=sum;
            sum-=(mint)(max(lim,n/j)-max(lim,n/(j+1)))*sumdp[i-2][j];
        }
        repi(j,1,lim+1){
            sumdp[i][j]=sumdp[i][j-1]+dp[i][j];
        }
    }
    mint ans=sumdp[k-1][lim];
    repi(j,1,lim+1){
        ans+=(mint)(max(lim,n/j)-lim)*dp[k-2][j];
    }
