int main() {

    ios::sync_with_stdio(false); // stdioを使うときはコメントアウトすること
    cin.tie(nullptr);            // インタラクティブ問題ではコメントアウトすること

    ll n, k; cin >> n >> k;

    ll s = sqrtl(n)-1;
    while ((s+1) * (s+1) <= n) s++;

    vector<ll> v = {n};
    RANGE(i, 2, s) {
        ll vn = n / i;
        if (v.back() != vn) {
            v.push_back(vn);
        }
    }
    REP(i, v.size()) {
        v.push_back(n / v[i]);
    }
    UNIQUE(v);

    ll m = v.size();

    vector<modint> dp(m, 1), ddp;
    REP(i, m-1) dp[i+1] = v[i+1] - v[i];
    reverse(ALL_OF(dp));
    ddp = dp;

    REP(i, k-1) {
        vector<modint> dq(m, 0);
        REP(j, m) {
            ll idx = lower_bound(ALL_OF(v), n / v[j]) - v.begin();
            dq[idx] += dp[j];
        }
        REP(j, m-1) dq[j+1] += dq[j];
        REP(j, m) {
            dq[j] *= ddp[j];
        }
        dp.swap(dq);
    }

    say(accumulate(ALL_OF(dp), 0_p));

}

