ll tagget_for_0 = 0;
ll tagget_for_1 = 0;

ll Compute[150000];
ll LL[150000];
ll RR[150000];

ll compute(ll x)
{
    if (Compute[x] != -1)
        return Compute[x];
    long long L = 0, R = 0;
    ll l = 0, r = 1e9;
    while (l + 1 < r)
    {
        ll mid = (l + r) / 2;
        if (n / mid > x)
            l = mid;
        else
            r = mid;
    }
    L = r;

    l = 0, r = 1e9;
    while (l + 1 < r)
    {
        ll mid = (l + r) / 2;
        if (n / mid >= x)
            l = mid;
        else
            r = mid;
    }

    R = l;
    //cout << x << " : " << L << " " << R << endl;
    LL[x] = L;
    RR[x] = R;
    return Compute[x] = R - L + 1;
}

ll ok(int vetka, int x)
{
    if (vetka == 0)
    {
        return x <= tagget_for_0;
    }
    else
    {
        return x <= tagget_for_1;
    }
}

ll calc(int t, int len, int x)
{
    if (t == 0)
    {
        dp[t][len][x] = (sigma[0][len - 1][ROOT] + sigma[1][len - 1][x]) % MOD;
    }
    else
    {
        dp[t][len][x] = compute(x) * sigma[0][len - 1][x] % MOD;
    }
}

