#include <bits/stdc++.h>
#define mod 1000000007
using namespace std;
typedef long long ll;
typedef long double ld;
typedef pair<int,int> pii;
typedef pair<ll,ll> pll;
ll n,k;
ll dp[101][200001],s[101][200001];
vector<ll> nums;
map<ll,bool> f;
int main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);
    cin>>n>>k;
    for(ll i=1;i*i<=n;i++)
    {
        nums.push_back(i);
        f[i]=1;
    }
    for(ll j=nums.size()-1;j>=0;j--)
    {
        if(f.count(n/nums[j])==0)
        {
            nums.push_back(n/nums[j]);
            f[n/nums[j]]=1;
        }
    }
    /*for(auto j:nums)
        cout<<j<<" ";
    cout<<'\n';*/
    ll m=nums.size();
    for(int i=0;i<m;i++)
    {
        dp[1][i]=1;
        if(i==0)
        {
            s[1][i]=dp[1][i];
            continue;
        }
        s[1][i]=(s[1][i-1]+(dp[1][i]*(nums[i]-nums[i-1])%mod))%mod;
    }
    for(int j=2;j<=k;j++)
    {
        for(int i=0;i<m;i++)
        {
            dp[j][i]=s[j-1][m-i-1];
            if(i==0)
            {
                s[j][i]=dp[j][i];
                continue;
            }
            s[j][i]=(s[j][i-1]+(dp[j][i]*(nums[i]-nums[i-1])%mod))%mod;
        }
    }
    cout<<s[k][m-1]%mod;
    return 0;
}

