  for(auto i = dp.size() - 1; 0 < i; --i) dp.emplace_back(i), num.emplace_back(dp[i - 1] - dp[i] + M % M);

  dp = num;
  for(auto i = 1; i < K; ++i) {
    vector<LL> nex(dp.size(), 0);
    for(auto j = 0; j < dp.size(); ++j)
      for(auto k = 0; k < dp.size() - j; ++k)
        (nex[k] += dp[j] * num[k]) %= M;
    dp = nex;
  }

  LL res = 0;
  for(auto i = 0; i < dp.size(); ++i) (res += dp[i]) %= M;
  cout << res << endl;
}

