const int MOD = 1000000007;
const int INF = 1000000000;
const int MAXN = 110;
const int MAXP = 40010;

ll F[MAXN][MAXP], G[MAXN][MAXP];
ll sF[MAXN][MAXP], sG[MAXN][MAXP];

int main()
{

	int n, k;
	cin >> n >> k;

	int p = sqrt(n); // p*p <= n
	while ((p+1)*(p+1) <= n) ++ p;

	for (int i = 1; i <= p; ++ i)
		F[1][i] = 1;
	for (int i = p+1; i <= n; )
	{
		int j = n/(n/i);
		G[1][n/i] = j-i+1;
		i = j+1;
	}

	for (int x = 2; x <= k; ++ x)
	{
		for (int i = 1; i <= p; ++ i)
		{
			sF[x-1][i] = (sF[x-1][i-1]+F[x-1][i])%MOD;
			sG[x-1][i] = (sG[x-1][i-1]+G[x-1][i])%MOD;
		}
		for (int i = 1; i <= p; ++ i)
		{
			F[x][i] = (sF[x-1][p]+sG[x-1][p]+MOD-sG[x-1][i-1])%MOD; // i*? <= n --> ? <= n/i --> n/? >= i
		}
		for (int i = p+1; i <= n; )
		{
			int j = n/(n/i);
			G[x][n/i] = sF[x-1][n/i]*(j-i+1)%MOD; // i*? <= n --> i <= n/?
			i = j+1;
		}
	}

	ll ans = 0;
	for (int i = 1; i <= p; ++ i)
		ans = (ans+F[k][i]+G[k][i])%MOD;
	cout << ans << endl;

	return 0;
}

