const int64_t MOD = 1000000007;
const int64_t M = 128;
const int64_t X = 32768; // >= sqrt(N)

int64_t a[M][X], b[M][X];
void solve(std::istream &in, std::ostream &out) {
  int N, K;
  in >> N >> K;
  for (int i = 1; i < X; i++) {
    a[1][i] = min(i, N);
    b[1][i] = N / i;
  }
  for (int m = 2; m <= K; m++) {
    a[m][0] = 0;
    for (int i = 1; i < X; i++) {
      a[m][i] = (a[m][i - 1] + b[m - 1][i]) % MOD;
    }
    b[m][X - 1] = a[m][N / (X - 1)];
    for (int i = X - 2; i >= 1; i--) {
      b[m][i] = (b[m][i + 1] + a[m - 1][i] * (N / i - N / (i + 1))) % MOD;
    }
  }
  out << b[K][1] << '\n';
}

