class DP{
public:

  vector<map<ll, ll>> dp;
  vector<ll> divable;
  map<ll, ll> a;

  DP(ll N, ll K){
    //cout << "init" << endl;

    //vector<vector<ll>> dp1(K + 1, vector<ll>(N + 1));
    vector<map<ll, ll>> dp1(K + 1);
    //cout << "init" << endl;
    dp = dp1;

    std::vector<ll> v;
    divable = v;
    for (ll i = 1; i * i <= N; i++){
      divable.push_back(i);
      divable.push_back(N/i);
    }
    sort(divable.begin(), divable.end());
    divable.erase(unique(divable.begin(), divable.end()), divable.end());

    map<ll, ll> a1;
    a = a1;
    REP(i, divable.size() - 1){
      a[divable[i + 1]] = divable[i + 1] - divable[i];
    }

    REPI(i, 1, K + 1){
      for(ll j = divable.size() - 1; j >= 0; j--){
        if (i == 1) dp[1][divable[j]] = 1;
        else if (divable[j] == divable[divable.size() - 1]) dp[i][divable[j]] = dp[i - 1][1];
