          ll tmp1 = (dp[i - 1][tmp] * a[tmp]) % MOD;
          dp[i][divable[j]] = (dp[i][divable[j + 1]] + tmp1) % MOD;
        }
      }
      //cout << i << endl;
    }

  }



};

