const int N = 70000;

struct mint {
    ll x;
    mint(ll x=0):x((x%MOD+MOD)%MOD){}
    mint operator-() const { return mint(-x);}
    mint& operator+=(const mint a) {if ((x+=a.x)>=MOD) x-=MOD; return *this;}
    mint& operator-=(const mint a) {if ((x+=MOD-a.x)>=MOD) x-=MOD; return *this;}
    mint& operator*=(const mint a) {(x*=a.x)%=MOD; return *this;}
    mint operator+(const mint a) const {mint res(*this); return res+=a;}
    mint operator-(const mint a) const {mint res(*this); return res-=a;}
    mint operator*(const mint a) const {mint res(*this); return res*=a;}
    mint pow(ll t) const {
        if (!t) return 1;
        mint a = pow(t>>1);
        a *= a;
        if (t&1) a *= *this;
        return a;
    }

    // for prime mod
    mint inv() const { return pow(MOD-2);}
    mint& operator/=(const mint a) { return (*this) *= a.inv();}
    mint operator/(const mint a) const {mint res(*this); return res/=a;}
};

int main() {
	int n, k;
	cin >> n >> k;

	int base[N];
	int last;
	for(int i = 1; i <= sqrt(n) + 1; i++) {
		base[i] = i;
		if(n / i <= i) {
			last = i;
			break;
		}
	}
	int start, ref;
	if(n / last == last) {
		start = last + 1;
	}
	else if(n / last < last) {
		start = last;
	}
	int i_max;
	for(int i = start, ref = last - 1; ref >= 1;i++, ref--) {
		base[i] = n / ref;
		i_max = i;
	}
	// if n=10, base={1,2,3,5,10}
	for(int i = i_max; i >= 2; i--) {
		base[i] = base[i] - base[i - 1];
	}
	// if n=10, base={1,1,1,2,5}

	vector<vector<mint>> dp(k + 1, vector<mint>(i_max + 1));
//	mint dp[101][N];
	for(int i = 1; i <= i_max; i++) {
		dp[1][i] = base[i];
	}
	for(int i = 2; i <= k; i++) {
		dp[i][i_max + 1] = 0;
		for(int j = i_max; j >= 1; j--) {
			dp[i][j] = dp[i][j + 1] + dp[i - 1][i_max - j + 1];
		}
		for(int j = 1; j <= i_max; j++) {
			dp[i][j] *= base[j];
		}
	}

	mint ans = 0;
	for(int i = 1; i <= i_max; i++) {
		ans += dp[k][i];
	}
	cout << ans.x << endl;
}

