		L[id]=R[id]=i;
		id++;
	}
	int T=L[id-1];
	if(T*T==N)T--;
	for(;T>=1;T--)
	{
		L[id]=R[id-1]+1;
		R[id]=N/T;
		id++;
	}
	for(int i=0;i<id;i++)dp[0][i]=R[i]-L[i]+1;
	for(int i=0;i<K-1;i++)
	{
		for(int j=1;j<id;j++)dp[i][j]=(dp[i][j]+dp[i][j-1])%mod;
		for(int j=0;j<id;j++)
		{
			dp[i+1][j]=(dp[i+1][j]+dp[i][id-j-1]*(R[j]-L[j]+1)%mod)%mod;
		}
	}
	long ans=0;
	for(int j=0;j<id;j++)ans=(ans+dp[K-1][j])%mod;
	cout<<ans<<endl;
}

