const int maxn = 1e5+15;
int n,k,block;
LL sum[maxn],a[maxn],num[maxn];
int main(){
    cin >> n >> k;
    block = 1;
    for(int i = 1;i <= n; ){
        int t = n/i;
        int up = n/t;
        num[block] = up-i+1;
        sum[block] = t;
        i = up + 1;
        block++;
    }
    for(int i = 2;i <= k; ++i){
        for(int j = 1;j < block; ++j){
            a[j] = sum[j]*num[j]%mod;
        }
        for(int j = 1;j < block; ++j){
            sum[j] = (sum[j-1] + a[j])%mod;
        }
        int t = block/2;
        for(int j = 1;j <= t; ++j) swap(sum[j],sum[block-j]);
    }
    cout << sum[1] << endl;
    return 0;
}

