struct modular_arithmetic{
	int mod;

	modular_arithmetic(){
		mod = 1000000007;
	}
	//No specific settings.
	int add(int x,int y){return (x+=y)<mod?x:x-mod;}
	int mul(int x,int y){return (int)((long long int)x*y%mod);}
};
modular_arithmetic ma;

int get_s(int id, int x) {
	if(x<=lim_pre) return sf[id][x];

	int res = sf[id][lim_pre];
	int it = lim/x;
	res = ma.add(res, sg[id][it+1]);
	int rem = x - (lim/(it+1));
	res = ma.add(res, ma.mul(rem, tmp[id][it]));

	// printf("- %d %d\n", rem, res);
	return res;
}

int main() {
	scanf("%d%d", &lim, &n);

	MAGIC = sqrt(lim);

	lim_pre = lim/(MAGIC+1);
	lim_suf = MAGIC;

	memset(f, 0, sizeof f);
	memset(sf, 0, sizeof sf);
	memset(g, 0, sizeof g);
	memset(tmp, 0, sizeof tmp);
	memset(sg, 0, sizeof sg);

	f[0][1] = 1;
	for(int i=1;i<=lim_pre;i++)
		sf[0][i] = 1;

	for(int id=1; id<=n; id++) {
		for(int i=1;i<=lim_pre;i++) {
			f[id][i] = get_s(id-1, lim/i);
			sf[id][i] = ma.add(sf[id][i-1], f[id][i]);
		}
		for(int i=lim_suf;i>0;i--) {
			int l = lim/(i+1)+1;
			int r = lim/i;
			tmp[id][i] = get_s(id-1, i);
			g[id][i] = ma.mul((r-l+1), tmp[id][i]);
			sg[id][i] = ma.add(sg[id][i+1], g[id][i]);
		}
	}

	printf("%d\n", get_s(n, lim));

	return 0;
}

