int main() {
    init();
    ll N,K;
    cin >> N >> K;
    ll sqN = (ll)sqrt(N);

    repe(i, 1, sqN + 1) divl[i] = N / i;
    repe(i, 1, sqN) cnt[i] = divl[i] - divl[i + 1];
    cnt[sqN] = divl[sqN] - sqN;

    // dp[i+1][k] i番目の整数がkであるような個数
    // dp2[i+1][k] i-1番目の整数がkのときにとりうることのできるsqNより大きい整数の個数和
    // sum[k] dp[i][1]~dp[i][k]までの個数

    dp[0][1] = 1;
    repe(i, 1, sqN + 1) sum[i] = 1;
    rep(i,K){
        repe(j,1,sqN+1){
            // dp -> dp
            (dp[i + 1][1] += dp[i][j]) %= MOD;
            (dp[i + 1][sqN + 1] += MOD - dp[i][j]) %= MOD;

            // sum -> dp2
            (dp2[i + 1][j] += cnt[j]*sum[j]) %= MOD;

            // dp2 -> dp
            (dp[i + 1][1] += dp2[i][j]) %= MOD;
            (dp[i + 1][j + 1] += MOD - dp2[i][j]) %= MOD;
        }

        sum[0] = 0;
        // imos
        repe(j,1,sqN+1){
            (dp[i + 1][j + 1] += dp[i + 1][j]) %= MOD;
            sum[j] = sum[j - 1] + dp[i + 1][j];
        }
    }

    ll ans = 0;
    repe(j, 1, sqN + 1)(ans += dp[K][j]) %= MOD;
    repe(j, 1, sqN + 1)(ans += dp2[K][j]) %= MOD;
    cout << ans << endl;
