// Mod int
// cf. https://www.youtube.com/watch?v=1Z6ofKN03_Y
struct mint {
  ll x;
  mint(ll x = 0) : x((x + MOD) % MOD) {}
  mint& operator+= (const mint a) {
    if ((x += a.x) >= MOD) x %= MOD;
    return *this;
  }
  mint operator+ (const mint a) const {
    mint res(*this);
    return res += a;
  }
  mint& operator-= (const mint a) {
    if ((x += MOD - a.x) >= MOD) x %= MOD;
    return *this;
  }
  mint operator- (const mint a) const {
    mint res(*this);
    return res -= a;
  }
  mint& operator*= (const mint a) {
    (x *= a.x) %= MOD;
    return *this;
  }
  mint operator* (const mint a) const {
    mint res(*this);
    return res *= a;
  }
  mint pow(ll t) const {
    if (!t) { return 1; }
    mint a = pow(t >> 1);
    a *= a;
    if (t & 1) a *= *this;
    return a;
  }

  // for prime mod
  mint inv() const {
    return pow(MOD-2);
  }
  mint& operator/= (const mint a) {
    return (*this) *= a.inv();
  }
  mint operator/ (const mint a) const {
    mint res(*this);
    return res /= a;
  }
};

int main(int argc, char** argv) {
  cin.tie(NULL);
  cout.tie(NULL);
  ios_base::sync_with_stdio(false);
  //cout << setprecision(10) << fixed;

  ll n, k;
  cin >> n >> k;
  vector<pair<ll, ll>> s; // s[i] .. pair of <n/number, count>
  for (int i = 1; i * i <= n; ++i) {
    s.push_back(P(i,0));
    s.push_back(P(n/i,0));
  }
  sort(all(s));
  s.erase(unique(all(s)), s.end());
  rep(i, s.size()-1) {
    ll l = n/s[i+1].first;
    ll r = n/s[i].first;
    s[i].second = r-l;
  }
  s.back().second = 1;

  ll m = s.size();
  map<ll, ll> mp; // map real number to index in s.
  rep(i, m) {
    mp[s[i].first] = i;
  }

  // dp[i][j]
  vector<vector<mint>> dp(k+1, vector<mint>(m));
  dp[0][mp[n]] = 1;
  rep(i, k) {
    // calculate cummulated sum
    for (int j = m-2; j >= 0; --j) {
      dp[i][j] += dp[i][j+1];
    }
    rep(j, m) {
      // Add the contribution where j*j' <= n
      int nj = mp[n/s[j].first];
      dp[i+1][j] += dp[i][nj] * s[j].second;
    }
  }
  mint ans(0);
  rep(j, m) {
    ans += dp[k][j];
  }
  cout << ans.x << endl;
}

