constexpr int M = 1000000007;

int main() {
    int N, K; cin >> N >> K;
    const int b = int(sqrt(N)) + 2;
    long long dps[2][b], dpl[2][b];
    int cur = 0, prev = 1;
    dps[0][0] = dps[1][0] = dpl[0][0] = dpl[1][0] = 0;
    for (int i = 1; i < b; i++) {
        dps[prev][i] = i;
        dpl[prev][i] = N/i;
    }
    while (--K) {
        for (int i = 1; i < b; i++) {
            dps[cur][i] = (dps[cur][i-1] + (N/i < b ? dps[prev][N/i] : dpl[prev][i])) % M;
        }
        for (int i = b-1; i > 0; i--) {
            dpl[cur][i] = ((i == b-1 ? dps[cur][N/b] : dpl[cur][i+1]) +
                           (N/(N/i) < b ? dps[prev][N/(N/i)] : dpl[prev][N/i])
                           * (N/i - N/(i+1))) % M;
        }
        swap(prev, cur);
    }
    cout << dpl[prev][1] << endl;
}

