using namespace std;
typedef long long ll;
const ll mod = 1e9 + 7;

class STlazy{
private:
    int n;
    vector<ll> node, lazy;

public:
    STlazy(vector<ll> v){
        int siz = v.size();
        n = 1;
        while(n < siz)  n *= 2;
        node.resize(2*n-1, 0);
        lazy.resize(2*n-1, 0);

        for(int i = 0; i < siz; i++)    node[n-1+i] = v[siz];
        for(int i = n-2; i >= 0; i--)   node[i] = node[2*i+1] + node[2*2+2];
    }

    void eval(int k, int l, int r){
        if(lazy[k] == 0)    return;
        node[k] += lazy[k]; node[k] %= mod;
        if(r-l > 1){
            lazy[2*k+1] += lazy[k]/2;   lazy[2*k+1] %= mod;
            lazy[2*k+2] += lazy[k]/2;   lazy[2*k+2] %= mod;
        }
        lazy[k] = 0;
    }

    void add(int a, int b, ll x, int k=0, int l=0, int r=-1){
        x %= mod;
        if(r < 0)   r = n;
        eval(k, l, r);
        if(r <= a || b <= l)    return;
        if(a <= l && r <= b){
            lazy[k] += (r-l)*x; lazy[k] %= mod;
            eval(k, l, r);
            return;
        }
        add(a, b, x, 2*k+1, l, (l+r)/2);
        add(a, b, x, 2*k+2, (l+r)/2, r);
        node[k] = (node[2*k+1] + node[2*k+2])%mod; // 自分の全ての子孫の値伝播が終わったら自分を更新する
    }

    // find(i)を区間幅1の区間和に対するクエリとみなすので実質b=a+1
    ll query(int a, int b, int k=0, int l=0, int r=-1){
        if(r < 0)   r = n;
        if(r <= a || b <= l)    return 0;
        eval(k, l, r); // 最初の呼び出しが必ずeval(0,0,n)となるので漏れなく上から値の伝播がなされている
        if(a <= l && r <= b)    return node[k];
        ll lx = query(a, b, 2*k+1, l, (l+r)/2);
        ll rx = query(a, b, 2*k+2, (l+r)/2, r);
        return (lx+rx)%mod;
    }
};

int main(){
    int n, k;
    cin >> n >> k;

    vector<int> to, val;
    int r = 1;
    while(r <= n){
        int tmp = n/r;
        int reach = n/tmp;
        to.push_back(reach);
        val.push_back(tmp);
        r = reach+1;
    }

    int siz = to.size(); // 恐らくO(logN)程度

    vector<ll> cnt(siz, 1);
    for(int i = 1; i < siz; i++)    cnt[i] = to[i]-to[i-1];

    auto f = [&](int x)->int{
        return upper_bound(to.begin(),to.end(),x)-to.begin();
    };

    // O(sqrt(N) * log(sqrt(N)) * K) ?
    STlazy seg(cnt);
    // for(int i = 0; i < cnt.size(); i++) cout << cnt[i] << " " ;
    // cout << endl;

    vector<ll> nil(siz, 0);
    while(k-- > 1){
        // cout << "from:" << endl;
        // for(int i = 0; i < siz; i++)    cout << seg.query(i,i+1) << " ";
        // cout << endl;

        STlazy next(nil);
        for(int i = 0; i < siz; i++){
            next.add(0, f(val[i]), seg.query(i,i+1)*cnt[i]%mod);
        }
        vector<ll> cp(siz);
        for(int i = 0; i < siz; i++)    cp[i] = next.query(i,i+1);
        seg = STlazy(cp);

        // cout << "to:" << endl;
        // for(int i = 0; i < siz; i++)    cout << seg.query(i,i+1) << " ";
        // cout << endl;
    }

    cout << seg.query(0, siz+1) << endl;
    return 0;
}

