}

void sub(int & x, int y) {
    x -= y;
    if (x < 0) {
        x += MOD;
    }
}

int main() {
    ios_base::sync_with_stdio(false), cin.tie(NULL);
    #ifdef LOCAL
        freopen("input.txt", "r", stdin);
    #endif

    cin >> n >> k;
    int cur = 1;
    vector <int> vec;
    while (cur <= n) {
        int val = n / cur;
        int nxt = n / val;
        vec.pb(val);
        num[val] = nxt - cur + 1;
        cur = nxt + 1;
    }
    reverse(all(vec));
    vec.erase(unique(all(vec)), vec.end());
    m = vec.size();
    for (int i = 1; i <= m; i++) {
        cnt[i] = num[vec[i - 1]];
    }
    for (int i = 1; i <= m; i++) {
        dp[1][i] = cnt[i];
        p[1][i] = p[1][i - 1];
        add(p[1][i], dp[1][i]);
    }
    for (int i = 2; i <= k; i++) {
        for (int j = 1; j <= m; j++) {
            int x = n / vec[j - 1];
            int pos = lower_bound(all(vec), x) - vec.begin();
            int res = p[i - 1][m];
            sub(res, p[i - 1][pos]);
            dp[i][j] = (ll)res * cnt[j] % MOD;
            p[i][j] = p[i][j - 1];
            add(p[i][j], dp[i][j]);
        }
    }
    int ans = 0;
    for (int i = 1; i <= m; i++) {
        add(ans, dp[k][i]);
    }
    cout << ans;
}

