template<typename T>
struct Compress {
private:
    vector<T> value;

public:
    Compress(const vector<T> &v, bool distinct = false) {
        int n = v.size();
        value.resize(n);
        value = v;
        sort(value.begin(), value.end());
        if (distinct) value.erase(unique(value.begin(), value.end()), value.end());
    }

    int size() {
        return value.size();
    }

    int val(int idx) {
        return value[idx];
    }

    int get(int v) {
        return lower_bound(value.begin(), value.end(), v) - value.begin();
    }
};

struct mint {
    const int mod = 1e9 + 7;
    long long x;

    mint (long long x = 0) : x((x % mod + mod) % mod) {

    }

    mint& operator=(const long long a) {
        x = a % mod;
        return *this;
    }

    mint& operator=(const mint a) {
        x = a.x % mod;
        return *this;
    }

    mint& operator+=(const mint a) {
        if ((x += a.x) >= mod) x -= mod;
        return *this;
    }

    mint operator+(const mint a) const {
        mint res(*this);
        return res += a;
    }

    mint& operator-=(const mint a) {
        if ((x += (mod - a.x)) >= mod) x -= mod;
        return *this;
    }

    mint operator-(const mint a) const {
        mint res(*this);
        return res -= a;
    }

    mint& operator*=(const mint a) {
        (x *= a.x) %= mod;
        return *this;
    }

    mint operator*(const mint a) const {
        mint res(*this);
        return res *= a;
    }

    mint pow(long long t) const {
        if (!t) return 1;
        mint a = pow(t >> 1);
        a *= a;
        if (t & 1) a *= *this;
        return a;
    }

    mint inv() const {
        return pow(mod - 2);
    }

    mint& operator/=(const mint a) {
        return (*this) *= a.inv();
    }

    mint operator/(const mint a) const {
        mint res(*this);
        return res /= a;
    }
};

