  for(; N / (s + 1) > M; s++) {
    right.push_back(fp(N / s - N / (s + 1)));
    rs.push_back(fp(N / s - N / (s + 1)));
  }

  right.push_back(fp(1));
  rs.push_back(fp(1));

  M = N / s - 1;

  //M = N;
