const ll MOD=1e9+7;

int main(){
    ll n,k;
    cin>>n>>k;
    vector<ll> b;
    {   
        set<ll> s;
        for(int i=1;i<=min((ll)(sqrt(n)+1),n);i++){
            s.insert(n/i);
        }
        for(int i=1;i<=min(ll(sqrt(n))+1,n);i++){
            s.insert(i);
        }
        b=vector<ll>(s.begin(),s.end());
    }
    if(*min_element(b.begin(),b.end())<=0) return 0;
    int m=b.size();
    vector<vector<ll>> dp(k+1,vector<ll>(m,0));
    dp[0][m-1]=1;
    for(int i=0;i<k;i++){
        vector<ll> sum(m+1);
        for(int j=0;j<m;j++){
            sum[j+1]=(sum[j]+dp[i][j])%MOD;
        }
        vector<ll> wsum(m+1);
        for(int j=0;j<m;j++){
            wsum[j+1]=(wsum[j]+b[j]*dp[i][j])%MOD;
        }
        for(int j=0;j<m;j++){
            ll lb=n/(b[j]+1);
            ll ub0=n/b[j];
            int id=(lower_bound(b.begin(),b.end(),ub0)-b.begin());
            int idl=(lower_bound(b.begin(),b.end(),lb)-b.begin());
            if(id>=lb) dp[i+1][j]+=wsum[id]-wsum[idl]-lb*(sum[id]-sum[idl]);
            dp[i+1][j]%=MOD;
            dp[i+1][j]+=(ub0-lb)*(sum[m]-sum[id]);
            dp[i+1][j]=(dp[i+1][j]%MOD+MOD)%MOD;
        }
    }
    cout<<accumulate(dp[k].begin(),dp[k].end(),0LL)%MOD<<endl;
    return 0;
}

