    vp rho(int v) {        assert(v);        if (v == 1)return vp();        vi ret;        if (!sz(primes)) setprime();        int lim = 300;                      /*64bit*/        if (v < 4294967296)lim = 80;      /*32bit*/        else if (v < 281474976710656LL)lim = 120; /*48bit*/        for (int i = 0; i < lim; i += 5) {            /*v<=1の判定回数を減らせる分高速化できる事を期待している*/            while (v % primes[i] == 0) ret.push_back(primes[i]), v /= primes[i];            while (v % primes[i + 1] == 0) ret.push_back(primes[i + 1]), v /= primes[i + 1];            while (v % primes[i + 2] == 0) ret.push_back(primes[i + 2]), v /= primes[i + 2];            while (v % primes[i + 3] == 0) ret.push_back(primes[i + 3]), v /= primes[i + 3];            while (v % primes[i + 4] == 0) ret.push_back(primes[i + 4]), v /= primes[i + 4];            if (v <= 1) {                sort(ret);/*試し割りだけで終わった時*/                return run_length(ret);            }        }        int lower_prime_bound = primes[lim - 1] * primes[lim - 1];        /*試し割りするか*/        mt19937 mr;        mr.seed(clock());        int c;        auto fac = [&](int v, const int loop = 10) {/*        if (v == 4)return 2ll; //試し割りで消えた*/            c = mr() % v;            int x = mr() % v;            int y = x;            int d = 1;            int lim = sqrt(v) + 2;            /*brentによる改良 差分を一操作で求められる*/            for (int i = 1, mul = 1, next_2pow = 2; d == 1 && i <= lim; i++) {                if (i == next_2pow) {                    y = x;                    next_2pow <<= 1;                }                x = ((u128) x * x + c) % v;                mul = ((u128) mul * abs(x - y)) % v;/*ユークリッドの互除法と同じ原理で因数は保たれる*/                if (i % loop == 0) {/*10とかなんとか iによっては死ぬ*/                    d = gcd(mul, v);                    mul = 1;                }            }            if (d == v) return -1ll;            return d;        };        queue<int> q;        q.push(v);        while (!q.empty()) {            int v = q.front();            q