using namespace std;

typedef long long swl;
typedef struct PATTERN {
  swl sum;
  swl ran;
} pattern_t;

int main() {
#ifdef  DEBUG
  ifstream in("input.txt");
  cin.rdbuf(in.rdbuf());
#endif  // for local.
  int n, k;
  cin >> n >> k;
  int rt_n = (int)floot(sqrt(n));
  int ptnn = n/(rt_n+1) + rt_n;

  pattern_t ptn[ptnn];
  for (int i = 0; i < rt_n; i++) {
    ptn[i].sum = n / (i+1);
    ptn[i].ran = 1;
  }
  if (ptnn & 1 == 0) { // rt_n * (rt_n+1) <= n
    ptn[rt_n+1].sum = n / rt_n;
    ptn[rt_n+1].ran = 1;
  }
  for (int i = 1; i < n/(rt_n+1) + 1; i++) {
    ptn[ptnn-i].ran = ptn[i-1].sum - ptn[i].sum;
    ptn[ptnn-i].sum = ptn[ptnn-i].ran * i % MOD;
  }

  for (int i = 2; i < k; i++) {
    for (int j = 0; j < ptnn; j++) {
      for (int x = 0; x < ptnn-j; x++) {
        ptn[j].sum = (ptn[j].sum + ptn[x].sum * ptn[x].ran) % MOD;
      } 
    }
  }
  swl ans = 0;
  for (int i = 0; i < ptnn; i++) {
    ans = (ans + ptn[i].sum * ptn[i].ran) % MOD;
  }

  cout << ans << endl;

  return 0;
}

