    num[cnt] = right2 - right1; 
    cnt++;
  }

  for (int i = 1; i < K; i++) {
    for (int j = 0; j < sz; j++) {
      if (j == 0) {
        DP[i][j] = DP[i-1][(sz-1)-j] * num[(sz-1)-j];
        DP[i][j] %= Mod;
      } else {
        DP[i][j] = DP[i-1][(sz-1)-j] * num[(sz-1)-j];
        DP[i][j] %= Mod;
        DP[i][j] += DP[i][j-1];
        DP[i][j] %= Mod;
      }
    }
  }
  cout << DP[K-1][sz-1] << endl;
  return 0;
}

