class CumulativeSum {
	const ll size;
	std::vector<ll> sumList;
public:

	CumulativeSum() = delete;
	CumulativeSum(const std::vector<ll>& v) :size(v.size()), sumList(size + 1) {
		for (ll i = 0; i < size; ++i) {
			sumList[i + 1] = sumList[i] + v[i];
		}
	}
	ll get(ll n) {
		return sumList[n + 1];
	}
	ll get(ll l, ll r) {
		if (r < l) { return 0LL; }
		l = std::max(l, 0LL); r = std::min(r, size - 1);
		return sumList[r + 1] - sumList[l];
	}
};

signed main() {
	ll n, k;
	cin >> n >> k;

	list<ll> v_;
	auto& p = n;
	RFOR(i, 1, std::sqrt(p) + 1) {
		ll a = p / i;
		if (a != i) {
			v_.emplace_front(i);
		}
		v_.emplace_back(p / i);
	}
	VL v;
	v.reserve(3 * std::sqrt(n));
	REPC(x, v_) {
		v.emplace_back(x);
	}
	const auto size = v.size();
	VL to(size, 1);
	auto now = v.begin();
	FOR(i, 1, size) { to[i] = -(*now) + *(++now); }
	VVL dp(k + 1, VL(size));
	dp[1] = to;
	FOR(i, 2, k + 1) {
		VL sum(size + 1);
		sum[0] = dp[i - 1][0] * to[0];
		FOR(j, 1, size) {
			sum[j] = sum[j - 1] + dp[i - 1][j];
			sum[j] %= MOD;
		}
		FOR(j, 0, size) {
			dp[i][j] = (sum[size - j - 1]) * to[j];
			dp[i][j] %= MOD;
		}
	}
	ll ans = 0;
	REPC(x, dp[k]) {
		ans += x;
		ans %= MOD;
	}
	cout << ans << endl;
}

