ll n;
ll sqn;
int k;

//up 上限
ll func(int place,ll up){
	static int cnt = 0;
	++cnt;
	//cout << cnt << endl;
	if(place==k)return 1;

	if(up*up<=n){
		static vvector<ll> memo(k,vector<ll>(sqn,-1));
		if(memo[place][up]>=0)return memo[place][up];
		ll res = 0;
		if(up>=2){
			res = func(place,up-1);
		}
		res += func(place+1,n/up);
		res %= MOD;
		--cnt;
		return memo[place][up] = res;
	}else{
		ll upr = n / up;
		static vvector<ll> memo(k,vector<ll>(sqn,-1));
		if(memo[place][upr]>=0)return memo[place][upr];
		ll res = 0;
		res += func(place,n/(n/up+1));
		res += (up-n/(n/up+1)) * func(place+1,upr);
		res %= MOD;
		--cnt;
		return memo[place][upr] = res;
	}
}

int main(){
	cin >> n >> k;
	sqn = sqrt(n) + 2;
	for(int i=k-1;i>=0;--i){
		func(i,n);
	}
	cout << func(0,n) << endl;
	return 0;
}

