//区間和
struct RSQ{
    ll n;
    vector<ll>data;
    void init (ll vs){
        n=1;
        while(n<vs)n*=2;
        data.resize(2*n-1,0);
    }
    void update(ll k,ll a){
        k+=n-1;
        data[k]=a;
        while(k>0){
            k=(k-1)/2;
            data[k]=data[2*k+1]+data[2*k+2];
        }
    }
    void add(ll k,ll a){
        k+=n-1;
        data[k]+=a;
        while(k>0){
            k=(k-1)/2;
            data[k]=data[2*k+1]+data[2*k+2];
        }
    }
    ll query(ll a,ll b,ll k,ll l,ll r){
        if(r<=a||b<=l)return 0;
        if(a<=l&&r<=b){
            return data[k];
        }else{
            ll vl=query(a,b,2*k+1,l,(l+r)/2);
            ll vr=query(a,b,2*k+2,(l+r)/2,r);
            return vl+vr;
        }
    }
    ll query(ll a,ll b){return query(a,b,0,0,n);}//[a,b)の和
};
