int main(){fastio
    ll n,k;cin>>n>>k;
    ll m=30000;
    RSQ dp[k];
    RSQ ep[k];
    rep(i,0,k-1){
        dp[i].init(m+1);
        ep[i].init(m+1);
    }
    //ll dp[k][m+1];memset(dp,0,sizeof(dp));
    rep(i,1,min(m,n)){
        dp[0].update(i,1);
    }
    ll se[m+1],te[m+1];
    rep(j,1,m){
        ll s=n/j;
        ll t=n/(j+1)+1;
        Min(s,n);
        Max(t,m+1);
        se[j]=s;
        te[j]=t;
        if(t>s)continue;
        ep[0].update(j,s-t+1);
    }
    rep(i,1,k-1){
        rep(j,1,m){
            ll bou=n/j;
            Min(bou,m);
            ll add=dp[i-1].query(1,bou+1);
            ll add2=ep[i-1].query(j,m+1);
            Add(add,add2);
            dp[i].update(j,add);
        }
        rep(j,1,m){
            if(te[j]>se[j])continue;
            ll add=mod(dp[i-1].query(1,j+1)*(se[j]-te[j]+1));
            ep[i].update(j,add);
        }
    }
    ll ans=dp[k-1].query(1,m+1)+ep[k-1].query(1,m+1);
    cout<<mod(ans)<<endl;
    return 0;
}

