#include <bits/stdc++.h>
using namespace std;
using ll = long long;

#define mod 1000000007

int main() {
    int N, K;
    cin >> N >> K;

    int rootN = sqrt(N);

    // (a, b, c) は区間[a, b] の要素iが i*c <= N かつ i*(c+1) > N を満たすことを示す
    // cはいらないので(a, b)だけ保存
    // b = N/c, aは一個前のbに+1
    vector<pair<int, int>> element;
    element.reserve(2*rootN+2);

    for (int i = 1; i <= rootN; ++i) {
        element.push_back(make_pair(i, i));
    }
    int last = rootN;
    // i = c で回す
    for (int i = N / (rootN+1); i > 0; --i) {
        int b = N / i;
        element.push_back(make_pair(last+1, b));
        last = b;
    }

    // i番目の数はelement[i]が右端に来る場合の数
    vector<ll>ans(element.size(), 0);
    ans[0] = 1; // 0回目, 右には[1, N]の任意の数が来る

    // K回の更新で答えが出る
    for (int i = 0; i < K; ++i) {
        vector<ll>temp(element.size());
        ll c_sum = 0;
        for (int j = 0; j < element.size(); ++j) {
            int rev = element.size()-1-j;
            c_sum = (c_sum + ans[j]) % mod;
            temp[rev] = c_sum * (element[rev].second - element[rev].first + 1) % mod;
        }
        ans.swap(temp);
    }

    ll sum = 0;
    for (int i = 0; i < ans.size(); ++i) {
        sum = (sum + ans[i]) % mod;
    }
    cout << sum;
    return 0;
}

