LLI dp[110][70000];

int main(){
  cin.tie(0);
  ios::sync_with_stdio(false);

  int N,K;
  while(cin >> N >> K){

    vector<int> div;
    for(int i=1; i*i<=N; ++i){
      div.push_back(i);
      div.push_back(N/i);
    }
    sort(RALL(div));
    UNIQ(div);

    int m = div.size();

    vector<int> cnt(m);

    cnt[0] = 1;
    FOR(i,1,m){
      cnt[i] = N/div[i] - N/div[i-1];
    }

    fill_array(dp, 0);

    REP(i,m) dp[1][i] = cnt[i];

    FOR(i,1,K){
      vector<LLI> sum(m+1);
      REP(j,m) sum[j+1] = (sum[j] + dp[i][j]) % mod;

      REP(j,m){
	dp[i+1][j] += sum[m-j] * cnt[j] % mod;
      }
    }

    LLI ans = 0;
    REP(i,m) (ans += dp[K][i]) %= mod;

    cout << ans << endl;
  }


  return 0;
}

