void solve() {
	cin >> N >> K;
	vector<int> s;
	for(int i = 1; i * i <= N; i++) {
		s.pb(i); s.pb(N / i);
	}
	// debug(sz(s), K);
	s.pb(0);
	sort(all(s)); s.erase(unique(all(s)), s.end());
	rep(i, 1, sz(s)) {
		T[i] = lower_bound(all(s), N / s[i]) - s.begin();
	}
	dp[0][1] = 1;
	rep(i, 0, K) {
		rep(j, 1, sz(s)) ADD(dp[i][j + 1], dp[i][j]);
		rep(j, 1, sz(s)) {
			ADD(dp[i + 1][j], dp[i][T[j]] * (s[j] - s[j - 1]) % mod);
		}
	}
	ll res = 0;
	rep(j, 1, sz(s)) ADD(res, dp[K][j]);
	cout << res << "\n";
}

