using namespace std;

int mod = 1000000007;

int main() {
  int n, k;
  scan(n, k);
  deque<int> sep;
  FOR (i, 1, n) {
    sep.push_front(n / i);
    if (n / i <= sqrt(n)) {
      for (int j = n / i - 1; j >= 0; --j) {
        sep.push_front(j);
      }
      break;
    }
  }
  int sz = sep.size();
  rep (i, sz-1) {
    int width = sep[i+1] - sep[i];
    assert (width > 0);
  }
  vll dp(sz-1, 0);
  dp[0] = 1;
  rep (j, k) {
    vll dp1(sz, 0);
    rep (i, sz-1) {
      dp1[0] += dp[i];
      dp1[sz-1 - i] -= dp[i];
    }
    rep (i, sz-1) {
      dp1[i+1] = dp1[i] + dp1[i+1];
    }
    rep (i, sz-1) {
      dp1[i] = dp1[i] % mod * (sep[i+1] - sep[i]) % mod;
    }
    swap(dp, dp1);
  }

  ll ans = 0;
  rep (i, sz-1) {
    ans = (ans + dp[i]) % mod;
  }
  print(ans);

  return 0;
}

