{
    long long N, K;
    cin >> N >> K;

    map<long long, long long> count;
    for (long long i = 1; i * i <= N; i++)
    {
        count[i] = 0;
        count[N / i] = 0;
    }

    long long pre = 0;
    long long idx = 0;
    map<long long, long long> dict;
    for (auto itr = count.begin(); itr != count.end(); itr++, idx++)
    {
        count[itr->first] = itr->first - pre;
        pre = itr->first;

        dict[idx] = itr->first;
    }

    vector<vector<long long>> dp(K + 1, vector<long long>(count.size(), 0));
    dp[0][0] = 1;

    for (long long i = 1; i <= K; i++)
    {
        long long sum = 0;
        for (long long j = count.size() - 1; j >= 0; j--)
        {
            sum += dp[i - 1][count.size() - j - 1];
            sum %= MOD;
            dp[i][j] = sum * count[dict[j]];
            dp[i][j] %= MOD;
        }
    }

    long long ans = 0;
    for (long long v : dp.back())
    {
        ans += v;
        ans %= MOD;
    }
    cout << ans << endl;
}

