	constexpr modint& operator*=(const modint rhs) noexcept
	{
		a = a * rhs.a % Modulus;
		return *this;
	}
	constexpr modint& operator/=(modint rhs) noexcept
	{
		u64 exp = Modulus - 2;
		while (exp)
		{
			if (exp % 2)
			{
				*this *= rhs;
			}
			rhs *= rhs;
			exp /= 2;
		}
		return *this;
	}
};
typedef modint<MOD> ModInt;

ModInt mod_pow(ModInt x, ModInt n) {
	ModInt ret = 1;
	while (n.a > 0) {
		if (n.a & 1) (ret *= x);
		(x *= x);
		n.a >>= 1;
	}
	return ret;
}

lint N, K;

int main() {
	cin >> N >> K;
	ModInt ans = 0;
	for (int i = 1; i <= sqrt(N); i++) {
		ans += mod_pow(i, K - 1) * (N / i - N / (i + 1));
	}
	for (int i = 1; i < sqrt(N); i++) {
		if(i != N / i) ans += mod_pow(N / i, K - 1);
	}
	cout << ans.a << endl;
}

