void solv() {
	ll k;
	cin >> n>> k;
	vector<ll> v;
	for (ll i = 1; i * i <= n; i++)
	{
		v.push_back(i);
		v.push_back(n / i);
	}
	vsort(v);
	dup(v);
	ll dp[110][100010];
	all0(dp);
	for (int i = 0; i < v.Len; i++)
	{
		dp[0][i] = v[i] - (i > 0 ?v[i-1]:0);
	}

	rep2(i, 1, k) {
		// 累積
		vector<ll> v2(v.Len);
		rep(j, v.Len) {
			v2[j] = dp[i - 1][j];
			if (j > 0)v2[j] += v2[j - 1];
		}

		rep(j, v.Len) {
			dp[i][j] = v2[v.Len- j - 1] * (v[j] - (j > 0 ? v[j - 1] : 0));
			dp[i][j] %= INF;
		}
	}

	ll res = 0;
