  int sqrt = [n]{
    for (int i = 1; i <= n; i++) {
      if (i * i > n) return i - 1;
    }
    assert(false);
    return -1;
  }();
  std::vector<int> a = [n, sqrt]{
    std::vector<int> b(sqrt);
    std::iota(b.begin(), b.end(), 1);
    auto c = b;
    std::for_each(c.begin(), c.end(), [n](int& x){x = n / x;});
    std::reverse(c.begin(), c.end());
    if (b.back() == c.front()) c.erase(c.begin());
    b.insert(b.end(), c.begin(), c.end());
    return b;
  }();
  int N = a.size();
  assert(N == sqrt * 2 || N == sqrt * 2 - 1);
  assert(a[0] == 1);
  assert(a[N - 1] == n);
  auto w = a;
  for (int i = N - 1; i >= 1; i--) {
    w[i] -= w[i - 1];
  }
  auto lb = [&] (int x) {
    if (x <= sqrt) return x - 1;
    else return N - (n / x);
  };
  std::vector<int> dp(N, 1);
  auto make_cum = [&] (const std::vector<int>& x) {
    assert(((int)x.size() == N));
    std::vector<int> y(N + 1, 0);
    for (int i = 1; i <= N; i++) {
      y[i] = mint::sum(y[i - 1], mint::prod(x[i - 1], w[i - 1]));
    }
    return y;
  };
  auto cum = make_cum(dp);
  auto sum = [&] (int x) {
    assert(1 <= x && x <= n);
    int i = lb(x);
    assert(0 <= i && i < N);
    assert(x <= a[i]);
    int ret = cum[i + 1];
    mint::dif(ret, mint::prod(dp[i], a[i] - x));
    return ret;
  };
  auto renew = [&] {
    std::vector<int> new_dp(N);
    for (int i = 0; i < N; i++) {
      new_dp[i]  = sum(n / a[i]);
    }
    dp  = new_dp;
    cum = make_cum(dp);
  };
  for (int i = 0; i < k - 1; i++) {
    renew();
  }
  std::cout << sum(n) << std::endl;
  return 0;
}

