using namespace std;

typedef long long ll;
const ll mod = 1e9 + 7;

class STlazy{
private:
    int n;
    vector<ll> node, lazy;

public:
    STlazy(vector<ll> v){
        int siz = v.size();
        n = 1;
        while(n < siz)  n *= 2;
        node.resize(2*n-1, 0);
        lazy.resize(2*n-1, 0);

        for(int i = 0; i < siz; i++)    node[n-1+i] = v[i];
        for(int i = n-2; i >= 0; i--)   node[i] = node[2*i+1] + node[2*2+2];
    }

    void eval(int k, int l, int r){
        if(lazy[k] == 0)    return;
        node[k] += lazy[k]; node[k] %= mod;
        if(r-l > 1){
            lazy[2*k+1] += lazy[k]/2;
            lazy[2*k+2] += lazy[k]/2;
        }
        lazy[k] = 0;
    }

    void add(int a, int b, ll x, int k=0, int l=0, int r=-1){
        if(r < 0)   r = n;
        eval(k, l, r);
        if(r <= a || b <= l)    return;
        if(a <= l && r <= b){
            lazy[k] += (r-l)*x;
            eval(k, l, r);
            return;
        }
        add(a, b, x, 2*k+1, l, (l+r)/2);
        add(a, b, x, 2*k+2, (l+r)/2, r);
        node[k] = (node[2*k+1] + node[2*k+2])%mod; // 自分の全ての子孫の値伝播が終わったら自分を更新する
    }

    ll query(int a, int b, int k=0, int l=0, int r=-1){
        if(r < 0)   r = n;
        if(r <= a || b <= l)    return 0;
        eval(k, l, r); // 最初の呼び出しが必ずeval(0,0,n)となるので漏れなく上から値の伝播がなされている
        if(a <= l && r <= b)    return node[k];
        ll lx = query(a, b, 2*k+1, l, (l+r)/2);
        ll rx = query(a, b, 2*k+2, (l+r)/2, r);
        return (lx+rx)%mod;
    }
};

int main(){
    int n, k;
    cin >> n >> k;

    vector<int> to, val;
    int r = 1;
    while(r <= n){
        int tmp = n/r;
        int reach = n/tmp;
        to.push_back(reach);
        val.push_back(tmp);
        r = reach+1;
    }

    int siz = to.size(); // O(sqrt(N)) ?

    vector<ll> cnt(siz, 1);
    for(int i = 1; i < siz; i++)    cnt[i] = to[i]-to[i-1];

    auto f = [&](int x)->int{
        return upper_bound(to.begin(),to.end(),x)-to.begin();
    };

    // memo (needless)
    vector<int> memo(siz);
    for(int i = 0; i < siz; i++)    memo[i] = f(val[i]);

    // O(sqrt(N) * log(sqrt(N)) * K) ?
    vector<vector<ll>> dp(k, vector<ll>(siz+1, 0));
    for(int i = 0; i < siz; i++)    dp[0][i] = cnt[i];
    for(int i = 0; i+1 < k; i++){
        for(int j = 0; j < siz; j++){
            dp[i+1][0] = (dp[i+1][0] + dp[i][j]) % mod;
            dp[i+1][memo[j]] = (dp[i+1][memo[j]] - dp[i][j] + mod) % mod;
        }
        for(int j = 1; j < siz; j++){
            dp[i+1][j] += dp[i+1][j-1];
            if(dp[i+1][j] < 0)    dp[i+1][j] += mod;
            dp[i+1][j] %= mod;
        }
        for(int j = 0; j < siz; j++){
            dp[i+1][j] *= cnt[j];
            dp[i+1][j] %= mod;
        }
    }

    // for(int i = 0; i < k; i++){
    //     for(int j = 0; j < siz; j++){
    //         cout << dp[i][j] << " ";
    //     }
    //     cout << endl;
    // }

    ll ans = 0;
    for(int i = 0; i < siz; i++)    ans += dp[k-1][i], ans %= mod;
    cout << ans << endl;

    return 0;
}

