int main() {

	int n,k;cin >> n >> k; //積n以下、k個並べる
	int m = (int)sqrt(n);
	vector<int> b;
	for (int i = 1; i <= m; i++) {
		b.pb(i);
		b.pb(n/i);
	}
	sort(all(b));UNIQUE(b);
	int s = b.size();

	//例:10... {1,2,3,5,10} -> {1,1,1,2,5}
	vector<int> d;//[n/i]がいくつ重複するか
	bool first = true; int pre;
	for (auto i : b) {
		if (first) {
			d.pb(i);pre = i;
			first = false;
		}
		else {
			d.pb(i - pre);pre = i;
		}
	}

	//dp[i][j]はdp[i-1][s+1-j]までの累積和
	//dが0-indexであることに注意！

	//i == 1に埋めておく
	for (int j = 1; j <= s; j++) {
		//cout << b[j-1] << " ";
		dp[1][j] = (mint)((n / b[j-1]));
		//cout << dp[1][j].x << " ";
	}
	//cout << endl;
	//i >= 2
	for (int i = 2; i <= k + 1; i++) {
		//jまでの累積和を作る
		vector<mint> cum;
		cum.pb(0);
		for (int j = 1; j <= s; j++) {
			cum.pb(cum[j-1] + (mint)d[j - 1] * dp[i-1][j]);
		}
		//dp[i][]を埋める
		for (int j = 1; j <= s; j++) {
			dp[i][j] = cum[s+1-j];
		}
	}
