template <int MOD = 1000000007>
struct Mint{
    int x;

    Mint() : x(0) {}
    Mint(int t){
        x = t % MOD;
        if(x < 0) x += MOD;
    }

    Mint pow(int n){
        Mint res(1), t(x);
        while(n > 0){
            if(n & 1) res *= t;
            t *= t;
            n >>= 1;
        }
        return res;
    }

    Mint inv() const {
        ll a = x, b = MOD, u = 1, v = 0, t;
        while(b > 0){
            t = a / b;
            a -= t * b;
            swap(a, b);
            u -= t * v;
            swap(u, v);
        }
        return Mint(u);
    }

    Mint & operator += (Mint a){
        x += a.x;
        if(x >= MOD) x -= MOD;
        return *this;
    }

    Mint & operator -= (Mint a){
        x += MOD - a.x;
        if(x >= MOD) x -= MOD;
        return *this;
    }

    Mint & operator *= (Mint a){
        x = 1LL * x * a.x % MOD;
        return *this;
    }

    Mint & operator /= (Mint a){
        return (*this) *= a.inv();
    }

    Mint operator + (Mint a) const { return Mint(x) += a; }
    Mint operator - (Mint a) const { return Mint(x) -= a; }
    Mint operator * (Mint a) const { return Mint(x) *= a; }
    Mint operator / (Mint a) const { return Mint(x) /= a; }

    Mint operator - () const{ return Mint(-x); }

    bool operator == (const Mint a){ return x == a.x; }
    bool operator != (const Mint a){ return x != a.x; }
    bool operator < (const Mint a){ return x < a.x; }

    friend ostream & operator << (ostream & os, const Mint &a){
        return os << a.x;
    }

    friend istream & operator >> (istream & is, Mint &a){
        int t;
        is >> t;
        a = Mint<MOD>(t);
        return (is);
    }
};

signed main(){
    int n,k;
    cin >> n >> k;
    vector<int> v;
    for(int i = 1; i * i <= n; i++){
        v.emplace_back(i);
        if(i != n / i) v.emplace_back(n / i);
    }
    sort(ALL(v));
    int m = v.size();
    int cnt[m];
    cnt[0] = 1;
    for(int i = 1; i < m; i++){
        cnt[i] = v[i] - v[i - 1];
    }
    Mint<> dp[k + 1][m];
    dp[0][0] = 1;
    for(int i = 0; i < k; i++){
        Mint<> sum[m + 1];
        for(int j = 0; j < m; j++){
            sum[j + 1] = sum[j] + dp[i][j];
        }
        for(int j = 0; j < m; j++){
            dp[i + 1][j] += sum[m - j] * cnt[j];
        }
    }
    Mint<> ans = 0;
    for(int i = 0; i < m; i++){
        ans += dp[k][i];
    }
    cout << ans << endl;
    return 0;
}

