long MOD = 1000000007;

int main() {
  long N, K;
  cin >> N >> K;
  long sN = sqrt(N);
  long dp[K + 5][sN + 5];

  vector<NumSet> ns;

  long num = 1;
  while (num < N) {
    long start = num;
    long next = N / num;
    long end = N / next;
    ns.push_back({start, end, next});

    num = end + 1;
    // cout << "start: " << start << endl;
    // cout << "end: " << end << endl;
    // cout << "next: " << next << endl;
  }

  // cout << "dp 1" << endl;
  for (long i = 0; i < ns.size(); i++) {
    dp[1][i] = ns[i].end - ns[i].start + 1;

    // cout << dp[1][i] << endl;
  }

  for (long i = 2; i <= K; i++) {
    // cout << "dp " << i << endl;
    long tempSum = 0;
    for (long j = ns.size() - 1; j >= 0; j--) {
      if (j + 1 == ns.size()) {
        tempSum += dp[i - 1][0];
        dp[i][j] = tempSum * (ns[j].end - ns[j].start + 1);
      } else {
        tempSum += dp[i - 1][ns.size() - 1 - j];
        dp[i][j] = tempSum * (ns[j].end - ns[j].start + 1);
      }
      dp[i][j] %= MOD;
      // cout << dp[i][j] << endl;
    }
  }

  // cout << ns.size() << endl;

  long sum = 0;
  for (long i = 0; i < ns.size(); i++) {
    sum += dp[K][i];
  }
  sum %= MOD;
  cout << sum << endl;
  return 0;
}

