template <class T>
T lower_gauss(T num, T den) {
    assert(den != 0);
    if (num == 0) return 0;
    if (num > 0 and den > 0) return num / den;
    if (num < 0 and den > 0) return (num - den + 1) / den;
    return lower_gauss(-num, -den);
}

template <class T>
T upper_gauss(T num, T den) {
    return lower_gauss(num, den) + (num % den == 0 ? 0 : 1);
}



void solve() {
    const i64 mod = 1'000'000'007;

    i64 N,K;
    cin >> N >> K;

    set<i64> a;
    rep(i,1,N) {
        if (i * i > N) break;
        a.insert(i);
        a.insert(N / i);
    }

    vector<i64> vals;
    for(auto x:a) vals.emplace_back(x);

    map<i64,i64> count; // |lower_gauss(N/j) = i : 1<=j<=N| = count[i]
    for(auto i:a){
        i64 lower; // lower_gauss(N/lower)>=i, lower_gauss(N/(lower-1))>i
        i64 upper; // lower_gauss(N/upper)<i, lower_gauss(N/(upper-1))>=i
        {
            i64 lb=0; // lower_gauss(N/lb) > i
            i64 ub=N; // lower_gauss(N/ub) <=i
            while(ub-lb>1){
                i64 mid=(lb+ub)/2;
                if(N/mid<=i) ub=mid;
                else lb=mid;
            }
            lower=ub;
        }
        {
            i64 lb=1; // lower_gauss(N/lb) >= i
            i64 ub=N+1; // upper_gauss(N/ub) < i
            while(ub-lb>1){
                i64 mid=(lb+ub)/2;
                if(N/mid<i) ub=mid;
                else lb=mid;
            }
            upper=ub;
        }
        assert(N/lower>=i);
        assert(N/upper<i);
        count[i]=upper-lower;
    }
    map<i64,i64> idx;
    rep(i,0,vals.size()) idx[vals[i]]=i;

    vector<vector<i64>> dp(K,vector<i64>(a.size()));

    dp[0][0]=count[N/vals[0]];
    rep(i,1,vals.size()){
        dp[0][i]=(dp[0][i-1]+count[N/vals[i]])%mod;
    }

    rep(i,1,K){
        dp[i][0]=dp[i-1][idx[N]];
        rep(j,1,vals.size()){
            dp[i][j]=(dp[i][j-1]+dp[i-1][idx[N/vals[j]]]*count[N/vals[j]]%mod)%mod;
        }
    }

    cout << dp[K-1][idx[N]] << endl;
}

