    reverse(begin(dp), end(dp));
    vector< modint > dp2(range.size());
    modint add = 0;
    for(int j = range.size() - 1; j >= 0; j--) {
      add += dp[j];
      dp2[j] = add * (range[j].first.second - range[j].first.first + 1);
    }
    dp.swap(dp2);
  }
  modint ret;
  for(auto &t : dp) ret += t;
  cout << ret << endl;
}

