long long solve(){
    long long bf = sqn;
    for(long long i = sqn;i > 0;--i){
        cnt.push_back(n / i - bf);
        bf = n / i;
    }
    dp.assign(k + 1,vector<long long>(2 * sqn,0));
    for(int i = 0;i < sqn;++i)dp[0][i] = 1;
    for(int i = 0;i < k;++i){
        for(int j = 0;j < sqn;++j){
            // <= sqrt(n)
            dp[i+1][j] = (dp[i][sqn-1] + dp[i][2 * sqn - 1 - j]) % N;
            if(j != 0)(dp[i+1][j] += dp[i+1][j-1]) %= N;
            // >sqrt(n)
            dp[i+1][j+sqn] = dp[i][sqn-1-j] * cnt[j] % N;
            if(j != 0)(dp[i+1][j+sqn] += dp[i+1][j-1+sqn]) %= N;
        }
    }
    return (dp[k][sqn-1] + dp[k][2 * sqn - 1]) % N;
}

