ll dp[105][100005];
ll cnt[100005];
const ll MOD =1e9+7;
template<class Type>
Type solve(Type res = Type()){
    ll N,K; cin >> N >> K;

    ll M = 0;
    for(ll i = 1; i <= N;){
        ll j = N/i;
        if(i <= j){
            cnt[M++] = 1;
            i++;
        }else{
            cnt[M++] = N/j - i + 1;
            i = N/j + 1;
        }
    }

    auto add = [&](ll& l,const ll v){
        (l += v)%=MOD;
    };

    vector<ll> cusum(M+5);

    dp[0][0] = 1;
    for(int k = 0; k < K;k++){
        fill(cusum.begin(),cusum.end(),0);

        for(int j = 0; j <= M;j++){
            cusum[j+1] = cusum[j] + dp[k][j];
        }
        for(int j = 0; j < M;j++){
            add(dp[k+1][j],cusum[M-j]*cnt[j]%MOD);
        }
    }

    for(auto v:dp[K]){
        add(res,v);
    }

    return res;
}
int main(void) {
    cin.tie(0); ios_base::sync_with_stdio(false);
    // solve(0);
    cout << fixed << setprecision(15) << solve<ll>() << endl;
    return 0;
}

