void pre() //calculate n/k
{
    ll st = n , l , h , mid , tmp , res;
    while(st > 0) //max sqrt * 2
    {
        l = 1 , h = st , tmp = n/st , res = 2e9;
        while(l<=h)
        {
            mid = (l+h)/2;
            if (n/mid > tmp) l = mid+1;
            else
            {
                res = min(res , mid);
                h = mid-1;
            }
        }
        a[idx].f = st-res+1 , a[idx].s = st;
        mp[st] = idx;
        idx++ , st = res-1;
    }

    for(int i=1; i<idx; i++)
    {
        tmp = n/a[i].s;
        to[i] = mp[tmp];
    }
 //   cout << idx << " okkk\n";
}

ll solve(int i , int lst)
{
    if (i > k)
        return 1;

    if (dp[i][lst] != -1)
        return dp[i][lst];

    ll ans = 0;
    if (lst < idx-1) ans += solve(i , lst+1);
    ans %= mod;
    ans = ((ans%mod) + ((solve(i+1 , to[lst])%mod) *(a[lst].f%mod))%mod )%mod;

    return dp[i][lst] = ans;
}

