int f[maxk][maxn];
int main(){
	int n, k; cin >> n >> k;
	set<tuple<int,int,int>> can;
	vector<int> split_at;
	for(int i = 1; i <= n; ){
		int lo = i + 1, hi = n, ans = i;
		int desire = n / i;
		while(lo <= hi){
			int mid = (lo+hi)>>1;
			if(n / mid == desire) ans = mid, lo = mid + 1;
			else hi = mid - 1;
		}
		can.insert(make_tuple(i, ans, desire));
		split_at.push_back(desire);
		i = ans + 1;
	}
	for(int v : split_at){
		auto it = can.lower_bound(make_tuple(v + 1, -1, -1));
		if(it != can.begin()){
			it--;
			int x, y, z; tie(x, y, z) = *it;
			if(y != v){
				can.erase(it);
				can.insert(make_tuple(x, v, z));
				can.insert(make_tuple(v + 1, y, z));
			}	
		}
	}
	vector<tuple<int,int,int> > conv;
	for(auto e : can) conv.push_back(e);
	for(int i = 0; i < conv.size(); i++){
		int x, y, z; tie(x, y, z) = conv[i];
		int pt = lower_bound(conv.begin(), conv.end(), make_tuple(z + 1, -1, -1)) - conv.begin(); pt--;
		if(get<1>(conv[pt]) != z){
			cout << get<1>(conv[pt]) << " " << pt << " " << z << endl;
		}
		assert(y - x + 1 >= 1);
		assert(get<1>(conv[pt]) == z);
		opt.push_back({y - x + 1, pt});
	}
	int len = opt.size();
	for(int i = 0; i < len; i++) f[0][i] = 1;
	for(int i = 1; i <= k; i++){
		for(int j = 0; j < len; j++){
			if(j) f[i][j] = f[i][j - 1];
			f[i][j] += mul(opt[j].first, f[i - 1][opt[j].second]);
			if(f[i][j] >= mod) f[i][j] -= mod;
		}
	}	
	cout << f[k][len - 1] << endl;
	return 0;
}

