int main() {
    ll N, K;
    cin >> N >> K;
    ll m = (ll)sqrt(N);
    while ( (m+1)*(m+1) <= N ) m++;
    vector<ll> dp1(m+1, 1), dp2(m+1), c(m+1);
    for ( int i = 1; i <= m; i++ ) {
        if ( i < m ) c[i] = N/i - N/(i+1);
        else c[i] = N/i - m;
        dp2[i] = c[i];
    }

    vector<ll> dp1t(m+1), dp2t(m+1);
    vector<ll> dp1s(m+1), dp1st(m+1); // 1..i
    vector<ll> dp2s(m+1), dp2st(m+1); // i..m
    for ( int i = 1; i <= m; i++ ) {
        if ( i > 0 ) dp1s[i] += dp1s[i-1];
        dp1s[i] += dp1[i];
    }
    for ( int i = m; i >= 1; i-- ) {
        if ( i < m ) dp2s[i] += dp2s[i+1];
        dp2s[i] += dp2[i];
    }
    for ( int k = 1; k < K; k++ ) {
        for ( int i = 1; i <= m; i++ ) {
            dp1t[i] = 0;
            dp1t[i] += dp1s[m];
            dp1t[i] += dp2s[i];
            dp1t[i] %= MOD;

        }
        for ( int i = 1; i <= m; i++ ) {
            dp2t[i] = 0;
            dp2t[i] += c[i] * dp1s[i];
            dp2t[i] %= MOD;
        }
        for ( int i = 1; i <= m; i++ ) {
            dp1st[i] = 0;
            if ( i > 0 ) dp1st[i] += dp1st[i-1];
            dp1st[i] += dp1t[i];
            dp1st[i] %= MOD;
        }
        for ( int i = m; i >= 1; i-- ) {
            dp2st[i] = 0;
            if ( i < m ) dp2st[i] += dp2st[i+1];
            dp2st[i] += dp2t[i];
            dp2st[i] %= MOD;
        }
        dp1.swap(dp1t);
        dp2.swap(dp2t);
        dp1s.swap(dp1st);
        dp2s.swap(dp2st);
    }

    ll ans = dp1s[m] + dp2s[1];
    ans %= MOD;
    cout << ans << '\n';
    return 0;
}

