ll cnt[70000];
ll hoge[70000];
ll dp[111][70000];
ll sm[111][70000];

void solve() {
    cin >> N >> K;
    map<ll, ll> mp;

    for (ll i = 1; i <= N; ) {
        ll x = N / i;
        ll lo = i;
        ll hi = N + 1;
        while (hi - lo > 1) {
            ll mid = (hi + lo) / 2;
            if (N / mid == x) lo = mid;
            else hi = mid;
        }
        mp[x] = lo - i + 1;
        i = lo + 1;
    }

    int M = mp.size();
    int idx = 0;
    for (auto x: mp) {
        cnt[idx] = x.second;
        comp[x.first] = idx++;
    }
    for (auto x: mp) {
        hoge[comp[x.first]] = comp[N/x.first];
    }

    ll prev = -1;
    for (int i = M - 1; i >= 0; --i) {
        dp[0][i] = cnt[i];
        sm[0][i] = cnt[i];
        if (prev != -1) (sm[0][i] += sm[0][prev]) %= MOD;
        prev = i;
    }

    REP2(i, 1, K) {
        prev = -1;
        for (int j = M - 1; j >= 0; --j) {
            (dp[i][j] += sm[i-1][hoge[j]] * cnt[j]) %= MOD;
            sm[i][j] = dp[i][j];
            if (prev != -1) (sm[i][j] += sm[i][prev]) %= MOD;
            prev = j;
        }
    }

    cout << sm[K-1][0] << endl;
}

