vector<ll> divisor(ll n) {
    vector<ll> res;
    ll pre = n+1;
    for (ll i = 1; i * i <= n; i++) {
        if (n / i < pre) {
            res.push_back(i);
            if (i != n / i) res.push_back(n / i);
        }
    }
    return res;
}

