typedef long long ll;

constexpr int M = 1000 * 1000 * 1000 + 7;

ll dp[2][100000];
int last_number[100000];

int main() {
    std::ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, k;
    cin >> n >> k;
    stack<int> tmp;
    int c = 0;
    for (int i = 1; i * i <= n; ++i) {
        last_number[c++] = i;
        tmp.push(n / i);
    }
    while (!tmp.empty()) {
        int cur = tmp.top();
        tmp.pop();
        if (last_number[c - 1] != cur) {
            last_number[c++] = cur;
        }
    }
    ll *dp_cur = dp[0];
    ll *dp_next = dp[1];
    dp_cur[0] = 1;
    ll total_sum = n;
    for (int i = 1; i < c; ++i) {
        dp_cur[i] = last_number[i] - last_number[i - 1];
    }
    for (int j = 1; j < k; ++j) {
        for (int i = 0; i < c; ++i) {
            dp_next[i] = total_sum * (last_number[i] - (i ? last_number[i - 1] : 0)) % M;
            total_sum -= dp_cur[c - i - 1];
            if (total_sum < 0) total_sum += M;
        }
        swap(dp_cur, dp_next);
        total_sum = 0;
        for (int i = 0; i < c; ++i) {
            total_sum += dp_cur[i];
            if (total_sum >= M) {
                total_sum -= M;
            }
        }
    }
    cout << total_sum << endl;
}

