    mint(ll x = 0) : x((x % mod + mod) % mod) {}

    mint &operator+=(const mint a) {
        if ((x += a.x) >= mod) x -= mod;
        return *this;
    }

    mint &operator-=(const mint a) {
        if ((x += mod - a.x) >= mod) x -= mod;
        return *this;
    }

    mint &operator*=(const mint a) {
        (x *= a.x) %= mod;
        return *this;
    }

    mint operator+(const mint a) const {
        mint res(*this);
        return res += a;
    }

    mint operator-(const mint a) const {
        mint res(*this);
        return res -= a;
    }

    mint operator*(const mint a) const {
        mint res(*this);
        return res *= a;
    }

    mint pow(ll t) const {
        if (!t) return 1;
        mint a = pow(t >> 1);
        a *= a;
        if (t & 1) a *= *this;
        return a;
    }

    // for prime mod
    mint inv() const {
        return pow(mod - 2);
    }

    mint &operator/=(const mint a) {
        return (*this) *= a.inv();
    }

    mint operator/(const mint a) const {
        mint res(*this);
        return res /= a;
    }

    friend std::istream &operator>>(std::istream &in, mint &o) {
        ll a;
        in >> a;
        o = a;
        return in;
    }

    friend std::ostream &operator<<(std::ostream &out, const mint &o) {
        out << o.x;
        return out;
    }

};

map<ll, mint> map_csum(map<ll, mint> m) {
    vector<ll> keys;
    for (auto e : m)keys.push_back(e.first);
    for (int i = 1; i < keys.size(); i++) {
        m[keys[i]] += m[keys[i - 1]];
    }
    return m;
}

int main() {

    ll n;
    int k;
    cin >> n >> k;

    set<ll> candidate;
    for (ll i = 1; i * i <= n; i++) {
        candidate.insert(i);
        candidate.insert(n / i);
    }

    vector<ll> candidate_vec;
    for (ll l : candidate) candidate_vec.push_back(l);
    reverse(candidate_vec.begin(), candidate_vec.end());

    map<ll, ll> conv;
    rep(i, candidate_vec.size()) conv[candidate_vec[i]] = i;

    vector<mint> layer(candidate_vec.size(), 0);

    layer[conv[1]] = 1;
    for (int i = 1; i < candidate_vec.size(); i++) {
        ll a = n / (candidate_vec[i - 1]);
        ll b = n / candidate_vec[i];

        ll cou = b - a;

        layer[conv[b]] = cou;
    }

    vector<mint> prev = layer;
    for (int i = 1; i < k; i++) {

        for (int j = candidate_vec.size() - 2; j >= 0; j--) {
            prev[conv[candidate_vec[j]]] += prev[conv[candidate_vec[j + 1]]];
        }

        vector<mint> next(candidate_vec.size());
        for (ll key : candidate_vec) {
            next[conv[key]] += prev[conv[n / key]] * layer[conv[key]];

        }
        prev = next;
    }
//
//
    mint ans = 0;
    for (auto e : prev) ans += e;
    cout << ans << endl;

}

