mint fact[N_MAX];
void init(){
  fact[0] = fact[1] = MINT 1;
  for(int i = 2; i < N_MAX; i++){
    fact[i] = fact[i-1] * i;
  }
}

//mod MOD上での逆元
inline mint inv(mint n){
  return modpow(n,MOD-2);
}

//二項係数の計算(mod MOD上)
inline mint COM(int n, int k){
  if(n<k) return 0;
  return fact[n]/(fact[k]*fact[n-k]);
}

vector<PII> divisor(int n){
  vector<PII> v;
  int pre = -1;
  for(int i = 1; i*i <= n; ++i){
    v.push_back(PII(i,0));
    v.push_back(PII(n/i,0));
  }
  sort(all(v));
  v.erase(unique(all(v)),v.end());
  rep(i,v.size()-1){
    int l = n/v[i+1].first;
    int r = n/v[i].first;
    v[i].second = r-l;
  }
  v.back().second = 1;
  return v;
}

