  for(int i = 0; i < K; ++i){
    CumSum<mint> cs(dp);
    vector<mint> dp_(2*M);
    for(int j = 1; j < M; ++j){
      dp_[j] = cs.getsum(R[N/V[j]]+1)*(V[j]-V[j-1]);
    }
    dp = dp_;
  }
  mint ans = 0;
  for(int i = 0; i < M; ++i){
    ans += dp[i];
  }
  cout << ans << endl;
}

