vector<int> quotients(int n) {
    assert(n > 0);
    vector<int> ret;
    int x = 1;
    for ( ; x*x <= n; x++) ret.push_back(n/x);
    --x; if (n/x == x) x--;
    for ( ; x > 0; x--) ret.push_back(x);
    return ret;
}

