LL sum1[N];
LL sum2[N];
int main()
{
	//freopen("input.txt", "r", stdin);
	//freopen("output.txt", "w", stdout);
	int n, k;
	cin >> n >> k;
	int rt = 1;
	while (rt * rt <= n) rt++;
	rt--;
	for (int i = 1; i <= n; i++)
	{
		int l = i;
		int r = n / (n / l);
		if (n / l <= rt && r > rt)
		{
			cnt[n / l] = r - max(l, rt + 1) + 1;
		}
		i = r;
	}
	int o = 0;
	dp1[o][1] = 1;
