int ans(int n, int k) {
    cout << n << " " << k << " called" << endl;
    if (k == 1)
        return d[n];
    else if (n == 0)
        return 0;
    else if (dp[n][k] != -1)
        return dp[n][k];

    ll a = ans(n - 1, k);
    a = (a + (ll(d[n] - d[n - 1]) * (ll)ans((int)d.size() - n, k - 1)) % MOD) % MOD;

    dp[n][k] = (int)a;
    return (int)a;
}

