ll newton(long long int a, long long int  b)
{
	if(a==b)
		return a;
	while(a != 0 && b != 0)
	{
		if(a > b)
		{
			b += a;
			a = b-a;
			b -= a;
		}
		b %= a;
	}
	return a;
}

struct UnionFind {
	vector<int> p;
	UnionFind(int N):p(N)
	{
		for(int i=0; i< N; i++)
		{
			p[i] = i;
		}
	}
	int root(int x)
	{
		if(p[x] == x)
			return x;
		return p[x] = root(p[x]);
	}
	void unite(int x, int y)
	{
		int rx = root(x);
		int ry = root(y);
		if(rx == ry) return;
		p[rx] = ry;
	}
	bool issame(int x, int y)
	{
		int rx = root(x);
		int ry = root(y);
		return rx == ry;
	}
};

//大きな数に対する割り算をするとき、MODを指定することで掛け算の値に変換できる

ll div2mul_calc(ll a, ll b, ll m)
{
	if (b == 0) {
        return 1;
    } else if (b % 2 == 0) {
        ll d = div2mul_calc(a, b / 2, m);
        return (d * d) % m;
    } else {
        return (a * div2mul_calc(a, b - 1, m)) % m;
    }
}
ll div2mul(ll n, ll mod)
{
	return div2mul_calc(n, mod-2, mod);
}

ll twoRow(ll a, ll b, ll mod)
{
	ll ret = 1;
	for(ll i = 1 ;i <= a+b;++i)
	{
		ret *= i;
		ret %= mod;
	}
	for(ll i = 1 ;i <= a;++i)
	{
		ret *= div2mul(i,mod);
		ret %= mod;
	}
	for(ll i = 1 ;i <= b;++i)
	{
		ret *= div2mul(i,mod);
		ret %= mod;
	}
	return ret;
}



int main()
{
	ll i,j,k;
	ll mod = 1000000007;
	ll N,K;
	vector<ll> mp;
	ll total[100000] = {0};
	ll tot_next[100000] = {0};
	cin >> N >> K;
	ll target = 1;
	while(target <= N/2)
	{
		ll next = (ll)(N/target);
		if(next == 1)
			break;
		ll top  = target;
		ll bot  = N;
		ll mid = (top+bot)/2;
		while(bot-top > 1)
		{
			if(next>(ll)(N/mid))
			{
				bot = mid;
			}
			else
			{
				top = mid;
			}
			mid = (top+bot)/2;
		}
		total[mp.size()] = mid;
		mp.push_back(mid);
		target = mid + 1;
	}
	total[mp.size()] = N;
	mp.push_back(N);
	int mp_size = mp.size();
	for(i=1;i<K;++i)
	{
		tot_next[0] = total[mp_size-1];
		tot_next[0] %= mod;
		for(j=1;j<mp_size;++j)
		{

			tot_next[j] = tot_next[j-1] + total[mp_size-j-1];
			tot_next[j] %= mod;
		}
		ll *tp  = total;
		ll *tnp = tot_next;
		ll *swap = tp;
		tp = tnp;
		tnp = swap;
	}
	ll ans = 0;
	for(j=0;j<mp_size;++j)
	{
		ans += total[j];
		ans %= mod;
	}
	cout << ans << endl;
	return 0;
}

