    mint(ll x=0) : x((x%mod+mod)%mod) {}
    mint operator-() const { return mint(-x); }
    mint& operator+=(const mint a) {
        if ((x += a.x) >= mod) x -= mod;
        return *this;
    }
    mint& operator-=(const mint a) {
        if ((x += mod-a.x) >= mod) x -= mod;
        return *this;
    }
    mint& operator*=(const mint a) {
        (x *= a.x) %= mod;
        return *this;
    }
    mint operator+(const mint a) const {
        mint res(*this);
        return res += a;
    }
    mint operator-(const mint a) const {
        mint res(*this);
        return res -= a;
    }
    mint operator*(const mint a) const {
        mint res(*this);
        return res *= a;
    }
    mint pow(ll t) const {
        if (t == 0) return 1;
        mint a = pow(t>>1);
        a *= a;
        if (t&1) a *= *this;
        return a;
    }

    // for prime mod
    mint inv() const {
        return pow(mod-2);
    }
    mint &operator/=(const mint a) {
        return (*this) *= a.inv();
    }
    mint operator/(const mint a) const {
        mint res(*this);
        return res /= a;
    }
};
istream& operator>>(istream& i, mint& var) {
    ll tmp; i >> tmp;
    var.x = tmp;
    return i;
}
ostream& operator<<(ostream& o, const mint& var) {
    o << var.x;
    return o;
}
using vm  = vector<mint>;
using vvm = vector<vm>;

vl getDivisor(ll x) {
    vl res;
    ll pre = x+1;
    for (ll i = 1; i*i <= x; ++i) {
        ll j = x / i;
        if (x % i == 0) {
            res.push_back(i);
            if (i*i != x) res.push_back(j);
            pre = j;
            continue;
        }
        if (j != pre) {
            res.push_back(i);
            if (j != i) res.push_back(j);
            pre = j;
        }
    }
    res.push_back(0);
    sort(res.begin(), res.end());
    return res;
}

map<int,int> getIndices(vl S) {
    map<int,int> res;
    for (int i = 0; i < S.size(); ++i) {
        res[S[i]] = i;
    }
    return res;
}

int main() {
    ll N, K; cin >> N >> K;

    vl divs = getDivisor(N);
    map<int, int> toIdx = getIndices(divs);

    vm dp(divs.size(), 0);
    for (int i = 1; i < divs.size(); ++i) {
        dp[i] += mint(divs[i] - divs[i-1]);
        dp[i] += dp[i-1];
    }
    for (int k = 0; k < K-1; ++k) {
        vm ndp(divs.size(), 0);
        for (int i = 1; i < divs.size(); ++i) {
            ll t = N / divs[i], ti = toIdx[t];
            ndp[i] += mint(divs[i] - divs[i-1]) * dp[ti];
            ndp[i] += ndp[i-1];
        }
        dp = ndp;
    }

    mint ans = dp[divs.size()-1];
    cout << ans << endl;
    return 0;
}

