  vector<ll> dp = v;
  rep(i, k - 1) {
    BIT bit(dp);
    rep(j, sz(v)) dp[j] = bit.sum(sz(v) - j) % mod * v[j] % mod;
    // cout << dp << '\n';
  }
  cout << accumulate(all(dp), 0LL) % mod << '\n';
}

