namespace NyaGadget
{
	/*** MOD ライブラリ ***/

	template<ll maxv> struct ModLL
	{
		ll x;

		// コンストラクタ
		ModLL() { x = 0; }
		ModLL(ll x_)
		{
			x = x_ % maxv + maxv;
			if (x >= maxv)
				x -= maxv;
		}

		// 符号
		ModLL operator + () const { return x; }
		ModLL operator - () const { return (-x < 0) ? maxv - x : -x; }

		// 加減乗除演算子
		ModLL& operator += (ModLL r)
		{
			if ((x += r.x) >= maxv)
				x -= maxv;
			return *this;
		}
		ModLL& operator -= (ModLL r)
		{
			if ((x -= r.x) < 0)
				x += maxv;
			return *this;
		}
		ModLL& operator *= (ModLL r)
		{
			x = (unsigned long long) x * r.x % maxv;
			return *this;
		}
		ModLL& operator /= (ModLL r)
		{
			x = x * Inv(r.x, maxv) % maxv;
			return *this;
		}

		ModLL operator + (ModLL r) const { return ModLL(*this) += r; }
		ModLL operator - (ModLL r) const { return ModLL(*this) -= r; }
		ModLL operator * (ModLL r) const { return ModLL(*this) *= r; }
		ModLL operator / (ModLL r) const { return ModLL(*this) /= r; }

		// 逆元 x^{-1} (主に除算演算子で使用)
		ll Inv(ll a, ll m)
		{
			ll b = m, u = 1, v = 0;

			while (b)
			{
				ll t = a / b;
				a -= t * b; swap(a, b);
				u -= t * v; swap(u, v);
			}

			u %= m;

			return (u < 0) ? u + m : u;
		}

		// 比較演算子
		bool operator == (ModLL& r) const { return x == r.x; }
		bool operator != (ModLL& r) const { return x != r.x; }
		bool operator <  (ModLL& r) const { return x < r.x; }
		bool operator <= (ModLL& r) const { return x <= r.x; }
		bool operator >  (ModLL& r) const { return x > r.x; }
		bool operator >= (ModLL& r) const { return x >= r.x; }

		// 入出力演算子
		friend ostream& operator << (ostream& s, ModLL<maxv> a)
		{
			s << a.x;
			return s;
		}
		friend istream& operator >> (istream& s, ModLL<maxv>& a)
		{
			s >> a.x;
			return s;
		}
	};
}

namespace NyaGadget
{

	/*** 除算の同値商集合を列挙するライブラリ ***/

	struct TableOfEqualDivResult
	{	// q = fn / [fdmin, fdmax] 
		ll c = 0;     // 分母集合の要素数
		ll q = 0;     // 商
		ll fn = 0;    // 分子
		ll fdmin = 0; // 分母最小値
		ll fdmax = 0; // 分母最大値
	};

	/**
	@brief 除算の同値商集合を求める関数
	@param rmax 分子最大値
	@param res 結果を格納する構造体
	@note
	 除算の同値商集合を返す。
	 つまり、分数の計算 rmax / [fdmin, fdmax] をll型に変換したとき
	 同値となる集合[fdmin, fdmax]を返す。
	 計算量はO(sqrt(rmax))
	**/
	void TableOfEqualDiv
	(ll rmax, vt<TableOfEqualDivResult>& res)
	{
		TableOfEqualDivResult test;
		for (ll i = 1; i * i <= rmax; i++)
		{
			test.c = 1;
			test.q = rmax / i;
			test.fn = rmax;
			test.fdmin = test.fdmax = i;
			res.push_back(test);
		}
		while (test.q != 1)
		{
			test.q = rmax / (res.back().fdmax + 1);
			test.fdmin = res.back().fdmax + 1;
			test.fdmax = rmax / test.q;
			test.c = test.fdmax - test.fdmin + 1;
			res.push_back(test);
		}
	}
};

