class Mint {
    using u64 = std::uint_fast64_t;
    u64 Modulus = MOD;

public:
    u64 a;

    constexpr Mint(const u64 x = 0) noexcept : a(x % Modulus) {}

    constexpr u64 &value() noexcept { return a; }

    constexpr const u64 &value() const noexcept { return a; }

    constexpr Mint operator+(const Mint rhs) const noexcept {
        return Mint(*this) += rhs;
    }

    constexpr Mint operator-(const Mint rhs) const noexcept {
        return Mint(*this) -= rhs;
    }

    constexpr Mint operator*(const Mint rhs) const noexcept {
        return Mint(*this) *= rhs;
    }

    constexpr Mint operator/(const Mint rhs) const noexcept {
        return Mint(*this) /= rhs;
    }

    constexpr Mint &operator+=(const Mint rhs) noexcept {
        a += rhs.a;
        if (a >= Modulus) {
            a -= Modulus;
        }
        return *this;
    }

    constexpr Mint &operator-=(const Mint rhs) noexcept {
        if (a < rhs.a) {
            a += Modulus;
        }
        a -= rhs.a;
        return *this;
    }

    constexpr Mint &operator*=(const Mint rhs) noexcept {
        a = a * rhs.a % Modulus;
        return *this;
    }

    constexpr Mint &operator/=(Mint rhs) noexcept {
        u64 exp = Modulus - 2;
        while (exp) {
            if (exp % 2) {
                *this *= rhs;
            }
            rhs *= rhs;
            exp /= 2;
        }
        return *this;
    }

    constexpr Mint &pow(int rhs) noexcept {
        u64 exp = static_cast<u64>(rhs);
        Mint base(a);
        a = 1;
        while (exp) {
            if (exp % 2) {
                *this *= base;
            }
            base *= base;
            exp /= 2;
        }
        return *this;
    }

};

class Solve {
public:
    void solve() {
        Int N, K;
        cin >> N >> K;

        vector<Int> v;
        for (Int i = 1; i * i <= N; ++i) {
            v.push_back(i);
            if (i != N / i) v.push_back(N / i);
        }
        sort(all(v));

        vector<Mint> dp(v.size());
        dp[0] = 1;
        for (int i = 0; i < K; ++i) {
            vector<Mint> ndp(v.size());
            for (int l = 0, r = v.size() - 1; l < v.size(); ++l) {
                while (v[l] * v[r] > N) r--;
                ndp[r] += dp[l];
            }
            for (int j = ndp.size() - 1; j > 0; --j) {
                ndp[j - 1] += ndp[j];
            }
            for (int j = 0; j < ndp.size(); ++j) {
                ndp[j] *= (j == 0 ? 1 : v[j] - v[j - 1]);
            }
            swap(dp, ndp);
        }

        Mint ans = accumulate(all(dp), Mint(0));
        cout << ans.value() << endl;
    }
};


