            else dp2[i][j] = 0;
        }
        for(int j = m; j >= 1; --j){
            s = (s + dp2[i - 1][j]) % mod;
            dp1[i][j] = s;
        }
    }
    i64 ans = 0;
    for(int i = 1; i <= m; ++i) ans = (ans + dp1[k - 1][i]) % mod;
    for(int i = 1; i <= m; ++i) ans = (ans + dp2[k - 1][i]) % mod;
