long long mul(long long a, long long b, long long mod) {
    long long keta[20] = {};
    long long c = b;
    long long now = 0;
    while (c != 0ll) {
        keta[now] = c % 10; c /= 10; now++;
    }
    long long res = 0;
    for (int i = 19; i >= 0; --i) {
        res *= 10; res %= mod;
        res += keta[i] * a % mod;
    }
    return res % mod;
}

void solve() {
    int n, k; cin >> n >> k;
    int A = sqrt(n);
    vector<int> cand;
    cand.pb(0);
    rep (i, A) cand.pb(i+1);
    for (int i = A; i > 0; i--) cand.pb(n/i);
    static int dp[105][70000] = {};
    rep (i, cand.size()-1) {
        dp[0][i+1] = cand[i+1]-cand[i];
    }
    rep (K, k-1) {
        int now = 0;
        rep (i, cand.size()) now += dp[K][i]; now %= mod;
        FOR (i, 1, cand.size()) {
            // cout << 111 << now << endl;
            dp[K+1][i] = now * (cand[i] - cand[i-1]) % mod;
            now += mod; now -= dp[K][cand.size()-i]; now %= mod;
        }
    }
    int ans = 0;
    rep (i, cand.size()) {
        ans += dp[k-1][i];
        ans %= mod;
    }
    cout << ans << endl;
}

