    fac[1]=inv[1]=ifac[1]=1;

    for (int i=2; i<maxn; i++) {
	fac[i]=fac[i-1]*i%mod;
	inv[i]=(mod-(mod/i)*inv[mod%i]%mod)%mod;
	ifac[i]=ifac[i-1]*inv[i]%mod;
    }

    assert(nck(4,2)==6);
}

ll pw(ll x, ll y) {
    ll res=1;
    while (y) {
	if (y%2) res=res*x%mod;
	x=x*x%mod;y=y/2;
    }
    return ((res%mod)+mod)%mod;
}

void add(ll& x, ll y) {
    if (x>=mod) x%=mod;
    if (y>=mod) y%=mod;
    x += y;
    if (x>=mod) x%=mod;
}

void mul(ll& x, ll y) {
    if (x>=mod) x%=mod;
    if (y>=mod) y%=mod;
    x *= y;
    if (x>=mod) x%=mod;
}



ll brute(ll n, ll k) {
    assert(k>1);
    vector<ll> v;
    ll res=0;
    function<void(int i)> dfs = [&](int rem) {
	if (rem==0) {
	    bool ok = true;
	    for (int i=0; i+1<k && ok; i++) {
		if (v[i+1]>n/v[i]) ok=false;
	    }
	    res += ok;
	} else {
	    for (ll i=1; i<=n; i++) {
		v.push_back(i);
		dfs(rem-1);
		v.pop_back();
	    }
	}
    };
    dfs(k);
    return res;
}


