    for (int i=1; i<=k; i++) {

	// prefix sum
	for (int j=1; j<N; j++) {
	    add(dp[i-1][j], dp[i-1][j-1]);
	}

	for (int j=0; j<N; j++) {
	    if (terms[j] <= Q) {
		ll fac = n / terms[j];
		int idx = std::prev(upper_bound(terms.begin(),terms.end(),fac))-terms.begin();
		add(dp[i][j], dp[i-1][idx]);
