typedef long long ll;
const ll mod = 1e9 + 7;

int main(){
    int n, k;
    cin >> n >> k;

    vector<int> to, val;
    int r = 1;
    while(r <= n){
        int tmp = n/r;
        int reach = n/tmp;
        to.push_back(reach);
        val.push_back(tmp);
        r = reach+1;
    }

    int siz = to.size(); // 恐らくO(logN)程度 -> 違う.logNより大きい
    cout << "size is " << siz << endl;

    vector<ll> cnt(siz, 1);
    for(int i = 1; i < siz; i++)    cnt[i] = to[i]-to[i-1];

    auto f = [&](int x)->int{
        return upper_bound(to.begin(),to.end(),x)-to.begin();
    };

    // O(logN * logN * K) ? -> 違う.

    vector<vector<ll>> dp(k, vector<ll>(siz, 0));
    for(int i = 0; i < siz; i++)    dp[0][i] = cnt[i];

    for(int i = 0; i+1 < k; i++){
        for(int j = 0; j < siz; j++){
            int to = f(val[j])-1;
            while(to >= 0)  dp[i+1][to] = (dp[i+1][to] + dp[i][j]*cnt[to]) % mod, to--;
        }
    }

    ll ans = 0;
    for(int i = 0; i < siz; i++)    ans = (ans + dp[k-1][i]) % mod;
    cout << ans << endl;

    return 0;
}

