const int mo = 1e9 + 7;
const int N = 62010;

int n, k, ans;
int L[N], R[N], val[N], pos[N], cnt, sum[110][N]; //dp[i][j]前i位, a[i]值为L[i] ~ R[i]

int main() {
	scanf("%d%d", &k, &n);
	for(int l = 1, r; l <= k; l = r + 1) {
		r = k / (k / l);
		L[++ cnt] = l; R[cnt] = r; val[cnt] = k / l;
	}
	for(int i = 1; i <= cnt; i ++) {
		sum[0][i] = 1;
		pos[i] = upper_bound(L + 1, L + cnt + 1, val[i]) - L - 1;
	}
	for(int i = 1; i <= n; i ++) {
		for(int j = 1; j <= cnt; j ++) {
			sum[i][j] = (sum[i][j - 1] + sum[i - 1][pos[j]] * 1ll * (R[j] - L[j] + 1) % mo) % mo;
		}
	}
	printf("%d\n", sum[n][cnt]);
	return 0;
}

