//約数の列挙O(√n)
vector<ll> divisor(ll n){
  vector<ll> xs;
    for(int i = 1; i <= sqrt(n); i++){
      xs.push_back(i);
      xs.push_back(n/i);
      if(n/i+1 <= n) xs.push_back(n/i+1);
    }
    sort(xs.begin(), xs.end());
    xs.erase(unique(xs.begin(), xs.end()), xs.end());
    return xs;

}

