int main() {
    lint N, K;
    cin >> N >> K;

    vector<int> A;
    lint R = N;
    for (int i = 1;; ++i) {
        // R以下で、iをかけてもセーフだがi+1を掛けると死ぬ数を列挙
        if (R * (i + 1) <= N) {
            while (R > 0) {
                A.push_back(1);
                --R;
            }
            break;
        }

        // ok * (i + 1) <= N
        lint ok = 0, ng = R;
        while (ng - ok > 1) {
            lint mid = (ok + ng) / 2;
            (mid * (i + 1) <= N ? ok : ng) = mid;
        }
        // (ok, R]は全部死ぬ
        A.push_back(R - ok);
        R = ok;
    }
    reverse(A.begin(), A.end());

    int M = A.size();
    vector<mint> dp(M + 1);
    dp[0] = 0;
    for (int i = 1; i <= M; ++i) {
        dp[i] = dp[i - 1] + A[i - 1];
    }

    for (int j = 1; j < K; ++j) {
        vector<mint> ndp(M + 1);
        ndp[0] = 0;
        for (int i = 1; i <= M; ++i) {
            ndp[i] = ndp[i - 1] + (dp[M - i + 1] - dp[0]) * A[i - 1];
        }
        swap(dp, ndp);
    }

    cout << dp[M] << endl;
    return 0;
}

