struct Data {
	int first;
	int last;
	int dst;
	int num() {
		return last - first + 1;
	}
};


void proc() {
	LOAD(int, N);
	LOAD(int, K);
	vector<Data> vp;
	vp.reserve((int)(sqrt(N) + 1));
	for (int i = 1; i * i <= N; ++i) {
		vp.push_back({ -1,i, N / i });
	}
	for (int j = vp.size() - 1; 0 <= j; --j) {
		if (vp[j].last == vp[j].dst) continue;
		vp.push_back({ -1, vp[j].dst, vp[j].last });
	}
	vp[0].first = 1;
	for (int i = 1; i < vp.size(); ++i) {
		vp[i].first = vp[i - 1].last + 1;
	}
	int sz = vp.size();
	//
	vector<int> dp(sz);
	for (int j = 0; j < sz; ++j) {
		dp[j] = 1;// vp[j].num();
	}
	for (int k = 1; k < K; ++k) {
		vector<int> dpNew(sz);
		int sum = 0;
		int id = 0;
		int count = 0;
		auto exceed = [&](int dst) {
			if (count >= dst)return;
			for (; id < sz; ) {
				assert(vp[id].first <= dst);
				if (dst <= vp[id].last) {
					sum += dp[id]/* / vp[id].num()*/ * (dst - count);
					count = dst;
					modify(sum);
					return;
				}
				if (vp[id].last < dst) {
					sum += dp[id] /*/ vp[id].num()*/ * (vp[id].last - count);
					modify(sum);
					count = vp[id].last;
					++id;
				}
			}
		};
		for (int i = sz - 1; 0 <= i; --i) {
			exceed(vp[i].dst);
			dpNew[i] = sum;
			modify(dpNew[i]);
		}
		dp = dpNew;
	}
	int res = 0;
	for (int i = 0; i < sz; ++i) {
		res += dp[i] * vp[i].num();
		modify(res);
	}
	cout << res << endl;
	//
}


