ll N;
int K;

int main(int argc, char** argv) {
  cin >> N >> K;

  map<ll, int> index; // num to index
  for (ll x=1; x*x<=N; x++) {
    index.insert({x, -1});
    index.insert({N/x, -1});
  }
  int i = 0;
  for (auto& kv : index) {
    kv.second = i++;
  }


  vector<vll> dp(K, vll(index.size()));

  int j = 0;
  for (auto kv : index) {
    dp[0][j++] = kv.first;
  }

  for (int i=1; i<K; i++) {

    int j=0;
    pair<ll,int> prev = *index.begin();
    for (auto kv : index) {
      if (j>0) {
        addmod(dp[i][j], dp[i][j] + dp[i][j-1]);
      }
      ll c = j==0 ? 1 : kv.first - prev.first;

      addmod(dp[i][j], c*(dp[i-1][index[N/kv.first]])%MOD);

      prev = kv;
      j++;
    }
  }

  cout << dp[K-1][index.size()-1] << endl;

  return 0;
}

