/////////////         modの計算

int mod = 1000000007;

ll mod_adjust(ll a) {//	余りをとる(0～mod-1に調整する)
	if (a >= mod) {
		return a % mod;
	}
	if (a < 0) {
		a *= -1;
		a %= mod;
		return mod - a;
	}
	return a;
}
int mod_add(int a, int b) {//	足し算
	ll k = mod_adjust((ll)a); k += mod_adjust((ll)b);
	k = mod_adjust(k);
	return (int)k;
}
int mod_sub(int a, int b) {//	引き算
	return mod_add(a, -b);
}
int mod_multi(int a, int b) {//	掛け算
	ll k = mod_adjust((ll)a);
	k *= mod_adjust((ll)b);
	k = mod_adjust(k);
	return (int)k;
}

int main() {
	int N, K; cin >> N >> K;

	set<int> st;
	for (int i = 1; i <= sqrt(N); i++) {
		st.insert(i);
		st.insert(N / i);
	}

	N = st.size();
	vector<int> X;
	vector<int> Y;

	int prev = 0;
	for (auto itr = st.begin(); itr != st.end(); itr++) {
		X.push_back(*itr);
		Y.push_back(*itr - prev);
		prev = *itr;
	}

	int** dp = new int* [K];
	for (int k = 0; k < K; k++) {
		dp[k] = new int[N];
		for (int i = 0; i < N; i++) {
			dp[k][i] = 0;
		}
	}
	for (int i = 0; i < N; i++) {
		dp[0][i] = X[i];
	}

	for (int k = 1; k < K; k++) {
		int j = N - 1;
		dp[k][0] = mod_multi(dp[k - 1][j], Y[0]);
		for (int i = 1; i < N; i++) {
			dp[k][i] = mod_add(dp[k][i - 1], mod_multi(dp[k - 1][N - 1 - i], Y[i]));
		}
	}

	cout << dp[K - 1][N - 1] << endl;

	return 0;
}

