// O(log n)
mint mod_pow(mint x, uint64_t n) {
	mint res = 1;
	while (n > 0) {
		if (n & 1) res = res * x;
		x = x*x;
		n >>= 1;
	}
	return res;
}


void solve() {
	int N, K; cin >> N >> K;
	int window = sqrt(N);
	vector<int> nums;
	unordered_map<int, int> enc;

	RFOR(i, 1, window + 1) {
		int tar = N / i;
		nums.push_back(i);
		if (i != tar) {
			nums.push_back(tar);
		}
	}
	sort(ALL(nums));

	REP(i,nums.size()){
		enc[nums[i]] = i;
	}

	vector<vector<mint> > dp(K, vector<mint>(nums.size()));
	REP(i, dp[0].size()) {
		dp[0][i] = nums[i];
	}

	FOR(i, 1, dp.size()) {
		REP(j, dp[i].size()) {
			int cnt = (j >= 1 ? nums[j] - nums[j - 1] : 1);
			dp[i][j] = dp[i - 1][enc[N / nums[j]]] * cnt;
		}
		FOR(j, 1, dp[i].size()) {
			dp[i][j] += dp[i][j - 1];
		}
	}

	cout << dp.back().back() << endl;
}

