    REP(i, k-1){
        FOR(j, 1, m+1){
            dp[0][i+1][1] += dp[0][i][j];
            dp[0][i+1][m+1] -= dp[0][i][j];
            dp[1][i+1][j] += dp[0][i][j];
            dp[1][i+1][m+1] -= dp[0][i][j];

            dp[0][i+1][1] += dp[1][i][j];
            dp[0][i+1][j+1] -= dp[1][i][j];
        }

        REP(j, m+1){
            dp[0][i+1][j+1] += dp[0][i+1][j];
            dp[1][i+1][j+1] += dp[1][i+1][j];
        }

        REP(j, m+2){
            dp[1][i+1][j] *= dp[1][0][j];
        }
    }

    mint ans = accumulate(all(dp[0][k-1]), mint(0)) + accumulate(all(dp[1][k-1]), mint(0));
    cout << ans << endl;

    return 0;
}

