using mod_t = lib::modnum<1000000007>;

namespace lib
{
	template<class T>constexpr auto sqrt(T const& v)
		->std::enable_if_t<std::is_integral<T>::value, T>
	{
		if (v < T())
		{
			return std::numeric_limits<T>::max();
		}
		else if (v == T())
		{
			return T();
		}
		auto ret = T();
		while (ret * ret < v)
		{
			if ((ret + 1) * (ret + 1) > v)
			{
				return ret;
			}
			++ret;
		}
		return ret;
	}
}

void Main()
{
	int N, K;
	std::cin >> N >> K;
	if (N == 1)
	{
		std::cout << 1 << std::endl;
		return;
	}
	auto n = lib::sqrt(N);
	std::vector<mod_t> prod(1);
	auto rng = boost::irange(n + 1, N);
	auto end = rng.end();
	for (int i = 1; i <= n; ++i)
	{
		auto p = std::partition_point(rng.begin(), end, [&](int x)
			{
				return N / x != i;
			});
		--p;
		prod.emplace_back(end - p);
		end = p;
	}
	std::vector<mod_t> lower(n + 1);
	std::vector<mod_t> upper(n + 1);
	for (int i : boost::irange(1, n + 1))
	{
		lower[i] = lower[i - 1] + 1;
	}
	upper[n] = prod[n];
	for (int i : boost::irange(0, n) | adaptor::reversed)
	{
		upper[i] = upper[i + 1] + prod[i];
	}
	lower[0] = 0;
	for (int i : boost::irange(1, K))
	{
		std::vector<mod_t> nlower(n + 1);
		std::vector<mod_t> nupper(n + 1);
		nupper[n] = lower[n] * prod[n];

		for (int k : boost::irange(1, n + 1))
		{
			nlower[k] = nlower[k - 1] + lower[n] + upper[k];
		}
		for (int k : boost::irange(1, n) | adaptor::reversed)
		{
			nupper[k] = nupper[k + 1] + lower[k] * prod[k];
		}
		std::swap(nlower, lower);
		std::swap(nupper, upper);
	}
	std::cout << lower[n] + upper[1] << std::endl;
}

