int main()
{
	int64_t N, K;
	scanf("%lld%lld", &N, &K);
	std::vector<int64_t> spanTable;
	for (int64_t i{1}; i * i <= N; i++)
		spanTable.push_back(i);
	{
		std::vector<int64_t> tmp;
		for (int64_t i{1}; i * i < N; i++)
			tmp.push_back(N / i);
		while (!tmp.empty())
		{
			spanTable.push_back(tmp.back());
			tmp.pop_back();
		}
	}
	for (int i{(int)spanTable.size() - 1}; i > 0; i--)
		spanTable[i] -= spanTable[i - 1];
	using vi = std::vector<int64_t>;
	int size{(int)spanTable.size()};
	std::vector<vi> dp(K + 1, vi(size));
	dp[0][0] = 1;
	for (int k_i{1}; k_i <= K; k_i++)
	{
		for (int from_i{}; from_i < size; from_i++)
			dp[k_i][size - 1 - from_i] = dp[k_i - 1][from_i] * spanTable[from_i] % mod;
		for (int to_i{size - 1}; to_i > 0; to_i--)
			dp[k_i][to_i - 1] = (dp[k_i][to_i - 1] + dp[k_i][to_i]) % mod;
	}
	int64_t sum{};
	for (int i{}; i < size; i++)
		sum = (sum + dp.back()[i] * spanTable[i] % mod) % mod;
	printf("%lld\n", sum);

	return 0;
}

