int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0), cout.tie(0);

    int N, K;
    cin >> N >> K;

    vi bnd;
    for (int i = 1; i * i <= N; i++) {
        bnd.pb(i);
        bnd.pb(N/i - 1);
        bnd.pb(N/i);
        bnd.pb(N/i + 1);
    }
    sort(all(bnd));
    bnd.erase(unique(all(bnd)), bnd.end());

    vi uniq{ bnd[0] }, divs{ N };
    FOR (i, 1, sz(bnd)) {
        uniq.pb(bnd[i]);
        divs.pb(N / bnd[i]);
    }

    int U = sz(uniq);
    F0R (i, U - 1) {
        assert(N / uniq[i] == divs[i]);
        assert(N / uniq[i] == N / (uniq[i + 1] - 1));
    }

    vi canp(U - 1), elts(U - 1);
    F0R (j, U - 1) {
        canp[j] = j ? canp[j - 1] : U - 2;
        while (canp[j] > 0 && (bnd[j + 1] - 1) * (bnd[canp[j] + 1] - 1) > N)
            canp[j]--;
        elts[j] = bnd[j + 1] - bnd[j];
    }

    vmn dp(U - 1, 1);

    F0R (i, K) {
        vmn upd(U - 1, 0);
        F0R (j, sz(upd)) {
            upd[j] = elts[j] * dp[canp[j]];
        }
        F0R (j, sz(upd) - 1)
            upd[j+1] += upd[j];
        swap(dp, upd);
    }

    cout << dp.back() << endl;

    return 0;
}

