template<class T>class CulSum {
	int n; vector<T> s;
public:
	static vector<T> bulid(const vector<T>& a) {
		int N = a.size();
		vector<T> ret(N + 1);
		for (int i = 0; i < N; ++i)ret[i + 1] = ret[i] + a[i];
		return ret;
	}
	template<class U, class F>static vector<T> bulid(const U& a, F f) {
		int N = a.size();
		vector<T> ret(N + 1);
		for (int i = 0; i < N; ++i)ret[i + 1] = ret[i] + static_cast<T>(f(a[i]));
		return ret;
	}
	CulSum(const vector<T>& a) :n(a.size()) {
		s = bulid(a);
	}
	template<class U, class F>CulSum(const U& a, F f) : n(a.size()) {
		s = bulid(a, f);
	}
	// [l, r)
	T operator()(int l, int r)const {
		l = min(max(l, 0), n); r = min(max(r, 0), n);
		return l > r ? 0 : s[r] - s[l];
	}
	// [0, r)
	T operator()(int r)const {
		r = min(max(r, 0), n);
		return s[r];
	}
	vector<T> get_s()const { return s; }
};

