        Compute[i] = -1;
    for (int i = 1; i <= 49999; i++)
    {
        ll len = compute(i);
        if (len <= ROOT)
        {
            tagget_for_0 = RR[i];
            tagget_for_1 = i - 1;
            break;
        }
    }

    cout << ROOT << " " << tagget_for_0 << " " << tagget_for_1 << endl;

    for (int i = 1; i <= 49999; i++)
    {
        if (ok(0, i)) dp[0][1][i] = 1;
        if (ok(1, i)) dp[1][1][i] = compute(i);
        sigma[0][1][i] = (sigma[0][1][i - 1] + dp[0][1][i]) % MOD;
        sigma[1][1][i] = (sigma[1][1][i - 1] + dp[1][1][i]) % MOD;
    }

    for (int i = 2; i <= k; i++)
    {
        for (int x = 1; x <= 49999; x++)
        {
            if (ok(0, x)) calc(0, i, x);
