        num.push_back(i);
        if (i != n / i) {
            num.push_back(n / i);
        }
    }
    int m = num.size();
    sort(num.begin(), num.end());
    auto tmp = num;
    for (int i = 1; i < m; i++) {
        num[i] = tmp[i] - tmp[i - 1];
    }
    vector<vector<lint>> dp(k + 1, vector<lint>(m + 1));
    for (int j = 0; j < m; j++) {
        dp[0][j] = 1;
    }
    for (int i = 1; i <= k; i++) {
        for (int j = 0; j < m; j++) {
            dp[i][m - 1 - j] = (dp[i][m - j] + dp[i - 1][j] * num[j] % MOD) % MOD;
        }
    }
    cout << dp[k][0] << endl;
    return 0;
}

