  long long int rootN = 1;
  long long int l = 1, r = N+1, mid;
  while(r-l > 1){
    mid = (r+l)/2;
    if(mid*mid <= N)l = mid;
    else r = mid;
  }
  rootN = l;

  //std::cerr << "rootN = " << rootN << std::endl;

  // prepare n
  std::vector<long long int> n;
  n.push_back(0);
  for(long long int i = 1; i <= rootN; i++){
    n.push_back(N/i - rootN);
    n[i] = (n[i]+MOD)%MOD;
  }

  /*std::cerr << "n:" << std::endl;
  for(long long int i = 0; i <= rootN; i++){
    std::cerr << n[i] << " ";
  }std::cerr << std::endl << std::endl;*/

  // prepare dp table
  std::vector<std::vector<long long int> > dp(rootN+1), dp2(rootN+1);
  for(long long int i = 0; i <= rootN; i++){
    for(long long int j = 0; j <=K; j++){
      dp[i].push_back(0);
      dp2[i].push_back(0);
    }
  }
  for(long long int i = 1; i <= rootN; i++){
    dp[i][0] = 1;
    dp2[i][0] = dp2[i-1][0] + (dp[i][0] - dp[i-1][0])*n[i];
  }
  for(long long int i = 1; i <= rootN; i++){
    dp[i][1] = i;
    dp2[i][1] = dp2[i-1][1] + (dp[i][1] - dp[i-1][1])*n[i];
  }

  for(long long int j = 2; j <= K; j++){
    for(long long int i = 1; i <= rootN; i++){

      dp[i][j] = dp[i-1][j] + dp[rootN][j-1] + (dp2[rootN][j-2] - dp2[i-1][j-2]) + dp[i-1][j-2]*n[i];
      dp[i][j] = hogemod(dp[i][j]);

      dp2[i][j] = dp2[i-1][j] + (dp[i][j]-dp[i-1][j])*n[i];
      dp2[i][j] = hogemod(dp2[i][j]);
    }
  }

  /*std::cerr << "dp:" << std::endl;
  for(long long int i = 0; i <= rootN; i++){
    for(long long int j = 0; j <= K; j++){
      std::cerr << dp[i][j] << " ";
    }std::cerr << std::endl;
  }std::cerr << std::endl;

  std::cerr << "dp2:" << std::endl;
  for(long long int i = 0; i <= rootN; i++){
    for(long long int j = 0; j <= K; j++){
      std::cerr << dp2[i][j] << " ";
    }std::cerr << std::endl;
  }std::cerr << std::endl;*/

  long long int ans = 0;
  ans = dp[rootN][K] + dp2[rootN][K-1];
  ans = hogemod(ans);

  std::cerr << "Answer:" << std::endl;
  std::cout << ans << std::endl;

  return 0;

}

