    if(n/m>m) a.push_back(n/m);
    for(i=m-1; i>=1; i--) {
        a.push_back(n/i);
    }
    int nn=(int)a.size();

    dp[0][0]=1;
    for(j=0; j<nn; j++) sdp[0][j]=1;
    for(i=1; i<=k; i++) {
        for(j=0; j<nn; j++) {
            dp[i][j]=sdp[i-1][nn-1-j];
            sdp[i][j]=((j==0? 0: sdp[i][j-1]) + dp[i][j] * (j==0? a[j]: (a[j]-a[j-1])))%MOD;
        }
    }
    printf("%lld\n", sdp[k][nn-1]);

    return 0;
}

