    rep (i, A) cand.pb(i+1);
    for (int i = A; i > 0; i--) cand.pb(n/i);
    static int dp[105][40000] = {};
    rep (i, cand.size()-1) {
        dp[0][i+1] = cand[i+1]-cand[i];
    }
    rep (K, k-1) {
