void solver::run(){
    if(!input()) return;
    if(N < 50) {
        auto dp = VEC(K, N, 1_mod);
        for (int k = 1; k < K; ++k) {
            for (int t = 0; t < N; ++t) {
                dp[k][t] = 0;
                for (int j = 0; j < N; ++j) {
                    if((t+1) * (j+1) <= N) dp[k][t] += dp[k-1][j];
                } // end j
            } // end t
        } // end k

        RCR ans = accumulate(ALL(dp.back()), 0_mod);
        os << ans <<endl;
    }
    else {
        vector<int> compn;
        int n = 1;
        while(n * n <= N){
            compn.push_back(1);
            n++;
        }
        int m = n-1;
        if(m*m == N){
            m--;
        }
        n--;
        while(m > 0){
            int nextn = N / m;
            compn.push_back(nextn - n);
            n = nextn ;
            m--;
        }
//        cerr << accumulate(ALL(compn), 0) << endl;
//        assert(accumulate(ALL(compn), 0) == N);

        auto dp = VEC(K, compn.size(), 1_mod);
        for (int i = 0; i < compn.size(); ++i) {
            dp[0][i] = compn[i];
        } // end i
        for (int i = 1; i < K; ++i) {
            auto S = VEC(compn.size(), 0_mod);
            S[0] = dp[i-1][0];
            for (int k = 1; k < S.size(); ++k) {
                S[k] = dp[i-1][k] + S[k-1];
            } // end k
            int f = S.size()-1;
            for (int j = 0; j < compn.size(); ++j) {
                dp[i][j] = S[f--] * compn[j];
            } // end j
        } // end i
        os << accumulate(ALL(dp.back()), 0_mod) << endl;

    }

}

