		for(ll j=1;j<=r;j++)dp[j][i]=(dp[r][i-1]+dq[j][i-1])%M;
	}
	for(ll i=1;i<=r;i++)ans=(ans+dp[i][m-1])%M;
	for(ll i=1;i<=l;i++)ans=(ans+dq[i][m-1])%M;
	cout<<ans<<endl;
}

