      REPR(j,m) {
        dp[i+1][j] = ((j+1<m ? dp[i+1][j+1] * invc[j+1] : 0) + dp[i][k]) * c[j];
        k++;
      }
    }
    mint ans = 0;
    REP(i,m) ans += dp[K][i];
    cout << ans << endl;
  }
}

