LL solve(int now, LL bef){
	if(now >= K) return 1;
	LL ret = 0;
	for(LL i=1; i<=sqrt(N); i++){
		if(bef*i > N) break;
		ret += solve(now+1, i);
		ret %= MOD;
		//cout << "solve " << now << " " << bef << " " << i << " " << ret << endl;
	}
	//cout << ret << endl;
	if(bef*(sqrt(N)) <= N){
