ll compute(ll x)
{
    if (Compute[x] != -1)
        return Compute[x];
    long long L = 0, R = 0;
    ll l = 0, r = 1e9;
    while (l + 1 < r)
    {
        ll mid = (l + r) / 2;
        if (n / mid > x)
            l = mid;
        else
            r = mid;
    }
    L = r;

    l = 0, r = 1e9;
    while (l + 1 < r)
    {
