            l = mid;
        else
            r = mid;
    }

    R = l;
    //cout << x << " : " << L << " " << R << endl;
    LL[x] = L;
    RR[x] = R;
    return Compute[x] = R - L + 1;
}

ll ok(int vetka, int x)
{
