//階乗先に計算
long long int kaizyou[200005] = { 1 };
long long int kai(long long int a, long long int b, long long int mod) {
	long long int tmp = 1;
	for (long long int i = a; i <= b; i++) {
		tmp *= i;
		tmp %= mod;

		kaizyou[i] = tmp;
	}
	return tmp;
}


//累乗(繰り返し2乗法)　aのb乗(mod)を求める。
long long int rui(long long int a, long long int b, long long mod) {
	int memo[65] = {};
	long long int A[65] = {};
	long long int tmp = 1;
	for (int i = 0; i < 65; i++) {
		memo[i] = b % 2;
		b /= 2;
	}

	A[0] = a;
	A[0] %= mod;

	for (int i = 1; i < 65; i++) {
		A[i] = A[i - 1] * A[i - 1];
		A[i] %= mod;
	}
	for (int i = 0; i < 65; i++) {
		if (memo[i] == 1) {
			tmp *= A[i];
			tmp %= mod;
		}
	}
	tmp %= mod;
	return tmp;
}

//コンビネーション計算
long long int comb(long long int n, long long int r, long long int mod) {
	long long int tmp;

	tmp = (kaizyou[n] * rui(kaizyou[r], mod - 2, mod)) % mod;
	tmp *= rui(kaizyou[n - r], mod - 2, mod);
	tmp %= mod;
	if (tmp < 0) { tmp = (mod - tmp) % mod; }
	return tmp;
}

//約数列挙 累乗の関数とともに用いる。
long long int soinnsuu[2100000] = {}, yakusuu[2100000] = {1}, kosuu = 1;
int yakusuu_rekkyo(long long int n) {
	long long int N = n;
	for (int i = 2; i * i <= N; i++) {
		int tmp = 1;
		while (n % i == 0) {
			soinnsuu[i]++;
			n /= i;
			tmp++;
		}
		int tmp2 = tmp;

		while (tmp != 1) {
			for (int j = 0; j < kosuu; j++) {
				yakusuu[j + (tmp - 1) * kosuu] = rui(i, tmp - 1, mod) * yakusuu[j];
			}
			tmp--;
		}
		kosuu *= tmp2;

	}
	if (n != 1) {
		for (int j = 0; j < kosuu; j++) {
			yakusuu[j + kosuu] = rui(n, 1, mod) * yakusuu[j];
		}
		kosuu *= 2;
	}
}


