        l = r+1;
    }
    map<int,int> idx;
    int M = 0;
    for(auto e:mp) idx[e.first.second] = M++;
    vector<ll> cnt(M);
    vector<vector<ll>> dp(K,vector<ll>(M));
    for(auto e:mp) dp[0][idx[e.first.second]] = e.first.second;
    for(auto e:mp) cnt[idx[e.first.second]] = e.first.second-e.first.first+1;
    for(int i = 1; i < K; ++i) {
        for(auto& e:mp) {
            int& j = idx[e.first.second];
            int& k = idx[e.second];
            dp[i][j] = (cnt[j]*dp[i-1][k]) % MOD;
        }
        for(int j = 1; j < M; ++j) (dp[i][j] += dp[i][j-1]) %= MOD;
    }
    cout << dp[K-1].back() << endl;

	return 0;
}

