class BIT {
  vector<mint> dat;
public:
  BIT (int n) {
    dat.resize(n+1, 0);
  }
  void add(int i, mint n) {
    while (i < dat.size()) {
      dat[i] += n;
      i += i & -i;
    }
  }
  mint sum(int i) {
    mint res = 0;
    while (i > 0) {
      res += dat[i];
      i -= i & -i;
    }
    return res;
  }
  void clear() {
    for (int i = 1; i < dat.size(); i++)
      dat[i] = 0;
  }
};

