    for (int i = 1; i * i <= n; i++) {
        div.push_back(i);
        if (i != n / i) div.push_back(n / i);
    }
    sort(div.begin(), div.end());
    int m = div.size();
    vector<vector<mint>> dp(k, vector<mint>(m));
    dp[0][0] = 1;
    for (int i = 1; i < m; i++) {
        dp[0][i] = div[i] - div[i - 1];
    }

    for (int i = 1; i < k; i++) {
        vector<mint> sum(m);
        for (int j = 0; j < m; j++) sum[j] = dp[i - 1][j];
        for (int j = 1; j < m; j++) sum[j] += sum[j - 1];
        for (int j = 0; j < m; j++) {
            dp[i][j] = sum[m - 1 - j] * (j ? div[j] - div[j - 1] : 1);
        }
    }
    mint ans = 0;
    for (int i = 0; i < m; i++) {
        ans += dp.back()[i];
    }
    cout << ans << endl;
}

