template<typename Ring>
struct Fact {
    vector<Ring> fact;
    Fact(int n) {
        fact.resize(n+1);
        fact[0] = Ring{1};
        for (int i = 1; i <= n; ++i) {
            fact[i] = fact[i-1] * i;
        }
    }
    Ring operator[](int i) {
        return fact[i];
    }
};

template<typename Field>
struct Comb {
    Fact<Field> fact;
    Comb(int n) : fact(n) {}
    Field operator()(int n, int r) {
        if (n < 0 || n-r < 0 || r < 0) {
            return 0;
        }
        return fact[n] / (fact[n-r] * fact[r]);
    }
};

