void solve(){
  cin >> N >> K;
  vector<pair<ll, ll>> range;
  for(ll i = 1; i <= N; ){
    range.pb({N/(i+1)+1, N/i});
    if(N/(i+1)+1 == 1) break;
    i = N / (N/(i+1));
  }
  sort(range.begin(), range.end());
  ll M = range.size();
  rep(i, M){
    dp[0][i] = (range[i].s - range[i].f + 1) % MOD;
  }
  rep(i, K-1){
    rep(j, M){
      ll ok = 0, ng = M;
      while(ng - ok > 1){
        ll mid = (ok + ng) / 2;
        if(range[j].f * range[mid].f <= N) ok = mid;
        else ng = mid;
      }
      dp[i+1][0] += dp[i][j];
      dp[i+1][0] %= MOD;
      dp[i+1][ok+1] += MOD - dp[i][j];
      dp[i+1][ok+1] %= MOD;
    }
    rep(j, M){
      dp[i+1][j+1] += dp[i+1][j];
      dp[i+1][j+1] %= MOD;
    }
    rep(j, M){
      dp[i+1][j] *= (range[j].s + MOD - range[j].f + 1) % MOD;
      dp[i+1][j] %= MOD;
    }
  }
  ll ans = 0;
  rep(i, M){
    ans += dp[K-1][i];
    ans %= MOD;
  }
  cout << ans << endl;
}



