long long p = 1000000007;
long long n, k;
long long d;
long long s[50000], sn[50000];
long long l[50000], ln[50000];
long long cc[50000];
long long t;
int main() {
	scanf("%lld%lld", &n, &k);
	while (d * d <= n)d++;
	d--;
	for (long long i = 1; i <= d; i++) {
		s[i] = 1;
		t = n / (i + 1);
		if (t < d)t = d;
		l[i] = ((n / i) - t) % p;
		cc[i] = ((n / i) - t) % p;
	}
	for (int i = 1; i < k; i++) {
		for (int j = 0; j < 50000; j++) {
			sn[j] = 0;
			ln[j] = 0;
		}
		t = 0;
		for (int j = 1; j <= d; j++) {
			t += s[j];
			t %= p;
		}
		sn[d] = l[d] + t;
		sn[d] %= p;
		for (int j = 0; j < d - 1; j++) {
			sn[d - 1 - j] = sn[d - j] + l[d - i - j];
			sn[d - 1 - j] %= p;
		}
		ln[1] = s[1];
		for (int j = 0; j < d - 1; j++) {
			ln[j + 2] = ln[j + 1] + s[j + 2];
			ln[j + 2] %= p;
		}
		for (int j = 1; j <= d; j++) {
			l[j] = ln[j] * cc[j] % p;
			s[j] = sn[j];
		}
	}
	for (int i = 1; i <= d; i++) {
		t += s[i]; t %= p;
		t += l[i]; t %= p;
	}
	printf("%lld\n", t);
}

