int num[200001];
int main() {
	int N, K;
	cin >> N >> K;
	int M = 0;
	int i = 1;
	while (i <= N) {
		int j = N / i;
		if (i <= j) {
			num[M++] = 1;
			i++;
		}
		else {
			num[M++] = N / j - i + 1;
			i = N / j + 1;
		}
	}
	dp[0][0] = 1;
	for (int k = 0; k < K; k++) {
		memset(sdp, 0, sizeof(sdp));
		sdp[0] = dp[k][0];
		for (int j = 1; j < M; j++) {
			sdp[j] = (sdp[j - 1] + dp[k][j]) % MOD;
		}
		for (int j = 0; j < M; j++) {
			dp[k + 1][j] = sdp[M - j - 1] * num[j] % MOD;
		}
	}
	ll ans = 0;
	for (int i = 0; i < M; i++) (ans += dp[K][i]) %= MOD;
	cout << ans << endl;
}

