ostream& operator<<(ostream& os, const mint& a) { return os << a.x; }
using Vm = vector<mint>;


int main() {
  ll n, k; cin >> n >> k;

  Vm c;
  int l = 1;
  while (l <= n) {
    int r = n/(n/l) + 1;
    c.push_back(r-l);    
    l = r;
  }
  int m = sz(c);
  Vm dp = c;
  rep(i, m-1) dp[i+1] += dp[i];

  rep(i, k-1) {
    Vm _dp(m);
    rep(j, m) _dp[j] = dp[m-1-j] * c[j];
    swap(dp, _dp);
    rep(i, m-1) dp[i+1] += dp[i];
  }

  cout << dp[m-1] << '\n';
  return 0;
}

