void z_algorithm(string str){//計算量はO(str.size())
  Z.resize(str.size());
  Z.at(0)=str.size();
  int m=1,n=0;
  while(m<(int)str.size()){
    while(m+n<(int)str.size()&&str.at(n)==str.at(m+n)){n++;}
    Z.at(m)=n;
    if(n==0){
      m++;
      continue;
    }
    int k=1;
    while(k+Z.at(k)<n){
      Z.at(m+k)=Z.at(k);
      k++;
    }
    m+=k;
    n-=k;
  }
}
template <typename T>
struct BIT{
    //区間加算O(log(N))
    //区間シグマ計算O(log(N))
    //単点加算O(log(N))
    //単点計算O(log(N))
    int n;//元の数列のサイズ
    vector<T> bit[2];//データ収納用
    vector<T> for_bubblesort;
    void init(int n_){
        n=n_+1;
        for(int j=0;j<2;j++){
            bit[j].assign(n,0);
        }
    }
    void add_sub(int p,int i,T x){
        for(int j=i;j<n;j+=j&-j){
            bit[p][j]+=x;
        }
    }
    void add(int l,int r,T x){//[l,r]に加算
        add_sub(0,l,-x*(l-1));
        add_sub(0,r+1,x*r);
        add_sub(1,l,x);
        add_sub(1,r+1,-x);
    }
    T sum_sub(int p,int i){
        T s(0);
        for (int j=i;j>0;j-=j&-j){
            s+=bit[p][j];
        }
        return s;
    }
    T sum(int i,int j){//[i,j]のΣを計算
        return sum_sub(0,j)+sum_sub(1,j)*j-sum_sub(0,i-1)-sum_sub(1,i-1)*(i-1);
    }
    //ここから二分探索関連
    T binary_search_sum1(int key){//a_1+a_2+...+a_x>=keyとなるような最小のxを求める(ただしa_i>=0)
    //key以上の値
            if(key<=0){
                return 0;
            }
            else{
                int x=0,r=1;
                while(r<n){
                    r=r<<1;
                }
                for(int length=r;length>0;length=length>>1){//長さlenは1段下るごとに半分に
                    if(x+length<n&&sum(x+1,x+length)<key){//採用するとき
                        key-=sum(x+1,x+length);
                        x+=length;
                    }
                }
                return x+1;
            }
    }
    T binary_search_sum2(int key){//a_1+a_2+...+a_x<=keyとなるような最大のxを求める(ただしa_i>=0)
    //key以下の値
            key++;
            if(key<=0){
                return 0;
            }
            else{
                int x=0,r=1;
                while(r<n){
                    r=r<<1;
                }
                for(int length=r;length>0;length=length>>1){//長さlenは1段下るごとに半分に
                    if(x+length<n&&sum(x+1,x+length)<key){//採用するとき
                        key-=sum(x+1,x+length);
                        x+=length;
                    }
                }
                return x;
            }
    }
    //二分探索終わり
    //ここからはbubblesort関連
    void init_bubblesort(int n_){
        n=n_+1;
        for_bubblesort.assign(n,0);
    }
    void add_bubblesort(int i,T x) {
        for(int j=i;j<n;j+=j&-j){
            for_bubblesort[j]+=x;
        }
    }
    T calculate_bubblesort(int i) {
        T s=0;
        for(int j=i;j>0;j-=j&-j){
            s+=for_bubblesort[j];
        }
        for(int j=i-1;j>0;j-=j&-j){
            s-=for_bubblesort[j];
        }
        return s;
    }
    T bubblesort(){
        //bitとfor_bubblesort両方initしてadd_for_bubblesortしてから使う
        int answer_for_bubblesort=0;
        int sum_for_bubblesort;
        for(int i=1;i<=n-1;i++){
            sum_for_bubblesort=calculate_bubblesort(i);
            answer_for_bubblesort+=i-sum(1,sum_for_bubblesort)-1;
            add(sum_for_bubblesort,sum_for_bubblesort,1);
        }
        return answer_for_bubblesort;
    }
    //bubblesort関連終わり
    /*
    使い方
    BIT<int> rock;
    rock.init(N);    Nは加算などの操作を行う配列のサイズ
    ...(その後は適当に)
    */
};
template<typename T>
struct BIT2D{
    //単点に値たすO(1)
    //[1,h][1,w]の総和O(log(h)*log(w))
    //[h,hh][w,ww]の値の総和O(4*log(max(h,w,hh,ww)))
    int H,W;
    vector<vector<T>> bit;
    void init(int H_,int W_){
        H=H_+1;
        W=W_+1;
        bit.assign(H,vector<T>(W,0));
    }
    void add(int h,int w,T x){//(h,w)にxを足す0(log(h)*log(w))  (区間サイズnの場合O(N))
        for(int i=h;i<H;i+=i&-i){
            for(int j=w;j<W;j+=j&-j){
                bit[i][j]+=x;
            }
        }
    }
    T sum(int h,int w){//[1,h][1,w]の総和O(log(h)*log(w))
        T s=0;
        for(int i=h;i>0;i-=i&-i){
            for(int j=w;j>0;j-=j&-j){
                s+=bit[i][j];
            }
        }
        return s;
    }
    T partsum(int h,int w,int hh,int ww){//[h,hh][w,ww]の総和O(log(max(h,w,hh,ww)))
        //前処理でsumを計算しておけば計算量減らせるかも
        return sum(hh,ww)+sum(h-1,w-1)-sum(hh,w-1)-sum(h-1,ww);
    }
};
template<typename T>
struct Fiduccia{
    //Qの定数項の方が大きい場合はできないので注意！！！！！　
    /*
    [x^N]P(x)/Q(x)を求める
    */
    int PP,QQ;
    vector<T> P;
    vector<T> Q;
    vector<T> Pcopy;
    vector<T> Qcopy;
    vector<T> R;
    vector<T> RR;
    void init(int PP_,int QQ_){//最高次
        PP=PP_+1;
        QQ=QQ_+1;
        P.assign(PP+QQ,0);
        Q.assign(PP+QQ,0);
        R.assign(PP+QQ,0);
        RR.assign(PP+QQ,0);
    }
    void consist(char S,int a,int b){
        /*
        ax^bの計算
        0乗も忘れずに
        */
        if(S=='P'){
            P.at(b)=a;
        }
        else{
            Q.at(b)=a;
        }
    }
    void calculate_init(long long N){
        /*
        n乗の係数を求める。
        */
        while(N>0){
            /*
            P(x)とQ(-x)の積をまず計算(R(x))で表す
            偶数乗項の係数のみを順番に集めていく
            */
            for(int i=0;i<PP;i++){
                for(int j=0;j<QQ;j++){
                    int a;
                    if(j%2==0){
                        a=P.at(i)*Q.at(j);
                    }
                    else{
                        a=-1*P.at(i)*Q.at(j);
                    }
                    if((i+j)%2==0){
                        R.at((i+j)/2)+=a;
                    }
                }
            }
            for(int i=0;i<PP;i++){
                for(int j=0;j<QQ;j++){
                    int a;
                    if(j%2==0){
                        a=P.at(i)*Q.at(j);
                    }
                    else{
                        a=-1*P.at(i)*Q.at(j);
                    }
                    if((i+j)%2==1){
                        RR.at((i+j)/2)+=a;
                    }
                }
            }
            /*
            R(x)とRR(x)で表すのは終わり
            */
            if(N%2==0){
                N/=2;
                for(int i=0;2*i<PP+QQ;i++){
                    P.at(i)=R.at(i);
                }
                Qcopy=Q;
                for(int i=0;i<QQ;i++){
                    Q.at(i)=0;
                }
                for(int i=0;i<QQ;i++){
                    for(int j=0;j<QQ;j++){
                        if((i+j)%2==0 && j%2==0){
                            //cout<<i<<" "<<j<<endl;
                            Q.at((i+j)/2)+=Qcopy.at(i)*Qcopy.at(j);
                        }
                        if((i+j)%2==0 && j%2==1){
                            //cout<<i<<" "<<j<<endl;
                            Q.at((i+j)/2)+=-1*Qcopy.at(i)*Qcopy.at(j);
                        }
                    }
                }
            }
            else{
                N--;
                N/=2;
                for(int i=0;2*i<PP+QQ;i++){
                    P.at(i)=RR.at(i);
                }
                Qcopy=Q;
                for(int i=0;i<QQ;i++){
                    Q.at(i)=0;
                }
                for(int i=0;i<QQ;i++){
                    for(int j=0;j<QQ;j++){
                        if((i+j)%2==0 && j%2==0){
                            //cout<<i<<" "<<j<<endl;
                            Q.at((i+j)/2)+=Qcopy.at(i)*Qcopy.at(j);
                        }
                        if((i+j)%2==0 && j%2==1){
                            //cout<<i<<" "<<j<<endl;
                            Q.at((i+j)/2)+=-1*Qcopy.at(i)*Qcopy.at(j);
                        }
                    }
                }
            }
            for(int i=0;i<(int)R.size();i++){
                R.at(i)=0;
                RR.at(i)=0;
            }
        }
    }
    T calculate(){//N=0の時を考える//Qの定数項の方が大きい場合はできないので注意
        int a=P.at(0);
        int b=Q.at(0);
        return a/b;
    }
};
