    const int N = read<int>(), K = read<int>();
    const int M = (int)std::sqrt(N), RM = (N / M == M ? M - 1 : M);
    std::vector<int> min, max;
    for (int i = 1; i <= M; i++) { min.push_back(i), max.push_back(i); }
    for (int i = RM; i >= 1; i--) { min.push_back((N + i + 1) / (i + 1)), max.push_back(N / i); }
    std::vector<mint> dp(M + RM, 0);
    dp[0] = 1;
    for (int i = 0; i < K; i++) {
        std::reverse(dp.begin(), dp.end());
        for (int j = M + RM - 2; j >= 0; j--) { dp[j] += dp[j + 1]; }
        for (int j = 0; j < M + RM; j++) { dp[j] *= (max[j] - min[j] + 1); }
    }
    std::cout << std::accumulate(dp.begin(), dp.end(), mint(0)) << std::endl;
    return 0;
}

