  }

  deque<int> sep = {n};
  FOR (i, 2, n+2) {
    int n_i = n / i;
    if (sep.front() > n_i) {
      sep.push_front(n_i);
    } else if (sep.front() == n_i) {
      for (int j = n_i - 1; j >= 0; --j) {
        sep.push_front(j);
      }
      break;
    } else {
      assert (false);
    }
  }

  int sz = sep.size();
  rep (i, sz-1) {
    int width = sep[i+1] - sep[i];
