template <uint MD> struct ModInt {
    using M = ModInt;
    const static M G;
    uint v;
    ModInt(ll _v = 0) { set_v(uint(_v % MD + MD)); }
    M& set_v(uint _v) {
        v = (_v < MD) ? _v : _v - MD;
        return *this;
    }
    explicit operator bool() const { return v != 0; }
    M operator-() const { return M() - *this; }
    M operator+(const M& r) const { return M().set_v(v + r.v); }
    M operator-(const M& r) const { return M().set_v(v + MD - r.v); }
    M operator*(const M& r) const { return M().set_v(uint(ull(v) * r.v % MD)); }
    M operator/(const M& r) const { return *this * r.inv(); }
    M& operator+=(const M& r) { return *this = *this + r; }
    M& operator-=(const M& r) { return *this = *this - r; }
    M& operator*=(const M& r) { return *this = *this * r; }
    M& operator/=(const M& r) { return *this = *this / r; }
    bool operator==(const M& r) const { return v == r.v; }
    M pow(ll n) const {
        M x = *this, r = 1;
        while (n) {
            if (n & 1) r *= x;
            x *= x;
            n >>= 1;
        }
        return r;
    }
    M inv() const { return pow(MD - 2); }
    friend ostream& operator<<(ostream& os, const M& r) { return os << r.v; }
};
using Mint = ModInt<1000000007>;

Mint dp[105][32010];
Mint dpsum[105][32010];

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    ll N, K;
    cin >> N >> K;
    ll P = min(N, 32000LL);
    REP(i, 1, P + 1) {
        dp[0][i] = 1;
        dpsum[0][i] += dp[0][i] + dpsum[0][i - 1];
        dp[1][i] = N / i;
        dpsum[1][i] += dp[1][i] + dpsum[1][i - 1];
    }
    REP(i, 2, K) {
        Mint sum = 0;
        PER(j, P, 0) {
            dp[i][j] += dpsum[i - 1][min(P, N / j)];
            if (P < N / j) {
                dp[i][j] += sum;
                dp[i][j] += (Mint)(N / j - P) * dpsum[i - 2][j];
                sum += (Mint)(N / j - P) * dp[i - 2][j];
            }
        }
        REP(j, 1, P + 1) {
            dpsum[i][j] += dp[i][j] + dpsum[i][j - 1];
        }
    }
    Mint ans = dpsum[K - 1][P];
    REP(i, 1, P + 1) {
        if (P < N / i) {
            ans += dp[K - 2][i] * (Mint)(N / i - P);
        }
    }
    cout << ans << endl;
}

