void init()
{
    for(ll i=1;;)
    {
        ll sh=n/i;
        s.insert(sh);
        if(sh==1)
        {
            break;
        }
        ll nex=n/sh+1;
        i=nex;
    }
    ll pre=0;
    for(auto it=s.begin();it!=s.end();it++)
    {

        //3代表3和2 因为他们都是由1更新来
        represent[++cnt]=*it-pre;
        x[cnt]=*it;
        pre=*it;
     //   printf("%lld %lld\n",*it,represent[cnt]);
    }
}
void solve()
{
    init();
    for(ll i=1;i<=cnt;i++)
    {
        dp[1][i]=represent[i];
    }

    for(ll i=2;i<=k;i++)
    {
        for(ll j=1;j<=cnt;j++)
        {
            sum[j]=add(sum[j-1],dp[i-1][j]);
        }
        for(ll j=1;j<=cnt;j++)
        {
            dp[i][j]=mul(sum[cnt-j+1],represent[j]);
        }
    }
    ll ans=0;
    for(ll i=1;i<=cnt;i++)
    {
        ans=add(ans,dp[k][i]);
    }
    printf("%lld\n",ans);


