        for(int j = FS-1; j >= 1; j--){
            dp[i][j] = (dp[i][j+1]+dp[i-1][FS-j+1]) % MOD;
        }
        repr(j, 1, FS+1){
            dp[i][j] *= F[j-1];
            dp[i][j] %= MOD;
        }
    }
    ll ans = 0;
    repr(i, 1, FS+1){
        ans += dp[k][i];
        ans %= MOD;
    }
    cout << ans << endl;
    return 0;
}

