template<typename T>
struct BIT {
    // 0 indexed
    int n;
    vector<T> bit;

    BIT(vector<T> v) {
        n = sz(v);
        bit.resize(n);
        rep(i, n) add(i, v[i]);
    }
    void add(int a, T w) {
        for (int x = a; x < n; x |= x + 1) bit[x] += w;
    }
    // [0, a)
    T sum(int a) {
        T ret = 0;
        for (int x = a - 1; x >= 0; x = (x & (x + 1)) - 1) {
            ret += bit[x];
        }
        return ret;
    }
    // [a, b)
    T sum(int a, int b) {
        return sum(b) - sum(a);
    }
};

