        dp = vector<ll>(sz(v), 0);
        rep(j, sz(v)) {
            (dp[j] = bit.sum(0, sz(v) - j) % mod * v[j]) %= mod;
        }
    }
    cout << accumulate(all(dp), 0LL) % mod << endl; // debuged, 0LL

}

