// 0-indexed
struct BIT {
	static constexpr ll MAX_N = 5e4;

	BIT(int n_) :n(n_) {}

	void add(ll a, ll b, ll x) {
		add(a, b, x, 0, 0, MAX_N);
	}

	void add(ll a, ll b, ll x, ll k, ll l, ll r) {
		if (a <= l && r <= b)(data[k] += x) %= MOD;
		else if (l < b && a < r) {
			(datb[k] += (min(b, r) - max(a, l))*x) %= MOD;
			add(a, b, x, k * 2 + 1, l, (l + r) / 2);
			add(a, b, x, k * 2 + 2, (l + r) / 2, r);
		}
	}

	ll at(ll a) {
		return ((sum(0, a + 1) - sum(0, a) % MOD) + MOD) % MOD;
	}

	ll sum(ll a, ll b) {
		return sum(a, b, 0, 0, MAX_N);
	}

	ll sum(ll a, ll b, ll k, ll l, ll r) {
		if (b <= l || r <= a)return 0;
		else if (a <= l && r <= b)return (data[k] * (r - l) + datb[k]) % MOD;
		else {
			ll res = (min(b, r) - max(a, l))*data[k];
			res += sum(a, b, k * 2 + 1, l, (l + r) / 2);
			res += sum(a, b, k * 2 + 2, (l + r) / 2, r);
			return res % MOD;
		}
	}

	ll n;
	array<ll, MAX_N * 2> data, datb;
};


int main()
{
	ll N, K;
	cin >> N >> K;

	ll len = sqrt(N);
	ll rlen = (len*len == N ? len - 1 : len);
	vector<ll> normal(len + 1, 1);
	normal[0] = 0;
	vector<ll> dup(rlen + 1);
	FOR(i, 1, rlen) dup[i] = N / i - N / (i + 1);
	dup[rlen] = N / rlen - len;
	vector<ll> inv = dup;

	BIT nbit(len + 1), rbit(rlen + 1);
	REP(i, K - 1) {
		// init
		REP(i, 1e5) {
			nbit.data[i] = 0;
			nbit.datb[i] = 0;
			rbit.data[i] = 0;
			rbit.datb[i] = 0;
		}
		// add
		FOR(i, 1, len + 1) {
			nbit.add(1, len + 1, normal[i]);
			rbit.add(i, rlen + 1, normal[i]);
		}
		FOR(i, 1, rlen + 1) {
			nbit.add(1, i + 1, inv[i]);
		}
		FOR(i, 1, len + 1)normal[i] = nbit.at(i);
		FOR(i, 1, rlen + 1)inv[i] = rbit.at(i)*dup[i];
	}

	ll res = accumulate(normal.begin(), normal.end(), 0ll) + accumulate(inv.begin(), inv.end(), 0ll);
	res %= MOD;
	cout << res << endl;
	return 0;
}

