	  int pa, pb, pc;
	  tie(pa,pb,pc) = S[j-1];
	  bit[i+1].add(0,to[c]+1,bit[i].sum(j,j+1)*(b-pb));
	}
      }
    }
  }

  int ans = 0;

  for(int i=0;i<S.size();i++){
    ans = ans + bit[K].sum(i,i+1) % mod;
  }

  cout<<ans<<endl;

  return 0;
}

