    // 各レイヤーの数値の個数
    int iter = 0;
    for (int i = 1; i <= N;) {
        int j = N / i;
        if (i <= j){
            num[iter++] = 1;
            ++i; // 前半
        }
        else{
            num[iter++] = N/j - i + 1;
            i = N/j + 1; // 後半
        }
    }

    // DP
    memset(dp, 0, sizeof(dp));
    dp[0][0] = 1;
    for (int k = 0; k < K; ++k) {
        memset(sdp, 0, sizeof(sdp));
        for (int j = 0; j <= iter; ++j){
            sdp[j+1] = sdp[j] + dp[k][j];
        }

        for (int j = 0; j < iter; ++j){
            dp[k+1][j] = sdp[iter - j] * mint(num[j]);
        }
    }

    // 集計
    mint res = 0;
    for (int j = 0; j <= iter; ++j){
        res += dp[K][j];
    }
    cout << res << endl;
    return 0;
}

