const int MOD = 1000000007;
const int INF = 0x3f3f3f3f3f3f3f3f;
const double EPS = 1e-10;

vector<pair<pair<int,int>,int>> quotient_range(int N) {
  int M;
  vector<pair<pair<int,int>,int>> ret;
  for (M = 1; M * M <= N; M++) {
    ret.emplace_back(make_pair(M, M), N / M);
  }
  for (int i = M; i >= 1; i--) {
    int L = N / (i + 1) + 1;
    int R = N / i;
    if (L <= R && ret.back().first.second < L) {
      ret.emplace_back(make_pair(L, R), N / L);
    }
  }
  return ret;
}

signed main() {
  cin.tie(nullptr);
  ios::sync_with_stdio(false);
  cout << fixed << setprecision(10);

  int N,K;
  cin >> N >> K;
  auto v = quotient_range(N);
  auto dp = make_v<int>(K,v.size());
  fill_v(dp,0);
  vector<int> sz(v.size());
  REP(j,v.size()) dp[0][j] = sz[j] = (v[j].first.second-v[j].first.first+1) % MOD;
  FOR(i,1,K) {
    vector<int> cum;
    int sum = 0;
    for (int j = 0; j < v.size(); j++) {
      (sum += dp[i-1][j]);
      cum.push_back(sum);
    }
    REV(cum);
    for (int j = v.size()-1; j >= 0; j--) {
      dp[i][j] = (cum[j] * sz[j]) % MOD;
    }
  }
  int ans = 0;
  REP(j,v.size()) (ans += dp[K-1][j]) %= MOD;
  cout << ans << endl;

  return 0;
}

