#define MOD 1000000007

LL N, K;
LL dp[102][32000];
LL sum[102][32000],keisu[102][32000];
int main(){
	cin >> N >> K;
	for(int i=K+1; i>=0; i--){
		sum[i][0] = 0;
		keisu[i][0] = 0;
		for(int j=1; j<=sqrt(N); j++){
			if(i >= K){
				dp[i][j] = 1;
			}
			else{
				dp[i][j] = 0;
				dp[i][j] += sum[i+1][min((LL)sqrt(N),N/j)];
				if(j*(LL)sqrt(N) <= N){
					if(i == K-1){
						dp[i][j] += dp[i+2][1] * max(0LL, N/j-(LL)sqrt(N));
					}
					else{
						dp[i][j] += sum[i+2][j]*max(0LL, N/j-(LL)sqrt(N));
						dp[i][j] += keisu[i+2][(LL)sqrt(N)]-keisu[i+2][j];
					}
				}
				dp[i][j] += 2*MOD;
				dp[i][j] %= MOD;
			}

			sum[i][j] = (dp[i][j] + sum[i][j-1]) % MOD;
			keisu[i][j] = (dp[i][j]*max(0LL,(N/j-(LL)sqrt(N))) + keisu[i][j-1]) % MOD;
		}
	}
	cout << dp[0][1] << endl;
}

#include<bits/stdc++.h>

using namespace std;
const int N = 1e6+100;
const long long INF = 999999999999;
long long dis[N][3];
vector<int> G[N];
bool vis[N][3];
struct node{
    int id;
    int  dis;
};
int n,m,S,T;
queue<node> q;
void dijkstra(int S){
    for(int i=1;i<=n+100;i++){
        for(int j=0;j<3;j++) dis[i][j]=INF,vis[i][j]=0;
    }
    dis[S][0]=0;
    q.push({S,0});
    while(!q.empty()){
        node rt=q.front();q.pop();
        int u=rt.id;
        int L=rt.dis;
        if(vis[u][L%3]) continue;
        vis[u][L%3]=1;
        for(auto v:G[u]){
            int nowL=(L+1)%3;
            if(dis[v][nowL]>dis[u][L]+1){
                dis[v][nowL]=dis[u][L]+1;
                q.push({v,nowL});
            }
        }
    }
}
int main(){
    cin>>n>>m;
    int u,v;
    for(int i=1;i<=m;i++){
        cin>>u>>v;
        G[u].push_back(v);
    }
    cin>>S>>T;
    dijkstra(S);
    //cout<<dis[T][0]<<endl;
    if(dis[T][0]==INF) puts("-1");
    else cout<<dis[T][0]/3<<endl;
    return 0;
}

