const int MOD = 1000000007;

int main()
{
    int n, k;
    cin >> n >> k;

    int m = 1;
    while(m * m <= n)
        ++ m;
    -- m;
    m *= 2;

    vector<int> cnt(m, 1);
    for(int i=1; i<=m/2; ++i)
        cnt[m-i] = (n / i) - max(m/2, (n / (i + 1)));

    vector<long long> dp(cnt.begin(), cnt.end());
    while(--k > 0){
        vector<long long> nextDp(m, 0);
        long long sum = 0;
        for(int i=0; i<m; ++i){
            sum += dp[i];
            sum %= MOD;
            nextDp[m-1-i] += sum * cnt[m-1-i];
            nextDp[m-1-i] %= MOD;
        }
        dp = move(nextDp);
    }
    long long ans = accumulate(dp.begin(), dp.end(), 0LL) % MOD;
    cout << ans << endl;

    return 0;
}

