const int A = 1e9 + 7;
int n, k;
unsigned int l[100][40000];

int main() {
    scanf("%d %d", &n, &k);
    const int sqn = static_cast<int>(std::sqrt(n));
    for (int i = 1; i * i <= n; i++) {
        l[0][i] = i;
        l[1][i] = (n / i + l[1][i - 1]) % A;
    }
    for (int i = 2; i < k; i++) {
        l[i][sqn] = (l[i - 1][sqn]
                  + static_cast<long>(l[i - 2][sqn]) * (n / sqn - sqn)) % A;
        for (int j = sqn - 1; j > 0; j--) {
            l[i][j] = (static_cast<long>(l[i][j + 1])
                    + static_cast<long>(l[i - 2][j]) * (n / j - n / (j + 1))) % A;
        }
        for (int j = 2; j * j < n; j++) {
            l[i][j] = (l[i][j] + l[i][j - 1]) % A;
        }
    }

    unsigned int sum = (l[k - 1][sqn]
                     + static_cast<long>(l[k - 2][sqn]) * (n / sqn - sqn)) % A;
    for (int j = sqn - 1; j > 0; j--) {
        sum = (sum + static_cast<long>(l[k - 2][j]) * (n / j - n / (j + 1))) % A;
    }

    printf("%u\n", sum);
    return 0;
}

