	vector<ll> cnt(d.size());
	for (int i = 0; i + 1 < d.size(); i++) {
		cnt[i] += n / d[i] - n / d[i + 1];
	}

	cnt.back() = 1;
	vector dp(K + 1, vector<mint>(d.size() + 1));
	auto get = [&](ll x)-> int {
		return lower_bound(d.begin(), d.end(), x) - d.begin();
