const li mod = 1e9 + 7;

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    li n, k;
    cin >> n >> k;

    li sqrtn;
    for (li i = 0; i * i <= n; ++i) {
        sqrtn = i;
    }

    vector<li> ub, upperub;
    for (int i = 0; i < sqrtn; ++i) {
        ub.push_back(i + 1);
        upperub.push_back(n / (i + 1));
    }
    sort(upperub.begin(), upperub.end());
    ub.insert(ub.end(), upperub.begin(), upperub.end());

    const li m = ub.size();
    vector<vector<li>> dp(k + 1, vector<li>(m));
    dp[0][0] = 1;
    for (int i = 0; i < k; ++i) {
        li accum = 0;
        for (int j = 0; j < m; ++j) {
            accum += dp[i][j];
            accum %= mod;
            li revj = m - 1 - j;
            li size = revj ? ub[revj] - ub[revj - 1] : ub[revj];
            dp[i + 1][revj] = accum * size % mod;
        }
    }

    li ans = 0;
    for (int i = 0; i < m; ++i) {
        ans += dp[k][i];
        ans %= mod;
    }
    cout << ans << endl;
    return 0;
}

