void Calc(){
	long N = rei();
	int K = rei();
	vector<long> C;
	{
		int i;
		int sq;
		for(i=1;i*i<=N;i++){
			C.push_back(1);
		}
		sq = i-1;
		if(N/sq-sq != 0){
			C.push_back(N/sq-sq);
		}
		for(i=sq;i>=2;i--){
			C.push_back(N/(i-1)-N/i);
		}
	}
	DP[0][0] = 1;
	for(int i=1;i<=K;i++){
		long sum = 0;
		for(int j=C.size()-1;j>=0;j--){
			sum += DP[i-1][C.size()-1-j];
			sum %= mod;
			DP[i][j] = sum * C[j] % mod;
		}
	}
	long ans = 0;
	for(int i=0;i<C.size();i++){
		ans += DP[K][i];
	}
	ans %= mod;
	cout << ans << endl;
}
