#include <bits/stdc++.h>
using namespace std;
typedef long long int64;
const int MOD = 1000000007;

int main() {
    int N, K;
    cin >> N >> K;

    // [N / x] の値でグループ分け
    vector<pair<int, int>> layer; // ([N / x], 個数)
    for(int i = 1; i * i <= N; ++i) {
        layer.emplace_back(i, 0);
        layer.emplace_back(N / i, 0);
    }
    sort(layer.begin(), layer.end());
    reverse(layer.begin(), layer.end());
    layer.erase(unique(layer.begin(), layer.end()), layer.end());
    for(int i = 0; i < layer.size() - 1; ++i) {
        int l = N / layer[i].first;
        int r = N / layer[i + 1].first;
        layer[i + 1].second = r - l;
    }
    layer.front().second = 1;

    // map で [N / x] と id を対応させる
    int M = layer.size();
    map<int, int> ma;
    for(int i = 0; i < M; ++i) {
        ma[layer[i].first] = i;
    }

    // dp[i][j] := i 個目の数を j 層目の数にするときの条件を満たす場合の数
    vector<vector<int64>> dp(K + 1, vector<int64>(M));
    dp[0][ma[N]] = 1;
    for(int i = 0; i < K; ++i) {
        for(int j = 0; j < M - 1; ++j) {
            dp[i][j + 1] += dp[i][j];
            dp[i][j + 1] %= MOD;
        }
        for(int j = 0; j < M; ++j) {
            int x = layer[j].first;
            int cnt = layer[j].second;
            int id = ma[N / x];
            dp[i + 1][j] = dp[i][id] * cnt;
            dp[i + 1][j] %= MOD;
        }
    }

    // 集計
    int ans = 0;
    for(int j = 0; j < M; ++j) {
        ans += dp[K][j];
        ans %= MOD;
    }
    cout << ans << '\n';
    return 0;
}

