int main() {
#ifdef  DEBUG
  ifstream in("input.txt");
  cin.rdbuf(in.rdbuf());
#endif  // for local.
  int n, k;
  cin >> n >> k;
  int rt_n = (int)floor(sqrt(n));
  int ptnn = n/(rt_n+1) + rt_n;
  uwl p_rng[ptnn];
  uwl ptnbf[ptnn];
  uwl ptnaf[ptnn];
  memset(ptnaf, 0, sizeof(ptnaf));
  memset(p_rng, 0, sizeof(p_rng));

  for (int i = 0; i < rt_n; i++) {
    ptnaf[i] = n / (i+1);
    p_rng[i] = 1;
  }
  for (int i = 1; i < n/(rt_n+1) + 1; i++) {
    ptnaf[ptnn-i] = i;
  }
  for (int i = 1; i < n/(rt_n+1) + 1; i++) {
    p_rng[ptnn-i] = ptnaf[i-1] - ptnaf[i];
  }

  for (int i = 2; i < k; i++) {
    swl bfttl = 0;
    memcpy(ptnbf, ptnaf, sizeof(ptnaf));
    memset(ptnaf,     0, sizeof(ptnaf));

    for (int i = 0; i < ptnn; i++) {
      bfttl = (bfttl + ptnbf[i] * p_rng[i]) % MOD;
    }
    ptnaf[0] = bfttl;
    for (int j = 1; j < ptnn; j++) {
      bfttl = (bfttl - (swl)ptnbf[ptnn-j] * (swl)p_rng[ptnn-j]) % MOD;
      bfttl = bfttl < 0 ? bfttl + MOD : bfttl;
      ptnaf[j] = bfttl;
    }
  }

  uwl ans = 0;
  for (int i = 0; i < ptnn; i++) {
    ans = (ans + ptnaf[i] * p_rng[i]) % MOD;
  }

  cout << ans << endl;

  return 0;
}

