        for (int j = 0; j < v.size(); j++) {
            S[j+1] = (dp[i][j] + S[j])%mod;
        }
        for (int j = 0; j < v.size(); j++) {
            dp[i+1][j] = (S[v.size()-j] * v[j])%mod;
        }
    }
    LL ans = 0;
    for (int i = 0; i < v.size(); i++) {
        ans = (ans + dp[k-1][i])%mod;
    }
    cout << ans << endl;
    return 0;
}

