#define rep(i, n) for(UL i = 0; i < (n); i++)

struct Problem {

	const ULL M = 1000000007;

	ULL dp[101][100000] = {};

	void Solve() {
		UL N, K; cin >> N >> K;
		UL n = 1;
		while (n * n <= N) n++; n--;
		UL nn = n;
		vector<UL> Sz(n);
		for (UL i = 0; i < n; i++) { Sz[i] = 1; }
		UL p = n, d = N / (p + 1);
		while (d > 0) {
			Sz.push_back(N / d - p);
			p = N / d;
			nn++;
			d--;
		}
		rep (i, nn) dp[0][i] = 1;
		for (UL k = 1; k <= K; k++) {
			ULL S = 0;
			for (UL np = 0; np < nn; np++) {
				S += Sz[np] * dp[k - 1][nn - np - 1];
				S %= M;
				dp[k][np] = S;
			}
		}
		cout << dp[K][nn - 1] << endl;
	}


	Problem();
};
int main() {
	unique_ptr<Problem> p(new Problem());
	p->Solve();
	return 0;
}
