struct BIG
{
	int l, r, value;
	BIG() {}
	BIG(int _l, int _r, int _value) {
		l = _l, r = _r, value = _value;
	}
};

vector< BIG > getbigs(int x) {
	int K = (int)sqrt(x);
	vector< BIG > res;
	int i = 1;
	while (i <= x) {
		int value = x / i;
		int nw = x / value;
		while (x / nw == value) ++nw;
		int l = i;
		int r = nw - 1;
		uax(l, K + 1);
		if (l <= r)
			res.push_back(BIG(l, r, value));
		i = nw;
	}
	return res;
}

