lint dp[101][40000];

int main(){
    lint n; int k; cin >> n >> k;

    vector<lint> c;
    for(lint i = 1; i*i <= n; i++){
        lint j = n / i;
        c.push_back(i); c.push_back(j);
    }
    sort(all(c));
    int m = c.size();

    rep(j, m) dp[1][j] = c[j];
    for(int i = 2; i <= k; i++){
        rep(j, m){
            if(j == 0){
                dp[i][0] = dp[i-1][m-1];
                continue;
            }
            dp[i][j] = (dp[i][j-1] + ((c[j] - c[j-1]) * dp[i-1][m-j-1]) % MOD) % MOD;
        }
    }
    out(dp[k][m-1]);
}

