signed main() {
	INIT;

	VAR(int, n, k);
	V<int> d;
	{
		std::set<int> set;
		for (int i = 1; i * i <= n; ++i) set.emplace(n / i), set.emplace(i);
		for (auto& x : set) d.emplace_back(x);
	}
	int sz = d.size();

	V<int> len(sz, 1);

	len[0] = 1;
	FOR(i, 1, sz) len[i] = d[i] - d[i - 1];

	REP(i, sz) dp[0][i] = len[i];

	REP(_, k - 1) {
		auto& cur = dp[_ & 1];
		auto& nex = dp[1 - _ & 1];

		V<int> c(sz + 1, 0);
		REP(i, sz) c[i + 1] = (c[i] + cur[i]) % MOD;

		REP(i, sz) (nex[i] += c[sz - i] * len[i] % MOD) %= MOD;

		FILL(cur, 0LL);
	}

	int ans = 0;
	REP(i, sz) (ans += dp[(k - 1) & 1][i]) %= MOD;
	OUT(ans)BR;

	return 0;
}

