ll dp[2][100001][2];
ll sum[2][100001][2];
ll num[100001];
ll mod = 1000000007;

void solve()
{
    ll n,k;
    cin >> n >> k;

    ll xx = sqrt(n);
    ll kit = n/xx;
    kit--;

    fr(i,1,kit)
    {
        ll fir = n/i;
        ll sec = n/(i+1);
        sec++;
        ll kit2 = fir-sec+1;
        kit2 %= mod;

        num[i] = kit2;
    }

    fr(i,1,sqrt(n))
    {
        dp[0][i][0] = 1;
    }
    fr(i,1,kit)
    {
        dp[0][i][1] = num[i];
    }

    frr(i,kit,1)
    {
        sum[0][i][1] = sum[0][i+1][1]+dp[0][i][1];
        sum[0][i][1] %= mod;
    }

    fr(i,1,xx)
    {
        sum[0][i][0] = sum[0][i-1][0]+dp[0][i][0];
        sum[0][i][0] %= mod;
    }
    fr(i,xx+1,kit)
    {
        sum[0][i][0] = sum[0][xx][0];
    }

    fr(i,1,k-1)
    {
        fr(i,1,kit)
        {
            dp[1][i][1] = 0;
            sum[1][i][1] = 0;
        }
        fr(i,1,xx)
        {
            dp[1][i][0] = 0;
            sum[1][i][0] = 0;
        }

        fr(i,1,kit)
        {
            ll yy = sum[0][i][0];
            yy = yy*num[i];
            yy %= mod;
            dp[1][i][1] = yy;
        }
        fr(i,1,xx)
        {
            ll yy = sum[0][xx][0];
            ll zz = sum[0][i][1];
            yy = yy+zz;
            yy %= mod;
            dp[1][i][0] = yy;
        }

        frr(i,kit,1)
        {
            sum[1][i][1] = sum[1][i+1][1]+dp[1][i][1];
            sum[1][i][1] %= mod;
        }

        fr(i,1,xx)
        {
            sum[1][i][0] = sum[1][i-1][0]+dp[1][i][0];
            sum[1][i][0] %= mod;
        }
        fr(i,xx+1,kit)
        {
            sum[1][i][0] = sum[1][xx][0];
        }

        fr(i,1,kit)
        {
            dp[0][i][1] = dp[1][i][1];
            sum[0][i][1] = sum[1][i][1];
        }
        fr(i,1,xx)
        {
            dp[0][i][0] = dp[1][i][0];
            sum[0][i][0] = sum[1][i][0];
        }
    }

    ll ans = 0;
    fr(i,1,xx)
    {
        ans = ans + dp[0][i][0];
        ans %= mod;
    }
    fr(i,1,kit)
    {
        ans = ans + dp[0][i][1];
        ans %= mod;
    }

    cout << ans << endl;
}

