int binary_search(vector<long long> &prime, int &x){
    int ok = 0;
    int ng = prime.size();
    while (abs(ok - ng) > 1){
        int mid = (ok + ng) / 2;
        if (prime[x] * prime[mid] > n) ng = mid;
        else ok = mid;
    }
    return ng;
}

