ll N, K;

void solve() {
	scanf("%lld%lld", &N, &K);

	vector<ll> div;
	ll tval=-1;
	repeq(i,N){
		ll t=N/i;
		if(tval!=t){
			div.push_back(i);
			if(i==t)break;
			else{
				div.push_back(t);
				tval=t;
			}
		}
	}
	sort(all(div));

	vector<Modint> divnum(div.size(),1);
	repeq(i,div.size()-1)divnum[i]=div[i]-div[i-1];
	debug(div);
	debug(divnum);

	vector<Modint> rui(div.size()+1,0);
	rep(i,div.size())rui[i+1]=rui[i]+divnum[i];

	vector<vector<Modint>> dp(div.size(), vector<Modint>(K,0));
	vector<vector<Modint>> dprui(div.size(), vector<Modint>(K,0));
	rep(i,div.size())dp[i][0]=divnum[i];
	dprui[0][0]=1;
	rep(i,div.size()-1)dprui[i+1][0]=dprui[i][0]+dp[i+1][0];
	debug(dp);
	debug(dprui);

	repeq(j,K-1) rep(i,div.size())  {
		ll t=div.size()-i-1;
		dp[i][j]=divnum[i]*(dprui[t][j-1]);

		if(i==0)dprui[0][j]=dp[0][j];
		else dprui[i][j]=dprui[i-1][j]+dp[i][j];
	}

	debug(dp);
	debug(dprui);

	printf("%lld\n", dprui[div.size()-1][K-1]);
}

