    while (N/lo != N/hi) {
        while (hi - lo > 1) {
            int mid = (lo+hi) / 2;
            if (N/lo == N/mid) lo = mid;
            else hi = mid;
        }
        nums.PB(lo);
        lo = lo+1;
        hi = N+1;
    }
