template<int MOD>
class ModInt {
public:
    ModInt() :value(0) {}
    ModInt(long long val) :value((int)(val<0 ? MOD + val%MOD : val%MOD)) { }

    ModInt& operator+=(ModInt that) {
        value = value + that.value;
        if (value >= MOD)value -= MOD;
        return *this;
    }
    ModInt& operator-=(ModInt that) {
        value -= that.value;
        if (value<0)value += MOD;
        return *this;
    }
    ModInt& operator*=(ModInt that) {
        value = (int)((long long)value * that.value % MOD);
        return *this;
    }
    ModInt &operator/=(ModInt that) {
        return *this *= that.inverse();
    }
    ModInt operator+(ModInt that) const {
        return ModInt(*this) += that;
    }
    ModInt operator-(ModInt that) const {
        return ModInt(*this) -= that;
    }
    ModInt operator*(ModInt that) const {
        return ModInt(*this) *= that;
    }
    ModInt operator/(ModInt that) const {
        return ModInt(*this) /= that;
    }
    ModInt pow(long long k) const {
        ModInt n = *this, res = 1;
        while (k) {
            if (k & 1)res *= n;
            n *= n;
            k >>= 1;
        }
        return res;
    }
    ModInt inverse() const {
        long long a = value, b = MOD, u = 1, v = 0;
        while (b) {
            long long t = a / b;
            a -= t * b;
            swap(a, b);
            u -= t * v;
            swap(u, v);
        }
        return ModInt(u);
    }
    int toi() const { return value; }

private:
    int value;
};
typedef ModInt<1000000007> mint;
ostream& operator<<(ostream& os, const mint& x) {
    os << x.toi();
    return os;
}

void solve() {
    int N, K;
    cin >> N >> K;

    int r = 1;
    while (r*r <= N)++r;

    vector<mint> small(r), large(r), mul(r);
    for (int i = 1; i < r; ++i) {
        small[i] = 1;
        if (i != r - 1) {
            large[i] = mul[i] = N / i - N / (i + 1);
        } else {
            large[i] = mul[i] = N / i - r + 1;
        }
    }

    vector<mint> nSmall(r), nLarge(r);

    rep(i, K - 1) {
        fill(all(nSmall), 0);
        fill(all(nLarge), 0);

        for (int j = 1; j < r; ++j) {
            nSmall[1] += small[j];
            nLarge[j] += small[j];

            if (j + 1 < r)nSmall[j + 1] -= large[j];
            nSmall[1] += large[j];
        }
        for (int j = 1; j < r - 1; ++j) {
            nSmall[j + 1] += nSmall[j];
            nLarge[j + 1] += nLarge[j];
        }
        rep(j, r) {
            nLarge[j] *= mul[j];
        }

        swap(nSmall, small);
        swap(nLarge, large);
    }

    mint ans = 0;
    rep(i, r) {
        ans += small[i] + large[i];
    }
    cout << ans << endl;
}

int main() {
	ios::sync_with_stdio(false);
	cin.tie(0);
	cout << fixed << setprecision(15);
	solve();
	return 0;
}

