template<typename T>
T MOD(T a, T m) {
    a %= m;
    if (a < 0)a += m;
    return a;
}

template<typename T>
T inverse(T a, T m) {
    a = MOD(a, m);
    if (a <= 1)return a;
    return MOD((1 - inverse(m, a) * m) / a, m);
}

