template< int mod >
struct ModInt {
  int x;

  ModInt() : x(0) {}

  ModInt(int64_t y) : x(y >= 0 ? y % mod : (mod - (-y) % mod) % mod) {}

  ModInt &operator+=(const ModInt &p) {
    if((x += p.x) >= mod) x -= mod;
    return *this;
  }

  ModInt &operator-=(const ModInt &p) {
    if((x += mod - p.x) >= mod) x -= mod;
    return *this;
  }

  ModInt &operator*=(const ModInt &p) {
    x = (int) (1LL * x * p.x % mod);
    return *this;
  }

  ModInt &operator/=(const ModInt &p) {
    *this *= p.inverse();
    return *this;
  }

  ModInt operator-() const { return ModInt(-x); }

  ModInt operator+(const ModInt &p) const { return ModInt(*this) += p; }

  ModInt operator-(const ModInt &p) const { return ModInt(*this) -= p; }

  ModInt operator*(const ModInt &p) const { return ModInt(*this) *= p; }

  ModInt operator/(const ModInt &p) const { return ModInt(*this) /= p; }

  bool operator==(const ModInt &p) const { return x == p.x; }

  bool operator!=(const ModInt &p) const { return x != p.x; }

  ModInt inverse() const {
    int a = x, b = mod, u = 1, v = 0, t;
    while(b > 0) {
      t = a / b;
      swap(a -= t * b, b);
      swap(u -= t * v, v);
    }
    return ModInt(u);
  }

  ModInt pow(int64_t n) const {
    ModInt ret(1), mul(x);
    while(n > 0) {
      if(n & 1) ret *= mul;
      mul *= mul;
      n >>= 1;
    }
    return ret;
  }

  friend ostream &operator<<(ostream &os, const ModInt &p) {
    return os << p.x;
  }

  friend istream &operator>>(istream &is, ModInt &a) {
    int64_t t;
    is >> t;
    a = ModInt< mod >(t);
    return (is);
  }
};

using modint = ModInt< mod >;

vector< int64_t > divisor(int64_t n) {
  vector< int64_t > ret;
  for(int64_t i = 1; i * i <= n; i++) {
    if(n % i == 0) {
      ret.push_back(i);
      if(i * i != n) ret.push_back(n / i);
    }
  }
  sort(begin(ret), end(ret));
  return (ret);
}


int main() {
  int N, K;
  cin >> N >> K;

  int left = 1;
  vector< pair< int, int > > range;
  while(left <= N) {
    int ok = left - 1, ng = N + 1;
    while(ng - ok > 1) {
      int mid = (ok + ng) / 2;
      if(N / mid >= N / left) ok = mid;
      else ng = mid;
    }
    range.emplace_back(left, ok);
    left = ok + 1;
  }

  vector< modint > dp(range.size());
  dp[0] = 1;

  vector< int > correct(range.size());
  for(int j = 0; j < range.size(); j++) {
    int ok = -1, ng = range.size();
    while(ng - ok > 1) {
      int mid = (ok + ng) / 2;
      if(1LL * range[mid].first * range[j].first <= N) ok = mid;
      else ng = mid;
    }
    correct[j] = ok;
  }

  for(int i = 0; i < K; i++) {
    vector< modint > dp2(range.size()), dp3(range.size());
    for(int j = 0; j < range.size(); j++) {
      if(~correct[j]) dp3[correct[j]] += dp[j];
    }
    modint add = 0;
    for(int j = range.size() - 1; j >= 0; j--) {
      add += dp3[j];
      dp2[j] = add * (range[j].second - range[j].first + 1);
    }
    dp.swap(dp2);
  }
  modint ret;
  for(auto &t : dp) ret += t;
  cout << ret << endl;
}

