const ll MOD = 1000000007;

int main()
{

	ll N, K;
	cin >> N >> K;

	vec A;

	for (ll i = 1; i <= sqrt(N); ++i)
	{
		A.emplace_back(N / i);
	}

	for (ll i = sqrt(N); i > 0; --i)
	{
		if (N / i == i)continue;
		A.emplace_back(i);
	}

	for (ll i = 0; i < A.size() - 1; ++i)
	{
		A[i] -= A[i + 1];
	}

	reverse(A.begin(), A.end());

	for (auto& a : A) { a %= MOD; }

	vec B(A.size() + 1,0);

	for(ll i=0;i<A.size();++i)
	{
		B[i] = A[i];
	}

	for (ll i = 0; i < K-1; ++i)
	{
		vec tmp(B.size(), 0);
		for (ll j = 0; j < tmp.size(); ++j)
		{
			tmp[0] = (tmp[0] + B[j]) % MOD;
			tmp[tmp.size() - j - 1] = (tmp[tmp.size() - j - 1] - B[j] + MOD) % MOD;
		}

		for (ll j = 1; j < tmp.size(); ++j)
		{
			tmp[j] += tmp[j - 1];
			tmp[j] %= MOD;
		}

		for (ll j = 0; j < A.size(); ++j)
		{
			tmp[j] *= A[j];
			tmp[j] %= MOD;
		}
		B = tmp;
	}

	ll ans = 0;
	for (ll i = 0; i < B.size(); ++i)
	{
		ans += B[i];
		ans %= MOD;
	}
