const int MAXD = 1e5, MAXK = 105, MOD = 1e9 + 7;
vector<int> d;
void addb(int a) {
	int m = a;
	d.push_back(1);
	while (m && m != 1) {
		int t = a / m, nxm = a / (t + 1);
		d.push_back(nxm + 1);
		d.push_back(t);
		m = nxm;
	}
	sort(d.begin(), d.end());
	d.resize(unique(d.begin(), d.end()) - d.begin());
	d.push_back(a + 1);
}
long long dp[MAXD], dpo[MAXD];
int n, k;

int main() {
	cin >> n >> k;
	addb(n);
	dpo[0] = d[1] - d[0];
	for (int i = 1; i < d.size() - 1; i++)
		dpo[i] = d[i + 1] - d[i] + dpo[i - 1];
	for (int i = 1; i < k; i++) {
		for (int j = 0; j < d.size() - 1; j++) {
			int ind = upper_bound(d.begin(), d.end(), n / d[j]) - d.begin();
			dp[j] = dpo[ind - 1] * (d[j + 1] - d[j]) % MOD;
		}
		swap(dp, dpo);
		for (int i = 1; i < d.size() - 1; i++)
			dpo[i] += dpo[i - 1], dpo[i] %= MOD;
	}
	cout << dpo[d.size() - 2];
}

