int main() {
	int n, k; scanf("%d%d", &n, &k);

	std::vector<std::pair<int, int>> vec(1, {0, 1});
	{
		int now = 1;
		while(now < n) {
			int ok = n + 1, ng = now;
			while(std::abs(ok - ng) > 1) {
				int mid = (ok + ng) >> 1;

				if(n / now > n / mid) ok = mid;
				else ng = mid;
			}

			vec.push_back({now, ok});
			now = ok;
		}
	}

	#ifndef NDEBUG
	for(auto v: vec) printf("[%d, %d)\n", v.first, v.second);
	#endif

	auto calc = [&](std::pair<int, int> p) -> mint { return p.second - p.first; };

	std::vector<mint> dp(vec.size()); dp[0] = 1;
	for(int l = 0; l < k; l++) {
		std::vector<mint> nxt(vec.size());

		mint tmp = 0;
		int cur = (int)vec.size() - 1;
		for(int i = (l != 0); i < dp.size(); i++) {
			while(cur > 0 and vec[cur].first * vec[i].first > n) {
				nxt[cur] += tmp * calc(vec[cur]);
				cur--;
			}
			tmp += dp[i];
		}
		while(cur > 0) {
			nxt[cur] += tmp * calc(vec[cur]);
			cur--;
		}

		dp.swap(nxt);
	}

	mint ans = 0;
	for(auto v: dp) ans += v;
	printf("%d\n", ans.value()); 
	return 0;
}

