  REP(i, size-1) dp[0][i+1] = (dp[0][i] + dp[0][i+1]) % MOD;
  FOR(i, 1, K) {
    REP(j, size) dp[i][j] = dp[i-1][size-1-j] * state[j] % MOD;
    REP(j, size-1) dp[i][j+1] = (dp[i][j] + dp[i][j+1]) % MOD;
  }
  cout << dp[K-1][size-1] << endl;
}

