using namespace std;

using mint = ModInt<MOD>;

int main() {
    lint N, K;
    cin >> N >> K;

    vector<int> A;
    lint R = N;
    for (int i = 1;; ++i) {
        // R以下で、iをかけてもセーフだがi+1を掛けると死ぬ数を列挙
        if (R * (i + 1) <= N) {
            while (R > 0) {
                A.push_back(1);
                --R;
            }
            break;
        }

        // ok * (i + 1) <= N
        lint ok = 0, ng = R;
        while (ng - ok > 1) {
            lint mid = (ok + ng) / 2;
            (mid * (i + 1) <= N ? ok : ng) = mid;
        }
        // (ok, R]は全部死ぬ
        A.push_back(R - ok);
        R = ok;
    }

    int M = A.size();
    SegmentTree<mint, mint>
        seg(M, 0,
            [](mint a, mint b) { return a + b; },
            [](mint a, mint b) { return a + b; });

    for (int i = 0; i < M; ++i) seg.update(i, A[i]);

    for (int j = 1; j < K; ++j) {
        SegmentTree<mint, mint>
            nseg(M, 0,
                 [](mint a, mint b) { return a + b; },
                 [](mint a, mint b) { return a + b; });

        for (int i = 0; i < M; ++i) {
            nseg.update(i, seg.query(M - i - 1, M) * A[i]);
        }
        swap(seg, nseg);
    }

    cout << seg.query(0, M) << endl;
    return 0;
}

