const int MOD = 1e9 + 7;
const int N = 101;
const int K = sqrt(1e9) + 2;

int n, k, lim;
int cache[N][K];

int dp(int idx, int val)
{
	if(idx == k)
		return 1;
	int &ans = cache[idx][val];
	if(ans != -1)
		return ans;
	ans = 0;
	for(int i = 1; i <= lim; i++)
		ans += dp(idx + 1, i);
	ans %= MOD;
	if(idx == k - 1)
	{
		int extra = n / val - lim;
		if(extra >= 0)
			ans += extra;
		ans %= MOD;
	}
	else
	{
		int mx = n / val;
		int mn = lim + 1;
		for(int i = 1; i <= lim; i++)
		{
			int mx2 = n / i;
			int curmx = min(mx, mx2);
			if(curmx >= mn)
			{
				ans += (curmx - mn + 1) * (dp(idx + 2, i));
				ans %= MOD;
			}
		}
	}
	return ans;
}	

