	for(int i = 1; i <= lim; i++)
	{
		ans += dp(1, i);
		int mn = lim + 1;
		int mx = n / i;
		ans += (mx - mn + 1) * dp(2, i);
		ans %= MOD;
	}
	ans %= MOD;
	cout << ans;
	return 0;
}

