	auto idx = [ &n, &n2 ]( ll a )
	{
		return ( 2 * n2 + 1 ) - ( n / a );
	};
	REP( kk, k )
	{
		(*pdpsum2)[0] = 0;
		REP( i, n2 )
		{
			ll a = (*pdpsum)[ idx(  n / ( i + 1 ) ) ];
