	vector<long long> vp = { 0 }, vq;
	for (int i = 1; 1LL * i * i <= N; ++i) {
		vp.push_back(i);
		vq.push_back(N / i);
	}
	if (vp.back() == vq.back()) vq.pop_back();
	while (!vq.empty()) vp.push_back(vq.back()), vq.pop_back();
	int S = vp.size() - 1;
	vector<mint> dp(S);
	for (int i = 0; i < S; ++i) {
		dp[i] = vp[i + 1] - vp[i];
	}
	for (int i = 1; i < K; ++i) {
		vector<mint> ndp(S);
		int ptr = 0;
		mint sum = 0;
		for (int j = S - 1; j >= 0; --j) {
			while (ptr != S && vp[ptr + 1] * vp[j + 1] <= N) {
				sum += dp[ptr++];
			}
			ndp[j] = sum * (vp[j + 1] - vp[j]);
		}
		dp = ndp;
	}
	mint ans = 0;
	for (int i = 0; i < S; ++i) ans += dp[i];
	cout << ans.get() << endl;
	return 0;
}

