void solve() {
  int n, k;
  cin >> n >> k;
  vector<ll> v;
  // dp[i + 1][j] = \sum_{k = 1}^{n/j} dp[i][k]
  for (ll i = 1; i * i <= n; ++i) {
    v.eb(n / i); v.eb(i);
  }
  sort(all(v));
  v.erase(unique(all(v)), v.end());
  // 各ブロックの個数を求める
  rep(i, sz(v) - 1) v[i] = v[i + 1] - v[i];
  v.pop_back();
  v.insert(v.begin(), 1);
  // cout << v << '\n';
  vector<ll> dp = v;
  rep(i, k - 1) {
    BIT bit(dp);
    rep(j, sz(v)) dp[j] = bit.sum(sz(v) - j) % mod * v[j] % mod;
    // cout << dp << '\n';
  }
  cout << accumulate(all(dp), 0LL) << '\n';
}

