ll N, K;
ll M = 1000000007;
vector<ll> gids; // グループID一覧
map<ll, ll> next_gid; // 直前のグループID
map<ll, ll> sizes; // グループID => グループの要素数
vector<map<ll,ll>> dp; // dp[i][gid]: i個の並べた時に、最後の数が gid に属する

ll f (ll i, ll gid) {
  static map<PLL, ll> memo;
  if (memo.find(make_pair(i, gid)) != memo.end())
    return memo[make_pair(i, gid)];

  ll res;
  if (i == 0)
    res = 0;
  else if (gid == 0)
    res = 0; // need?
  else if (gid == N)
    res =  dp[i][N];
  else
    res = f(i, next_gid[gid]) + (dp[i][gid] * sizes[gid]) %M;

  // cout<<"i="<<i<<" gid="<<gid<<endl;
  res %= M;
  return memo[make_pair(i, gid)] = res;
}

signed main() {
  cin >> N >> K;

  for (int x = 1; x * x <= N; x++) {
    gids.push_back(x);
    gids.push_back(N/x);
  }
