  gids.erase(unique(begin(gids), end(gids)), end(gids));
  //for (auto gid: gids)
  //  cout<<"gid="<<gid<<endl;

  for (int i = 0; i < gids.size()-1; i++) {
    sizes[gids[i]] = N/gids[i] - N/gids[i+1];
    sizes[gids[i]] %= M;
    next_gid[gids[i]] = gids[i+1];
  }
  sizes[gids[gids.size()-1]] = 1;

  // for (auto p: sizes) {
