  dp.resize(K+1);
  for (auto gid: gids) {
    dp[1][gid] = 1;
    // printf("dp[%d][%d] = %d\n", 1, gid, dp[1][gid]);
  }
  for (int i=2; i<=K; i++) {
    // for (int x = 1; x <= N; x++) {
    // for (auto gid: gids) {
    for (int p=gids.size()-1; p>=0; p--) {
      auto gid = gids[p];
      dp[i][gid] = f(i-1, N/gid) %M;
      // printf("dp[%d][%d] = %d\n", i, x, dp[i][x]);
    }
  }

  ll ans = 0;
  for (auto gid: gids) {
    ans += (dp[K][gid] * sizes[gid])%M;
    ans %= M;
  }
  cout << ans << endl;
  return 0;
