public struct Modint{
	const int mod=(int)1e9+7;
	private long d;
	public Modint(long d){this.d=d;}
	public static implicit operator Modint(long d){return new Modint(d);}
	public static explicit operator long(Modint d){return d.d;}
	public override string ToString(){return d.ToString();}
	public static Modint operator+(Modint a,long b){a.d=(a.d+b)%mod;return a;}
	public static Modint operator+(Modint a,Modint b){a.d=(a.d+b.d)%mod;return a;}
	public static Modint operator-(Modint a,long b){a.d=(mod+a.d-b)%mod;return a;}
	public static Modint operator-(Modint a,Modint b){a.d=(mod+a.d-b.d)%mod;return a;}
	public static Modint operator*(Modint a,long b){a.d=(a.d*b)%mod;return a;}
	public static Modint operator*(Modint a,Modint b){a.d=(a.d*b.d)%mod;return a;}
	public static Modint operator/(Modint a,long b){a.d=(a.d*Mi(b))%mod;return a;}
	public static Modint operator/(Modint a,Modint b){a.d=(a.d*Mi(b.d))%mod;return a;}
	private static long Mi(long a){
		a=(a+mod)%mod;
		long b=mod,u=1,v=0;
		while(b>0){
			long t=a/b;
			a-=t*b;a^=b;b^=a;a^=b;
			u-=t*v;u^=v;v^=u;u^=v;
		}
		u%=mod;
		if(u<0){u+=mod;}
		return u%mod;
	}
}

