fun main(args: Array<String>) {
    val (N, K) = listOfInt()
    var s = mutableListOf<Pair<Int, Int>>()
    for (i in 1..Math.sqrt(N.toDouble()).toInt()) {
        s.add(Pair(i, 0))
        s.add(Pair(N / i, 0))
    }
    s.sortBy { it.first }
    s = s.distinctBy { it.first }.toMutableList()
    for (i in 0 until s.count() - 1) {
        val l = N / s[i + 1].first
        val r = N / s[i].first
        s[i] = Pair(s[i].first, r - l)
    }
    s[s.count() - 1] = Pair(s[s.count() - 1].first, 1)
    val m = s.count()
    val map = mutableMapOf<Int, Int>()
    repeat(m) {
        map[s[it].first] = it
    }
    var dp = Array<Array<ModInt>>(K + 1) { Array<ModInt>(m, { ModInt(0) }) }
    dp[0][map[N]!!] = ModInt(1)
    for (i in 0 until K) {
        for (j in m - 2 downTo 0) {
            dp[i][j] += dp[i][j + 1]
        }
        repeat(m) {
            val nj = map[N / s[it].first]!!
            dp[i + 1][it] += dp[i][nj] * ModInt(s[it].second.toLong())
        }
    }
    var ans = ModInt(0)
    repeat(m) { ans += dp[K][it] }
    println(ans)
}

