data class ModInt(private var v: Long) {

    companion object {
        private const val MOD = 1000000007L
    }

    init {
        if (v >= MOD) v %= MOD
    }

    operator fun plus(other: ModInt): ModInt {
        val x = v + other.v
        if (x >= MOD) {
            return ModInt(x - MOD)
        }
        return ModInt(x)
    }

    operator fun minus(other: ModInt): ModInt {
        val x = v + MOD - other.v
        if (x >= MOD) {
            return ModInt(x - MOD)
        }
        return ModInt(x)
    }

    operator fun times(other: ModInt): ModInt {
        return ModInt(v * other.v % MOD)
    }

    operator fun div(other: ModInt): ModInt {
        return ModInt(v * calc(other.v, MOD - 2) % MOD)
    }

    private fun calc(a: Long, b: Long): Long {
        if (b == 0L) return 1L
        if (b % 2L == 0L) {
            val d = calc(a, b / 2)
            return d * d % MOD
        }
        return a * calc(a, b - 1) % MOD
    }

    override fun toString(): String {
        return v.toString()
    }

}

