		}
		int q=len.size();
		long[]dp=new long[k*(q+1)];
		for(int j=1;j <=q;j++){
			dp[j]=len.get(j-1)+dp[j-1];
		}
		for(int i=1;i<k;i++){
			for(int j=1;j<=q;j++){
				int x=i*(q+1)+j;
				dp[x]=(dp[x-1]+dp[x-2*j]*len.get(j-1))%mod;
