            for (int j = 1; j <= q; j++) {
                dp[i * (q + 1) + j] = dp[i* (q + 1) + j - 1] + dp[(i - 1) * (q + 1) + q - j + 1] * len.get(j - 1);
                dp[i * (q + 1) + j] %= mod;
            }
        }
