public class F {
	final static long MOD = 1000000007;
	static long solveSmallDP(int N , int K){
		long dp[] = new long[N + 1];
		for(int i = 1 ; i <= N ; ++i){
			dp[i] = 1;			
		}
		for(int k = 0 ; k < K - 1; ++k){
//			System.out.println(k);
			long next[] = new long[N + 1];
			for(int i = 1 ; i <= N ; ++i){
				long S = 0;
				for(int j = 1  ; i * j <= N ; ++j){
					S = (S + dp[j]) % MOD;
				}
				next[i] = S;
			}
			dp = next;
		}
//		System.out.println(Arrays.toString(dp));		
		long S = 0;
		for(long d : dp){
			S = (S + d) % MOD;
		}
		return S;
	}
	public static void main(String[] args) {
		//
		// dp[k][i] = dp[k - 1][
		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();
		int K = sc.nextInt();
		if(N <= 100000){
			System.out.println(solveSmallDP(N, K));
			return ;
		}
		// dp[10] = dp[1]
		// dp[5]  = dp[1] + dp[2]
		// dp[4]  = dp[1] + dp[2]
		// dp[3]  = dp[1] + dp[2] + dp[3]
		// dp[2]  = dp[1] + ... + dp[3] + dp[4] * 2
		// dp[1]  = dp[1] + dp[2] + dp[3] + dp[4] * 2 + dp[5] * 5
		// (50001 .. 100000 ) dp2[1] = dp1[1]
		// (33334 .. 50000) dp2[2] = dp1[1] + dp1[2]
		// (25001 .. 33333) dp2[3] = dp1[1] + dp1[2] + dp1[3]
		// (20001 .. 25000) dp2[4] = dp1[1] + dp1[2] + dp1[3] + dp1[4]
		// ..
		// (991 .. 1000) dp2[100] = dp1[1] + ... + dp1[100]
		// dp1[990] = S + dp1[101]
		// dp1[989] = S + dp1[101] 		
		// dp1[988] = 
		int M = 1000;		
		int L = N / (M + 1);
		long dp1[] = new long[L + 1];
		long dp2[] = new long[M + 1];
		Arrays.fill(dp1, 1);
		Arrays.fill(dp2, 1);
		for(int k = 0 ; k < K - 1; ++k){
			long next1[] = new long[dp1.length];
			long next2[] = new long[dp2.length];
			long S = 0;
			for(int t = 1 ; t < dp2.length ; ++t){
				S = (S + dp1[t] ) % MOD;
				next2[t] = S;
			}
			int T = M + 1;
//			System.out.println(T +" "+ M + " "+L +" "+N+" "+(L * T));
			for(int i = dp1.length - 1; i >= 1 ; --i){
				while(i * T <= N){
					if(T < dp1.length){
						S = (S + dp1[T]) % MOD;
						T++;						
					}else{
						int len = N / i - (N / (i + 1));
						S = (S + dp2[i] * len) % MOD;
						break;
					}
				}
				next1[i] = S;
			}
			dp1 = next1;
			dp2 = next2;
		}
//		System.out.println(Arrays.toString(dp1));	
//		System.out.println(Arrays.toString(dp2));	

		long S = 0;
		for(long d : dp1){
			S = (S + d) % MOD;
		}
		// 10000 - 5000 [5001..10000]
		// 10001 - 5000 [5000..10001]
		for(int i = 1 ; i < dp2.length ; ++i){
			int len = N / i - (N / (i + 1));
			S = (S + dp2[i] * len) % MOD;
		}
		System.out.println(S);
	}
}

import java.util.*;

public class Main {

    void run() {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt(), k = sc.nextInt();
        long MOD = (long) 1e9 + 7;

        List<Integer> units = new ArrayList<>();
        List<Integer> counts = new ArrayList<>();

        for (int i = 1; i * i <= n; i++) {
            units.add(i);
        }

        List<Integer> unitsRev = new ArrayList<>();
        for (int i = 1; i * i < n; i++) {
            if (i != n / i) unitsRev.add(n / i);
        }
        Collections.reverse(unitsRev);
        units.addAll(unitsRev);

        int size = units.size();
        counts.add(1);
        for (int i = 1; i < size; i++) {
            counts.add(units.get(i) - units.get(i - 1));
        }

        long[][] dp = new long[k][size];

        for (int j = 0; j < size; j++) {
            dp[0][j] = 0;
        }

        for (int j = 0; j < size; j++) {
            dp[1][j] = counts.get(j) * (n / units.get(j)) % MOD;
        }

        for (int i = 2; i < k; i++) {
            dp[i][size - 1] = counts.get(size - 1) * dp[i - 1][0] % MOD;
            for (int j = size - 2; j >= 0; j--) {
                long sum = 0;
                for (int l = 0; l < size - j; l++) {
                    sum = (sum + dp[i - 1][l]) % MOD;
                }
                dp[i][j] = counts.get(j) * sum % MOD;
            }
        }

        long ans = 0;
        for (int j = 0; j < size; j++) {
            ans = (ans + dp[k - 1][j]) % MOD;
        }
        System.out.println(ans);

    }

    void debug(Object... os) {
        System.err.println(Arrays.deepToString(os));
    }

    public static void main(String[] args) {
        new Main().run();
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.InputMismatchException;
import java.util.NoSuchElementException;

public class Main {

	static PrintWriter out;
	static InputReader ir;

	static void solve() {
		int n = ir.nextInt();
		int k = ir.nextInt();
		int m = (int) Math.sqrt(n);
		long[][] dp = new long[m + 1][k + 1];
		long[] sum = new long[k + 1];
		long[] num = new long[m + 1];
		for (int i = 1; i <= m; i++) {
			dp[i][2] = n / i;
			sum[2] = add(sum[2], dp[i][2]);
			num[i] = n / i - Math.max(m, n / (i + 1));
			dp[i][1] = 1;
		}
		for (int i = 3; i <= k; i++) {
			long[] s1 = new long[m + 1];
			long[] s2 = new long[m + 1];
			for (int j = 1; j <= m; j++) {
				s1[j] = add(s1[j - 1], dp[j][i - 2]);
				s2[j] = add(s2[j - 1], mul(dp[j][i - 2], n / j - m));
			}
			for (int j = 1; j <= m; j++) {
				dp[j][i] = sum[i - 1];
				dp[j][i] = add(dp[j][i], mul(n / j - m, s1[j]));
				dp[j][i] = add(dp[j][i], sub(s2[m], s2[j]));
				sum[i] = add(sum[i], dp[j][i]);
			}
		}
		long res = sum[k];
		long[] ss = new long[m + 1];
		for (int i = 1; i <= m; i++) {
			ss[i] = add(ss[i - 1], dp[i][k - 1]);
		}
		for (int i = 1; i <= m; i++) {
			res = add(res, mul(num[i], ss[i]));
		}
		out.println(res);
	}

	static long mod = (long) 1e9 + 7;

	static long add(long a, long b) {
		return (a + b) % mod;
	}

	static long sub(long a, long b) {
		long d = a - b;
		while (d < 0)
			d += mod;
		return d;
	}

	static long mul(long a, long b) {
		return a * b % mod;
	}

	static long div(long a, long b) {
		return a * mod_inverse(b) % mod;
	}

	public static long[] fact(int n) {
		long[] ret = new long[n + 1];
		ret[0] = 1 % mod;
		for (int i = 1; i <= n; i++) {
			ret[i] = mul(ret[i - 1], i);
		}
		return ret;
	}

	private static long[] factInv(int n) {
		long[] ret = new long[n + 1];
		ret[0] = 1;
		for (int i = 1; i <= n; i++) {
			ret[i] = div(ret[i - 1], i);
		}
		return ret;
	}

	public static long comb(int n, int m, long[] fact, long[] factInv) {
		long ret = fact[n];
		ret = mul(ret, factInv[m]);
		ret = mul(ret, factInv[n - m]);
		return ret;
	}

	public static long[][] stirling(int n) {
		long[][] ret = new long[n + 1][n + 1];
		ret[0][0] = 1;
		for (int i = 1; i <= n; i++)
			for (int j = 1; j <= i; j++)
				ret[i][j] = add(ret[i - 1][j - 1], mul(ret[i - 1][j], j));
		return ret;
	}

	public static long mod_inverse(long a) {
		long[] ret = extgcd(a, mod);
		return add(mod, ret[0] % mod);
	}

	private static long[] extgcd(long a, long b) {
		long[] ret = new long[3];
		ret[2] = _extgcd(a, b, ret);
		return ret;
	}

	private static long _extgcd(long a, long b, long[] x) {
		long g = a;
		x[0] = 1;
		x[1] = 0;
		if (b != 0) {
			g = _extgcd(b, a % b, x);
			long temp = x[0];
			x[0] = x[1];
			x[1] = temp;
			x[1] -= (a / b) * x[0];
		}
		return g;
	}

	static long modpow(long a, long n) {
		long res = 1;
		while (n > 0) {
			if ((n & 1) != 0)
				res = res * a % mod;
			a = a * a % mod;
			n >>= 1;
		}
		return res;
	}

	public static void main(String[] args) {
		ir = new InputReader(System.in);
		out = new PrintWriter(System.out);
		solve();
		out.flush();
	}

	static class InputReader {

		private InputStream in;
		private byte[] buffer = new byte[1024];
		private int curbuf;
		private int lenbuf;

		public InputReader(InputStream in) {
			this.in = in;
			this.curbuf = this.lenbuf = 0;
		}

		public boolean hasNextByte() {
			if (curbuf >= lenbuf) {
				curbuf = 0;
				try {
					lenbuf = in.read(buffer);
				} catch (IOException e) {
					throw new InputMismatchException();
				}
				if (lenbuf <= 0)
					return false;
			}
			return true;
		}

		private int readByte() {
			if (hasNextByte())
				return buffer[curbuf++];
			else
				return -1;
		}

		private boolean isSpaceChar(int c) {
			return !(c >= 33 && c <= 126);
		}

		private void skip() {
			while (hasNextByte() && isSpaceChar(buffer[curbuf]))
				curbuf++;
		}

		public boolean hasNext() {
			skip();
			return hasNextByte();
		}

		public String next() {
			if (!hasNext())
				throw new NoSuchElementException();
			StringBuilder sb = new StringBuilder();
			int b = readByte();
			while (!isSpaceChar(b)) {
				sb.appendCodePoint(b);
				b = readByte();
			}
			return sb.toString();
		}

		public int nextInt() {
			if (!hasNext())
				throw new NoSuchElementException();
			int c = readByte();
			while (isSpaceChar(c))
				c = readByte();
			boolean minus = false;
			if (c == '-') {
				minus = true;
				c = readByte();
			}
			int res = 0;
			do {
				if (c < '0' || c > '9')
					throw new InputMismatchException();
				res = res * 10 + c - '0';
				c = readByte();
			} while (!isSpaceChar(c));
			return (minus) ? -res : res;
		}

		public long nextLong() {
			if (!hasNext())
				throw new NoSuchElementException();
			int c = readByte();
			while (isSpaceChar(c))
				c = readByte();
			boolean minus = false;
			if (c == '-') {
				minus = true;
				c = readByte();
			}
			long res = 0;
			do {
				if (c < '0' || c > '9')
					throw new InputMismatchException();
				res = res * 10 + c - '0';
				c = readByte();
			} while (!isSpaceChar(c));
			return (minus) ? -res : res;
		}

		public double nextDouble() {
			return Double.parseDouble(next());
		}

		public int[] nextIntArray(int n) {
			int[] a = new int[n];
			for (int i = 0; i < n; i++)
				a[i] = nextInt();
			return a;
		}

		public long[] nextLongArray(int n) {
			long[] a = new long[n];
			for (int i = 0; i < n; i++)
				a[i] = nextLong();
			return a;
		}

		public char[][] nextCharMap(int n, int m) {
			char[][] map = new char[n][m];
			for (int i = 0; i < n; i++)
				map[i] = next().toCharArray();
			return map;
		}
	}

	static void tr(Object... o) {
		out.println(Arrays.deepToString(o));
	}
}

import java.io.*;
import java.util.NoSuchElementException;


public class Main {

	private static Scanner sc;
	private static Printer pr;

	private static void solve() {
		final int MOD = 1_000_000_007;

		int n = sc.nextInt();
		int k = sc.nextInt();

		int sqrt = (int)Math.sqrt(n);

		long[][] dp = new long[k][sqrt + 1];
		long[][] dp2 = new long[k][sqrt + 1];
		for (int i = 1; i <= sqrt; i++) {
			dp[0][i] = 1;
		}
		for (int i = 1; i <= sqrt; i++) {
			dp2[0][i] = n / i - n / (i + 1);
		}
		if (n / sqrt == sqrt) {
			dp2[0][sqrt] = 0;
		}

		for (int i = 1; i < k; i++) {
			long[] cumsum = new long[sqrt + 1];
			for (int j = 1; j <= sqrt; j++) {
				cumsum[j] = cumsum[j - 1] + dp[i - 1][j];
				cumsum[j] %= MOD;
			}
			long[] cumsum2 = new long[sqrt + 2];
			for (int j = sqrt; j >= 1; j--) {
				cumsum2[j] = cumsum2[j + 1] + dp2[i - 1][j];
				cumsum2[j] %= MOD;
			}

			for (int j = 1; j <= sqrt; j++) {
				dp[i][j] = cumsum2[j] + cumsum[sqrt];
				dp[i][j] %= MOD;
				dp2[i][j] = cumsum[j] * (n / j - n / (j + 1));
			}
			if (n / sqrt == sqrt) {
				dp2[i][sqrt] = 0;
			}
		}

		long ans = 0;
		for (int i = 1; i <= sqrt; i++) {
			ans += dp[k - 1][i];
			ans += dp2[k - 1][i];
			ans %= MOD;
		}

		pr.println(ans);
	}

	// ---------------------------------------------------
	public static void main(String[] args) {
		sc = new Scanner(System.in);
		pr = new Printer(System.out);

		solve();

		pr.close();
		sc.close();
	}

	static class Scanner {
		BufferedReader br;

		Scanner (InputStream in) {
			br = new BufferedReader(new InputStreamReader(in));
		}

		private boolean isPrintable(int ch) {
			return ch >= '!' && ch <= '~';
		}

		private boolean isCRLF(int ch) {
			return ch == '\n' || ch == '\r' || ch == -1;
		}

		private int nextPrintable() {
			try {
				int ch;
				while (!isPrintable(ch = br.read())) {
					if (ch == -1) {
						throw new NoSuchElementException();
					}
				}

				return ch;
			} catch (IOException e) {
				throw new NoSuchElementException();
			}
		}

		String next() {
			try {
				int ch = nextPrintable();
				StringBuilder sb = new StringBuilder();
				do {
					sb.appendCodePoint(ch);
				} while (isPrintable(ch = br.read()));

				return sb.toString();
			} catch (IOException e) {
				throw new NoSuchElementException();
			}
		}

		int nextInt() {
			try {
				// parseInt from Integer.parseInt()
				boolean negative = false;
				int res = 0;
				int limit = -Integer.MAX_VALUE;
				int radix = 10;

				int fc = nextPrintable();
				if (fc < '0') {
					if (fc == '-') {
						negative = true;
						limit = Integer.MIN_VALUE;
					} else if (fc != '+') {
						throw new NumberFormatException();
					}
					fc = br.read();
				}
				int multmin = limit / radix;

				int ch = fc;
				do {
					int digit = ch - '0';
					if (digit < 0 || digit >= radix) {
						throw new NumberFormatException();
					}
					if (res < multmin) {
						throw new NumberFormatException();
					}
					res *= radix;
					if (res < limit + digit) {
						throw new NumberFormatException();
					}
					res -= digit;

				} while (isPrintable(ch = br.read()));

				return negative ? res : -res;
			} catch (IOException e) {
				throw new NoSuchElementException();
			}
		}

		long nextLong() {
			try {
				// parseLong from Long.parseLong()
				boolean negative = false;
				long res = 0;
				long limit = -Long.MAX_VALUE;
				int radix = 10;

				int fc = nextPrintable();
				if (fc < '0') {
					if (fc == '-') {
						negative = true;
						limit = Long.MIN_VALUE;
					} else if (fc != '+') {
						throw new NumberFormatException();
					}
					fc = br.read();
				}
				long multmin = limit / radix;

				int ch = fc;
				do {
					int digit = ch - '0';
					if (digit < 0 || digit >= radix) {
						throw new NumberFormatException();
					}
					if (res < multmin) {
						throw new NumberFormatException();
					}
					res *= radix;
					if (res < limit + digit) {
						throw new NumberFormatException();
					}
					res -= digit;

				} while (isPrintable(ch = br.read()));

				return negative ? res : -res;
			} catch (IOException e) {
				throw new NoSuchElementException();
			}
		}

		float nextFloat() {
			return Float.parseFloat(next());
		}

		double nextDouble() {
			return Double.parseDouble(next());
		}

		String nextLine() {
			try {
				int ch;
				while (isCRLF(ch = br.read())) {
					if (ch == -1) {
						throw new NoSuchElementException();
					}
				}
				StringBuilder sb = new StringBuilder();
				do {
					sb.appendCodePoint(ch);
				} while (!isCRLF(ch = br.read()));

				return sb.toString();
			} catch (IOException e) {
				throw new NoSuchElementException();
			}
		}

		int[] nextIntArray(int n) {
			int[] ret = new int[n];
			for (int i = 0; i < n; i++) {
				ret[i] = sc.nextInt();
			}

			return ret;
		}

		int[][] nextIntArrays(int n, int m) {
			int[][] ret = new int[m][n];
			for (int i = 0; i < n; i++) {
				for (int j = 0; j < m; j++) {
					ret[j][i] = sc.nextInt();
				}
			}

			return ret;
		}

		void close() {
			try {
				br.close();
			} catch (IOException e) {
//				throw new NoSuchElementException();
			}
		}
	}

	static class Printer extends PrintWriter {
		Printer(OutputStream out) {
			super(out);
		}

		void printInts(int... a) {
			StringBuilder sb = new StringBuilder(32);
			for (int i = 0, size = a.length; i < size; i++) {
				if (i > 0) {
					sb.append(' ');
				}
				sb.append(a[i]);
