import java.io.*;
import java.util.*;
//import java.math.*;
//import java.awt.Point;

public class Main {
	//static final long MOD = 998244353L;
	//static final long INF = -1000000000000000007L;
	static final long MOD = 1000000007L;
	//static final int INF = 1000000007;

	public static void main(String[] args) {
		FastScanner sc = new FastScanner();
		PrintWriter pw = new PrintWriter(System.out);
		int N = sc.ni();
		int K = sc.ni();
		int S = (int)Math.sqrt(N);
		long[][] dp = new long[K][2*S];
		for (int i = 0; i < S; i++) {
			dp[0][i] = 1L;
		}
		int num = S+1;
		for (int i = S; i < 2*S; i++) {
			int max = N/(2*S-i); //the maximum number in this group
			dp[0][i] = (long)(max-num+1);
			num = max+1;
		}

		for (int i = 1; i < K; i++) {
			long[] pref = new long[2*S+1];
			for (int p = 1; p <= 2*S; p++) {
				pref[p] = (pref[p-1]+dp[i-1][p-1])%MOD;
			}
			for (int j = 0; j < 2*S; j++) {
				dp[i][j] = (dp[0][j]*pref[2*S-j])%MOD;
			}
		}
		long ans = 0;
		for (int j = 0; j < 2*S; j++) {
			ans += dp[K-1][j];
			ans %= MOD;
		}
		pw.println(ans);
		pw.close();
	}

	public static long dist(long[] p1, long[] p2) {
		return (Math.abs(p2[0]-p1[0])+Math.abs(p2[1]-p1[1]));
	}

	//Find the GCD of two numbers
	public static long gcd(long a, long b) {
		if (a < b) return gcd(b,a);
		if (b == 0)
			return a;
		else
			return gcd(b,a%b);
	}

	//Fast exponentiation (x^y mod m)
	public static long power(long x, long y, long m) { 
		long ans = 1;
		x %= m;
		while (y > 0) { 
			if(y % 2 == 1) 
				ans = (ans * x) % m; 
			y /= 2;  
			x = (x * x) % m;
		} 
		return ans; 
	}

	public static int[][] shuffle(int[][] array) {
		Random rgen = new Random();
		for (int i = 0; i < array.length; i++) {
		    int randomPosition = rgen.nextInt(array.length);
		    int[] temp = array[i];
		    array[i] = array[randomPosition];
		    array[randomPosition] = temp;
		}
		return array;
	}

    public static int[][] sort(int[][] array) {
    	//Sort an array (immune to quicksort TLE)

		Arrays.sort(array, new Comparator<int[]>() {
			  @Override
        	  public int compare(int[] arr1, int[] arr2) {
				  //return arr1[0]-arr2[0]; //ascending order
				  if (arr1[0] != arr2[0]) {
					  return arr1[0]-arr2[0];
				  } else {
					  return arr1[1] - arr2[1];
				  }
	          }
		});
		return array;
	}

    public static long[][] sort(long[][] array) {
    	//Sort an array (immune to quicksort TLE)
		Random rgen = new Random();
		for (int i = 0; i < array.length; i++) {
		    int randomPosition = rgen.nextInt(array.length);
		    long[] temp = array[i];
		    array[i] = array[randomPosition];
		    array[randomPosition] = temp;
		}
		Arrays.sort(array, new Comparator<long[]>() {
			  @Override
        	  public int compare(long[] arr1, long[] arr2) {
				  //return 0;
				  if (arr1[0] < arr2[0]) {
					  return -1;
				  } else if (arr1[1] > arr2[1]) {
					  return 1;
				  } else {
					  return 0;
				  }
	          }
		});
		return array;
	}

    static class FastScanner { 
