public class Solver
{
	public void Solve()
	{
		int N = GetInt();
		int K = GetInt();

		var cnt = new List<ModInt>();
		int sqrt = (int)Sqrt(N);
		for(int i = 1; i <= sqrt; i++)
			cnt.Add(new ModInt(1));

		int current = sqrt + 1;
		while(current <= N)
		{
			int t = N / current;
			int next = (N / t) + 1;
			cnt.Add(new ModInt(next - current));
			current = next;
		}

		int L = cnt.Count;
		var dp = new ModInt[K + 1, L + 1];
		var csum = new ModInt[K + 1, L + 1];
		for(int i = 0; i <= K; i++)
		{
			for(int j = 0; j <= L; j++)
			{
				dp[i, j] = new ModInt(0);
				csum[i, j] = new ModInt(0);
			}
		}
		for(int i = 0; i < L; i++)
		{
			dp[1, i] = cnt[i];
			csum[1, i + 1] = csum[1, i] + dp[1, i];
		}
		for(int i = 1; i < K; i++)
		{
			for(int j = 0; j < L; j++)
			{
				dp[i + 1, j] = csum[i, L - j] * cnt[j];
				csum[i + 1, j + 1] = csum[i + 1, j] + dp[i + 1, j];
			}
		}

		WriteLine(csum[K, L].Val);
	}
}

public struct ModInt
{
	public long Mod { get; private set; }
	public long Val { get; private set; }

	public ModInt(long v)
	{
		Mod = 1000000007;
		Val = v;
	}

	public static ModInt operator+(ModInt x, ModInt y)
	{
		long mod = x.Mod;
		long tmp = x.Val + y.Val;
		if(tmp >= mod)
			tmp -= mod;
		return new ModInt(tmp);
	}

	public static ModInt operator-(ModInt x, ModInt y)
	{
		long mod = x.Mod;
		long tmp = x.Val;
		if(tmp < y.Val)
			tmp += mod;
		tmp -= y.Val;
		return new ModInt(tmp);
	}

	public static ModInt operator*(ModInt x, ModInt y)
	{
		long mod = x.Mod;
		return new ModInt((x.Val * y.Val) % mod);
	}

	public static ModInt operator/(ModInt x, ModInt y)
	{
		long mod = x.Mod;
		long pow = mod - 2;
		long yy = y.Val;
		long inv = 1;
		while(pow > 0)
		{
			if((pow & 1) == 1)
				inv = (inv * yy) % mod;
			yy = (yy * yy) % mod;
			pow >>= 1;
		}
		return new ModInt((x.Val * inv) % mod);
	}

	public static ModInt operator+(ModInt x, long y) => x + new ModInt(y);
	public static ModInt operator-(ModInt x, long y) => x - new ModInt(y);
	public static ModInt operator*(ModInt x, long y) => x * new ModInt(y);
	public static ModInt operator/(ModInt x, long y) => x / new ModInt(y);
	public static ModInt operator++(ModInt x) => x + new ModInt(1);
	public static ModInt operator--(ModInt x) => x - new ModInt(1);
}

