    public object Calc()
    {
        var N = cr.Int;
        var K = cr.Int;

        var sqrtN = (int)Math.Sqrt(N);
        Mod[] dp1 = NewArray(sqrtN + 1, new Mod(1));
        Mod[] dp2 = new Mod[sqrtN + 1];
        int[] cn2 = new int[sqrtN + 1];
        dp1[0] = 0;
        {
            var cur = sqrtN;
            for (var i = sqrtN; i > 0; i--)
            {
                dp2[i] = cn2[i] = N / i - cur;
                cur = N / i;
            }

            for (int i = 1; i < dp1.Length; i++)
            {
                dp1[i] += dp1[i - 1];
                dp2[i] += dp2[i - 1];
            }
        }

        for (int k = 1; k < K; k++)
        {
            Mod[] nd1 = new Mod[sqrtN + 1];
            Mod[] nd2 = new Mod[sqrtN + 1];

            for (int i = 1; i < nd1.Length; i++)
            {
                nd1[i] = dp1[sqrtN] + dp2[sqrtN] - dp2[i - 1] + nd1[i - 1];
                nd2[i] = dp1[i] * cn2[i] + nd2[i - 1];
            }

            dp1 = nd1;
            dp2 = nd2;
        }

        return dp1[sqrtN] + dp2[sqrtN];
    }
