class Program
{
	static void Main()
	{
    string[] input = Console.ReadLine().Split(' ');//Splitで区切り文字を指定して複数個受け取る。
    long n = long.Parse(input[0]);
    int k = int.Parse(input[1]);
    long mod = 1000000007;
    long[] compressions = DivisionCompression(n);
    n = compressions.Length;
    long[,] dp = new long[k+2,n];//置いた個数と右端の数番号
    long[,] sums = new long[k+2,n+1];

    for(int i = 0; i < n; i++)
    {
      dp[1,i] = 1;
      sums[1,i+1] = sums[1,i] + compressions[i]*dp[1,i];
      sums[1,i+1] %= mod;
    }

    for(int i = 2; i <= k+1; i++)
    {
      for(int j = 0; j < n; j++)
      {
        dp[i,j] = sums[i-1,n-j];
        dp[i,j] %= mod;
        sums[i,j+1] = sums[i,j];
        sums[i,j+1] %= mod;
        sums[i,j+1] += compressions[j]*dp[i,j];
        sums[i,j+1] %= mod;
      }
    }


    Console.WriteLine(dp[k+1,0]);
	}

  static long[] DivisionCompression(long num)
  {//x=1~numまでを[n/x]の値で座標圧縮。配列の個数を2√numまで圧縮できる。
  //返り値の配列は圧縮前の個数。
  //例えばnum=10なら、[1,1,1,2,5]を返す。
    int dividesCount = (int)Math.Sqrt(num);
    long[] divides = new long[dividesCount+1];//前半の(x/i)の値
    long[] answers;
    for(int i = 0; i < dividesCount; i++)
    {
      divides[i] = num/(i+1);
    }

    if(divides[dividesCount-1] == dividesCount)
    {
      answers = new long[2*dividesCount-1];
      for(int i = 0; i < dividesCount; i++) answers[i] = 1;

      for(int i = 0; i < dividesCount-1; i++)
      {
        answers[dividesCount+i] = divides[dividesCount-2-i]-divides[dividesCount-1-i];
      }
    }else
    {
      answers = new long[2*dividesCount];
      for(int i = 0; i < dividesCount; i++) answers[i] = 1;

      divides[dividesCount] = dividesCount;
      for(int i = 0; i < dividesCount; i++)
      {
        answers[dividesCount+i] = divides[dividesCount-1-i]-divides[dividesCount-i];
      }
    }

    return answers;
  }

}

