        candidate = candidate.Distinct().ToList();
        candidate.Sort();

        var nextState = candidate
            .Select(c => (c == 0) ? 0 : LowerBound(candidate, n / c))
            .ToArray();

        const int mod = 1000000000 + 7;
        // dp[i,j] = 最後が i の場合の長さ j の配列の場合の数
        // dp[i,j] = sum dp[k,j-1] where i*k <= n
        var dp = new int[candidate.Count];
        for (var i = 1; i < candidate.Count; i++) {
            dp[i] = candidate[i] - candidate[i - 1];
        }
        for (var _ = 0; _ < K - 1; _++) {
            var next = new int[candidate.Count];
            for (var i = 2; i < candidate.Count; i++) {
                dp[i] = (dp[i] + dp[i - 1]) % mod;
            }

            for (var i = 1; i < candidate.Count; i++) {
                next[i] = (int)(1L * dp[nextState[i]] * (candidate[i] - candidate[i - 1]) % mod);
            }
            dp = next;
        }
        long ans = 0;
        for (var i = 1; i < candidate.Count; i++) {
            ans += dp[i];
        }
        ans %= mod;
        cout.WriteLine(ans);
