    public static int LowerBound<T>(List<T> A, int start, int end, T x, Comparison<T> comp) { return LowerBound(A, start, end, x, Comparer<T>.Create(comp)); }
    public static int LowerBound<T>(List<T> A, int start, int end, T x, IComparer<T> comparer) {
        int lower = start, upper = end - 1;
        var result = end;
        while (lower <= upper) {
            var pos = (lower + upper) / 2;
            if (comparer.Compare(x, A[pos]) <= 0) {
                result = pos;
                upper = pos - 1;
            } else {
                lower = pos + 1;
            }
        }
        return result;
    }

