		int N = I[0], K = I[1], sq = FirstBinary(0, 32000, _i => _i * _i > N) - 1;
		var over = new int[sq + 1];
		for (var i = 1; i <= sq; i++) over[i] = N / i - sq;
		// dp[k, last] = k 個並べる, 最後は (last>0 ? last : sq 超過)
		var dp = new long[K + 1, sq + 1];
		dp[0, 1] = 1;
		for (var k = 1; k <= K; k++)
