			var tmp = 0L;
			for (var l = 1; l <= sq; l++) tmp = (tmp + dp[k - 1, l]) % MOD;
			var s = new long[sq + 1];
			if (k > 1) for (var l = 1; l <= sq; l++) s[l] = (s[l - 1] + dp[k - 2, l]) % MOD;
			var t = new long[sq + 1];
			if (k > 1) for (var l = 1; l <= sq; l++) t[l] = (t[l - 1] + dp[k - 2, l] * over[l]) % MOD;
