public class Program
{
    [System.Diagnostics.DebuggerBrowsable(System.Diagnostics.DebuggerBrowsableState.Never)] private ConsoleReader cr; public Program(ConsoleReader consoleReader) { this.cr = consoleReader; }
    static void Main() => Console.WriteLine(new Program(new ConsoleReader(Console.OpenStandardInput())).Result());
    #endregion
    public string Result() { var obj = Calc(); if (obj is bool) return (bool)obj ? "Yes" : "No"; if (obj is double) return ((double)obj).ToString("0.####################"); return obj.ToString(); }
    private object Calc()
    {
        N = cr;
        K = cr;
        var sqrtN = (int)Math.Sqrt(N);
        var bit1 = new BinaryIndexedTree(sqrtN);
        var bit2 = new BinaryIndexedTree(sqrtN);
        var b2f = new Mod[sqrtN];
        var c = sqrtN;
        for (int i = sqrtN - 1; i >= 0; i--)
        {
            bit1.Add(i, 1);
            var nc = N / (i + 1);
            bit2.Add(i, b2f[i] = nc - c);
            c = nc;
        }

        for (int q = 1; q < K; q++)
        {
            var nx1 = new BinaryIndexedTree(sqrtN);
            var nx2 = new BinaryIndexedTree(sqrtN);
            var s1 = bit1.Sum(sqrtN);

            for (int i = 0; i < sqrtN; i++)
            {
                nx1.Add(i, s1 + bit2.Sum(i, sqrtN));
                nx2.Add(i, b2f[i] * bit1.Sum(i + 1));
            }

            bit1 = nx1;
            bit2 = nx2;
        }

        return bit1.Sum(sqrtN) + bit2.Sum(sqrtN);
    }
    int N;
    int K;
}

struct Mod : IEquatable<Mod> { public const long mod = 1000000007; public static readonly Mod invalid = new Mod(-1, false); public readonly long val; private Mod(long val, bool isValid) : this(val) { if (!isValid) this.val = val; } public Mod(long val) { this.val = val % mod; if (this.val < 0) this.val += mod; } public override bool Equals(object obj) => (obj is Mod) ? this == ((Mod)obj) : false; public bool Equals(Mod obj) => this == obj; public override int GetHashCode() => val.GetHashCode(); public override string ToString() => val.ToString(); public static implicit operator Mod(long x) => new Mod(x); public static Mod operator +(Mod x, Mod y) => (x.val + y.val) % mod; public static Mod operator -(Mod x, Mod y) => x.val >= y.val ? (x.val - y.val) % mod : (x.val - y.val) % mod + mod; public static Mod operator *(Mod x, Mod y) => (x.val * y.val) % mod; public static Mod operator /(Mod x, Mod y) => x * y.Inverse(); public static bool operator ==(Mod x, Mod y) => x.val == y.val; public static bool operator !=(Mod x, Mod y) => x.val != y.val; public Mod Inverse() { long a = val, b = mod, u = 1, v = 0; while (b > 0) { long t = a / b; var b2 = a - t * b; a = b; b = b2; var v2 = u - t * v; u = v; v = v2; } u %= mod; if (u < 0) u += mod; return u; } public static Mod Pow(Mod x, int y) { Mod res = 1; for (; y > 0; y >>= 1) { if ((y & 1) == 1) res *= x; x *= x; } return res; } public static Factor CreateFactor(int max) => new Factor(max); public class Factor { private readonly Mod[] fac, finv; public Factor(int max) { ++max; var inv = new Mod[max]; fac = new Mod[max]; finv = new Mod[max]; fac[0] = fac[1] = 1; finv[0] = finv[1] = 1; inv[1] = 1; for (var i = 2; i < max; i++) { fac[i] = fac[i - 1] * i; inv[i] = mod - inv[mod % i].val * (mod / i) % mod; finv[i] = finv[i - 1] * inv[i]; } } /** <summary>組み合わせ関数(二項係数)</summary> */ public Mod Combine(int n, int k) { if (n < k) return 0; if (n < 0 || k < 0) return 0; return fac[n] * finv[k] * finv[n - k]; } public Mod Factorial(int n) => fac[n]; public Mod FactorialInvers(int n) => finv[n]; } }

