class BinaryIndexedTree
{
    public void Add(int i, Mod w)
    {
        for (++i; i < tree.Length; i += (i & -i))
            tree[i] += w;
    }
    public Mod Sum(int toExclusive)
    {
        Mod res = 0;
        for (var i = toExclusive; i > 0; i -= (i & -i))
            res += tree[i];
        return res;
    }
    public Mod Sum(int from, int toExclusive) => Sum(toExclusive) - Sum(from);

    private Mod[] tree;

    public BinaryIndexedTree(int size)
