	public class Program
	{
		static void Main(string[] args)
		{
			var nk = Console.ReadLine().Split(' ').Select(long.Parse).ToArray();
			int n = (int)nk[0];
			int k = (int)nk[1];

			var dic = new Dictionary<long, long>();
			long lastVal = 0;
			for (long i = 1; (i - 1) * (i - 1) <= n; i++) {
				long val = n / i;
				if (dic.ContainsKey(val) == false) {
					dic[val] = 1;
				}

				if (i != 1) {
					dic[i - 1] = lastVal - val;
				}

				lastVal = val;
			}

			int m = dic.Count();
			var keys = dic.Keys.OrderBy(x => x).ToArray();

			var mul = new ModInt[m];
			var dp = new ModInt[k + 1, m];
			for (int i = 0; i < m; i++) {
				mul[i] = dic[keys[i]];
				dp[0, i] = 1;
			}

			for (int i = 0; i < k; i++) {
				for (int j = 0; j < m; j++) {
					if (j == 0) {
						dp[i + 1, j] += dp[i, m - 1 - j] * mul[m - 1 - j];
					} else {
						dp[i + 1, j] += dp[i + 1, j - 1] + dp[i, m - 1 - j] * mul[m - 1 - j];
					}
				}
			}

			ModInt ans = dp[k, m - 1];
			Console.WriteLine(ans);
		}
	}

	public struct ModInt
	{
		public static long Mod { get; set; } = (long)1e9 + 7;

		public static ModInt Pow(ModInt value, long k)
		{
			return Pow(value.Value, k);
		}

		public static ModInt Pow(long value, long k)
		{
			long ret = 1;
			for (k %= Mod - 1; k > 0; k >>= 1, value = value * value % Mod) {
				if ((k & 1) == 1) {
					ret = ret * value % Mod;
				}
			}
			return new ModInt(ret);
		}

		public static ModInt Inverse(ModInt value)
		{
			return Pow(value, Mod - 2);
		}

		public long Value;

		public ModInt(long value)
		{
			Value = value;
		}

		public static ModInt operator +(ModInt lhs, ModInt rhs)
		{
			lhs.Value += rhs.Value;
			if (lhs.Value >= Mod) {
				lhs.Value -= Mod;
			}
			return lhs;
		}

		public static ModInt operator -(ModInt lhs, ModInt rhs)
		{
			lhs.Value -= rhs.Value;
			if (lhs.Value < 0) {
				lhs.Value += Mod;
			}

			return lhs;
		}

		public static ModInt operator *(ModInt lhs, ModInt rhs)
		{
			return new ModInt(lhs.Value * rhs.Value % Mod);
		}
		public static ModInt operator /(ModInt lhs, ModInt rhs)
		{
			long exp = Mod - 2;
			while (exp > 0) {
				if (exp % 2 > 0) {
					lhs *= rhs;
				}

				rhs *= rhs;
				exp /= 2;
			}

			return lhs;
		}

		public static implicit operator ModInt(long n)
		{
			n %= Mod;
			if (n < 0) {
				n += Mod;
			}

			return new ModInt(n);
		}

		public override string ToString()
		{
			return Value.ToString();
		}
	}
}

