class Solver {
    StreamWriter sw;
    Scan sc;
    void Prt(string a) => sw.WriteLine(a);
    void Prt<T>(IEnumerable<T> a) => Prt(string.Join(" ", a));
    void Prt(params object[] a) => Prt(string.Join(" ", a));
    public Solver(StreamWriter sw) {
        this.sw = sw;
        this.sc = new Scan();
    }

    public void solve() {
        int n, k;
        sc.Multi(out n, out k);
        int sqn = 1;
        while ((sqn + 1) * (long)(sqn + 1) <= n) ++sqn;

        var coeff = new int[sqn + 1];
        for (int i = 1; i < sqn + 1; i++)
        {
            coeff[i] = Math.Max(n / i - Math.Max(n / (i + 1), sqn), 0);
        }
        var dp1 = new long[sqn + 1];
        var dp2 = new long[sqn + 1];
        dp1[1] = 1;

        for (int i = 0; i < k; i++)
        {
            var nex1 = new long[sqn + 1];
            var nex2 = new long[sqn + 1];
            long sum = 0;
            for (int j = 1; j < sqn + 1; j++)
            {
                sum = (sum + dp1[j]) % M;
                nex2[j] = sum * coeff[j] % M;
            }
            for (int j = sqn; j >= 1 ; j--)
            {
                sum = (sum + dp2[j]) % M;
                nex1[j] = sum;
            }
            dp1 = nex1;
            dp2 = nex2;
        }
        Prt((dp1.Sum() + dp2.Sum()) % M);


    }
}

