    static StreamWriter sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
    static Scan sc = new Scan();
    const int M = 1000000007;
    const int M2 = 998244353;
    const long LM = 1L << 60;
    const double eps = 1e-11;
    static void Main(string[] args)
    {
        int n, k;
        sc.Multi(out n, out k);
        int sqn = 0;
        while ((sqn + 1) * (sqn + 1) <= n) ++sqn;
        int m = sqn + 1;
        var dp1 = new long[m];
        var dp2 = new long[m];
        var cnts = new long[m];
        for (int i = 1; i < m; i++)
        {
            // cnts[i] = n / i - n / (i + 1);
            cnts[i] = n / i - Math.Max(n / (i + 1), sqn);
        }
        dp1[1] = 1;
        for (int i = 0; i < k; i++)
        {
            var nex1 = new long[m];
            var nex2 = new long[m];
            long sum = 0;
            for (int j = 1; j <= sqn; j++)
            {
                sum = (sum + dp1[j]) % M;
                nex2[j] = sum * cnts[j] % M;
            }
            for (int j = sqn; j > 0; j--)
            {
                sum = (sum + dp2[j]) % M;
