namespace ConsoleApp1AtCoder_Beginner_Contest_132
{
    class Program
    {
        //解説動画参照(https://www.youtube.com/watch?v=mso8tE1yMl8)
        //配列にする
        static public long[] Sarray() { return ReadLine().Split().Select(long.Parse).ToArray(); }
        //Listにする
        static public List<long> Slist() { return ReadLine().Split().Select(long.Parse).ToList(); }
        public const long Mod7 = 1000000000 + 7;
        public class pair
        {
            public long first;
            public long second;
            public pair(long f,long s)
            {
                first = f;
                second = s;
            }
        }
        static void Main(string[] args)
        {
            var NK = Sarray();
            var N = NK[0];
            var K = NK[1];
            var s = new List<pair>();
            for (var i = 1; i * i <= N; ++i)
            {
                s.Add(new pair(i, 0));
                s.Add(new pair(N / i, 0));
            }
            s.Sort((l, r) => (int)(l.first - r.first));
            s = s.GroupBy(e => e.first).Select(g => g.First()).ToList();//firstの重複を除く
            for (var i = 0; i < s.Count - 1; ++i)
            {
                var l = N / s[i + 1].first;
                var r = N / s[i].first;
                s[i].second = r - l;
            }
            s[s.Count - 1].second = 1;
            var m = s.Count;
            var mp = new Dictionary<long, long>();
            for (var i = 0; i < m; ++i)
            { mp[(int)s[i].first] = i; }
            var dp = new long[K + 1, m];
            dp[0, mp[N]] = 1;
            for (var i = 0; i < K; ++i)
            {
                for (var j = m - 2; 0 <= j; --j)
                { dp[i, j] += dp[i, j + 1]; }
                for (var j = 0; j < m; ++j)
                {
                    var nj = mp[N / s[j].first];
                    dp[i + 1, j] = (dp[i + 1, j] + dp[i, nj] * s[j].second) % Mod7;
                }
            }
            var ans = 0L;
            for (var j = 0; j < m; ++j)
            { ans = (ans + dp[K, j]) % Mod7; }
            WriteLine(ans);
        }
    }
}

using System;
