partial class Solver {
    public void Run() {
        var n = ni();
        var K = ni();

        var candidate = new List<int>();

        for (int i = 1; i * i <= n; i++) {
            candidate.Add(i);
            candidate.Add(i + 1);
            candidate.Add(n / i + 1);
            candidate.Add(n / i);
        }
        candidate = candidate.Distinct().ToList();
        candidate.Sort();

        var nextState = candidate
            .Select(c => LowerBound(candidate, n / c))
            .ToArray();

        const int mod = 1000000000 + 7;
        // dp[i,j] = 最後が i の場合の長さ j の配列の場合の数
        // dp[i,j] = sum dp[k,j-1] where i*k <= n
        var dp = new int[candidate.Count];
        for (int i = 0; i < candidate.Count; i++) {
            if (candidate[i] <= n) dp[i] = 1;
        }
        var next = new int[candidate.Count];
        var sumDp = new int[candidate.Count];
        for (int i = 0; i < K - 1; i++) {
            for (int j = 0; j + 1 < candidate.Count; j++) {
                var val = 0L;
                if (j - 1 >= 0) val += sumDp[j - 1];
                var count = candidate[j + 1] - candidate[j];
                val += 1L * count * dp[j];
                sumDp[j] = (int)(val % mod);
            }

            for (int j = 0; j + 1 < candidate.Count; j++) {
                next[j] = sumDp[nextState[j]];
            }
            dp = next;
        }
        long ans = 0;
        for (int i = 0; i + 1 < candidate.Count; i++) {
            var count = candidate[i + 1] - candidate[i];
            ans = (ans + 1L * count * dp[i]) % mod;
        }
        ans %= mod;
        cout.WriteLine(ans);
    }
    public static int LowerBound<T>(List<T> A, T x) { return LowerBound(A, 0, A.Count, x); }
    public static int LowerBound<T>(List<T> A, T x, IComparer<T> comparer) { return LowerBound(A, 0, A.Count, x, comparer); }
    public static int LowerBound<T>(List<T> A, T x, Comparison<T> comp) { return LowerBound(A, 0, A.Count, x, Comparer<T>.Create(comp)); }
    public static int LowerBound<T>(List<T> A, int start, int end, T x) { return LowerBound(A, start, end, x, Comparer<T>.Default); }
    public static int LowerBound<T>(List<T> A, int start, int end, T x, Comparison<T> comp) { return LowerBound(A, start, end, x, Comparer<T>.Create(comp)); }
    public static int LowerBound<T>(List<T> A, int start, int end, T x, IComparer<T> comparer) {
        int lower = start, upper = end - 1;
        int result = end;
        while (lower <= upper) {
            int pos = (lower + upper) / 2;
            if (comparer.Compare(x, A[pos]) <= 0) {
                result = pos;
                upper = pos - 1;
            } else {
                lower = pos + 1;
            }
        }
        return result;
    }

}

