public class Solver
{
	public void Solve()
	{
		int N = GetInt();
		int K = GetInt();

		var num = new List<int>();
		for(int i = 1; i * i <= N; i++)
		{
			num.Add(i);
			if(i * i < N)
				num.Add(N / i);
		}
		num.Sort();

		int L = num.Count;
		var cnt = new List<ModInt>();
		cnt.Add(new ModInt(1));
		for(int i = 1; i < L; i++)
			cnt.Add(new ModInt(num[i] - num[i - 1]));

		var dp = Enumerable.Range(0, L).Select(_ => new ModInt(0)).ToArray();
		var csum = Enumerable.Range(0, L + 1).Select(_ => new ModInt(0)).ToArray();

		for(int i = 0; i < L; i++)
			csum[i + 1] = csum[i] + cnt[i];

		for(int i = 1; i < K; i++)
		{
			for(int j = 0; j < L; j++)
				dp[j] = csum[L - j] * cnt[j];

			for(int j = 0; j < L; j++)
				csum[j + 1] = csum[j] + dp[j];
		}

		WriteLine(csum[L].Val);
	}
}

public struct ModInt
{
	public long Mod { get; private set; }
	public long Val { get; private set; }

	public ModInt(long v)
	{
		Mod = 1000000007;
		Val = v;
	}

	public static ModInt operator+(ModInt x, ModInt y)
	{
		long mod = x.Mod;
		long tmp = x.Val + y.Val;
		if(tmp >= mod)
			tmp -= mod;
		return new ModInt(tmp);
	}

	public static ModInt operator-(ModInt x, ModInt y)
	{
		long mod = x.Mod;
		long tmp = x.Val;
		if(tmp < y.Val)
			tmp += mod;
		tmp -= y.Val;
		return new ModInt(tmp);
	}

	public static ModInt operator*(ModInt x, ModInt y)
	{
		long mod = x.Mod;
		return new ModInt((x.Val * y.Val) % mod);
	}

	public static ModInt operator/(ModInt x, ModInt y)
	{
		long mod = x.Mod;
		long pow = mod - 2;
		long yy = y.Val;
		long inv = 1;
		while(pow > 0)
		{
			if((pow & 1) == 1)
				inv = (inv * yy) % mod;
			yy = (yy * yy) % mod;
			pow >>= 1;
		}
		return new ModInt((x.Val * inv) % mod);
	}

	public static ModInt operator+(ModInt x, long y) => x + new ModInt(y);
	public static ModInt operator-(ModInt x, long y) => x - new ModInt(y);
	public static ModInt operator*(ModInt x, long y) => x * new ModInt(y);
	public static ModInt operator/(ModInt x, long y) => x / new ModInt(y);
	public static ModInt operator++(ModInt x) => x + new ModInt(1);
	public static ModInt operator--(ModInt x) => x - new ModInt(1);
}

