  for i := 1; i <= R; i++ {
    A[i] = N / i
  }
  B[R] = A[R] - R
  for i := R - 1; 0 < i; i-- {
    B[i] = A[i] - A[i + 1]
  }
  TA := make([][]int, K + 1)
