const p = 1000000007

func main() {
  NK := NextIntVec()
  N, K := NK[0], NK[1]
  R := 1
  for R * R <= N {
    R++
  }
  R--
  A := make([]int, R + 1)
  B := make([]int, R + 1)
  for i := 1; i <= R; i++ {
    A[i] = N / i
  }
  B[R] = A[R] - R
  for i := R - 1; 0 < i; i-- {
    B[i] = A[i] - A[i + 1]
  }
  TA := make([][]int, K + 1)
  SA := make([][]int, K + 1)
  TB := make([][]int, K + 1)
  SB := make([][]int, K + 1)
  for i := range TA {
