    SA[i] = make([]int, R + 1)
    TB[i] = make([]int, R + 1)
    SB[i] = make([]int, R + 2)
  }
  TA[0][1] = 1
  for i := 1; i <= R; i++ {
    SA[0][i] = 1
  }
  for i := 1; i <= K; i++ {
    for j := 1; j <= R; j++ {
      TA[i][j] = (SA[i - 1][R] + SB[i - 1][j]) % p
      SA[i][j] = (SA[i][j - 1] + TA[i][j]) % p
    }
    for j := R; 0 < j; j-- {
      TB[i][j] = SA[i - 1][j] * B[j] % p
      SB[i][j] = (SB[i][j + 1] + TB[i][j]) % p
    }
  }
  Write((SA[K][R] + SB[K][1]) % p)
  Output()
