func getCountsForLayer(N int) []int {
	layerCounts := []int{0}

	lastQuot := N / 1
	layerIndex := 0

	for i := 1; i <= N; i++ {
		if N/i == lastQuot {
			layerCounts[layerIndex]++
		} else {
			layerIndex++
			layerCounts = append(layerCounts, 1)
			lastQuot = N / i
		}
	}

	return layerCounts
}

// d: debug IO. it can print debug in test.
func solve(io *Io, d *Io) {
	N := io.NextInt()
	K := io.NextInt()

	countsForLayer := getCountsForLayer(N)

	// dp[i][j] i 桁で末尾のレイヤー index が j のものの個数
	dp := make([][]int, K+1)

	for i := range dp {
		dp[i] = make([]int, len(countsForLayer))
	}

	for i, countForLayer := range countsForLayer {
		dp[1][i] = countForLayer
	}

	for i := 2; i <= K; i++ {
		// sdp[j] i-1 桁で 末尾のレイヤー index が j 以下のものの個数
		sdp := make([]int, len(countsForLayer))
		sdp[0] = dp[i-1][0]

		for j := 1; j < len(countsForLayer); j++ {
			sdp[j] = (sdp[j-1] + dp[i-1][j]) % MOD
		}

		for j, countForLayer := range countsForLayer {
			maxMultiplierLayer := len(countsForLayer) - 1 - j
			dp[i][j] = sdp[maxMultiplierLayer] * countForLayer % MOD
		}
	}

	res := 0

	for i := 0; i < len(countsForLayer); i++ {
		res += dp[K][i]
		res %= MOD
	}

	io.Println(res)
}

