// GetDivisor is function that get all divisors of n
func GetDivisor(n int) []int {
	res := []int{}
	tmp := []int{}
	for i := 1; i*i <= n; i++ {
		// if n%i != 0 {
		// 	continue
		// }
		res = append(res, i)
		tmp = append(tmp, n/i)
	}
	if res[len(res)-1] == tmp[len(tmp)-1] {
		tmp = tmp[:len(tmp)-1]
	}
	for i := 0; i < len(tmp); i++ {
		res = append(res,tmp[len(tmp)-1-i])
	}
	return res
}

