module Mod = struct
  module type S = sig val modulo : int end
  module Make (S : S) = struct open S
    let modulo = modulo
    let (+^) a b = (a + b) mod modulo
    let (-^) a b = (a - b + modulo) mod modulo
    let ( *^ ) a b = (a * b) mod modulo
    let rec ( **^ ) a n =
      if n = 0 then 1
      else if n mod 2 = 1 then a *^ a **^ (n-1)
      else let t = a **^ (n/2) in t *^ t
    let inv a = a **^ (modulo-2)
    let (/^) a b = a *^ inv b
  end
end
