    while (M*M <= N) {
        M++;
    }
    M--;

    auto dp1 = new Mint[][](K + 1, N / M + 2);
    auto dp2 = new Mint[][](K + 1, M + 1);
    dp1[0][1] = Mint(1);

    foreach (i ; 0 .. K) {
        foreach (j ; 1 .. N / M + 1) {
            dp1[i + 1][1] += dp1[i][j];
            dp1[i + 1][min(N / M, N / j) + 1] -= dp1[i][j];
            if (j < M) {
                dp2[i + 1][j] += dp1[i][j];
                dp2[i + 1][M] -= dp1[i][j];
            }
        }
        foreach (j ; 1 .. M) {
            dp1[i + 1][1] += dp2[i][j] * (N / j - N / (j + 1));
            dp1[i + 1][j + 1] -= dp2[i][j] * (N / j - N / (j + 1));
        }
        foreach (j ; 1 .. N / M + 2) {
            dp1[i + 1][j] += dp1[i + 1][j - 1];
        }
        foreach (j ; 1 .. M + 1) {
            dp2[i + 1][j] += dp2[i + 1][j - 1];
        }
