proc toModInt*(n: int): ModInt =
  if n >= modulus + modulus:
    ModInt(n mod modulus)
  elif n >= modulus:
    ModInt(n - modulus)
  elif n >= 0:
    ModInt(n)
  elif n >= -modulus:
    ModInt(n + modulus)
  else:
    ModInt((n mod modulus + modulus) mod modulus)
proc inverse*(n: ModInt): ModInt =
  var (a, x, b, y) = (modulus, 0, n.toInt, 1)
  while b != 0:
    let tmp = a div b
    a -= tmp * b; swap(a, b)
    x -= tmp * y; swap(x, y)
  return x.toModInt
