    for i in 1.. {
        if i * i > n {
            root_n_loof = i - 1;
            break;
        }
    }
    let mut thresholds = vec![];
    for i in 1..root_n_loof + 1 {
        thresholds.push(i);
        thresholds.push(n / i);
    }
    thresholds.sort();
    thresholds.dedup();
    // debug!(thresholds);

    let mut bandwidths = vec![0; thresholds.len()];
    bandwidths[0] = thresholds[0];
    for i in 1..thresholds.len() {
        bandwidths[i] = thresholds[i] - thresholds[i - 1];
    }
