const MODULO: usize = 1_000_000_007;

fn main() {
    let input = read_stdin();
    let tokens = &mut input.split_whitespace();
    let n: usize = scan(tokens);
    let k: usize = scan(tokens);
    if n == 1 {
        println!("1");
        return;
    }
    let mut r = 0;
    while r * r <= n {
        r += 1;
    }
    r -= 1;
    let mut c: Vec<usize> = vec![1; 2 * r + 1];
    for i in 1..r {
        c[2 * r + 1 - i] = n / i - n / (i + 1);
    }
    c[r + 1] = n / r - r;
    let mut dp: Vec<Vec<usize>> = vec![vec![1; 2 * r + 1]; 2];
    for i in 2..k + 1 {
        dp[i & 1][2 * r] = dp[(i - 1) & 1][1] * c[1] % MODULO;
        for j in 2..2 * r + 1 {
            dp[i & 1][2 * r + 1 - j] =
                (dp[i & 1][2 * r + 1 - j + 1] + dp[(i - 1) & 1][j] * c[j]) % MODULO;
        }
    }
    let mut ans: usize = 0;
    for i in 1..2 * r + 1 {
        ans = (ans + dp[k & 1][i] * c[i]) % MODULO;
    }
    println!("{}", ans);
}

