const MOD: usize = 1e9 as usize + 7;

fn main() {
    input!{
      n: usize,
      k: usize,
    }
    let root = (n as f64).sqrt() as usize;
    let mut nums = vec![];
    {
        let mut i = 1;
        while i <= n {
            if i <= root {
                nums.push(1);
                i += 1;
            } else {
                let lower = i;
                let upper = n / (n/lower);
                nums.push(upper - lower + 1);
                i = upper + 1;
            }
        }
    }
    let nn = nums.len();
    let mut dp = vec![vec![0; nn]; k];

    for i in 0..nn {
        dp[0][i] = nums[i];
    }
    for i in 0..k-1 {
        let mut acm = vec![0; nn+1];
        for j in 0..nn {
            acm[j+1] = acm[j] + dp[i][j];
            acm[j+1] %= MOD;
        }
        for j in 0..nn {
            dp[i+1][j] = acm[nn-j] * nums[j] % MOD;
        }
    }
    let mut ans = 0;
    for i in 0..nn {
        ans += dp[k-1][i];
        ans %= MOD;
    }
    println!("{}", ans);
}

