#[allow(dead_code)]
fn read<T: FromStr>() -> T {
    let stdin = stdin();
    let stdin = stdin.lock();
    let token: String = stdin
        .bytes()
        .map(|c| c.expect("failed to read char") as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().expect("failed to parse token")
}

const MOD: usize = 1e+9 as usize + 7;
fn main() {
    let n = read::<usize>();
    let k = read::<usize>();
    let sqn = ((n as f64).sqrt().floor()) as usize;
    let mut kinds = vec![];
    for i in 1..sqn + 1 {
        kinds.push((i, n / i));
    }
    for i in (1..sqn + 1).rev() {
        let mut v = n / (i + 1) + 1;
        kinds.push((v, i));
    }
    kinds.sort();
    kinds.dedup();
    let m = kinds.len();
    let mut width = vec![0; m];
    let mut prev = n + 1;
    for i in (0..m).rev() {
        width[i] = prev - kinds[i].0;
        prev = kinds[i].0;
    }
    // println!("{:?}", kinds);
    let mut dp = vec![0; m];
    dp[0] = 1;
    for _iter in 0..k {
        let mut ndp = vec![0; m];
        let mut sum = 0;
        let mut pos = 0;
        for i in (0..m).rev() {
            while pos < kinds.len() && kinds[pos].0 <= kinds[i].1 {
                sum = (sum + width[pos] * dp[pos]) % MOD;
                pos += 1;
            }
            ndp[i] = sum;
        }
        dp = ndp;
        // println!("{:?}", dp);
    }
    let mut ans = 0;
    for i in 0..m {
        ans = (ans + width[i] * dp[i]) % MOD;
    }
    println!("{}", ans);
}

