use algonium::math::Mint107;
pub struct BIT {
    tree: Vec<Mint107>,
}
pub struct BITRange {
    bit0: BIT,
    bit1: BIT,
}
impl BIT {
    pub fn new(len: usize) -> BIT {
        BIT {
            tree: vec![0.into(); len],
        }
    }
    pub fn len(&self) -> usize {
        self.tree.len()
    }
    pub fn add(&mut self, index: usize, value: Mint107) {
        assert!(index < self.tree.len());
        let mut idx = index;
        while idx < self.tree.len() {
            self.tree[idx] += value;
            idx |= idx + 1;
        }
    }
    pub fn get(&self, begin: usize, end: usize) -> Mint107 {
        if begin >= end {
            return 0.into();
        }
        let a = if end > 0 { self.cum(end - 1) } else { 0.into() };
        let b = if begin > 0 {
            self.cum(begin - 1)
        } else {
            0.into()
        };
        a - b
    }
    fn cum(&self, last: usize) -> Mint107 {
        assert!(last < self.tree.len());
        let mut res = 0.into();
        let mut idx = last as i64;
        while idx >= 0 {
            res += self.tree[idx as usize];
            idx = (idx & (idx + 1)) - 1;
        }
        res
    }
}
impl BITRange {
    pub fn new(n: usize) -> BITRange {
        BITRange {
            bit0: BIT::new(n + 1),
            bit1: BIT::new(n + 1),
        }
    }
    pub fn add(&mut self, begin: usize, end: usize, by: Mint107) {
        if begin >= end {
            return;
        }
        let a = begin as i64;
        let b = end as i64;
        self.bit0.add(begin, by * a * -1);
        self.bit0.add(end, by * b);
        self.bit1.add(begin, by);
        self.bit1.add(end, by * -1);
    }
    pub fn get(&self, begin: usize, end: usize) -> Mint107 {
        if begin >= end {
            return 0.into();
        }
        self.cum(end) - self.cum(begin)
    }
    fn cum(&self, end: usize) -> Mint107 {
        let a = self.bit0.get(0, end);
        let b = self.bit1.get(0, end);
        a + b * end as i64
    }
}
fn run() {
    input! {
        n: usize,
        k: usize,
    }
    let mut vs = Vec::new();
    for i in 1..n {
        if i * i > n {
            break;
        }
        vs.push(i);
        if i * i != n {
            vs.push(n / i);
        }
    }
    vs.push(0);
    vs.sort();

    let mut ranges = Vec::new();
    let mut index = HashMap::new();
    for i in 0..vs.len() - 1 {
        ranges.push((vs[i] + 1, vs[i + 1] + 1));
        index.insert(vs[i + 1], i);
    }
    let mut bit = BITRange::new(vs.len());
    bit.add(0, vs.len(), 1.into());
    for _ in 0..k - 1 {
        let mut nbit = BITRange::new(vs.len());
        for (i, &(l, r)) in ranges.iter().enumerate() {
            let ub = index[&(n / l)] + 1;
            let value = bit.get(i, i + 1) * (r - l);
            nbit.add(0, ub, value);
        }
        bit = nbit;
    }
    let mut answer: Mint107 = 0.into();
    for (i, &(l, r)) in ranges.iter().enumerate() {
        let value = bit.get(i, i + 1) * (r - l);
        answer += value;
    }
    println!("{}", answer);
}

