use crate::mod_int::ModInt;
use std::collections::{BTreeMap, BTreeSet};

const MOD: usize = 1e9 as usize + 7;

fn main() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };
    let n: usize = sc.read();
    let k: usize = sc.read();

    let mut seg = BTreeSet::new();
    for i in 1.. {
        if i * i > n {
            break;
        }
        let j = i + 1;
        let m = n / j;
        let from = m + 1;
        let to = n / i;

        seg.insert((from, to));
        seg.insert((i, i));
    }

    let seg = seg.into_iter().collect::<Vec<_>>();
    let map = seg
        .iter()
        .enumerate()
        .map(|(i, &(from, to))| ((from, to), i))
        .collect::<BTreeMap<_, _>>();
    let n = map.len();
    let mut dp = vec![ModInt::new(1); n];
    //    for i in 0..n {
    //        let (from, to) = seg[i];
    //        dp[i] = ModInt::new(to - from + 1);
    //    }
    for _ in 1..k {
        let mut sum = vec![ModInt::new(0); n + 1];
        for i in 0..n {
            // i -> [0, n-1-i]
            let (from, to) = seg[i];
            let tmp = dp[i] * (to - from + 1);
            sum[n - i] -= tmp;
            sum[0] += tmp;
        }
        let mut next = vec![ModInt::new(0); n];
        let mut cur = ModInt::new(0);
        for i in 0..n {
            cur += sum[i];
            next[i] = cur;
        }
        //        eprintln!("{:?}", dp);
        //        eprintln!("{:?}", next);

        dp = next;
    }

    let mut ans = ModInt::new(0);
    for i in 0..n {
        let (from, to) = seg[i];
        ans += dp[i] * (to - from + 1);
    }
    println!("{}", ans.0);
}

