fn main() {
    let v = read_vec::<i64>();
    let (n, k) = (v[0], v[1]);
    let big_int: i64 = 1000_000_000 + 7;

    let mut divides = vec![];
    for i in 1..(n as f64).sqrt().floor() as i64 + 1 {
        divides.push(i);
        divides.push(n / i);
    }
    let divides = divides.into_iter().collect::<BTreeSet<_>>();
    let divides = divides.into_iter().collect::<Vec<_>>();
    let mut spans = vec![1]; // spans[0] == 1
    for i in 1..divides.len() {
        spans.push(divides[i] - divides[i - 1]);
    }

    let mut dp = vec![0i64; divides.len()];
    dp[0] = 1;
    for _ in 0..k {
        let mut dp_sum = vec![0; divides.len()];
        dp_sum[0] = dp[0];
        for i in 1..divides.len() {
            dp_sum[i] = dp_sum[i - 1] + dp[i];
            dp_sum[i] %= big_int;
        }

        let mut next = vec![0i64; divides.len()];
        for i in 0..divides.len() {
            next[i] = dp_sum[divides.len() - 1 - i] * spans[i];
            next[i] %= big_int;
        }
        dp = next;
        // debug!(dp);
    }
    let mut ans = 0i64;
    for elem in dp {
        ans += elem;
        ans %= big_int;
    }
    println!("{}", ans);
}

