const M: usize = 1e9 as usize + 7;

fn main() {
    input! {
        n: usize,
        k: usize,
    }

    let mut v = std::collections::HashSet::new();
    for i in 1..n+1 {
        if i * i > n {
            break;
        }
        v.insert(i);
        v.insert(n / i);
    }
    let mut v = v.into_iter().collect::<Vec<_>>();
    v.sort();

    let mut limits = vec![0; v.len()];
    for i in 0..v.len() {
        let x = v.binary_search(&(n/v[i])).unwrap();
        limits[i] = x;
    }

    let mut cand = vec![0; v.len()];
    cand[0] = 1;
    for i in 1..v.len() {
        cand[i] = v[i] - v[i-1];
    }

    // println!("{:?}", v);
    // println!("{:?}", limits);
    // println!("{:?}", cand);

    let mut dp = vec![vec![0; v.len()]; k + 1];
    dp[0][0] = 1;
    for i in 1..k+1 {
        let mut sum = vec![0; v.len() + 1];
        sum[0] = dp[i-1][0];
        for j in 1..v.len() {
            sum[j] = sum[j-1] + dp[i-1][j];
            sum[j] %= M;
        }

        for j in 0..v.len() {
            let mut next = sum[limits[j]];
            next *= cand[j];
            next %= M;
            dp[i][j] = next;
        }
    }
    // println!("{:?}", dp);
    let mut ans = 0;
    for i in 0..v.len() {
        ans += dp[k][i];
        ans %= M;
    }
    println!("{}", ans);
}

