const MOD: i64 = 1e9 as i64 + 7;

fn main() {
    input! {
        n: i64, k: usize
    };
    if n == 1 {
        println!("1");
        return;
    }

    let mut bucket_low = vec![];
    let mut bucket_high = vec![];
    for p in 1..n {
        if p*p <= n {
            bucket_low.push(vec![p, p+1]);
            if p*p < n {
                let low = n/(p+1);
                let high = n/p;
                bucket_high.push(vec![low+1, high+1, p]);
            }
        } else {
            break;
        }
    }

    bucket_high.reverse();
    if bucket_high.len() >= 1 && bucket_low.len() >= 1 {
        if bucket_high[0][0] == bucket_low[bucket_low.len()-1][0] && bucket_high[0][1] == bucket_low[bucket_low.len()-1][1] {
            bucket_high.remove(0);
        }
    }

    let bl = bucket_low.len();
    bucket_low.append(&mut bucket_high);
    let mut bucket = bucket_low;
    for i in 0..bl {
        let w = bucket.len()-i;
        bucket[i].push(w as i64);
    }

    // debug!(bucket);

    let n = bucket.len();
    let mut dp = dvec!(0; 2, n+1);
    dp[0][0] = 1;
    dp[0][n] = MOD-1;
    for w in 0..k {
        let fr = w % 2;
        let to = 1 - fr;
        fill!(dp[to], 0);
        for i in 0..n {
            dp[fr][i+1] += dp[fr][i];
            dp[fr][i+1] %= MOD;
        }
        if w == k-1 {
            break;
        }
        for i in 0..n {
            let base = dp[fr][i] * (bucket[i][1] - bucket[i][0]) % MOD;
            dp[to][0] += base;
            dp[to][0] %= MOD;
            dp[to][bucket[i][2] as usize] += MOD-base;
            dp[to][bucket[i][2] as usize] %= MOD;
        }
    }
    let mut total = 0;
    for i in 0..n {
        let base = dp[(k+1)%2][i] * (bucket[i][1] - bucket[i][0]) % MOD;
        total += base;
    }
    println!("{}", total % MOD);
}

const MOD: usize = 1e9 as usize + 7;

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());
    let n: usize = sc.read();
    let k: usize = sc.read();
    let mut indices = vec![];
    for i in 1.. {
        if i * i > n {
            break;
        }
        indices.push(i);
        indices.push(n / i);
    }
    indices.sort();
    indices.dedup();

    let n = indices.len();
    let mut dp = vec![0; n];
    dp[0] = 1;
    for i in 1..n {
        let prev_index = indices[i - 1];
        let index = indices[i];
        dp[i] = index - prev_index;
    }

    for _ in 1..k {
        let mut next = vec![0; n];

        let mut sum = 0;
        for i in 0..n {
            sum += dp[i];
            sum %= MOD;

            let count = if n - 1 - i == 0 {
                1
            } else {
                let prev = indices[n - 1 - i - 1];
                let index = indices[n - 1 - i];
                index - prev
            };
            next[n - 1 - i] = (sum * count) % MOD;
        }
        dp = next;
    }

    println!("{}", dp.into_iter().sum::<usize>() % MOD);
}

pub struct IO<R, W: std::io::Write>(R, std::io::BufWriter<W>);

impl<R: std::io::Read, W: std::io::Write> IO<R, W> {
    pub fn new(r: R, w: W) -> Self {
        Self(r, std::io::BufWriter::new(w))
    }
    pub fn write<S: ToString>(&mut self, s: S) {
        use std::io::Write;
        self.1.write(s.to_string().as_bytes()).unwrap();
    }
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .0
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r' || b == b'\t')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r' && b != b'\t')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

