    for i in 0..k as usize {
        for j in (0..m - 1).rev() {
            dp[i][j] += dp[i][j + 1];
        }
        for j in 0..m {
            let nj = s.lower_bound(n / s[j]);
            dp[i + 1][j] += dp[i][nj] * w[j];
        }
    }

    let mut ans = ModInt(0);
    for j in 0..m {
        ans += dp[k as usize][j];
    }
    println!("{}", ans);
}

trait LowerBound<T: Ord> {
    fn lower_bound(&self, x: T) -> usize;
}

impl<T: Ord> LowerBound<T> for [T] {
    fn lower_bound(&self, x: T) -> usize {
        let mut l = -1 as i64;
        let mut r = self.len() as i64;
        while r - l > 1 {
            let m = ((l + r) / 2) as usize;
            if self[m] >= x {
                r = m as i64;
            } else {
                l = m as i64;
            }
        }
        r as usize
    }
}

