fn main() {
    input! {
        n:i64,
        k:usize,
    }
    let mut group = vec![];
    for i in (1..=n).take_while(|&i| i <= n / i) {
        group.push(i);
        if i != n / i {
            group.push(n / i);
        }
    }
    group.sort();
    let group: Vec<(i64, i64)> = group
        .iter()
        .scan(0, |before, &x| {
            let res = (*before + 1, x);
            *before = x;
            Some(res)
        })
        .collect();
    let m = group.len();
    //dp[i][j]:長さi,ラストがgroup[j]に含まれるやつの個数
    let mut dp: Vec<Vec<i64>> = vec![vec![0; m]; k + 1];
    dp[0][0] = 1;
    let modulo = 1e9 as i64 + 7;
    for i in 0..k {
        let mut imos = vec![0; m + 1];
        for j in 0..m {
            let left = 0;
            let right = m - j;
            imos[left] = (imos[left] + dp[i][j]) % modulo;
            imos[right] = (imos[right] - dp[i][j]) % modulo;
        }
        let mut now = 0;
        for j in 0..m {
            now = (now + imos[j]) % modulo;
            let res = now * (group[j].1 - group[j].0 + 1) % modulo;
            dp[i + 1][j] = res;
        }
    }
    let sum = dp
        .last()
        .unwrap()
        .iter()
        .fold(0, |acc, &x| (acc + x) % modulo);
    let ans = if sum >= 0 {
        sum
    } else {
        (sum % modulo + modulo) % modulo
    };
    println!("{}", ans);
}

