pub trait Bisect: Copy {
    fn halve(self, other: Self) -> Self;
    fn section_end(self, other: Self) -> bool;
}
impl Bisect for usize {
    fn halve(self, other: Self) -> Self {
        if self > other {
            other + (self - other) / 2
        } else {
            self + (other - self) / 2
        }
    }
    fn section_end(self, other: Self) -> bool {
        (if self > other {
            self - other
        } else {
            other - self
        }) <= 1
    }
}
impl Bisect for i64 {
    fn halve(self, other: Self) -> Self {
        (self + other) / 2
    }
    fn section_end(self, other: Self) -> bool {
        (self - other).abs() <= 1
    }
}
impl Bisect for f64 {
    fn halve(self, other: Self) -> Self {
        (self + other) / 2.
    }
    fn section_end(self, other: Self) -> bool {
        (self - other).abs() <= 1e-8
    }
}
pub fn binary_search<T: Bisect, F: Fn(T) -> bool>(f: F, ok: T, err: T) -> T {
    let mut ok = ok;
    let mut err = err;
    while !ok.section_end(err) {
        let m = ok.halve(err);
        if f(m) {
            ok = m;
        } else {
            err = m;
        }
    }
    ok
}
pub fn lower_bound<T: Bisect + Ord>(v: &[T], x: T) -> usize {
    binary_search(|i| v[i as usize] >= x, v.len() as i64, -1) as usize
}
pub fn upper_bound<T: Bisect + Ord>(v: &[T], x: T) -> usize {
    binary_search(|i| v[i as usize] > x, v.len() as i64, -1) as usize
}
fn main() {
    input! { n, k };
    let sqn = (n as f32).sqrt() as usize;
    let mut v = vec![];
    for _i in 1..sqn + 1 {
        v.push(Modi64(1));
    }
    for i in (1..sqn + 1).rev() {
        let l = binary_search(|j| n / j <= i, n, sqn);
        let r = binary_search(|j| n / j >= i, 1, n + 1);
        if r <= sqn {
            continue;
        }
        v.push(Modi64((r - l + 1) as i64));
    }
    let m = v.len();
    let mut dp = vec![vec![Modi64(1); m], vec![Modi64(1); m]];
    for i in 0..k {
        let ni = (i & 1) ^ 1;
        let i = i & 1;
        dp[ni][0] = dp[i][m - 1] * v[0];
        for j in 1..m {
            dp[ni][j] = dp[ni][j - 1] + dp[i][m - j - 1] * v[j];
        }
    }
    println!("{}", dp[k & 1][m - 1]);
}

