#![allow(unused, non_snake_case, dead_code, non_upper_case_globals)]
use {
    proconio::{marker::*, *},
    std::{cmp::*, collections::*, mem::*},
};

#[fastout]
fn main() {
    input! {//
        n:usize,k:usize,
    }
    let mut iter = 0;
    let mut num = vec![0; MX];
    let mut dp = vec![vec![0; MX]; 111];
    let mut dp_sum = vec![0; MX];
    let mut i = 1;
    while i <= n {
        let j = n / i;
        if i <= j {
            num[iter] = 1;
            i += 1;
        } else {
            num[iter] = n / j - i + 1;
            i = n / j + 1;
        }
        iter += 1;
    }
    dp[0][0] = 1;
    for kk in 0..k {
        dp_sum = vec![0; MX];
        for j in 0..=iter {
            dp_sum[j + 1] = dp_sum[j] + dp[kk][j] % MOD;
        }
        for j in 0..iter {
            dp[kk + 1][j] = dp_sum[iter - j] * num[j] % MOD;
        }
    }
    let mut ans = 0;
    for i in 0..=iter {
        ans += dp[k][i];
        ans %= MOD;
    }
    println!("{}", ans);
}
const MOD: usize = 1000000007;
const MX: usize = 101101;

use std::io::{self, BufRead};
use std::mem::swap;

const M: i64 = 1000000007;

fn main() {
  let stdin = io::stdin();
  let mut lines = stdin.lock().lines();
  let xs: Vec<usize> = lines.next().unwrap().unwrap().split(' ').map(|x| x.parse().unwrap()).collect();
  let (n, k) = (xs[0], xs[1]);
  let mut count: Vec<i64> = (1..(n as i64 + 1)).collect();
  for _ in 0..(k-1) {
    let mut temp: Vec<i64> = vec![0; n];
    temp[0] = count[n-1];
    for i in 1..n {
      temp[i] = (temp[i-1] + count[(n/(i+1))-1]) % M;
    }
    swap(&mut count, &mut temp);
  }
  println!("{}", count[n-1]);
}

