type Mod = Modular<Mod_1_000_000_007>;

use std::fmt::Write;
fn solve<R: BufRead>(parser: &mut Parser<R>) -> String {
    let mut buf = String::new();
    input! {
        parser = parser,
        n: usize,
        m: usize,
    }
    let mut xs = vec![];
    for i in 1.. {
        if i * i > n {
            break;
        }
        xs.push(i);
        if i != n / i {
            xs.push(n / i);
        }
    }
    xs.sort();
    //// eprintln!("xs = {:?}", xs);
    let mut ys = vec![];
    ys.push(Mod::new(1));
    for i in 1..xs.len() {
        ys.push(Mod::new((xs[i] - xs[i - 1]) as u32));
    }
    //// eprintln!("ys = {:?}", ys);
    let mut zs = vec![];
    for _ in 0..ys.len() {
        zs.push(Mod::new(1));
    }
    for _ in 0..m - 1 {
        let mut zs_cum = vec![];
        let mut cum = Mod::new(0);
        for i in 0..ys.len() {
            cum += ys[i] * zs[i];
            zs_cum.push(cum);
        }
        zs_cum.reverse();
        zs = zs_cum;
    }
    let mut res = Mod::new(0);
    for (i, &z) in zs.iter().enumerate() {
        res += z * ys[i];
    }
    writeln!(buf, "{}", res.as_u32());
    buf
}

