    let mut sq = 1;
    while sq * sq <= n {
        sq += 1;
    }
    sq -= 1;
    let m = n / (sq + 1);
    let len = sq + m;
    let mut c = vec![0; m];
    for i in 0..m {
        c[i] = (n / (m - i) - n / (m + 1 - i)) % d;
    }
    let mut dp = vec![vec![0; len]; k + 1];
