    for i in 1..k + 1 {
        let mut ac = vec![0; len];
        ac[0] = dp[i - 1][0];
        for j in 1..len {
            ac[j] = (ac[j - 1] + dp[i - 1][j]) % d;
        }
        for j in 0..sq {
            dp[i][j] = ac[len - j - 1];
        }
        for j in 0..m {
            dp[i][sq + j] = c[j] * ac[n / (n / (m - j)) - 1] % d;
        }
    }
    println!("{}", dp[k].iter().fold(0, |ac, x| (ac + x) % d));
}

