	std::io::stdin().read_to_string(&mut s).unwrap();
	let mut s = s.split_whitespace();
	let n: usize = s.next().unwrap().parse().unwrap();
	let k: usize = s.next().unwrap().parse().unwrap();
	use num::integer::Roots;
	let sqrtn = n.sqrt();
	let mut small = vec![0; sqrtn + 1];
	let mut large = vec![0; sqrtn + 1];
	small[1] = 1;

	for _ in 0..k {
		std::mem::swap(&mut small, &mut large);

		for i in 1..sqrtn {
			large[i + 1] = (large[i + 1] + large[i]) % MOD;
			large[i] = (large[i] * (n / i - n / (i + 1)) as i64) % MOD;
		}
		if sqrtn == n / sqrtn {
			small[sqrtn] = large[sqrtn];
		} else {
			small[sqrtn] = (small[sqrtn] + large[sqrtn]) % MOD;
		}
		large[sqrtn] = (large[sqrtn] * (n / sqrtn - n / (sqrtn + 1)) as i64) % MOD;

		for i in (1..sqrtn).rev() {
			small[i] = (small[i] + small[i + 1]) % MOD;
		}
	}

	let ans = small[sqrtn]
		+ if sqrtn == n / sqrtn { 0 } else { large[sqrtn] }
		+ (1..sqrtn).fold(0, |r, i| (r + small[i] + large[i])) % MOD;
	println!("{}", ans % MOD);
}

const MOD: i64 = 1000000007;

fn main() {
	let mut s = String::new();
	std::io::stdin().read_line(&mut s).unwrap();
	let mut s = s.split_whitespace();
	let n: usize = s.next().unwrap().parse().unwrap();
	let k: usize = s.next().unwrap().parse().unwrap();

	let mut pattern = vec![];
	for i in (1..).take_while(|&i| i * i <= n) {
		pattern.push((i, 0));
		pattern.push((n / i, 0));
	}
	pattern.sort();
	pattern.dedup();
	for i in 0..pattern.len() - 1 {
		let l = n / pattern[i + 1].0;
		let r = n / pattern[i].0;
		pattern[i].1 = r - l;
	}
	pattern.last_mut().unwrap().1 = 1;

	let get_index = |n| pattern.binary_search_by_key(&n, |p| p.0).unwrap();

	let mut dp = vec![vec![0; pattern.len()]; k + 1];
	dp[0][get_index(n)] = 1;
	for i in 0..k {
		for j in (0..pattern.len() - 1).rev() {
			dp[i][j] = (dp[i][j] + dp[i][j + 1]) % MOD;
		}
		for j in 0..pattern.len() {
			dp[i + 1][j] = (dp[i + 1][j] + dp[i][get_index(n / pattern[j].0)] * pattern[j].1 as i64) % MOD;
		}
	}
	let mut ans = (0..pattern.len()).fold(0, |r, i| (r + dp[k][i]) % MOD);
	println!("{}", ans);
}

