const MOD: i64 = 1e9 as i64 + 7;

fn main() {
    input! {
        n: i64, k: usize
    };

    let mut nums = vec![];
    if n <= 100 {
        for i in 1..n+1 {
            nums.push((i, i));
        }
    } else {
        for s in 1..n+1 {
            nums.push((s,s));
            if n/(s+1)+1 <= n/s {
                let lft = max(s+1, n/(s+1)+1);
                if lft <= n/s {
                    // debug!(lft, n/s);
                    nums.push((lft, n/s));
                }
            }
            if s > n/(s+1)+1 || s > n/s {
                break;
            }
        }
        nums.sort();
        nums.dedup();
    }

    let w = nums.len();
    for i in 0..w-1 {
        if nums[i].1 + 1 != nums[i+1].0 {
            nums[i+1].0 = nums[i].1 + 1;
        }
    }

    let mut upto = vec![0; w];

    for i in (0..w).rev() {
        let ma = nums[i].1;
        while upto[i] < w && nums[upto[i]].1 * ma <= n {
            upto[i] += 1;
        }
        if i >= 1 {
            upto[i-1] = upto[i];
        }
    }

    let mut dp = dvec!(0; k+1, w);
    dp[0][0] = 1;
    for i in 1..k+2 {
        let mut psum = vec![0; w+1];
        for j in 0..w {
            psum[j+1] = (psum[j] + dp[i-1][j]) % MOD;
        }
        if i == k+1 {
            println!("{}", psum[w]);
            return;
        }
        for j in 0..w {
            dp[i][j] = psum[upto[j]] * (nums[j].1 - nums[j].0 + 1) % MOD;
        }
    }
}

