const P: usize = 1_000_000_007;

fn find_r(x: usize, N: usize) -> usize {
    // N/y < N/x となる最小の y を探す

    let mut l = x; // ng
    let mut r = N + 1; // ok
    while r - l > 1 {
        let m = l + (r - l) / 2;
        // debug!((x, N, l, r, m, N / l, N / m));

        if N / m < N / l {
            r = m;
        } else {
            l = m;
        }
    }

    r
}

fn main() {
    let (N, K) = read!(usize, usize);

    let mut mul = vec![];
    let mut val = vec![];

    let mut l = 1;
    while l < N {
        let r = find_r(l, N);
        mul.push((r - l) % P);
        val.push((N / l) % P);
        l = r;
    }
    // while r <= N + 1 {
    //     if r == N + 1 || N / r != N / l {
    //         mul.push(r - l);
    //         val.push(N / l);
    //         l = r;
    //         r = l + 1;
    //         continue;
    //     }

    //     r += 1;
    // }
    // debug!(mul);

    let R = mul.len();

    let k = 2;
    let mut inc = vec![0; R];
    let mut acc = vec![0; R];

    for r in 0..R {
        inc[r] = val[r] % P;
    }

    acc[0] = inc[0];
    for r in 1..R {
        acc[r] = (acc[r - 1] + (mul[r] % P * inc[r] % P)) % P;
    }

    // debug!(k, inc, acc);

    for k in 3..K + 1 {
        for r in 0..R {
            inc[r] = acc[R - 1 - r];
        }

        acc[0] = inc[0];
        for r in 1..R {
            acc[r] = (acc[r - 1] + (mul[r] % P * inc[r] % P)) % P;
        }

        // debug!(k, inc, acc);
    }

    println!("{}", acc[R - 1])
}

