fn counts(n: u64) -> Vec<ModP> {
    let last_i = (1..).take_while(|&i| i*i <= n).last().unwrap();
    let res1: Vec<ModP> = (1..last_i+1)
        .map(|i| modp((i * n).ceil_div(i+1) - ((i-1) * n).ceil_div(i)))
        .collect();
    let mut res = vec![modp(1); (1..).take_while(|&i| n/i > last_i).count()];
    res.extend(res1.into_iter().rev());
    res
}

