    read!(n = u64, k = u64);
    let cs = counts(n);
    let mut dp = cs.clone();
    for _ in 1..k {
        let prefsums: Vec<_> = dp.iter().lscan(modp(0), |&acc, &x| acc + x).collect();
        dp = (0..cs.len()).map(|i| {
            cs[i] * prefsums[cs.len() - i]
        }).collect();
    }
    println!("{}", dp.into_iter().sum::<ModP>());
}

