use mod_int::ModInt;

const MAX_K: usize = 210;
const MAX_SN: usize = 100100;

fn solve() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };
    let n: usize = sc.read();
    let k: usize = sc.read();
    let mut cnts = vec![0; MAX_SN];
    let mut iter = 0;
    {
        let mut i = 1;
        while i <= n {
            let j = n / i;
            //less than root N
            if i <= j {
                cnts[iter] += 1;
                i += 1;
            } else {
                cnts[iter] += n / j - i + 1;
                i = n / j + 1;
            }
            iter += 1;
        }
    }
    let mut dp = vec![vec![ModInt::new(0); MAX_SN]; MAX_K];

    dp[0][0] = ModInt::new(1);
    for i in 0..k {
        let mut sdp = vec![ModInt::new(0); MAX_SN];

        for j in 0..iter + 1 {
            sdp[j + 1] = sdp[j] + dp[i][j];
        }
        for j in 0..iter {
            dp[i + 1][j] = ModInt::new(cnts[j] as usize) * sdp[iter - j];
        }
    }
    let mut result = ModInt::new(0);
    for j in 0..iter + 1 {
        result += dp[k][j];
    }

    println!("{}", result.0);
}

fn main() {
    std::thread::Builder::new()
        .stack_size(64 * 1024 * 1024) // 64MB
        .spawn(|| solve())
        .unwrap()
        .join()
        .unwrap();
}


pub mod mod_int {
    use std::ops::{Add, AddAssign, Mul, MulAssign, Sub, SubAssign};
    type Num = usize;
    //we may need to change this value
    const MOD: Num = 1e9 as Num + 7;
    #[derive(Clone, Copy, Debug)]
    pub struct ModInt<T: Copy + Clone>(pub T);

    impl ModInt<Num> {
        pub fn new(x: Num) -> Self {
            ModInt(x)
        }
        pub fn pow(self, e: usize) -> ModInt<Num> {
            let mut result = ModInt::new(1);
            let cur = self;
            let mut e = e;
            while e > 0 {
                if e & 1 == 1 {
                    result *= cur;
                }
                e >>= 1;
            }
            result
        }
    }

    impl Add<ModInt<Num>> for ModInt<Num> {
        type Output = ModInt<Num>;
        fn add(self, rhs: ModInt<Num>) -> ModInt<Num> {
            self + rhs.0
        }
    }

    impl Add<Num> for ModInt<Num> {
        type Output = ModInt<Num>;
        fn add(self, rhs: Num) -> ModInt<Num> {
            let mut tmp = rhs + self.0;
            if tmp >= self::MOD {
                tmp = tmp - self::MOD;
            }
            ModInt(tmp)
        }
    }
    impl Sub<ModInt<Num>> for ModInt<Num> {
        type Output = ModInt<Num>;
        fn sub(self, rhs: ModInt<Num>) -> ModInt<Num> {
            self - rhs.0
        }
    }
    impl Sub<Num> for ModInt<Num> {
        type Output = ModInt<Num>;
        fn sub(self, rhs: Num) -> ModInt<Num> {
            let rhs = if rhs >= MOD { rhs % MOD } else { rhs };
            let value = if self.0 < rhs { self.0 + MOD } else { self.0 };
            ModInt(value - rhs)
        }
    }
    impl AddAssign<ModInt<Num>> for ModInt<Num> {
        fn add_assign(&mut self, rhs: ModInt<Num>) {
            *self = *self + rhs;
        }
    }
    impl AddAssign<Num> for ModInt<Num> {
        fn add_assign(&mut self, rhs: Num) {
            *self = *self + rhs;
        }
    }
    impl SubAssign<ModInt<Num>> for ModInt<Num> {
        fn sub_assign(&mut self, rhs: ModInt<Num>) {
            *self = *self - rhs;
        }
    }

    impl SubAssign<Num> for ModInt<Num> {
        fn sub_assign(&mut self, rhs: Num) {
            *self = *self - rhs;
        }
    }

    impl Mul<ModInt<Num>> for ModInt<Num> {
        type Output = ModInt<Num>;
        fn mul(self, rhs: ModInt<Num>) -> ModInt<Num> {
            self * rhs.0
        }
    }
    impl Mul<Num> for ModInt<Num> {
        type Output = ModInt<Num>;
        fn mul(self, rhs: Num) -> ModInt<Num> {
            ModInt(self.0 * rhs % self::MOD)
        }
    }
    impl MulAssign<ModInt<Num>> for ModInt<Num> {
        fn mul_assign(&mut self, rhs: ModInt<Num>) {
            *self = *self * rhs;
        }
    }

    impl MulAssign<Num> for ModInt<Num> {
        fn mul_assign(&mut self, rhs: Num) {
            *self = *self * rhs;
        }
    }

}

